    public function ict_render_ads($page) {
        if (get_option('ict_enable_ads') !== 'yes') return '';
        if ($page === 'home' && get_option('ict_home_ads') !== 'yes') return '';
        if ($page === 'blog' && get_option('ict_blog_ads') !== 'yes') return '';
        if ($page === 'job'  && get_option('ict_job_ads')  !== 'yes') return '';

        $code = get_option('ict_adsense_code');
        if (!$code) return '';

        return '<div style="margin:40px 0;text-align:center;">'.$code.'</div>';
    }
    public function ict_ads_admin_menu() {
