            'dashicons-megaphone',
            30
        );
    }

    public function ict_ads_register_settings() {
        register_setting('ict_ads_group', 'ict_enable_ads');
        register_setting('ict_ads_group', 'ict_home_ads');
        register_setting('ict_ads_group', 'ict_blog_ads');
        register_setting('ict_ads_group', 'ict_job_ads');
        register_setting('ict_ads_group', 'ict_adsense_code');
    }
