            if (!get_query_var('ict_blog_post')) return;

            global $wpdb;
            $slug = sanitize_title(get_query_var('ict_blog_post'));
            $table = $wpdb->prefix . 'ict_blog_posts';

            $post = $wpdb->get_row(
                $wpdb->prepare("SELECT * FROM $table WHERE slug=%s AND status='publish'", $slug)
            );

            if (!$post) return;

            $title = esc_html($post->title) . ' | Innovative Code Tech';
            $description = esc_attr($post->excerpt);
            $url = esc_url(home_url('/blog/' . $post->slug . '/'));
            $image = esc_url($post->image_url ?: 'https://innovativecodetech.in/default-blog.jpg');
            $date = esc_attr(date('c', strtotime($post->created_at)));

            echo "
            <title>{$title}</title>
            <meta name='description' content='{$description}' />

            <link rel='canonical' href='{$url}' />

            <!-- Open Graph -->
            <meta property='og:type' content='article' />
            <meta property='og:title' content='{$title}' />
            <meta property='og:description' content='{$description}' />
            <meta property='og:url' content='{$url}' />
            <meta property='og:image' content='{$image}' />

            <!-- Twitter -->
            <meta name='twitter:card' content='summary_large_image' />
            <meta name='twitter:title' content='{$title}' />
            <meta name='twitter:description' content='{$description}' />
            <meta name='twitter:image' content='{$image}' />

