            );

            // Category Page
            add_rewrite_rule(
                '^jobs/([^/]+)/?$',
                'index.php?pagename=job-portal&job_category=$matches[1]',
                'top'
            );


            // Job Sitemap
            add_rewrite_rule(
                '^job-sitemap\.xml$',
                'index.php?ict_job_sitemap=1',
                'top'
            );
        });

        // Register query vars
        add_filter('query_vars', function ($vars) {
            $vars[] = 'ict_job_slug';
            $vars[] = 'job_category';
            $vars[] = 'ict_job_sitemap';
            return $vars;
