            global $wpdb;
            $table = $wpdb->prefix . 'ict_jobs';
            $jobs = $wpdb->get_results("SELECT slug, updated_at FROM $table WHERE status='publish'");

            echo '<?xml version="1.0" encoding="UTF-8"?>';
            echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';

            foreach ($jobs as $job) {
                echo '<url>';
                echo '<loc>' . esc_url(home_url('/job/' . $job->slug)) . '</loc>';
                echo '<lastmod>' . esc_html(date('Y-m-d', strtotime($job->updated_at))) . '</lastmod>';
                echo '<changefreq>daily</changefreq>';
                echo '<priority>0.8</priority>';
                echo '</url>';
            }

            echo '</urlset>';
            exit;
