            <script>
                document.addEventListener("DOMContentLoaded", function () {
                    const popup = document.getElementById('ict-wa-popup');
                    const closeBtn = document.getElementById('ict-wa-close');
                    const joinBtn = document.getElementById('ict-wa-join');
                    
                    // Get today's date in YYYY-MM-DD format
                    const today = new Date().toISOString().split('T')[0];
                    
                    // Check localStorage
                    const lastShown = localStorage.getItem('ict_wa_popup_date');
                    const joined = localStorage.getItem('ict_wa_joined');
                    
                    // Show popup if conditions are met
                    if (!joined && lastShown !== today) {
                        // Wait 2 seconds for better UX
                        setTimeout(() => {
                            popup.style.display = 'block';
                            localStorage.setItem('ict_wa_popup_date', today);
                            
                            // Add slight pulse animation to button
                            setTimeout(() => {
                                joinBtn.style.animation = 'pulse 2s infinite';
                            }, 1000);
                        }, 2000);
                    }
                    
                    // Close button
                    closeBtn.addEventListener('click', function() {
                        popup.style.opacity = '0';
                        popup.style.transition = 'opacity 0.3s ease';
                        setTimeout(() => {
                            popup.style.display = 'none';
                        }, 300);
                    });
                    
                    // Join button
                    joinBtn.addEventListener('click', function() {
                        // Track click
                        localStorage.setItem('ict_wa_joined', 'yes');
                        
                        // Optional: Add slight delay before redirect for animation
                        setTimeout(() => {
                            window.open(this.href, '_blank');
                        }, 200);
                        
                        // Close popup
                        popup.style.opacity = '0';
                        setTimeout(() => {
                            popup.style.display = 'none';
                        }, 300);
                    });
                    
                    // Close on background click
                    popup.addEventListener('click', function(e) {
                        if (e.target.id === 'ict-wa-popup') {
                            popup.style.opacity = '0';
                            setTimeout(() => {
                                popup.style.display = 'none';
                            }, 300);
                        }
                    });
                });
            </script>
