            <!-- JavaScript -->
            <script>
            function ICTcalcSalary() {
                const roleSelect = document.querySelector('#role option:checked');
                const expSelect = document.getElementById('exp');
                const resultDiv = document.getElementById('ict-result');
                const minSpan = document.getElementById('ict-salary-min');
                const maxSpan = document.getElementById('ict-salary-max');
                
                // Validation
                if(!roleSelect || !roleSelect.value || !expSelect.value) {
                    alert('Please select both job role and experience level');
                    return;
                }
                
                // Calculate salary
                const min = Math.round(roleSelect.dataset.min * expSelect.value);
                const max = Math.round(roleSelect.dataset.max * expSelect.value);
                
                // Format numbers with commas
                const formatNumber = (num) => num.toLocaleString('en-IN');
                
                // Update result
                minSpan.textContent = formatNumber(min);
                maxSpan.textContent = formatNumber(max);
                
                // Show result with animation
                resultDiv.style.display = 'block';
                resultDiv.style.animation = 'none';
                setTimeout(() => {
                    resultDiv.style.animation = 'fadeIn 0.5s ease-out';
                }, 10);
                
                // Scroll to result
                resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                
                // Google Analytics Event Tracking (if configured)
                if(typeof gtag !== 'undefined') {
                    gtag('event', 'salary_calculation', {
                        'event_category': 'career_tools',
                        'event_label': roleSelect.textContent,
                        'value': expSelect.value
                    });
                }
            }
            
            // Add keyboard support
            document.addEventListener('DOMContentLoaded', function() {
                const inputs = document.querySelectorAll('#role, #exp, .ict-btn');
                
                inputs.forEach(input => {
                    input.addEventListener('keypress', function(e) {
                        if(e.key === 'Enter') {
                            ICTcalcSalary();
                        }
                    });
                });
                
                // Add input validation styling
                const selects = document.querySelectorAll('select');
                selects.forEach(select => {
                    select.addEventListener('change', function() {
                        if(this.value) {
                            this.style.borderColor = 'rgba(10, 25, 47, 0.1)';
                        }
                    });
                });
            });
            </script>
            
