    public function ict_salary_admin_page() {
        global $wpdb;
        $table = $wpdb->prefix . 'ict_salary_data';

        // DELETE
        if (isset($_GET['delete'])) {
            $wpdb->delete($table, ['id' => intval($_GET['delete'])]);
            echo '<div class="notice notice-success"><p>Role deleted</p></div>';
        }

        // ADD / UPDATE
        if (isset($_POST['save_salary'])) {
            $data = [
                'role' => sanitize_text_field($_POST['role']),
                'min_salary' => intval($_POST['min_salary']),
                'max_salary' => intval($_POST['max_salary'])
            ];

            if (!empty($_POST['id'])) {
                $wpdb->update($table, $data, ['id' => intval($_POST['id'])]);
                echo '<div class="notice notice-success"><p>Role updated</p></div>';
            } else {
                $wpdb->insert($table, $data);
                echo '<div class="notice notice-success"><p>Role added</p></div>';
            }
        }

        // EDIT
        $edit = null;
        if (isset($_GET['edit'])) {
            $edit = $wpdb->get_row(
                $wpdb->prepare("SELECT * FROM $table WHERE id=%d", intval($_GET['edit']))
            );
        }

        $rows = $wpdb->get_results("SELECT * FROM $table ORDER BY role ASC");
        ?>

        <div class="wrap">
            <h1>💰 Salary Estimator – Admin</h1>

            <form method="post" style="max-width:500px;background:#fff;padding:20px;border-radius:12px">
                <input type="hidden" name="id" value="<?php echo $edit->id ?? ''; ?>">

                <p>
                    <label>Job Role</label><br>
                    <input type="text" name="role" required style="width:100%"
                    value="<?php echo esc_attr($edit->role ?? ''); ?>">
                </p>

                <p>
                    <label>Min Salary (Year)</label><br>
                    <input type="number" name="min_salary" required style="width:100%"
                    value="<?php echo esc_attr($edit->min_salary ?? ''); ?>">
                </p>

                <p>
                    <label>Max Salary (Year)</label><br>
                    <input type="number" name="max_salary" required style="width:100%"
                    value="<?php echo esc_attr($edit->max_salary ?? ''); ?>">
                </p>

                <button name="save_salary" class="button button-primary">
                    <?php echo $edit ? 'Update Role' : 'Add Role'; ?>
                </button>
            </form>

            <hr>

            <table class="widefat striped">
                <thead>
                    <tr>
                        <th>Role</th>
                        <th>Min</th>
                        <th>Max</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                <?php foreach ($rows as $r): ?>
                    <tr>
                        <td><?php echo esc_html($r->role); ?></td>
                        <td>₹<?php echo number_format($r->min_salary); ?></td>
                        <td>₹<?php echo number_format($r->max_salary); ?></td>
                        <td>
                            <a href="?page=ict-salary-estimator&edit=<?php echo $r->id; ?>">Edit</a> |
