    //mail pop up
    public function ict_save_email(){
        global $wpdb;
        $table = $wpdb->prefix . 'customer_mail';

        $email = sanitize_email($_POST['email'] ?? '');

        if (!is_email($email)) {
            wp_send_json_error("Invalid email");
            wp_die();
        }

        $exists = $wpdb->get_var(
            $wpdb->prepare("SELECT id FROM $table WHERE email=%s", $email)
        );

        if ($exists) {
            wp_send_json_error("Already subscribed");
            wp_die();
        }

        $wpdb->insert($table, [
            'email' => $email,
            'ip_address' => $_SERVER['REMOTE_ADDR']
        ]);

        wp_send_json_success("Subscribed");
        wp_die();
    }


