    public function send_new_post_email($type, $title, $url) {
        global $wpdb;

        $emails = $wpdb->get_col(
            "SELECT email FROM {$wpdb->prefix}customer_mail WHERE status='active'"
        );

        if (empty($emails)) return;

        $api_key = 'xsmtpsib-f52f99c135a72d6093a486cd0c72ea9e214a5c9073146dae8a05aaa97be68d29-Ljix7xRLRkjyvpFm'; // <-- paste here

        foreach ($emails as $email) {

            $data = [
                "sender" => [
                    "name" => "Innovative Code Tech",
                    "email" => "no-reply@innovativecodetech.in"
                ],
                "to" => [
                    ["email" => $email]
                ],
                "subject" => "🔥 New $type Published – $title",
                "htmlContent" => $this->email_template($type, $title, $url)
            ];

            $ch = curl_init("https://api.brevo.com/v3/smtp/email");
            curl_setopt_array($ch, [
                CURLOPT_POST => true,
                CURLOPT_HTTPHEADER => [
                    "api-key: $api_key",
                    "Content-Type: application/json"
                ],
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_POSTFIELDS => json_encode($data)
            ]);

            $response = curl_exec($ch);
            $error = curl_error($ch);
            curl_close($ch);

            if ($error) {
                error_log('[ICT MAIL API] CURL ERROR: ' . $error);
            } else {
                error_log('[ICT MAIL API] SENT to ' . $email);
            }
        }
    }
