    public function get_today_career_tip() {
        global $wpdb;
        $table = $wpdb->prefix . 'ict_career_tips';
        $today = date('Y-m-d');

        $tip = $wpdb->get_row(
            $wpdb->prepare(
                "SELECT * FROM $table WHERE tip_date=%s AND status='active' LIMIT 1",
                $today
            )
        );

        // fallback – latest tip
        if (!$tip) {
            $tip = $wpdb->get_row(
                "SELECT * FROM $table WHERE status='active' ORDER BY tip_date DESC LIMIT 1"
            );
        }

        return $tip ? $tip->tip_text : null;
    }
    public function career_tip_shortcode() {
