    // Add these methods to InnovativeCodeTechPlugin class:

    public function optimize_page_load() {
        // Remove unnecessary WordPress scripts
        if (!is_admin()) {
            wp_deregister_script('jquery-migrate');
            wp_deregister_script('wp-embed');
            
            // Defer JavaScript
            add_filter('script_loader_tag', array($this, 'add_defer_attribute'), 10, 2);
        }
    }

    public function add_defer_attribute($tag, $handle) {
        // Add defer to scripts except jQuery
        if ($handle !== 'jquery' && $handle !== 'ict-admin-script') {
            return str_replace(' src', ' defer src', $tag);
        }
        return $tag;
    }
    public function add_seo_optimization() {
        // Only run if we're on the frontend AND Ultimate SEO Master is NOT active
        if (!is_admin() && !class_exists('Ultimate_SEO_Master')) {
            global $post;

            // --- Replace the related part inside add_seo_optimization() ---
            $site_name = get_option('ict_company_name', 'Innovative Code Tech');

            // Safer canonical/url detection
            $queried_id = get_queried_object_id();
            if ( $queried_id ) {
                $url = get_permalink( $queried_id );
            } else {
                $url = home_url( '/' );
            }
            $url = esc_url( $url );

            // Prefer WP Site Icon, otherwise use your provided image (the one you gave me)
            $site_icon = get_site_icon_url();
            $default_logo = 'https://innovativecodetech.in/wp-content/uploads/2026/01/innovative-codetech-logo.png';
            $logo_url = $site_icon ? esc_url( $site_icon ) : esc_url( $default_logo );

            // Use same image for OG and JSON-LD
            $image = $logo_url;

            // Title & Description (keeps your existing logic)
            $title = (is_singular() && !empty(get_the_title($queried_id))) ? get_the_title($queried_id) . ' | ' . $site_name : $site_name;
            $description = '';
            if ( is_singular() && $queried_id ) {
                $the_post = get_post( $queried_id );
                $description = $the_post && ! empty( $the_post->post_excerpt ) ? wp_strip_all_tags( $the_post->post_excerpt ) : wp_trim_words( wp_strip_all_tags( $the_post->post_content ), 30, '...' );
            } else {
                $description = get_bloginfo('description', 'display');
            }
            
            // Output meta tags (unchanged semantics)
            echo '<!-- ICT SEO -->' . "\n";
            echo '<title>' . esc_html( $title ) . '</title>' . "\n";
            echo '<meta name="description" content="' . esc_attr( $description ) . '">' . "\n";
            echo '<meta name="robots" content="index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1">' . "\n";
            echo '<link rel="canonical" href="' . esc_url( $url ) . '">' . "\n";

            // Open Graph + Twitter
            echo '<meta property="og:type" content="website">' . "\n";
            echo '<meta property="og:url" content="' . esc_url( $url ) . '">' . "\n";
            echo '<meta property="og:title" content="' . esc_attr( $title ) . '">' . "\n";
            echo '<meta property="og:description" content="' . esc_attr( $description ) . '">' . "\n";
            echo '<meta property="og:image" content="' . esc_url( $image ) . '">' . "\n";
            echo '<meta name="twitter:card" content="summary_large_image">' . "\n";
            echo '<meta name="twitter:title" content="' . esc_attr( $title ) . '">' . "\n";
            echo '<meta name="twitter:description" content="' . esc_attr( $description ) . '">' . "\n";
            echo '<meta name="twitter:image" content="' . esc_url( $image ) . '">' . "\n";

            // JSON-LD (Organization + WebSite + WebPage)
            $org_name = esc_js( $site_name );
            $org_email = esc_js( get_option('ict_admin_email', 'innovativecodetech@gmail.com') );
            $org_phone = esc_js( get_option('ict_phone', '+919751797695') );
            $org_address = esc_js( get_option('ict_address', 'Chennai, Tamil Nadu') );
            $home = trailingslashit( home_url() );

            $json_ld = array(
                "@context" => "https://schema.org",
                "@graph" => array(
                    array(
                        "@type" => "Organization",
                        "@id" => $home . "#organization",
                        "name" => $org_name,
                        "url" => $home,
                        "logo" => $logo_url,
                        "email" => $org_email,
                        "telephone" => $org_phone,
                        "address" => array(
                            "@type" => "PostalAddress",
                            "streetAddress" => $org_address,
                            "addressLocality" => "Chennai",
                            "addressRegion" => "Tamil Nadu",
                            "postalCode" => "600001",
                            "addressCountry" => "IN"
                        )
                    ),
                    array(
                        "@type" => "WebSite",
                        "@id" => $home . "#website",
                        "url" => $home,
                        "name" => $org_name,
                        "description" => $description
                    ),
                    array(
                        "@type" => "WebPage",
                        "@id" => $url . "#webpage",
                        "url" => $url,
                        "name" => $title,
                        "isPartOf" => array( "@id" => $home . "#website" ),
                        "about" => array( "@id" => $home . "#organization" ),
                        "description" => $description,
                        "inLanguage" => get_bloginfo('language')
                    )
                )
            );

            echo '<script type="application/ld+json">' . wp_json_encode( $json_ld, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT ) . '</script>' . "\n";
        }
    }

    // Add performance monitoring
    public function add_performance_tracking() {
        if (!is_admin()) {
            echo '
            <script>
            // Performance monitoring
            window.addEventListener("load", function() {
                // Measure Core Web Vitals
                setTimeout(function() {
                    const perfData = window.performance.timing;
                    const pageLoadTime = perfData.loadEventEnd - perfData.navigationStart;
                    const domReadyTime = perfData.domComplete - perfData.domLoading;
                    
                    // Send to analytics if needed
                    console.log("Page Load Time: " + pageLoadTime + "ms");
                    console.log("DOM Ready Time: " + domReadyTime + "ms");
                    
                    // Show load time in console for debugging
                    if(pageLoadTime > 3000) {
                        console.warn("Page load time exceeds 3 seconds. Consider optimization.");
                    }
                }, 0);
                
                // Lazy load images
                const images = document.querySelectorAll("img[data-src]");
                const imageObserver = new IntersectionObserver((entries, observer) => {
                    entries.forEach(entry => {
                        if(entry.isIntersecting) {
                            const img = entry.target;
                            img.src = img.dataset.src;
                            img.classList.add("loaded");
                            observer.unobserve(img);
                        }
                    });
                });
                
                images.forEach(img => imageObserver.observe(img));
            });
            </script>';
        }
    }
