    public function output_inline_js() {
        ?>
        <script>
            function ictInitialize() {
                if (typeof jQuery !== 'undefined') {
                    jQuery(document).ready(function($) {
                        if ('loading' in HTMLImageElement.prototype) {
                            const images = document.querySelectorAll('img[loading="lazy"]');
                            images.forEach(img => {
                                if (img.dataset.src) {
                                    img.src = img.dataset.src;
                                }
                            });
                        }

                        
                        // Defer non-critical CSS
                        const loadCSS = function(href) {
                            const link = document.createElement('link');
                            link.rel = 'stylesheet';
                            link.href = href;
                            document.head.appendChild(link);
                        };
                        window.addEventListener('load', function() {
                            loadCSS('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css');
                        });
                        $('a[href^="#"]').on('click', function(e) {

                            const targetId = $(this).attr('href');

                            // 🚫 Stop if href is empty or #
                            if (!targetId || targetId === '#') {
                                return;
                            }

                            // 🚫 Stop if element does not exist
                            if ($(targetId).length === 0) {
                                return;
                            }

                            e.preventDefault();

                            $('html, body').animate({
                                scrollTop: $(targetId).offset().top - 100
                            }, 800);

                            $('.ict-nav-link').removeClass('active');
                            $(this).addClass('active');
                        });

                        
                        // Navigation scroll effect
                        $(window).scroll(function() {
                            if($(this).scrollTop() > 50) {
                                $('.ict-navigation').addClass('scrolled');
                            } else {
                                $('.ict-navigation').removeClass('scrolled');
                            }
                            
                            // Update active nav based on scroll position
                            var scrollPos = $(document).scrollTop() + 150;
                            $('.ict-nav-link').each(function() {
                                var currLink = $(this);
                                var href = currLink.attr('href');

                                if (!href || !href.startsWith('#')) return;

                                var refElement = $(href);
                                if (!refElement.length) return;

                                if (
                                    refElement.position().top <= scrollPos &&
                                    refElement.position().top + refElement.height() > scrollPos
                                ) {
                                    $('.ict-nav-link').removeClass('active');
                                    currLink.addClass('active');
                                }
                            });

                        });
                        
                        // Mobile menu toggle
                        $('.ict-nav-mobile-toggle').click(function() {
                            $('.ict-nav-menu').toggleClass('active');
                        });

                        // Email validation function
                        function isValidEmail(email) {
                            var re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                            return re.test(email);
                        }

                        // Trigger file download (you can customize this for actual files)
                        function triggerResourceDownload(resourceSlug) {
                            // For now, just show a message
                            // You can add actual file download logic here
                            
                            // Example: If you have actual files, uncomment this:
                            /*
                            var downloadUrls = {
                                'website-cost-calculator': '<?php echo plugin_dir_url(__FILE__); ?>assets/downloads/cost-calculator.xlsx',
                                'project-requirements-template': '<?php echo plugin_dir_url(__FILE__); ?>assets/downloads/requirements-template.docx',
                                'seo-checklist': '<?php echo plugin_dir_url(__FILE__); ?>assets/downloads/seo-checklist.pdf'
                            };
                            
                            if (downloadUrls[resourceSlug]) {
                                window.open(downloadUrls[resourceSlug], '_blank');
                            }
                            */
                        }

                        // Also prevent form submission on Enter key
                        $(document).on('keypress', '.ict-lead-name, .ict-lead-email', function(e) {
                            if (e.which == 13) {
                                e.preventDefault();
                                $(this).closest('.ict-resource-card').find('.ict-download-btn').click();
                            }
                        });
                        // Contact form submission - FIXED VERSION
                        $('#ictContactForm').on('submit', function(e) {
                            e.preventDefault();
                            
                            var form = $(this);
                            var submitBtn = form.find('.ict-submit-btn');
                            var responseDiv = form.find('.ict-form-response');
                            
                            // Show loading
                            submitBtn.html('<i class="fas fa-spinner fa-spin"></i> Sending...').prop('disabled', true);
                            responseDiv.removeClass('success error').hide();
                            
                            // Collect form data
                            var formData = {
                                action: 'ict_contact_form',
                                security: '<?php echo wp_create_nonce("ict_contact_nonce"); ?>',
                                name: form.find('input[name="name"]').val(),
                                email: form.find('input[name="email"]').val(),
                                phone: form.find('input[name="phone"]').val(),
                                service: form.find('select[name="service"]').val(),
                                budget: form.find('select[name="budget"]').val(),
                                message: form.find('textarea[name="message"]').val()
                            };
                            
                            // Send AJAX request
                            $.ajax({
                                url: '<?php echo admin_url("admin-ajax.php"); ?>',
                                type: 'POST',
                                data: formData,
                                success: function(response) {
                                    if(response.success) {
                                        responseDiv.addClass('success').html(response.data.message).show();
                                        form[0].reset();
                                    } else {
                                        responseDiv.addClass('error').html(response.data.message).show();
                                    }
                                },
                                error: function() {
                                    responseDiv.addClass('error').text('Something went wrong. Please try again.').show();
                                },
                                complete: function() {
                                    submitBtn.html('Send Message').prop('disabled', false);
                                }
                            });
                        });
                        
                        // Razorpay payment for pricing buttons
                        $('.razorpay-pay').on('click', function(e) {
                            e.preventDefault();
                            var amount = $(this).data('amount');
                            var service = $(this).data('service');
                            
                            var options = {
                                "key": "<?php echo esc_js(get_option('ict_razorpay_key', 'rzp_test_')); ?>",
                                "amount": amount * 100, // Amount in paise
                                "currency": "INR",
                                "name": "Innovative Code Tech",
                                "description": service,
                                "handler": function (response){
                                    alert('Payment Successful! Payment ID: ' + response.razorpay_payment_id);
                                    // Redirect to thank you page or show success message
                                    window.location.href = '<?php echo home_url("/thank-you"); ?>';
                                },
                                "prefill": {
                                    "name": "",
                                    "email": "",
                                    "contact": ""
                                },
                                "theme": {
                                    "color": "#0d47a1"
                                }
                            };
                            
                            var rzp = new Razorpay(options);
                            rzp.open();
                        });
                        

                        
                        // Initialize animations on scroll
                        function animateOnScroll() {
                            $('.ict-service-card, .ict-project-card, .ict-testimonial-card, .ict-pricing-card').each(function() {
                                var elementTop = $(this).offset().top;
                                var elementBottom = elementTop + $(this).outerHeight();
                                var viewportTop = $(window).scrollTop();
                                var viewportBottom = viewportTop + $(window).height();
                                
                                if(elementBottom > viewportTop && elementTop < viewportBottom - 100) {
                                    $(this).css({
                                        'animation': 'ictFadeIn 0.8s ease forwards',
                                        'opacity': '0'
                                    });
                                }
                            });
                        }
                        
                        $(window).on('scroll load', animateOnScroll);
                        
                    });
                } else {
                // If jQuery not loaded yet, wait and try again
                setTimeout(ictInitialize, 100);
                }
            }
            ictInitialize();
        </script>
        <?php
    }
