    public function fix_flexibility_function_error() {
        if (!is_admin()) {
            echo '<script>
            // Fix for flexibility function error
            if (typeof flexibility === "undefined") {
                window.flexibility = function() {
                    return {
                        style: function() { return {}; },
                        parse: function() { return {}; },
                        layout: function() { return {}; },
                        apply: function() { return {}; }
                    };
                };
                
                // Also add the methods directly in case something calls them
                if (typeof window.flexibility.style === "undefined") {
                    window.flexibility.style = function() { return {}; };
                    window.flexibility.parse = function() { return {}; };
                    window.flexibility.layout = function() { return {}; };
                    window.flexibility.apply = function() { return {}; };
                }
            }
            
            // If flexibility exists but is not a function, make it one
            if (typeof flexibility !== "function" && typeof flexibility !== "undefined") {
                var oldFlexibility = flexibility;
                window.flexibility = function() {
                    return oldFlexibility;
                };
                // Copy any properties from old object
                for (var prop in oldFlexibility) {
                    if (oldFlexibility.hasOwnProperty(prop)) {
                        window.flexibility[prop] = oldFlexibility[prop];
                    }
                }
            }
            </script>';
        }
    }
    public function create_downloadable_files() {
        // Create downloads directory
        $upload_dir = wp_upload_dir();
        $ict_dir = $upload_dir['basedir'] . '/ict-resources/';
        
        if (!file_exists($ict_dir)) {
            wp_mkdir_p($ict_dir);
        }
        
        // Protect directory with .htaccess
        $htaccess = $ict_dir . '.htaccess';
        if (!file_exists($htaccess)) {
            file_put_contents($htaccess, 
                "Options -Indexes\n" .
                "Deny from all\n" .
                "<FilesMatch '\.(pdf|docx|xlsx|zip)$'>\n" .
                "   Allow from all\n" .
                "</FilesMatch>"
            );
        }
        
        // Create sample files (in real scenario, you'd upload actual files)
        $resources = array(
            'cost-calculator.xlsx' => 'Website Cost Calculator',
            'requirements-template.docx' => 'Project Requirements Template',
            'seo-checklist.pdf' => 'SEO Checklist for New Websites'
        );
        
        update_option('ict_downloadable_resources', $resources);
    }
    // Schedule email sequences
    public function schedule_lead_magnet_emails() {
        if (!wp_next_scheduled('ict_send_email_sequence')) {
            wp_schedule_event(time(), 'daily', 'ict_send_email_sequence');
        }
        
        add_action('ict_send_email_sequence', array($this, 'send_sequence_emails'));
    }
    public function setup_download_handler() {
        if (isset($_GET['ict_download']) && isset($_GET['lead_id'])) {
            $lead_id = intval($_GET['lead_id']);
            $resource = sanitize_text_field($_GET['resource']);
            
            // Verify lead exists and get email
            global $wpdb;
            $table_name = $wpdb->prefix . 'ict_contacts';
            $lead = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM $table_name WHERE id = %d AND service = 'Lead Magnet Download'",
                $lead_id
            ));
            
            if ($lead) {
                // Map resources to actual files
                $resource_files = array(
                    'website-cost-calculator' => array(
                        'name' => 'Website-Cost-Calculator.xlsx',
                        'path' => plugin_dir_path(__FILE__) . 'assets/downloads/Website-Cost-Calculator.xlsx'
                    ),
                    'project-requirements-template' => array(
                        'name' => 'Project-Requirements-Template.docx',
                        'path' => plugin_dir_path(__FILE__) . 'assets/downloads/Project-Requirements-Template.docx'
                    ),
                    'seo-checklist' => array(
                        'name' => 'SEO-Checklist.pdf',
                        'path' => plugin_dir_path(__FILE__) . 'assets/downloads/SEO-Checklist.pdf'
                    )
                );
                
                if (isset($resource_files[$resource]) && file_exists($resource_files[$resource]['path'])) {
                    // Force download
                    header('Content-Type: application/octet-stream');
                    header('Content-Disposition: attachment; filename="' . $resource_files[$resource]['name'] . '"');
                    header('Content-Length: ' . filesize($resource_files[$resource]['path']));
                    readfile($resource_files[$resource]['path']);
                    exit;
                }
            }
            
            // If download fails, redirect to contact page
            wp_redirect(home_url('/contact'));
            exit;
        }
    }
    // Add download page handler
    public function handle_download() {
        if (isset($_GET['ict_download']) && isset($_GET['resource']) && isset($_GET['email'])) {
            $resource = sanitize_text_field($_GET['resource']);
            $email = sanitize_email($_GET['email']);
            
            // Verify email exists in database
            global $wpdb;
            $table_name = $wpdb->prefix . 'ict_contacts';
            $exists = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $table_name WHERE email = %s AND message LIKE %s",
                $email,
                '%' . $resource . '%'
            ));
            
            if ($exists) {
                $upload_dir = wp_upload_dir();
                $file_path = $upload_dir['basedir'] . '/ict-resources/' . $resource;
                
                if (file_exists($file_path)) {
                    header('Content-Type: application/octet-stream');
                    header('Content-Disposition: attachment; filename="' . basename($file_path) . '"');
                    header('Content-Length: ' . filesize($file_path));
                    readfile($file_path);
                    exit;
                }
            }
            
            wp_die('Invalid download request.');
        }
    }
