    public function admin_dashboard_shortcode() {
        // Check if user has access
        $required_role = get_option('ict_dashboard_access', 'administrator');
        
        if (!current_user_can($required_role)) {
            return '<div style="text-align:center; padding:100px 20px;">
                        <h2 style="color:#f44336;">Access Denied</h2>
                        <p>You do not have permission to access the admin dashboard.</p>
                        <a href="' . home_url() . '" class="ict-btn ict-btn-primary" style="margin-top:20px;">Back to Home</a>
                    </div>';
        }
        
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_contacts';
        
        // Handle CRUD operations
        $message = '';
        $message_type = '';
        
        // Handle lead deletion
        if (isset($_GET['delete_lead']) && isset($_GET['nonce'])) {
            if (wp_verify_nonce($_GET['nonce'], 'ict_delete_lead_' . $_GET['delete_lead'])) {
                $lead_id = intval($_GET['delete_lead']);
                $result = $wpdb->delete($table_name, array('id' => $lead_id));
                
                if ($result) {
                    $message = 'Lead deleted successfully!';
                    $message_type = 'success';
                } else {
                    $message = 'Error deleting lead.';
                    $message_type = 'error';
                }
            }
        }
        
        // Handle status update via form
        if (isset($_POST['ict_update_lead']) && isset($_POST['nonce'])) {
            if (wp_verify_nonce($_POST['nonce'], 'ict_update_lead')) {
                $lead_id = intval($_POST['lead_id']);
                $status = sanitize_text_field($_POST['status']);
                $notes = sanitize_textarea_field($_POST['notes']);
                $assigned_to = sanitize_text_field($_POST['assigned_to']);
                $followup_date = sanitize_text_field($_POST['followup_date']);
                
                $result = $wpdb->update($table_name, array(
                    'status' => $status,
                    'notes' => $notes,
                    'assigned_to' => $assigned_to,
                    'followup_date' => $followup_date,
                    'updated_at' => current_time('mysql')
                ), array('id' => $lead_id));
                
                if ($result !== false) {
                    $message = 'Lead updated successfully!';
                    $message_type = 'success';
                } else {
                    $message = 'Error updating lead.';
                    $message_type = 'error';
                }
            }
        }
        
        // Get all leads
        $leads = $wpdb->get_results("SELECT * FROM $table_name ORDER BY created_at DESC", ARRAY_A);
        
        // Get statistics
        $total_leads = $wpdb->get_var("SELECT COUNT(*) FROM $table_name");
        $new_leads = $wpdb->get_var("SELECT COUNT(*) FROM $table_name WHERE status = 'new'");
        $contacted = $wpdb->get_var("SELECT COUNT(*) FROM $table_name WHERE status = 'contacted'");
        $converted = $wpdb->get_var("SELECT COUNT(*) FROM $table_name WHERE status = 'converted'");
        
        // Calculate revenue
        $revenue = 0;
        foreach ($leads as $lead) {
            switch($lead['budget']) {
                case '5k-15k': $revenue += 10000; break;
                case '15k-30k': $revenue += 22500; break;
                case '30k-50k': $revenue += 40000; break;
                case '50k-1L': $revenue += 75000; break;
                case '1L-2L': $revenue += 150000; break;
                case '2L+': $revenue += 300000; break;
            }
        }
        
        ob_start();
        ?>
        
