        <script>
        function showLeadDetails(leadId) {
            fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ict_get_lead_details',
                    lead_id: leadId,
                    nonce: '<?php echo wp_create_nonce("ict_admin_nonce"); ?>'
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    document.getElementById('leadDetailsContent').innerHTML = data.data.html;
                    document.getElementById('leadDetailsModal').style.display = 'flex';
                } else {
                    alert('Error loading lead details.');
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('Error loading lead details.');
            });
        }
        
        function editLead(leadId) {
            fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ict_get_lead_details',
                    lead_id: leadId,
                    nonce: '<?php echo wp_create_nonce("ict_admin_nonce"); ?>'
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    document.getElementById('edit_lead_id').value = leadId;
                    document.getElementById('edit_status').value = data.data.lead.status || 'new';
                    document.getElementById('edit_assigned_to').value = data.data.lead.assigned_to || '';
                    document.getElementById('edit_followup_date').value = data.data.lead.followup_date || '';
                    document.getElementById('edit_notes').value = data.data.lead.notes || '';
                    document.getElementById('editLeadModal').style.display = 'flex';
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('Error loading lead data.');
            });
        }
        
        function closeModal() {
            document.getElementById('leadDetailsModal').style.display = 'none';
        }
        
        function closeEditModal() {
            document.getElementById('editLeadModal').style.display = 'none';
        }
        
        // Close modal when clicking outside
        document.querySelectorAll('.ict-modal').forEach(modal => {
            modal.addEventListener('click', function(e) {
                if (e.target === this) {
                    this.style.display = 'none';
                }
            });
        });
        
        // Handle form submission for editing
        document.getElementById('editLeadForm').addEventListener('submit', function(e) {
            // Form will submit normally (page reload) since we're using POST
        });
        
        // Initialize tooltips and other UI enhancements
        document.addEventListener('DOMContentLoaded', function() {
            // Add confirm dialog for delete links
            document.querySelectorAll('a[onclick*="confirm"]').forEach(link => {
                link.addEventListener('click', function(e) {
                    if (!confirm(this.getAttribute('onclick').match(/confirm\('([^']+)'\)/)[1])) {
                        e.preventDefault();
                    }
                });
            });
        });
        </script>
        
        <?php
        return ob_get_clean();
    }
