    public function settings_page() {
        if (!current_user_can('manage_options')) return;
        
        // Save settings
        if (isset($_POST['ict_settings_nonce'])) {
            if (wp_verify_nonce($_POST['ict_settings_nonce'], 'ict_save_settings')) {
                update_option('ict_admin_email', sanitize_email($_POST['ict_admin_email']));
                update_option('ict_whatsapp_number', sanitize_text_field($_POST['ict_whatsapp_number']));
                update_option('ict_company_name', sanitize_text_field($_POST['ict_company_name']));
                update_option('ict_phone', sanitize_text_field($_POST['ict_phone']));
                update_option('ict_address', sanitize_text_field($_POST['ict_address']));
                update_option('ict_whatsapp_message', sanitize_text_field($_POST['ict_whatsapp_message']));
                update_option('ict_show_whatsapp', sanitize_text_field($_POST['ict_show_whatsapp']));
                update_option('ict_razorpay_key', sanitize_text_field($_POST['ict_razorpay_key']));
                update_option('ict_show_pricing', sanitize_text_field($_POST['ict_show_pricing']));
                update_option('ict_show_offer', sanitize_text_field($_POST['ict_show_offer']));
                update_option('ict_dashboard_access', sanitize_text_field($_POST['ict_dashboard_access']));
                update_option('ict_offer_end_date', sanitize_text_field($_POST['ict_offer_end_date']));
                echo '<div class="notice notice-success"><p>Settings saved successfully!</p></div>';
            }
        }
        
        // Get settings
        $settings = array(
            'admin_email' => get_option('ict_admin_email', 'karthik197454@gmail.com'),
            'whatsapp_number' => get_option('ict_whatsapp_number', '919876543210'),
            'company_name' => get_option('ict_company_name', 'Innovative Code Tech'),
            'phone' => get_option('ict_phone', '+91 9876543210'),
