    public function export_leads() {
        check_ajax_referer('ict_admin_nonce', 'nonce');
        
        if (!current_user_can('manage_options')) {
            wp_die('Unauthorized');
        }
        
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_contacts';
        
        $leads = $wpdb->get_results("SELECT * FROM $table_name ORDER BY created_at DESC", ARRAY_A);
        
        // Set headers for CSV download
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=ict-leads-' . date('Y-m-d') . '.csv');
        
        $output = fopen('php://output', 'w');
        
        // Add CSV headers
        fputcsv($output, array('ID', 'Name', 'Email', 'Phone', 'Service', 'Budget', 'Message', 'Status', 'Notes', 'Assigned To', 'Follow-up Date', 'Created At'));
        
        // Add data rows
        foreach ($leads as $lead) {
            fputcsv($output, array(
                $lead['id'],
                $lead['name'],
                $lead['email'],
                $lead['phone'],
                $lead['service'],
                $lead['budget'],
                $lead['message'],
                $lead['status'],
                $lead['notes'],
                $lead['assigned_to'],
                $lead['followup_date'],
                $lead['created_at']
            ));
        }
        
        fclose($output);
        exit;
    }
