    public function add_project_rewrite_rules() {
        // Project archive - use different path than page slug
        add_rewrite_rule(
            'projects-archive/?$',
            'index.php?ict_projects=1',
            'top'
        );
        
        // Single project - use different path than page slug
        add_rewrite_rule(
            'project/([^/]+)/?$',
            'index.php?ict_project=$matches[1]',
            'top'
        );
    }

