        $vars[] = 'ict_projects';
        $vars[] = 'ict_project';
        return $vars;
    }
    public function render_projects_admin_page() {
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_projects';
        
        // Handle delete action
        if (isset($_GET['action']) && $_GET['action'] == 'delete' && isset($_GET['id'])) {
            $wpdb->delete($table_name, array('id' => intval($_GET['id'])));
            echo '<div class="notice notice-success"><p>Project deleted successfully!</p></div>';
        }

        // Handle status toggle
        if (isset($_GET['action']) && $_GET['action'] == 'toggle_status' && isset($_GET['id'])) {
            $current = $wpdb->get_var($wpdb->prepare(
                "SELECT status FROM $table_name WHERE id = %d",
                intval($_GET['id'])
            ));
            $new_status = ($current == 'publish') ? 'draft' : 'publish';
            $wpdb->update($table_name, array('status' => $new_status), array('id' => intval($_GET['id'])));
        }

