    private function save_project() {
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_projects';
        
        // Verify nonce
        if (!wp_verify_nonce($_POST['ict_project_nonce_field'], 'ict_project_nonce')) {
            wp_die('Security check failed');
        }
        
        $data = array(
            'title' => sanitize_text_field($_POST['project_title']),
            'slug' => sanitize_title($_POST['project_slug']),
            'description' => wp_kses_post($_POST['project_description']),
            'short_description' => sanitize_text_field($_POST['short_description']),
            'technologies' => sanitize_text_field($_POST['technologies']),
            'image_url' => esc_url_raw($_POST['image_url']),
            'github_url' => esc_url_raw($_POST['github_url']),
            'live_url' => esc_url_raw($_POST['live_url']),
            'project_type' => sanitize_text_field($_POST['project_type']),
            'price' => sanitize_text_field($_POST['price']),
            'featured' => isset($_POST['featured']) ? 1 : 0,
            'status' => isset($_POST['status']) ? 'publish' : 'draft',
            'created_at' => current_time('mysql')
        );
        
        $wpdb->insert($table_name, $data);
        
        echo '<div class="notice notice-success"><p>Project added successfully!</p></div>';
    }
    public function projects_shortcode() {
