        $prefix = 'ps_';
        
        // Get all published projects
        $projects = $wpdb->get_results(
            "SELECT * FROM $table_name WHERE status = 'publish' ORDER BY featured DESC, created_at DESC LIMIT 12"
        );
        
        // If no projects in database, show default ones
        if (empty($projects)) {
            $projects = array(
                (object) array(
                    'id' => 1,
                    'title' => 'Smart HRM System',
                    'short_description' => 'Complete human resource management with attendance, payroll, leave management.',
                    'description' => 'Complete human resource management with attendance, payroll, leave management, and employee portal.',
                    'technologies' => 'PHP, Laravel, MySQL, Bootstrap',
                    'image_url' => '',
                    'price' => '₹85,000',
                    'live_url' => '#',
                    'github_url' => '#',
                    'project_type' => 'ERP/CRM System',
                    'featured' => 1
