                        <span>View All Projects</span>
                        <i class="fas fa-arrow-right"></i>
                    </a>
                </div>
            </div>

            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const grid = document.getElementById(prefix + 'grid');
                    
                    if (!grid) return;
                    
                    // Reveal animation
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                grid.parentElement.classList.add(prefix + 'appear');
                                observer.unobserve(entry.target);
                            }
                        });
                    }, { threshold: 0.1 });
                    
                    observer.observe(grid);
                    
                    // Button hover effects
                    const buttons = document.querySelectorAll('.' + prefix + 'button');
                    buttons.forEach(button => {
                        button.addEventListener('mouseenter', () => {
                            button.style.transform = 'translateY(-4px)';
                        });
                        
                        button.addEventListener('mouseleave', () => {
                            button.style.transform = 'translateY(0)';
                        });
                    });
                    
                    // Card click effect
                    const cards = document.querySelectorAll('.' + prefix + 'card');
                    cards.forEach(card => {
                        card.addEventListener('click', function(e) {
                            if (!e.target.closest('.' + prefix + 'button')) {
                                const link = this.querySelector('.' + prefix + 'button-primary');
                                if (link) window.location.href = link.href;
                            }
                        });
                        
                        card.style.cursor = 'pointer';
                    });
                    
                })();
            </script>

        </section>
        <?php
        
        return ob_get_clean();
    }
