    public function inject_seo_meta() {
        // Only on single blog pages
        if (!isset($_GET['ict_blog_post'])) return;
        global $wpdb;
        $slug = sanitize_title($_GET['ict_blog_post'] ?? '');
        if (!$slug) return;
        $post = $wpdb->get_row($wpdb->prepare(
            "SELECT seo_title, seo_description, seo_keywords, title, excerpt FROM {$wpdb->prefix}ict_blog_posts WHERE slug=%s AND status='publish'", $slug
        ));
        if (!$post) return;
        $title = $post->seo_title ?: $post->title;
        $desc  = $post->seo_description ?: $post->excerpt;
        $kws   = $post->seo_keywords;
        echo '<title>'.esc_html($title).' | '.get_bloginfo('name').'</title>'."\n";
        if ($desc) echo '<meta name="description" content="'.esc_attr($desc).'">'."\n";
        if ($kws)  echo '<meta name="keywords" content="'.esc_attr($kws).'">'."\n";
        echo '<meta property="og:title" content="'.esc_attr($title).'">'."\n";
        if ($desc) echo '<meta property="og:description" content="'.esc_attr($desc).'">'."\n";
        echo '<meta name="twitter:card" content="summary_large_image">'."\n";
        echo '<meta name="twitter:title" content="'.esc_attr($title).'">'."\n";
        if ($desc) echo '<meta name="twitter:description" content="'.esc_attr($desc).'">'."\n";
    }
    public function add_blog_query_var($vars) {
        $vars[] = 'ict_blog_post';
        return $vars;
    }

    public function handle_blog_template($template) {
        if (get_query_var('ict_blog_post')) {
            $single_template = plugin_dir_path(__FILE__) . 'templates/single-blog.php';
            if (file_exists($single_template)) {
                return $single_template;
            }
        }
        return $template;
    }

