    private function save_blog_post($edit_id = 0) {
        // Verify nonce
        if (!isset($_POST['blog_post_nonce']) || !wp_verify_nonce($_POST['blog_post_nonce'], 'save_blog_post_action')) {
            wp_die('Security check failed!');
        }
        
        // Sanitize inputs
        $title    = sanitize_text_field(stripslashes($_POST['title']));
        $excerpt  = sanitize_textarea_field(stripslashes($_POST['excerpt']));
        $content = current_user_can('unfiltered_html')
        ? stripslashes_deep($_POST['content'])
        : wp_kses_post(stripslashes_deep($_POST['content']));
        $read_time= sanitize_text_field(stripslashes($_POST['read_time']));
        $tags     = sanitize_text_field(stripslashes($_POST['tags']));
        $image_url= esc_url_raw($_POST['image_url']);
        $status   = sanitize_text_field($_POST['status']);
        $featured = isset($_POST['featured']) ? 1 : 0;
        $seo_title       = sanitize_text_field(stripslashes($_POST['seo_title'] ?? ''));
        $seo_keywords    = sanitize_text_field(stripslashes($_POST['seo_keywords'] ?? ''));
        $seo_description = sanitize_textarea_field(stripslashes($_POST['seo_description'] ?? ''));

        
        // Generate slug from title
        $slug = sanitize_title($title);
        
        // Check if slug already exists (except for current post)
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_blog_posts';
        $old_status = null;
        if ($edit_id) {
            $old_status = $wpdb->get_var(
                $wpdb->prepare("SELECT status FROM $table_name WHERE id=%d", $edit_id)
            );
        }
        if ($edit_id) {
            $existing = $wpdb->get_var($wpdb->prepare(
                "SELECT slug FROM $table_name WHERE slug = %s AND id != %d",
                $slug, $edit_id
            ));
        } else {
            $existing = $wpdb->get_var($wpdb->prepare(
                "SELECT slug FROM $table_name WHERE slug = %s",
                $slug
            ));
        }
        
        // If slug exists, add a number
        if ($existing) {
            $counter = 1;
            while ($wpdb->get_var($wpdb->prepare(
                "SELECT slug FROM $table_name WHERE slug = %s" . ($edit_id ? " AND id != %d" : ""),
                $slug . '-' . $counter,
                $edit_id
            ))) {
                $counter++;
            }
            $slug = $slug . '-' . $counter;
        }
        
        $data = array(
            'title'           => $title,
            'slug'            => $slug,
            'excerpt'         => $excerpt,
            'content'         => $content,
            'read_time'       => $read_time,
            'tags'            => $tags,
            'image_url'       => $image_url,
            'status'          => $status,
            'featured'        => $featured,
            'seo_title'       => $seo_title,
            'seo_keywords'    => $seo_keywords,
            'seo_description' => $seo_description,
            'updated_at'      => current_time('mysql'),
        );
        $is_new_post = false;

        if ($edit_id) {
            // Update existing post
            $wpdb->update($table_name, $data, array('id' => $edit_id));
            $message = 'Blog post updated successfully!';
        } else {
            // Insert new post
            $wpdb->insert($table_name, $data);
            $edit_id = $wpdb->insert_id;
            $message = 'Blog post created successfully!';
            $is_new_post = true;
        }
        if (
            $status === 'publish' &&
            (
                $is_new_post === true ||
                ($old_status && $old_status !== 'publish')
            )
        ) {
            $post_url = home_url('/blog/' . $slug . '/');

            // 🔥 Send email to subscribers
            $this->send_new_post_email(
                'Blog',
                $title,
                $post_url
            );
        }

        // Show success message
        echo '<div class="notice notice-success is-dismissible"><p>' . $message . '</p></div>';
        
        // Redirect to edit page if new post
        if (!$edit_id) {
            echo '<script>window.location.href = "' . admin_url('admin.php?page=ict-add-blog-post&edit=' . $edit_id) . '";</script>';
        }
    }

