    public function single_blog_shortcode() {
        // Get slug from URL parameter
        $slug = get_query_var('ict_blog_post');
        $slug = sanitize_title($slug);

        
        if (!$slug) {
            return '<div class="ict-error" style="text-align: center; padding: 60px 20px;">
                        <h3>Blog Post Not Found</h3>
                        <p>The article you are looking for doesn\'t exist or has been moved.</p>
                        <a href="' . home_url('/blog/') . '" style="
                            background: linear-gradient(135deg, #FFD700, #FFA500);
                            color: #0A1A2F;
                            padding: 12px 25px;
                            border-radius: 10px;
                            text-decoration: none;
                            font-weight: 600;
                            display: inline-block;
                            margin-top: 20px;
                        ">← Back to Blog</a>
                    </div>';
        }
        
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_blog_posts';
        $post = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_name WHERE slug = %s AND status = 'publish'",
            $slug
        ));
        
        if (!$post) {
            return '<div class="ict-error" style="text-align: center; padding: 60px 20px;">
                        <h3>Blog Post Not Found</h3>
                        <p>The article you are looking for doesn\'t exist or has been moved.</p>
                        <a href="' . home_url('/blog/') . '" style="
                            background: linear-gradient(135deg, #FFD700, #FFA500);
                            color: #0A1A2F;
                            padding: 12px 25px;
                            border-radius: 10px;
                            text-decoration: none;
                            font-weight: 600;
                            display: inline-block;
                            margin-top: 20px;
                        ">← Back to Blog</a>
                    </div>';
        }
        
        // Get related posts (3 posts with similar tags)
        $tags = explode(',', $post->tags);
        $tag_conditions = array();
        foreach ($tags as $tag) {
            $tag = trim($tag);
            if (!empty($tag)) {
                $tag_conditions[] = $wpdb->prepare("tags LIKE %s", '%' . $wpdb->esc_like($tag) . '%');
            }
        }
        
        $related_query = "SELECT * FROM $table_name 
                        WHERE status = 'publish' 
                        AND id != %d";
        
        if (!empty($tag_conditions)) {
            $related_query .= " AND (" . implode(' OR ', $tag_conditions) . ")";
        }
        
        $related_query .= " ORDER BY created_at DESC LIMIT 3";
        
        $related_posts = $wpdb->get_results($wpdb->prepare($related_query, $post->id));
        
        ob_start();
        ?>
