            <script>
                (function() {
                    // Share button analytics
                    const shareBtns = document.querySelectorAll('.sb_share_btn');
                    shareBtns.forEach(btn => {
                        btn.addEventListener('click', function() {
                            const platform = this.classList[1].replace('sb_share_', '');
                            
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'blog_share',
                                    'platform': platform,
                                    'article_title': '<?php echo addslashes($post->title); ?>'
                                });
                            }
                        });
                    });
                    
                    // Back to top button
                    const backToTop = document.createElement('button');
                    backToTop.innerHTML = '<i class="fas fa-arrow-up"></i>';
                    backToTop.style.cssText = `
                        position: fixed;
                        bottom: 30px;
                        right: 30px;
                        width: 50px;
                        height: 50px;
                        background: linear-gradient(135deg, var(--sb_gold-1), var(--sb_gold-2));
                        color: var(--sb_navy-900);
                        border: none;
                        border-radius: 50%;
                        cursor: pointer;
                        display: none;
                        align-items: center;
                        justify-content: center;
                        font-size: 1.2rem;
                        box-shadow: 0 5px 20px rgba(255, 215, 0, 0.3);
                        z-index: 1000;
                        transition: all 0.3s ease;
                    `;
                    
                    backToTop.addEventListener('mouseenter', function() {
                        this.style.transform = 'translateY(-3px)';
                    });
                    
                    backToTop.addEventListener('mouseleave', function() {
                        this.style.transform = 'translateY(0)';
                    });
                    
                    backToTop.addEventListener('click', function() {
                        window.scrollTo({top: 0, behavior: 'smooth'});
                    });
                    
                    document.body.appendChild(backToTop);
                    
                    window.addEventListener('scroll', function() {
                        if (window.scrollY > 500) {
                            backToTop.style.display = 'flex';
                        } else {
                            backToTop.style.display = 'none';
                        }
                    });
                    
                    // Table of contents (optional)
                    const headings = document.querySelectorAll('.sb_article_content h2');
                    if (headings.length > 2) {
                        const toc = document.createElement('div');
                        toc.className = 'sb_toc';
                        toc.style.cssText = `
                            background: var(--sb_gray-100);
                            padding: 25px;
                            border-radius: 15px;
                            margin: 30px 0;
                            border-left: 4px solid var(--sb_gold-2);
                        `;
                        
                        toc.innerHTML = '<h3 style="margin: 0 0 15px; color: var(--sb_navy-900);"><i class="fas fa-list"></i> Table of Contents</h3><ul style="margin: 0; padding-left: 20px;">';
                        
                        headings.forEach((heading, index) => {
                            if (!heading.id) {
                                heading.id = 'section-' + index;
                            }
                            toc.innerHTML += `<li style="margin-bottom: 10px;"><a href="#${heading.id}" style="color: var(--sb_navy-700); text-decoration: none;">${heading.textContent}</a></li>`;
                        });
                        
                        toc.innerHTML += '</ul>';
                        
                        const articleContent = document.querySelector('.sb_article_content');
                        if (articleContent) {
                            articleContent.insertBefore(toc, articleContent.firstChild);
                        }
                    }
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
