            <script>
                (function() {
                    const cards = document.querySelectorAll('.bl_card');
                    
                    // Add hover effect for cards
                    cards.forEach(card => {
                        card.addEventListener('mouseenter', function() {
                            this.style.zIndex = '10';
                        });
                        
                        card.addEventListener('mouseleave', function() {
                            this.style.zIndex = '1';
                        });
                    });
                    
                    // Read more button click tracking - REMOVE the loading spinner part
                    const readMoreBtns = document.querySelectorAll('.bl_read_more');

                    readMoreBtns.forEach(btn => {
                        btn.addEventListener('click', function(e) {
                            const card = this.closest('.bl_card');
                            const title = card.querySelector('h3').textContent;
                            
                            // Analytics tracking
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'blog_article_click',
                                    'article_title': title
                                });
                            }
                            
                            // Add loading state (optional - remove if you don't want it)
                            const originalText = this.innerHTML;
                            this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Loading...';
                            this.disabled = true;
                            
                            // The page will navigate automatically via the href
                            // The spinner just shows something is happening
                            setTimeout(() => {
                                this.innerHTML = originalText;
                                this.disabled = false;
                            }, 2000);
                        });
                    });
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    public function blog_management_page() {
