            /* Mobile Responsive */
            @media (max-width: 768px) {
                .nav-toggle-label {
                    display: flex;
                    order: 2;
                }
                
                .nav-menu {
                    position: fixed;
                    top: 80px;
                    left: 0;
                    width: 100%;
                    background: white;
                    flex-direction: column;
                    align-items: stretch;
                    padding: 20px;
                    gap: 10px;
                    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
                    transform: translateY(-100%);
                    opacity: 0;
                    visibility: hidden;
                    transition: all 0.3s ease;
                }
                
                .nav-toggle:checked ~ .nav-menu {
                    transform: translateY(0);
                    opacity: 1;
                    visibility: visible;
                }
                
                .nav-link {
                    padding: 15px;
                    text-align: center;
                    border-radius: 8px;
                }
                
                .nav-cta, .nav-admin-btn {
                    text-align: center;
                    margin-top: 10px;
                }
                
                /* Hamburger Animation */
                .nav-toggle:checked + .nav-toggle-label span:nth-child(1) {
                    transform: rotate(45deg) translate(5px, 5px);
                }
                
                .nav-toggle:checked + .nav-toggle-label span:nth-child(2) {
                    opacity: 0;
                }
                
                .nav-toggle:checked + .nav-toggle-label span:nth-child(3) {
                    transform: rotate(-45deg) translate(7px, -6px);
                }
            }
            
            /* Desktop only adjustments */
            @media (min-width: 769px) {
                .nav-menu {
                    position: static !important;
                    transform: none !important;
                    opacity: 1 !important;
                    visibility: visible !important;
                    box-shadow: none !important;
                    padding: 0 !important;
                    flex-direction: row;
                }
            }
            
            /* Scroll effect */
            .simple-nav.scrolled {
                padding: 10px 0;
                box-shadow: 0 2px 15px rgba(10, 26, 47, 0.15);
            }
            /* Dropdown Menu */
            .nav-dropdown {
                position: relative;
            }

            .nav-dropdown-toggle {
                cursor: pointer;
            }

            .nav-dropdown-menu {
                position: absolute;
                top: 100%;
                left: 0;
                background: white;
                min-width: 220px;
                border-radius: 10px;
                box-shadow: 0 10px 30px rgba(0,0,0,0.15);
                opacity: 0;
                visibility: hidden;
                transform: translateY(10px);
                transition: all 0.3s ease;
                z-index: 999;
            }

            .nav-dropdown-menu a {
                display: block;
                padding: 12px 18px;
                color: #1E3A5F;
                text-decoration: none;
                font-weight: 600;
                border-bottom: 1px solid #f1f1f1;
            }

            .nav-dropdown-menu a:hover {
                background: #f8f9fa;
                color: #FF8C00;
            }

            .nav-dropdown:hover .nav-dropdown-menu {
                opacity: 1;
                visibility: visible;
                transform: translateY(0);
            }

            /* Mobile dropdown */
            @media (max-width: 768px) {
                .nav-dropdown-menu {
                    position: static;
                    box-shadow: none;
                    opacity: 1;
                    visibility: visible;
                    transform: none;
                    background: transparent;
                }

                .nav-dropdown-menu a {
                    text-align: center;
                    background: #f5f5f5;
                    margin-bottom: 5px;
                    border-radius: 6px;
                }
            }

        </style>

        <script>
            // Simple JavaScript for scroll effect
            (function() {
                const nav = document.querySelector('.simple-nav');
                
                window.addEventListener('scroll', function() {
                    if (window.scrollY > 50) {
                        nav.classList.add('scrolled');
                    } else {
                        nav.classList.remove('scrolled');
                    }
                });
                
                // Close mobile menu when clicking a link
                document.querySelectorAll('.nav-link, .nav-cta, .nav-admin-btn').forEach(link => {
                    link.addEventListener('click', function() {
                        if (window.innerWidth <= 768) {
                            document.getElementById('nav-toggle').checked = false;
                        }
                    });
                });
            })();
        </script>
        <?php
        
        return ob_get_clean();
    }
