                .<?php echo $prefix; ?>button-icon { width: 16px; height: 16px; flex-shrink: 0; }

                /* ==============================================================
                   IMAGE — hidden mobile-first, sticky+centered on desktop
                   ============================================================== */
                .<?php echo $prefix; ?>image { display: none; }

                /* ---- Desktop ≥1025px ---- */
                @media (min-width: 1025px) {
                    .<?php echo $prefix; ?>section { overflow: visible !important; }

                    .<?php echo $prefix; ?>container {
                        flex-direction: row;
                        text-align: left;
                        align-items: flex-start; /* critical: enables sticky in flex child */
