                    .<?php echo $prefix; ?>description { margin-left: 0; margin-right: 0; }

                    /* ---- STICKY IMAGE ---- */
                    .<?php echo $prefix; ?>image {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        flex-shrink: 0;
                        width: 420px;

                        /*
                         * Sticky center fix:
                         * top: calc(50vh - 210px) → places image center at viewport middle.
                         * 210px = half of approx image column height (420px wrapper).
                         * align-self: flex-start is REQUIRED for sticky in flex container.
                         */
                        position: sticky;
                        top: calc(50vh - 80px);
                        align-self: flex-start;

                        animation: <?php echo $prefix; ?>fadeUp .65s .12s ease-out both;
                    }

                    .<?php echo $prefix; ?>image-wrapper {
