            <!--
                MINIMAL JS — only anchor smooth scroll.
                Removed: parallax scroll listener, animation init listeners.
                Those caused continuous paint/layout = bad TBT & CLS scores.
            -->
            <script>
            (function(){
                'use strict';
                var hero = document.getElementById('<?php echo $prefix; ?>hero');
                if (!hero) return;
                // Single delegated listener — no per-element listeners
                hero.addEventListener('click', function(e) {
                    var a = e.target.closest('a[href^="#"]');
                    if (!a) return;
                    var id = a.getAttribute('href');
                    if (id === '#') return;
                    var t = document.querySelector(id);
                    if (t) { e.preventDefault(); t.scrollIntoView({ behavior:'smooth', block:'start' }); }
                });
            })();
            </script>

        </section>
