            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const faqSection = document.getElementById(prefix + 'section');
                    
                    if (!faqSection) return;
                    
                    // Initialize FAQ functionality
                    const faqQuestions = faqSection.querySelectorAll('.' + prefix + 'faq-question');
                    let activeAnswer = null;
                    

                    
                    // Add click event to all FAQ questions
                    faqQuestions.forEach(question => {
                        question.addEventListener('click', function() {
                            const answerId = this.getAttribute('data-target');
                            const iconId = this.getAttribute('data-icon');
                            
                            if (activeAnswer === answerId) {
                                // Clicking the active FAQ, close it
                                closeFAQ(answerId, iconId, this);
                                activeAnswer = null;
                            } else {
                                // Close currently open FAQ if exists
                                if (activeAnswer) {
                                    const activeQuestion = faqSection.querySelector('[data-target="' + activeAnswer + '"]');
                                    const activeIcon = faqSection.querySelector('#' + activeAnswer.replace('answer', 'icon'));
                                    if (activeQuestion) closeFAQ(activeAnswer, activeIcon ? activeIcon.id : null, activeQuestion);
                                }
                                
                                // Open clicked FAQ
                                openFAQ(answerId, iconId, this);
                                activeAnswer = answerId;
                            }
                        });
                        
                        // Add keyboard support
                        question.addEventListener('keydown', function(e) {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                this.click();
                            }
                        });
                    });
                    
                    function openFAQ(answerId, iconId, question) {
                        const answer = document.getElementById(answerId);
                        const icon = document.getElementById(iconId);
                        
                        if (answer && icon) {
                            answer.classList.add('open');
                            question.classList.add('active');
                            icon.style.transform = 'rotate(180deg)';
                            
                            // Smooth scroll to FAQ if it's not in view
                            setTimeout(() => {
                                const rect = question.getBoundingClientRect();
                                const windowHeight = window.innerHeight;
                                
                                if (rect.top < 0 || rect.bottom > windowHeight) {
                                    question.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                                }
                            }, 100);
                        }
                    }
                    
                    function closeFAQ(answerId, iconId, question) {
                        const answer = document.getElementById(answerId);
                        const icon = document.getElementById(iconId);
                        
                        if (answer && icon) {
                            answer.classList.remove('open');
                            question.classList.remove('active');
                            icon.style.transform = 'rotate(0deg)';
                        }
                    }
                    
                    // Add intersection observer for animations
                    const observerOptions = {
                        threshold: 0.1,
                        rootMargin: '0px 0px -50px 0px'
                    };
                    
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                entry.target.style.opacity = '1';
                                entry.target.style.transform = 'translateY(0)';
                            }
                        });
                    }, observerOptions);
                    
                    // Observe FAQ items for scroll animations
                    const faqItems = faqSection.querySelectorAll('.' + prefix + 'faq-item');
                    faqItems.forEach((item, index) => {
                        item.style.opacity = '0';
                        item.style.transform = 'translateY(20px)';
                        item.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
                        item.style.transitionDelay = (index * 0.1) + 's';
                        observer.observe(item);
                    });
                    
                    // CTA button animation
                    const ctaButton = faqSection.querySelector('.' + prefix + 'cta-button');
                    if (ctaButton) {
                        ctaButton.addEventListener('mouseenter', () => {
                            ctaButton.style.transform = 'translateY(-5px)';
                            ctaButton.style.boxShadow = '0 15px 35px rgba(255, 215, 0, 0.4)';
                        });
                        
                        ctaButton.addEventListener('mouseleave', () => {
                            ctaButton.style.transform = 'translateY(0)';
                            ctaButton.style.boxShadow = '0 8px 25px rgba(255, 215, 0, 0.3)';
                        });
                    }
                    
                })();
            </script>
        </section>
        <?php
        return ob_get_clean();
    }
    public function pricing_faq_shortcode() {
        $prefix = 'pf_'; // pf = pricing faq
        
        $faqs = array(
            array(
                'question' => 'How much does a website cost in India?',
