            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const faqSection = document.getElementById(prefix + 'section');
                    
                    if (!faqSection) return;
                    
                    // Initialize FAQ functionality
                    const faqQuestions = faqSection.querySelectorAll('.' + prefix + 'faq-question');
                    let activeAnswer = prefix + 'answer1'; // First FAQ open by default
                    
                    // Open first FAQ
                    openFAQ(activeAnswer);
                    
                    // Add click event to all FAQ questions
                    faqQuestions.forEach(question => {
                        question.addEventListener('click', function() {
                            const answerId = this.getAttribute('data-target');
                            
                            if (activeAnswer === answerId) {
                                // Clicking the active FAQ, close it
                                closeFAQ(answerId);
                                activeAnswer = null;
                            } else {
                                // Close currently open FAQ if exists
                                if (activeAnswer) {
                                    closeFAQ(activeAnswer);
                                }
                                
                                // Open clicked FAQ
                                openFAQ(answerId);
                                activeAnswer = answerId;
                            }
                        });
                        
                        // Add keyboard support
                        question.addEventListener('keydown', function(e) {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                this.click();
                            }
                        });
                    });
                    
                    function openFAQ(answerId) {
                        const answer = document.getElementById(answerId);
                        const question = faqSection.querySelector('[data-target="' + answerId + '"]');
                        const icon = document.getElementById(answerId.replace('answer', 'icon'));
                        
                        if (answer && question && icon) {
                            answer.classList.add('open');
                            question.classList.add('active');
                            icon.style.transform = 'rotate(180deg)';
                            
                            // Smooth scroll if FAQ is partially out of view
                            setTimeout(() => {
                                const rect = question.getBoundingClientRect();
                                const windowHeight = window.innerHeight;
                                
                                if (rect.top < 100 || rect.bottom > windowHeight - 100) {
                                    question.scrollIntoView({ 
                                        behavior: 'smooth', 
                                        block: 'center' 
                                    });
                                }
                            }, 100);
                        }
                    }
                    
                    function closeFAQ(answerId) {
                        const answer = document.getElementById(answerId);
                        const question = faqSection.querySelector('[data-target="' + answerId + '"]');
                        const icon = document.getElementById(answerId.replace('answer', 'icon'));
                        
                        if (answer && question && icon) {
                            answer.classList.remove('open');
                            question.classList.remove('active');
                            icon.style.transform = 'rotate(0deg)';
                        }
                    }
                    
                    // Add hover effects for interactive elements
                    const interactiveItems = faqSection.querySelectorAll('.' + prefix + 'category-tag, .' . $prefix . 'job-type-card, .' . $prefix . 'service-item');
                    interactiveItems.forEach(item => {
                        item.addEventListener('mouseenter', () => {
                            item.style.transform = 'translateY(-3px)';
                        });
                        
                        item.addEventListener('mouseleave', () => {
                            item.style.transform = 'translateY(0)';
                        });
                    });
                    
                    // Add smooth scrolling for CTA button
                    const ctaButton = faqSection.querySelector('.' . $prefix . 'cta-button');
                    if (ctaButton) {
                        ctaButton.addEventListener('click', function(e) {
                            const href = this.getAttribute('onclick').match(/href='([^']+)'/);
                            if (href && href[1]) {
                                e.preventDefault();
                                const target = document.querySelector(href[1]);
                                if (target) {
                                    target.scrollIntoView({
                                        behavior: 'smooth',
                                        block: 'start'
                                    });
                                }
                            }
                        });
                        
                        ctaButton.addEventListener('mouseenter', () => {
                            ctaButton.style.transform = 'translateY(-5px)';
                            ctaButton.style.boxShadow = '0 15px 35px rgba(255, 215, 0, 0.4)';
                        });
                        
                        ctaButton.addEventListener('mouseleave', () => {
                            if (!ctaButton.classList.contains('active')) {
                                ctaButton.style.transform = 'translateY(0)';
                                ctaButton.style.boxShadow = '0 8px 25px rgba(255, 215, 0, 0.3)';
                            }
                        });
                    }
                    
                })();
            </script>
        </section>
        <?php
        return ob_get_clean();
    }
