            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const cards = document.querySelectorAll('.' + prefix + 'card');
                    const buttons = document.querySelectorAll('.' + prefix + 'button');
                    
                    // Add hover effect for cards
                    cards.forEach(card => {
                        card.addEventListener('mouseenter', function() {
                            this.style.zIndex = '10';
                        });
                        
                        card.addEventListener('mouseleave', function() {
                            this.style.zIndex = '1';
                        });
                    });
                    
                    // Button click tracking
                    buttons.forEach(button => {
                        button.addEventListener('click', function() {
                            const card = this.closest('.' + prefix + 'card');
                            const planName = card.querySelector('h3').textContent;
                            const planPrice = card.querySelector('.' + prefix + 'price').textContent;
                            
                            // Analytics tracking
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'plan_selection',
                                    'plan_name': planName,
                                    'plan_price': planPrice,
                                    'plan_type': 'pricing'
                                });
                            }
                            
                            // Add click animation
                            this.classList.add(prefix + 'button-clicked');
                            setTimeout(() => {
                                this.classList.remove(prefix + 'button-clicked');
                            }, 300);
                            
                            // Add visual feedback
                            const originalText = this.innerHTML;
                            this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Redirecting...';
                            this.disabled = true;
                            
                            setTimeout(() => {
                                this.innerHTML = originalText;
                                this.disabled = false;
                            }, 1500);
                        });
                    });
                    
                    // Plan comparison highlighting
                    const popularCard = document.querySelector('.' + prefix + 'card-popular');
                    if (popularCard) {
                        // Add glow effect to popular card
                        const glow = document.createElement('div');
                        glow.style.cssText = `
                            position: absolute;
                            top: -10px;
                            left: -10px;
                            right: -10px;
                            bottom: -10px;
                            background: linear-gradient(135deg, var(--${prefix}gold-1), var(--${prefix}gold-3));
                            border-radius: 30px;
                            z-index: -1;
                            opacity: 0.1;
                            filter: blur(10px);
                        `;
                        popularCard.style.position = 'relative';
                        popularCard.appendChild(glow);
                        
                        // Pulse animation for popular badge
                        const badge = popularCard.querySelector('.' + prefix + 'popular-badge');
                        if (badge) {
                            badge.style.animation = `${prefix}badge-pulse 2s infinite`;
                        }
                    }
                    
                    // Price formatting animation
                    const prices = document.querySelectorAll('.' + prefix + 'price');
                    prices.forEach(price => {
                        const originalPrice = price.textContent;
                        const numericPrice = originalPrice.replace(/[^0-9]/g, '');
                        
                        // Add Indian number formatting
                        if (numericPrice.length > 3) {
                            const formattedPrice = new Intl.NumberFormat('en-IN').format(numericPrice);
                            price.textContent = '₹' + formattedPrice;
                        }
                    });
                    
                    // Intersection observer for scroll animations
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach((entry, index) => {
                            if (entry.isIntersecting) {
                                setTimeout(() => {
                                    entry.target.style.opacity = '1';
                                    entry.target.style.transform = 'translateY(0)';
                                }, index * 200);
                            }
                        });
                    }, { threshold: 0.1 });
                    
                    cards.forEach((card, index) => {
                        card.style.opacity = '0';
                        card.style.transform = 'translateY(30px)';
                        card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
                        observer.observe(card);
                    });
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    
