                /* Reduced Motion */
                @media (prefers-reduced-motion: reduce) {
                    .<?php echo $prefix; ?>section *,
                    .<?php echo $prefix; ?>section *::before,
                    .<?php echo $prefix; ?>section *::after {
                        animation-duration: 0.01ms !important;
                        animation-iteration-count: 1 !important;
                        transition-duration: 0.01ms !important;
                    }
                    
                    .<?php echo $prefix; ?>button:hover,
                    .<?php echo $prefix; ?>card:hover {
                        transform: none !important;
                    }
                    
                    .<?php echo $prefix; ?>badge,
                    .<?php echo $prefix; ?>discount-badge {
                        animation: none !important;
                    }
