                        </div>
                    </div>

                    <!-- HRM System -->
                    <div class="<?php echo $prefix; ?>card">
                        <div class="<?php echo $prefix; ?>discount-badge">50% OFF</div>
                        <div class="<?php echo $prefix; ?>icon">🏢</div>
                        <h3>HRM System Template</h3>
                        <div class="<?php echo $prefix; ?>price">₹4,999 <del>₹9,999</del></div>
                        <ul class="<?php echo $prefix; ?>features">
                            <li>Complete HR Management System</li>
                            <li>Employee Attendance Tracking</li>
                            <li>Payroll Management Module</li>
                            <li>Employee Self-Service Portal</li>
                            <li>Fully Customizable Code</li>
                        </ul>
                        <button class="<?php echo $prefix; ?>button" data-product="hrm-system" data-price="4999">
                            Buy Now
                        </button>
                        <div class="<?php echo $prefix; ?>product-info">
                            <i class="fas fa-download"></i> Instant Download • <i class="fas fa-code"></i> Customizable
                        </div>
                    </div>
                </div>
            </div>

            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const cards = document.querySelectorAll('.' + prefix + 'card');
                    const buttons = document.querySelectorAll('.' + prefix + 'button');
                    
                    // Add hover effect for cards
                    cards.forEach(card => {
                        card.addEventListener('mouseenter', function() {
                            this.style.zIndex = '10';
                        });
                        
                        card.addEventListener('mouseleave', function() {
                            this.style.zIndex = '1';
                        });
                    });
                    
                    // Button click handling for products
                    buttons.forEach(button => {
                        button.addEventListener('click', function() {
                            const productName = this.closest('.' + prefix + 'card').querySelector('h3').textContent;
                            const productPrice = this.closest('.' + prefix + 'card').querySelector('.' + prefix + 'price').textContent;
                            const productId = this.getAttribute('data-product');
                            
                            // Analytics tracking
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'product_purchase_click',
                                    'product_name': productName,
                                    'product_id': productId,
                                    'product_price': productPrice
                                });
                            }
                            
                            // Add click animation
                            this.classList.add(prefix + 'button-clicked');
                            setTimeout(() => {
                                this.classList.remove(prefix + 'button-clicked');
                            }, 300);
                            
                            // Simulate purchase process
                            const originalText = this.innerHTML;
                            this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
                            this.disabled = true;
                            
                            // Show purchase modal
                            setTimeout(() => {
                                showPurchaseModal(productName, productPrice, productId);
                                this.innerHTML = originalText;
                                this.disabled = false;
                            }, 1000);
                        });
                    });
                    
                    // Purchase modal function
                    function showPurchaseModal(productName, productPrice, productId) {
                        const modal = document.createElement('div');
                        modal.className = prefix + 'purchase-modal';
                        modal.style.cssText = `
                            position: fixed;
                            top: 0;
                            left: 0;
                            right: 0;
                            bottom: 0;
                            background: rgba(10, 26, 47, 0.95);
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            z-index: 10000;
                            opacity: 0;
                            transition: opacity 0.3s ease;
                            backdrop-filter: blur(10px);
                        `;
                        
                        modal.innerHTML = `
                            <div style="
                                background: white;
                                padding: 40px;
                                border-radius: 20px;
                                max-width: 500px;
                                width: 90%;
                                text-align: center;
                                transform: translateY(20px);
                                transition: transform 0.3s ease;
                                position: relative;
                                border: 2px solid var(--${prefix}gold-2);
                                box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
                            ">
                                <button class="${prefix}modal-close" style="
                                    position: absolute;
                                    top: 15px;
                                    right: 15px;
                                    background: none;
                                    border: none;
                                    font-size: 1.5rem;
                                    color: var(--${prefix}navy-700);
                                    cursor: pointer;
                                    width: 30px;
                                    height: 30px;
                                    display: flex;
                                    align-items: center;
                                    justify-content: center;
                                    border-radius: 50%;
                                    transition: all 0.3s ease;
                                ">&times;</button>
                                
                                <div style="margin-bottom: 25px;">
                                    <div style="
                                        font-size: 2rem;
                                        margin-bottom: 15px;
                                        background: linear-gradient(135deg, var(--${prefix}gold-1), var(--${prefix}gold-2));
                                        -webkit-background-clip: text;
                                        -webkit-text-fill-color: transparent;
                                    ">🎉</div>
                                    <h3 style="
                                        color: var(--${prefix}navy-900);
                                        margin-bottom: 15px;
                                        font-size: 1.8rem;
                                    ">Purchase ${productName}</h3>
                                    <p style="
                                        color: var(--${prefix}navy-500);
                                        margin-bottom: 25px;
                                        font-size: 1.1rem;
                                    ">This product would be added to your cart for checkout.</p>
                                </div>
                                
                                <div style="
                                    background: var(--${prefix}gray-100);
                                    padding: 20px;
                                    border-radius: 15px;
                                    margin-bottom: 25px;
                                    text-align: left;
                                ">
                                    <div style="
                                        display: flex;
                                        justify-content: space-between;
                                        margin-bottom: 10px;
                                        font-weight: 600;
                                        color: var(--${prefix}navy-700);
                                    ">
                                        <span>Product:</span>
                                        <span>${productName}</span>
                                    </div>
                                    <div style="
                                        display: flex;
                                        justify-content: space-between;
                                        margin-bottom: 10px;
                                        font-weight: 600;
                                        color: var(--${prefix}navy-700);
                                    ">
                                        <span>Price:</span>
                                        <span style="color: var(--${prefix}gold-3);">${productPrice}</span>
                                    </div>
                                    <div style="
                                        display: flex;
                                        justify-content: space-between;
                                        margin-bottom: 0;
                                        font-weight: 600;
                                        color: var(--${prefix}navy-700);
                                    ">
                                        <span>Delivery:</span>
                                        <span style="color: var(--${prefix}success);">Instant Download</span>
                                    </div>
                                </div>
                                
                                <div style="display: flex; gap: 15px; justify-content: center;">
                                    <button class="${prefix}modal-btn ${prefix}modal-btn-primary" style="
                                        padding: 15px 30px;
                                        background: linear-gradient(135deg, var(--${prefix}gold-1), var(--${prefix}gold-2));
                                        color: var(--${prefix}navy-900);
                                        border: none;
                                        border-radius: 10px;
                                        font-weight: 700;
                                        cursor: pointer;
                                        font-size: 1rem;
                                        transition: all 0.3s ease;
                                    ">Proceed to Checkout</button>
                                    <button class="${prefix}modal-btn" style="
                                        padding: 15px 30px;
                                        background: var(--${prefix}navy-700);
                                        color: white;
                                        border: none;
                                        border-radius: 10px;
                                        font-weight: 700;
                                        cursor: pointer;
                                        font-size: 1rem;
                                        transition: all 0.3s ease;
                                    ">Add to Cart</button>
                                </div>
                            </div>
                        `;
                        
                        document.body.appendChild(modal);
                        
                        // Fade in
                        setTimeout(() => {
                            modal.style.opacity = '1';
                            modal.querySelector('div').style.transform = 'translateY(0)';
                        }, 10);
                        
                        // Close modal handlers
                        const closeBtn = modal.querySelector('.' + prefix + 'modal-close');
                        const modalBtns = modal.querySelectorAll('.' + prefix + 'modal-btn');
                        
                        closeBtn.addEventListener('click', () => removeModal(modal));
                        modal.addEventListener('click', (e) => {
                            if (e.target === modal) removeModal(modal);
                        });
                        
                        modalBtns.forEach(btn => {
                            btn.addEventListener('click', () => {
                                btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
                                btn.disabled = true;
                                
                                setTimeout(() => {
                                    alert('Purchase functionality would be integrated with WooCommerce or other e-commerce system.');
                                    removeModal(modal);
                                }, 1500);
                            });
                        });
                    }
                    
                    function removeModal(modal) {
                        modal.style.opacity = '0';
                        setTimeout(() => {
                            if (modal.parentNode) {
                                modal.parentNode.removeChild(modal);
                            }
                        }, 300);
                    }
                    
                    // Intersection observer for scroll animations
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach((entry, index) => {
                            if (entry.isIntersecting) {
                                setTimeout(() => {
                                    entry.target.style.opacity = '1';
                                    entry.target.style.transform = 'translateY(0)';
                                }, index * 200);
                            }
                        });
                    }, { threshold: 0.1 });
                    
                    cards.forEach((card, index) => {
                        card.style.opacity = '0';
                        card.style.transform = 'translateY(30px)';
                        card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
                        observer.observe(card);
                    });
                    
                    // Price formatting
                    const prices = document.querySelectorAll('.' + prefix + 'price');
                    prices.forEach(price => {
                        const originalText = price.innerHTML;
                        const currentPrice = originalText.split('<')[0];
                        const discountPrice = originalText.split('<del>')[1]?.split('</del>')[0];
                        
                        if (currentPrice && discountPrice) {
                            price.innerHTML = `
                                <span style="display: block; color: var(--${prefix}navy-700);">${currentPrice}</span>
                                <del style="font-size: 1.2rem; color: var(--${prefix}navy-500); opacity: 0.7;">
                                    ${discountPrice}
                                </del>
                            `;
                        }
                    });
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    
