            array('amount' => '₹2,50,000', 'commission' => '₹25,000'),
        );
        
        ob_start();
        ?>
        <section id="<?php echo $prefix; ?>referral" class="<?php echo $prefix; ?>section" aria-labelledby="<?php echo $prefix; ?>heading">
            <style>
                /* Import fonts matching hero shortcode */
                @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Poppins:wght@600;700;800&display=swap');

                :root {
                    --<?php echo $prefix; ?>gold-1: #FFD700;
                    --<?php echo $prefix; ?>gold-2: #FFA500;
                    --<?php echo $prefix; ?>gold-3: #FF8C00;
                    --<?php echo $prefix; ?>gold-light: #FFF9E6;
                    --<?php echo $prefix; ?>navy-900: #0A1A2F;
