            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const section = document.getElementById(prefix + 'referral');
                    const joinButton = document.getElementById(prefix + 'join-button');
                    
                    if (!section) return;
                    
                    // Initialize animations when section is in viewport
                    const initAnimations = () => {
                        const rect = section.getBoundingClientRect();
                        const windowHeight = window.innerHeight || document.documentElement.clientHeight;
                        
                        if (rect.top <= windowHeight - 100) {
                            section.classList.add(prefix + 'loaded');
                            window.removeEventListener('scroll', initAnimations);
                        }
                    };
                    
                    // Initial check
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', () => {
                            setTimeout(initAnimations, 300);
                        });
                    } else {
                        setTimeout(initAnimations, 300);
                    }
                    
                    // Add scroll listener
                    window.addEventListener('scroll', initAnimations, { passive: true });
                    
                    // Join button click handler
                    if (joinButton) {
                        joinButton.addEventListener('click', function(e) {
                            e.preventDefault();
                            
                            // Scroll to contact section
                            const contactSection = document.getElementById('cs_contact') || document.getElementById('contact');
                            if (contactSection) {
                                contactSection.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });
                                
                                // Add referral note to contact form
                                setTimeout(() => {
                                    const contactForm = document.querySelector('#cs_form form, #ictContactForm');
                                    if (contactForm) {
                                        const serviceField = contactForm.querySelector('[name="service"]');
                                        const messageField = contactForm.querySelector('[name="message"]');
                                        
                                        if (serviceField) {
                                            serviceField.value = 'referral';
                                        }
                                        
                                        if (messageField) {
                                            messageField.value = 'I want to join your referral program and become a referral partner. Please send me more details.';
                                            messageField.focus();
                                        }
                                        
                                        // Show a confirmation
                                        const responseDiv = document.querySelector('#cs_response, .ict-form-response');
                                        if (responseDiv) {
                                            responseDiv.innerHTML = `
                                                <div style="background: rgba(255, 215, 0, 0.1); color: #0A1A2F; padding: 15px; border-radius: 10px; border: 1px solid rgba(255, 215, 0, 0.2);">
                                                    <strong>Welcome to our referral program!</strong><br>
                                                    We'll send you the complete referral guide and agreement within 24 hours.
                                                </div>
                                            `;
                                            responseDiv.style.display = 'block';
                                        }
                                    }
                                }, 1000);
                            }
                        });
                    }
                    
                    // Animate numbers in stats
                    const stats = section.querySelectorAll('.' + prefix + 'main-stat-number');
                    stats.forEach(stat => {
                        const originalText = stat.textContent;
                        if (originalText.includes('%') || originalText.includes('K') || originalText.includes('h')) {
                            // Don't animate these
                            return;
                        }
                        
                        // Simple number animation
                        const observer = new IntersectionObserver((entries) => {
                            entries.forEach(entry => {
                                if (entry.isIntersecting) {
                                    const target = parseInt(originalText.replace(/\D/g, ''));
                                    const duration = 1500;
                                    const steps = 60;
                                    const increment = target / steps;
                                    let current = 0;
                                    
                                    const timer = setInterval(() => {
                                        current += increment;
                                        if (current >= target) {
                                            current = target;
                                            clearInterval(timer);
                                        }
                                        stat.textContent = Math.floor(current) + (originalText.includes('K') ? 'K' : '');
                                    }, duration / steps);
                                    
                                    observer.unobserve(stat);
                                }
                            });
                        }, { threshold: 0.5 });
                        
                        observer.observe(stat);
                    });
                    
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    
