                        </div>
                        <div class="<?php echo $prefix; ?>stat-item">
                            <div class="<?php echo $prefix; ?>stat-number">500+</div>
                            <div class="<?php echo $prefix; ?>stat-label">Students Helped</div>
                        </div>
                        <div class="<?php echo $prefix; ?>stat-item">
                            <div class="<?php echo $prefix; ?>stat-number">5+</div>
                            <div class="<?php echo $prefix; ?>stat-label">Years Experience</div>
                        </div>
