            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const grid = document.getElementById(prefix + 'grid');
                    const container = document.querySelector('.' + prefix + 'container');
                    
                    if (!grid || !container) return;
                    
                    // Initialize reveal animation
                    const initReveal = () => {
                        const rect = grid.getBoundingClientRect();
                        const windowHeight = window.innerHeight || document.documentElement.clientHeight;
                        
                        // Check if grid is in viewport (with 150px offset)
                        if (rect.top <= windowHeight - 150) {
                            container.classList.add(prefix + 'appear');
                            window.removeEventListener('scroll', initReveal);
                        }
                    };
                    
                    // Initial check
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', () => {
                            setTimeout(initReveal, 300);
                        });
                    } else {
                        setTimeout(initReveal, 300);
                    }
                    
                    // Add scroll listener
                    window.addEventListener('scroll', initReveal, { passive: true });
                    
                    // Badge hover effect
                    const badges = document.querySelectorAll('.' + prefix + 'badge-card');
                    badges.forEach(badge => {
                        badge.addEventListener('mouseenter', () => {
                            const icon = badge.querySelector('.' + prefix + 'badge-icon');
                            if (icon) {
                                icon.style.transform = 'scale(1.15) rotate(10deg)';
                            }
                        });
                        
                        badge.addEventListener('mouseleave', () => {
                            const icon = badge.querySelector('.' + prefix + 'badge-icon');
                            if (icon) {
                                icon.style.transform = 'scale(1.1) rotate(5deg)';
                            }
                        });
                        
                        // Accessibility - keyboard focus
                        badge.addEventListener('focus', () => {
                            badge.style.transform = 'translateY(-10px)';
                            badge.style.boxShadow = 'var(--' + prefix + 'hover-shadow)';
                        });
                        
                        badge.addEventListener('blur', () => {
                            badge.style.transform = 'translateY(0)';
                            badge.style.boxShadow = 'var(--' + prefix + 'shadow)';
                        });
                    });
                    
                    // Animate numbers in stats
                    const stats = document.querySelectorAll('.' + prefix + 'stat-number');
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                const stat = entry.target;
                                const originalText = stat.textContent;
                                const value = parseInt(originalText.replace(/[^0-9]/g, ''));
                                
                                if (!isNaN(value) && value > 0) {
                                    // Animate number
                                    const duration = 1500;
                                    const steps = 60;
                                    const increment = value / steps;
                                    let current = 0;
                                    
                                    const timer = setInterval(() => {
                                        current += increment;
                                        if (current >= value) {
                                            current = value;
                                            clearInterval(timer);
                                        }
                                        
                                        // Format number
                                        let displayValue = Math.floor(current);
                                        if (originalText.includes('+')) {
                                            displayValue += '+';
                                        }
                                        if (originalText.includes('%')) {
                                            displayValue += '%';
                                        }
                                        
                                        stat.textContent = displayValue;
                                    }, duration / steps);
                                }
                                
                                observer.unobserve(stat);
                            }
                        });
                    }, { threshold: 0.5 });
                    
                    stats.forEach(stat => observer.observe(stat));
                    
                    // Add click tracking for badges
                    badges.forEach(badge => {
                        badge.addEventListener('click', function() {
                            const title = this.querySelector('.' + prefix + 'badge-title')?.textContent || '';
                            
                            // Track in data layer for analytics
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'trust_badge_click',
                                    'badge_title': title,
                                    'section': 'trust_badges'
                                });
                            }
                            
                            // Add click animation
                            this.classList.add(prefix + 'badge-clicked');
                            setTimeout(() => {
                                this.classList.remove(prefix + 'badge-clicked');
                            }, 300);
                        });
                    });
                    
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    
