                    <p class="<?php echo $prefix; ?>cta-subtitle">
                        Get a personalized ROI calculation for your specific needs. Our team will analyze your requirements 
                        and show you exactly how much value our solution will generate for you.
                    </p>
                    <a href="#contact" class="<?php echo $prefix; ?>button" aria-label="Calculate your ROI">
                        <i class="fas fa-calculator"></i>
                        <span>Calculate Your Personalized ROI</span>
                    </a>
                </div>
            </div>

            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const grid = document.getElementById(prefix + 'grid');
                    const container = document.querySelector('.' + prefix + 'container');
                    
                    if (!grid || !container) return;
                    
                    // Initialize reveal animation
                    const initReveal = () => {
                        const rect = grid.getBoundingClientRect();
                        const windowHeight = window.innerHeight || document.documentElement.clientHeight;
                        
                        // Check if grid is in viewport (with 150px offset)
                        if (rect.top <= windowHeight - 150) {
                            container.classList.add(prefix + 'appear');
                            window.removeEventListener('scroll', initReveal);
                        }
                    };
                    
                    // Initial check
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', () => {
                            setTimeout(initReveal, 300);
                        });
                    } else {
                        setTimeout(initReveal, 300);
                    }
                    
                    // Add scroll listener
                    window.addEventListener('scroll', initReveal, { passive: true });
                    
                    // Animate numbers in investment/return sections
                    const animateNumbers = () => {
                        const investmentElements = document.querySelectorAll('.' + prefix + 'investment-amount');
                        const returnElements = document.querySelectorAll('.' + prefix + 'return-amount');
                        
                        const formatCurrency = (text) => {
                            return text.replace(/₹/g, '<span style="font-size:0.8em;margin-right:2px;">₹</span>');
                        };
                        
                        // Animate when element is in viewport
                        const observer = new IntersectionObserver((entries) => {
                            entries.forEach(entry => {
                                if (entry.isIntersecting) {
                                    const element = entry.target;
                                    const originalText = element.textContent;
                                    
                                    // Add subtle animation class
                                    element.classList.add(prefix + 'counting');
                                    
                                    // Format currency symbol
                                    element.innerHTML = formatCurrency(originalText);
                                    
                                    observer.unobserve(element);
                                }
                            });
                        }, { threshold: 0.5 });
                        
                        [...investmentElements, ...returnElements].forEach(el => observer.observe(el));
                    };
                    
                    // Initialize number animation
                    setTimeout(animateNumbers, 500);
                    
                    // Button click tracking
                    const button = document.querySelector('.' + prefix + 'button');
                    if (button) {
                        button.addEventListener('click', function(e) {
                            const href = this.getAttribute('href');
                            if (href === '#') return;
                            
                            e.preventDefault();
                            const target = document.querySelector(href);
                            if (target) {
                                target.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });
                                
                                // Track ROI calculation click
                                if (window.dataLayer) {
                                    window.dataLayer.push({
                                        'event': 'roi_calculation_click',
                                        'section': 'value_proposition'
                                    });
                                }
                            }
                        });
                    }
                    
                    // Card hover effect
                    const cards = document.querySelectorAll('.' + prefix + 'card');
                    cards.forEach(card => {
                        card.addEventListener('mouseenter', function() {
                            const icon = this.querySelector('.' + prefix + 'icon');
                            if (icon) {
                                icon.style.transform = 'scale(1.15) rotate(10deg)';
                            }
                        });
                        
                        card.addEventListener('mouseleave', function() {
                            const icon = this.querySelector('.' + prefix + 'icon');
                            if (icon) {
                                icon.style.transform = 'scale(1.1) rotate(5deg)';
                            }
                        });
                        
                        // Accessibility - keyboard focus
                        card.addEventListener('focus', function() {
                            this.style.transform = 'translateY(-10px)';
                            this.style.boxShadow = 'var(--' + prefix + 'hover-shadow)';
                        });
                        
                        card.addEventListener('blur', function() {
                            this.style.transform = 'translateY(0)';
                            this.style.boxShadow = 'var(--' + prefix + 'shadow)';
                        });
                    });
                    
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
