            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const form = document.getElementById(prefix + 'form');
                    const submitBtn = form.querySelector('.' + prefix + 'submit-btn');
                    const responseDiv = document.getElementById(prefix + 'response');
                    
                    if (!form) return;
                    
                    form.addEventListener('submit', function(e) {
                        e.preventDefault();
                        
                        // Validate form before submission
                        if (!validateForm()) {
                            return;
                        }
                        
                        // Disable submit button
                        submitBtn.disabled = true;
                        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending...';
                        
                        // Clear previous response
                        responseDiv.style.display = 'none';
                        responseDiv.className = prefix + 'form-response';
                        responseDiv.innerHTML = '';
                        
                        // Collect form data
                        const formData = new FormData(form);
                        
                        // Send AJAX request to WordPress
                        fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
                            method: 'POST',
                            body: formData,
                            headers: {
                                'X-Requested-With': 'XMLHttpRequest'
                            }
                        })
                        .then(response => response.json())
                        .then(data => {
                            if (data.success) {
                                // Success response - show WhatsApp button
                                responseDiv.innerHTML = `
                                    <div class="${prefix}response-success">
                                        <p><strong>Thank you! We received your inquiry.</strong></p>
                                        <p>${data.data.message}</p>
                                        <a href="https://wa.me/<?php echo esc_js($whatsapp_number); ?>?text=Hello! I just submitted a contact form on your website. My name is ${encodeURIComponent(formData.get('name'))}" 
                                        target="_blank" 
                                        class="${prefix}whatsapp-button">
                                            <i class="fab fa-whatsapp"></i> Chat on WhatsApp Now
                                        </a>
                                        <p style="margin-top: 10px; font-size: 0.9em; color: var(--${prefix}gray-600);">
                                            We saved your details and will contact you soon via email too.
                                        </p>
                                    </div>
                                `;
                                responseDiv.className = prefix + 'form-response';
                                
                                // Reset form
                                form.reset();
                            } else {
                                // Error response
                                responseDiv.innerHTML = `
                                    <div class="${prefix}response-error">
                                        <p><strong>Error!</strong></p>
                                        <p>${data.message || 'Something went wrong. Please try again.'}</p>
                                    </div>
                                `;
                                responseDiv.className = prefix + 'form-response';
                            }
                            
                            responseDiv.style.display = 'block';
                            
                            // Scroll to response
                            responseDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                            
                            // Hide response after 15 seconds (except for success with WhatsApp button)
                            if (!data.success) {
                                setTimeout(() => {
                                    responseDiv.style.display = 'none';
                                }, 15000);
                            }
                        })
                        .catch(error => {
                            console.error('Error:', error);
                            responseDiv.innerHTML = `
                                <div class="${prefix}response-error">
                                    <p><strong>Network Error</strong></p>
                                    <p>Unable to send message. Please try again or contact us directly.</p>
                                </div>
                            `;
                            responseDiv.className = prefix + 'form-response';
                            responseDiv.style.display = 'block';
                        })
                        .finally(() => {
                            // Re-enable submit button
                            submitBtn.disabled = false;
                            submitBtn.innerHTML = '<i class="fas fa-paper-plane"></i> Get Free Quote';
                        });
                    });
                    
                    // Form validation
                    function validateForm() {
                        let isValid = true;
                        const requiredFields = form.querySelectorAll('[required]');
                        
                        requiredFields.forEach(field => {
                            if (!field.value.trim()) {
                                showFieldError(field, 'This field is required');
                                isValid = false;
                            } else if (field.type === 'email' && !isValidEmail(field.value)) {
                                showFieldError(field, 'Please enter a valid email address');
                                isValid = false;
                            } else {
                                clearFieldError(field);
                            }
                        });
                        
                        return isValid;
                    }
                    
                    function isValidEmail(email) {
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        return emailRegex.test(email);
                    }
                    
                    function showFieldError(field, message) {
                        // Remove existing error
                        clearFieldError(field);
                        
                        // Add error class
                        field.classList.add(prefix + 'input-error');
                        
                        // Create error message
                        const errorDiv = document.createElement('div');
                        errorDiv.className = prefix + 'field-error';
                        errorDiv.textContent = message;
                        
                        field.parentNode.appendChild(errorDiv);
                    }
                    
                    function clearFieldError(field) {
                        field.classList.remove(prefix + 'input-error');
                        
                        const existingError = field.parentNode.querySelector('.' + prefix + 'field-error');
                        if (existingError) {
                            existingError.remove();
                        }
                    }
                    
                    // Clear errors on input
                    const inputs = form.querySelectorAll('.' + prefix + 'form-input, .' + prefix + 'form-select, .' + prefix + 'form-textarea');
                    inputs.forEach(input => {
                        input.addEventListener('input', function() {
                            clearFieldError(this);
                        });
                        
                        input.addEventListener('blur', function() {
                            if (this.hasAttribute('required') && !this.value.trim()) {
                                showFieldError(this, 'This field is required');
                            } else if (this.type === 'email' && this.value && !isValidEmail(this.value)) {
                                showFieldError(this, 'Please enter a valid email address');
                            } else {
                                clearFieldError(this);
                            }
                        });
                    });
                    
                    // Smooth scroll for anchor links
                    const anchorLinks = document.querySelectorAll('a[href="#' + prefix + 'contact"]');
                    anchorLinks.forEach(link => {
                        link.addEventListener('click', function(e) {
                            const target = document.getElementById(prefix + 'contact');
                            if (target) {
                                e.preventDefault();
                                target.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });
                                
                                // Focus on first input after scrolling
                                setTimeout(() => {
                                    const firstInput = form.querySelector('.' + prefix + 'form-input');
                                    if (firstInput) firstInput.focus();
                                }, 1000);
                            }
                        });
                    });
                    
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    public function handle_contact_form() {
        // Verify nonce
        check_ajax_referer('ict_contact_nonce', 'security');
        
        // Get form data
        $name = sanitize_text_field($_POST['name']);
        $email = sanitize_email($_POST['email']);
        $phone = sanitize_text_field($_POST['phone']);
        $service = sanitize_text_field($_POST['service']);
        $budget = sanitize_text_field($_POST['budget']);
        $message = sanitize_textarea_field($_POST['message']);
        
        // Validate required fields
        if (empty($name) || empty($email) || empty($message)) {
            wp_send_json_error(array('message' => 'Please fill in all required fields.'));
        }
        
        // Save to database
        global $wpdb;
        $table_name = $wpdb->prefix . 'ict_contacts';
        
        $result = $wpdb->insert($table_name, array(
            'name' => $name,
            'email' => $email,
            'phone' => $phone,
            'service' => $service,
            'budget' => $budget,
            'message' => $message,
            'status' => 'new',
            'created_at' => current_time('mysql')
        ));
        
        if ($result === false) {
            wp_send_json_error(array('message' => 'Error saving your message. Please try again.'));
        }
        
        // Prepare WhatsApp message
        $whatsapp_msg = urlencode("New Inquiry from Website:

        Name: $name
        Email: $email
        Phone: $phone
        Service: $service
        Budget: $budget

        Message:
        $message

        Website: " . home_url());
        
        $whatsapp_link = 'https://wa.me/919876543210?text=' . $whatsapp_msg;
        
        $response = array(
            'success' => true,
            'data' => array(
                'message' => 'Thank you ' . $name . '! We received your inquiry. For faster response, click below:<br><br>
                             <a href="' . $whatsapp_link . '" target="_blank" 
                                style="background:#25D366; color:white; padding:15px 30px; border-radius:8px; text-decoration:none; display:inline-block; font-size:16px; font-weight:bold;">
                                <i class="fab fa-whatsapp"></i> Chat on WhatsApp Now
                             </a>
                             <br><br><small>We saved your details and will contact you soon via email too.</small>'
            )
        );
        
        wp_send_json($response);
    }
