                        <span aria-hidden="true">&#9658;</span>
                    </button>
                </div>

                <!-- CTA Section -->
                <div class="<?php echo $prefix; ?>cta-section">
                    <a href="#contact" class="<?php echo $prefix; ?>button-cta">
                        <span>Share Your Experience</span>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
                        </svg>
                    </a>
                    
                    <div class="<?php echo $prefix; ?>links">
                        <a href="https://g.page/r/Ce0iL0U7rM2aEBM/review" target="_blank" class="<?php echo $prefix; ?>link">
                            ✨ Leave Google Review
                        </a>
                        <a href="#contact" class="<?php echo $prefix; ?>link">
                            📝 Write Testimonial
                        </a>
                        <a href="#services" class="<?php echo $prefix; ?>link">
                            🚀 Explore Services
                        </a>
                    </div>
                </div>
            </div>

            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const track = document.getElementById(prefix + 'track');
                    const pauseBtn = document.getElementById(prefix + 'pause');
                    const playBtn = document.getElementById(prefix + 'play');
                    const wrapper = document.querySelector('.' + prefix + 'wrapper');

                    if (!track || !pauseBtn || !playBtn) return;

                    // Pause function
                    const pauseCarousel = () => {
                        track.classList.add('paused');
                        pauseBtn.style.display = 'none';
                        playBtn.style.display = 'flex';
                    };

                    // Play function
                    const playCarousel = () => {
                        track.classList.remove('paused');
                        pauseBtn.style.display = 'flex';
                        playBtn.style.display = 'none';
                    };

                    // Initialize
                    document.addEventListener('DOMContentLoaded', () => {
                        // Button events
                        pauseBtn.addEventListener('click', pauseCarousel);
                        playBtn.addEventListener('click', playCarousel);

                        // Pause on hover
                        if (wrapper) {
                            wrapper.addEventListener('mouseenter', pauseCarousel);
                            wrapper.addEventListener('mouseleave', playCarousel);
                            
                            // Touch support
                            wrapper.addEventListener('touchstart', () => {
                                if (track.classList.contains('paused')) {
                                    playCarousel();
                                } else {
                                    pauseCarousel();
                                }
                            }, { passive: true });
                        }

                        // Keyboard support
                        document.addEventListener('keydown', (e) => {
                            if (e.key === 'Escape') {
                                pauseCarousel();
                            }
                            if (e.key === ' ') {
                                e.preventDefault();
                                if (track.classList.contains('paused')) {
                                    playCarousel();
                                } else {
                                    pauseCarousel();
                                }
                            }
                        });

                        // Auto pause after 30 seconds
                        setTimeout(() => {
                            if (!track.classList.contains('paused')) {
                                pauseCarousel();
                                setTimeout(playCarousel, 3000);
                            }
                        }, 30000);
                    });

                    // Click cards to expand
                    const cards = document.querySelectorAll('.' + prefix + 'card');
                    cards.forEach(card => {
                        card.addEventListener('click', function() {
                            this.classList.toggle(prefix + 'card-expanded');
                        });
                        
                        // Accessibility
                        card.addEventListener('keydown', (e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                card.click();
                            }
                        });
                    });

                })();
            </script>
        </section>
        <?php

        return ob_get_clean();
    }

