            <script>
                (function() {
                    const prefix = '<?php echo $prefix; ?>';
                    const section = document.getElementById(prefix + 'section');
                    const particlesContainer = document.getElementById(prefix + 'particles');
                    
                    if (!section || !particlesContainer) return;
                    
                    // Create floating particles
                    function createParticles() {
                        const particleCount = 20;
                        
                        for (let i = 0; i < particleCount; i++) {
                            const particle = document.createElement('div');
                            particle.className = prefix + 'particle';
                            
                            // Random position
                            particle.style.left = Math.random() * 100 + '%';
                            particle.style.top = Math.random() * 100 + '%';
                            
                            // Random size
                            const size = 2 + Math.random() * 6;
                            particle.style.width = size + 'px';
                            particle.style.height = size + 'px';
                            
                            // Random opacity
                            particle.style.opacity = 0.3 + Math.random() * 0.7;
                            
                            // Random animation delay and duration
                            const delay = Math.random() * 20;
                            const duration = 15 + Math.random() * 25;
                            particle.style.animationDelay = delay + 's';
                            particle.style.animationDuration = duration + 's';
                            
                            particlesContainer.appendChild(particle);
                        }
                    }
                    
                    // Initialize animations when section is in viewport
                    const initAnimations = () => {
                        const rect = section.getBoundingClientRect();
                        const windowHeight = window.innerHeight || document.documentElement.clientHeight;
                        
                        if (rect.top <= windowHeight - 100) {
                            section.classList.add(prefix + 'loaded');
                            createParticles();
                            window.removeEventListener('scroll', initAnimations);
                        }
                    };
                    
                    // Initial check
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', () => {
                            setTimeout(initAnimations, 300);
                        });
                    } else {
                        setTimeout(initAnimations, 300);
                    }
                    
                    // Add scroll listener
                    window.addEventListener('scroll', initAnimations, { passive: true });
                    
                    // Button click tracking
                    const buttons = document.querySelectorAll('.' + prefix + 'button');
                    buttons.forEach(button => {
                        button.addEventListener('click', function() {
                            const buttonText = this.querySelector('span')?.textContent || this.textContent;
                            
                            // Track in data layer for analytics
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'cta_click',
                                    'cta_type': buttonText,
                                    'section': 'call_to_action'
                                });
                            }
                            
                            // Add click animation
                            this.classList.add(prefix + 'button-clicked');
                            setTimeout(() => {
                                this.classList.remove(prefix + 'button-clicked');
                            }, 300);
                        });
                    });
                    
                    // Smooth scroll for contact button
                    const contactButton = document.querySelector('.' + prefix + 'button-primary');
                    if (contactButton) {
                        contactButton.addEventListener('click', function(e) {
                            const href = this.getAttribute('href');
                            if (href === '#') return;
                            
                            e.preventDefault();
                            const target = document.querySelector(href);
                            if (target) {
                                target.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });
                            }
                        });
                    }
                    
                    // Number animation for stats
                    const stats = section.querySelectorAll('.' + prefix + 'stat-number');
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                const stat = entry.target;
                                const originalText = stat.textContent;
                                const value = parseInt(originalText.replace(/[^0-9]/g, ''));
                                
                                if (!isNaN(value) && value > 0) {
                                    // Animate number
                                    const duration = 2000;
                                    const steps = 60;
                                    const increment = value / steps;
                                    let current = 0;
                                    
                                    const timer = setInterval(() => {
                                        current += increment;
                                        if (current >= value) {
                                            current = value;
                                            clearInterval(timer);
                                        }
                                        
                                        // Format number
                                        let displayValue = Math.floor(current);
                                        if (originalText.includes('+')) {
                                            displayValue += '+';
                                        }
                                        if (originalText.includes('L')) {
                                            displayValue = (displayValue / 100000) + 'L+';
                                        }
                                        
                                        stat.textContent = displayValue;
                                    }, duration / steps);
                                }
                                
                                observer.unobserve(stat);
                            }
                        });
                    }, { threshold: 0.5 });
                    
                    stats.forEach(stat => observer.observe(stat));
                    
                })();
            </script>
        </section>
        <?php
        
        return ob_get_clean();
    }
    
