                    window.addEventListener('scroll', function() {
                        if (window.scrollY > 300) {
                            backToTopBtn.style.display = 'flex';
                        } else {
                            backToTopBtn.style.display = 'none';
                        }
                    });
                    
                    backToTopBtn.addEventListener('click', function() {
                        window.scrollTo({
                            top: 0,
                            behavior: 'smooth'
                        });
                    });
                    
                    // Smooth scroll for anchor links
                    document.querySelectorAll('.' + prefix + 'links a[href^="#"]').forEach(anchor => {
                        anchor.addEventListener('click', function(e) {
                            const href = this.getAttribute('href');
                            if (href === '#' || href === '') return;
                            
                            const target = document.querySelector(href);
                            if (target) {
                                e.preventDefault();
                                target.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });
                            }
                        });
                    });
                    
                    // Social media share tracking
                    document.querySelectorAll('.' + prefix + 'social-link').forEach(link => {
                        link.addEventListener('click', function() {
                            const platform = this.classList.contains('facebook') ? 'facebook' :
                                            this.classList.contains('twitter') ? 'twitter' :
                                            this.classList.contains('linkedin') ? 'linkedin' : 'instagram';
                            
                            if (window.dataLayer) {
                                window.dataLayer.push({
                                    'event': 'social_click',
                                    'platform': platform,
                                    'section': 'footer'
                                });
                            }
                        });
                    });
                    
                    // Animation for elements when they come into view
                    const observer = new IntersectionObserver((entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                entry.target.style.opacity = '1';
                                entry.target.style.transform = 'translateY(0)';
                            }
                        });
                    }, { threshold: 0.1 });
                    
                    // Animate columns on scroll
                    const columns = document.querySelectorAll('.' + prefix + 'column');
                    columns.forEach((column, index) => {
                        column.style.opacity = '0';
                        column.style.transform = 'translateY(20px)';
                        column.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
                        observer.observe(column);
                    });
                })();
            </script>
        </footer>
