        <script>
            var ict_job_ajax = {
                ajax_url: '<?php echo admin_url("admin-ajax.php"); ?>',
                nonce: '<?php echo wp_create_nonce("ict_job_nonce"); ?>'
            };
            
            const categoryFromUrl = "<?php echo esc_js($category_from_url ?? ''); ?>";
            
            document.addEventListener("DOMContentLoaded", function() {
                // Initialize elements
                const categorySelect = document.getElementById("ict-job-category");
                const experienceSelect = document.getElementById("ict-job-experience");
                const locationSelect = document.getElementById("ict-job-location");
                const searchButton = document.getElementById("ict-job-search");
                const searchInput = document.getElementById("ict-job-search-input");
                const jobList = document.getElementById("ict-job-list");
                const pagination = document.getElementById("ict-pagination");
                const searchForm = document.getElementById("ict-job-search-form");
                
                // Set category from URL if present
                if (categoryFromUrl) {
                    categorySelect.value = categoryFromUrl.toUpperCase();
                }
                
                let isLoading = false;
                let currentPage = 1;
                const jobsPerPage = 12;
                let allJobs = [];
                let filteredJobs = [];
                
                // Initialize job portal
                function initializeJobPortal() {
                    // Initial load
                    fetchJobs();
                    
                    // Search form submission
                    searchForm.addEventListener("submit", function(e) {
                        e.preventDefault();
                        currentPage = 1;
                        fetchJobs();
                    });
                    
                    // Search button click
                    searchButton.addEventListener("click", function() {
                        currentPage = 1;
                        fetchJobs();
                    });
                    
                    // Enter key in search input
                    searchInput.addEventListener("keypress", function(e) {
                        if (e.key === 'Enter') {
                            currentPage = 1;
                            fetchJobs();
                        }
                    });
                    
                    // Filter change events
                    [categorySelect, experienceSelect, locationSelect].forEach(select => {
                        select.addEventListener("change", function() {
                            currentPage = 1;
                            fetchJobs();
                        });
                    });
                    
                    // Quick links
                    document.querySelectorAll('.ict-quick-link[data-filter]').forEach(link => {
                        link.addEventListener('click', function(e) {
                            e.preventDefault();
                            const filter = this.getAttribute('data-filter');
                            const value = this.getAttribute('data-value');
                            
                            if (filter === 'category') {
                                categorySelect.value = value;
                                currentPage = 1;
                                fetchJobs();
                            }
                        });
                    });
                }
                
                // Fetch jobs via AJAX
                async function fetchJobs() {
                    if (isLoading) return;
                    
                    const category = categorySelect.value;
                    const experience = experienceSelect.value;
                    const location = locationSelect.value;
                    const searchQuery = searchInput.value.trim();
                    
                    isLoading = true;
                    
                    // Show loading state
                    jobList.innerHTML = `
                        <div class="ict-job-loading">
                            <div style="margin-bottom: 25px;">
                                <i class="fas fa-spinner fa-spin fa-3x" style="color: var(--navy-dark);"></i>
                            </div>
                            <h3 style="color: var(--navy-dark); margin-bottom: 15px;">Searching Job Opportunities...</h3>
                            <p style="color: var(--navy-medium); max-width: 600px; margin: 0 auto;">
                                Searching for "${searchQuery || category || 'all'}" jobs with ${experience} experience in ${location}
                            </p>
                        </div>
                    `;
                    
                    // Show loading animation on button
                    searchButton.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Searching...';
                    searchButton.disabled = true;
                    
                    try {
                        const formData = new FormData();
                        formData.append("action", "fetch_jobs");
                        formData.append("category", category);
                        formData.append("experience", experience);
                        formData.append("location", location);
                        formData.append("search", searchQuery);
                        formData.append("nonce", ict_job_ajax.nonce);
                        
                        const response = await fetch(ict_job_ajax.ajax_url, {
                            method: "POST",
                            body: formData
                        });
                        
                        const jobs = await response.json();
                        isLoading = false;
                        searchButton.innerHTML = '<i class="fas fa-search"></i> Search Jobs';
                        searchButton.disabled = false;
                        
                        if (jobs && Array.isArray(jobs) && jobs.length > 0) {
                            allJobs = jobs;
                            applySearchFilter(searchQuery);
                        } else {
                            showNoJobsMessage(searchQuery, category, experience, location);
                        }
                    } catch (error) {
                        console.error("Job search error:", error);
                        isLoading = false;
                        searchButton.innerHTML = '<i class="fas fa-search"></i> Search Jobs';
                        searchButton.disabled = false;
                        
                        jobList.innerHTML = `
                            <div class="ict-job-empty">
                                <i class="fas fa-exclamation-triangle"></i>
                                <h3>Connection Error</h3>
                                <p>Unable to fetch jobs at the moment.</p>
                                <button onclick="fetchJobs()" class="ict-view-details" style="margin-top: 20px; width: auto;">
                                    <i class="fas fa-redo"></i> Retry
                                </button>
                            </div>
                        `;
                        
                        resetStats();
                        pagination.style.display = 'none';
                    }
                }
                
                // Show no jobs message
                function showNoJobsMessage(searchQuery, category, experience, location) {
                    jobList.innerHTML = `
                        <div class="ict-job-empty">
                            <i class="fas fa-search"></i>
                            <h3>No Jobs Found</h3>
                            <p>No job listings found for "${searchQuery || category}" with ${experience} experience in ${location}.</p>
                            <p style="font-size: 0.9rem; margin-top: 10px;">Try different filters or check back later.</p>
                            <button onclick="resetFilters()" class="ict-view-details" style="margin-top: 20px; width: auto;">
                                <i class="fas fa-redo"></i> Reset Filters
                            </button>
                        </div>
                    `;
                    
                    resetStats();
                    pagination.style.display = 'none';
                }
                
                // Reset filters
                window.resetFilters = function() {
                    categorySelect.value = '';
                    experienceSelect.value = 'all';
                    locationSelect.value = 'all';
                    searchInput.value = '';
                    currentPage = 1;
                    fetchJobs();
                };
                
                // Apply search filter
                function applySearchFilter(searchQuery) {
                    if (!searchQuery) {
                        filteredJobs = allJobs;
                    } else {
                        filteredJobs = allJobs.filter(job => {
                            const searchText = searchQuery.toLowerCase();
                            return (
                                (job.title && job.title.toLowerCase().includes(searchText)) ||
                                (job.company && job.company.toLowerCase().includes(searchText)) ||
                                (job.skills && job.skills.some(skill => skill.toLowerCase().includes(searchText))) ||
                                (job.category && job.category.toLowerCase().includes(searchText)) ||
                                (job.location && job.location.toLowerCase().includes(searchText))
                            );
                        });
                    }
                    
                    displayJobs();
                    updateJobStats(filteredJobs);
                }
                
                // Display jobs with pagination
                function displayJobs() {
                    const startIndex = (currentPage - 1) * jobsPerPage;
                    const endIndex = startIndex + jobsPerPage;
                    const jobsToShow = filteredJobs.slice(startIndex, endIndex);
                    const totalPages = Math.ceil(filteredJobs.length / jobsPerPage);
                    
                    if (jobsToShow.length === 0) {
                        jobList.innerHTML = `
                            <div class="ict-job-empty">
                                <i class="fas fa-search"></i>
                                <h3>No Matching Jobs</h3>
                                <p>Try adjusting your search criteria.</p>
                            </div>
                        `;
                        pagination.style.display = 'none';
                        return;
                    }
                    
                    let jobsHTML = '';
                    
                    jobsToShow.forEach((job, index) => {
                        const isFeatured = index < 3;
                        const isRemote = job.work_mode && job.work_mode.toLowerCase() === 'remote';
                        const isNew = job.posted && (job.posted.includes('hour') || job.posted.includes('today') || job.posted.includes('minute') || job.posted.includes('just'));
                        
                        // Determine badge
                        let badgeHTML = '';
                        if (isFeatured) {
                            badgeHTML = '<span class="ict-job-badge">Featured</span>';
                        } else if (isRemote) {
                            badgeHTML = '<span class="ict-job-badge">Remote</span>';
                        } else if (isNew) {
                            badgeHTML = '<span class="ict-job-badge">New</span>';
                        }
                        
                        // Skills HTML
                        let skillsHTML = '';
                        if (job.skills && Array.isArray(job.skills)) {
                            skillsHTML = `
                                <div class="ict-job-skills">
                                    ${job.skills.slice(0, 4).map(skill => `<span class="ict-skill-tag">${skill}</span>`).join('')}
                                    ${job.skills.length > 4 ? `<span class="ict-skill-tag">+${job.skills.length - 4} more</span>` : ''}
                                </div>
                            `;
                        }
                        
                        jobsHTML += `
                            <div class="ict-job-card ${isFeatured ? 'featured' : ''}">
                                ${badgeHTML}
                                <h3 class="ict-job-title">${job.title || 'Job Opening'}</h3>
                                <div class="ict-job-company">
                                    <i class="fas fa-building"></i> ${job.company || 'Company'}
                                </div>
                                <div class="ict-job-details">
                                    <div class="ict-job-detail">
                                        <i class="fas fa-map-marker-alt"></i>
                                        <span>${job.location || 'Location not specified'}</span>
                                    </div>
                                    <div class="ict-job-detail">
                                        <i class="fas fa-clock"></i>
                                        <span>${job.posted || 'Recently'}</span>
                                    </div>
                                    <div class="ict-job-detail">
                                        <i class="fas fa-chart-line"></i>
                                        <span>${job.experience || 'Experience not specified'}</span>
                                    </div>
                                    <div class="ict-job-detail">
                                        <i class="fas fa-briefcase"></i>
                                        <span>${job.work_mode || 'Work Mode'}</span>
                                    </div>
                                </div>
                                ${skillsHTML}
                                ${job.salary ? `<div class="ict-job-salary">${job.salary}</div>` : ''}
                                <div class="ict-job-actions">
                                    <a href="/job/${job.slug}/" class="ict-view-details">
                                        <i class="fas fa-eye"></i> View Details
                                    </a>
                                </div>
                            </div>
                        `;
                    });
                    
                    jobList.innerHTML = jobsHTML;
                    
                    // Generate pagination
                    if (totalPages > 1) {
                        let paginationHTML = '';
                        
                        // Previous button
                        if (currentPage > 1) {
                            paginationHTML += `<button class="ict-page-btn" onclick="changePage(${currentPage - 1})" aria-label="Previous page">
                                <i class="fas fa-chevron-left"></i>
                            </button>`;
                        }
                        
                        // Page numbers
                        const maxPagesToShow = 5;
                        let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
                        let endPage = Math.min(totalPages, startPage + maxPagesToShow - 1);
                        
                        if (endPage - startPage + 1 < maxPagesToShow) {
                            startPage = Math.max(1, endPage - maxPagesToShow + 1);
                        }
                        
                        for (let i = startPage; i <= endPage; i++) {
                            paginationHTML += `
                                <button class="ict-page-btn ${i === currentPage ? 'active' : ''}" onclick="changePage(${i})" aria-label="Page ${i}">
                                    ${i}
                                </button>
                            `;
                        }
                        
                        // Next button
                        if (currentPage < totalPages) {
                            paginationHTML += `<button class="ict-page-btn" onclick="changePage(${currentPage + 1})" aria-label="Next page">
                                <i class="fas fa-chevron-right"></i>
                            </button>`;
                        }
                        
                        pagination.innerHTML = paginationHTML;
                        pagination.style.display = 'flex';
                    } else {
                        pagination.style.display = 'none';
                    }
                }
                
                // Change page
                window.changePage = function(page) {
                    currentPage = page;
                    displayJobs();
                    window.scrollTo({ top: jobList.offsetTop - 100, behavior: 'smooth' });
                };
                
                // Update job statistics
                function updateJobStats(jobs) {
                    const totalJobs = jobs.length;
                    const todayJobs = jobs.filter(job => 
                        job.posted && (
                            job.posted.includes('hour') || 
                            job.posted.includes('today') || 
                            job.posted.includes('minute') ||
                            job.posted.includes('just')
                        )
                    ).length;
                    
                    const remoteJobs = jobs.filter(job => 
                        job.work_mode && job.work_mode.toLowerCase() === 'remote'
                    ).length;
                    
                    const fresherJobs = jobs.filter(job => 
                        job.experience && job.experience.toLowerCase().includes('fresher')
                    ).length;
                    
                    document.getElementById('ict-total-jobs').textContent = totalJobs.toLocaleString();
                    document.getElementById('ict-new-today').textContent = "15+";
                    document.getElementById('ict-remote-jobs').textContent = remoteJobs.toLocaleString();
                    document.getElementById('ict-fresher-jobs').textContent = fresherJobs.toLocaleString();
                }
                
                // Reset stats
                function resetStats() {
                    document.getElementById('ict-total-jobs').textContent = '0';
                    document.getElementById('ict-new-today').textContent = '15+';
                    document.getElementById('ict-remote-jobs').textContent = '0';
                    document.getElementById('ict-fresher-jobs').textContent = '0';
                }
                
                // Make fetchJobs available globally for retry button
                window.fetchJobs = fetchJobs;
                
                // Initialize on load
                initializeJobPortal();
            });
        </script>
        
        <?php
        return ob_get_clean();
    }
    public function fetch_jobs_ajax_handler() {
        if (!wp_verify_nonce($_POST['nonce'], 'ict_job_nonce')) {
            wp_die('Security check failed');
        }
        
        $category = sanitize_text_field($_POST['category'] ?? 'all');
        $experience = sanitize_text_field($_POST['experience'] ?? 'all');
        $location = sanitize_text_field($_POST['location'] ?? 'all');
        $search_query = sanitize_text_field($_POST['search'] ?? '');
        global $wpdb;

        $table = $wpdb->prefix . 'ict_jobs';

        $where = [
            "status = 'publish'",
            "work_mode = 'remote'"
        ];

        $params = [];

        if (!empty($category)) {
            $where[] = "category = %s";
            $params[] = $category;
        }

        if ($experience !== 'all' && $experience !== '') {
            $where[] = "experience LIKE %s";
            $params[] = '%' . $wpdb->esc_like($experience) . '%';
        }

        if ($location !== 'all' && $location !== '') {
            $where[] = "location LIKE %s";
            $params[] = '%' . $wpdb->esc_like($location) . '%';
        }
        if (!empty($search_query)) {
            $where[] = "(title LIKE %s OR company LIKE %s)";
            $params[] = '%' . $wpdb->esc_like($search_query) . '%';
            $params[] = '%' . $wpdb->esc_like($search_query) . '%';
        }
        $sql = "
            SELECT * FROM $table
            WHERE " . implode(' AND ', $where) . "
            ORDER BY created_at DESC
            LIMIT 50
        ";

        $jobs = $wpdb->get_results(
            $wpdb->prepare($sql, $params)
        );    
        wp_send_json($jobs);
    }
    // Add this method to your existing class
    public function ict_ads_placement() {

        if (get_option('ict_enable_ads') !== 'yes') return '';
        if (get_option('ict_job_ads') !== 'yes') return '';

        $code = get_option('ict_adsense_code');
        if (!$code) return '';

        return '
        <div class="ict-ads-container" style="
            width:100%;
            max-width:100%;
            min-height:120px;
            margin:0 auto;
            padding:16px;
            background:linear-gradient(135deg, rgba(26,35,126,0.04), rgba(255,215,0,0.04));
            border:1px solid rgba(26,35,126,0.15);
            border-radius:12px;
            box-sizing:border-box;
            overflow:hidden;
            display:flex;
            align-items:center;
            justify-content:center;
            position:relative;
        ">
            <div style="
                width:100%;
                max-width:100%;
                overflow:hidden;
                display:flex;
                justify-content:center;
            ">
                ' . $code . '
            </div>
        </div>';
    }
    public function enqueue_jquery_properly() {
        // Deregister any existing jQuery
        wp_deregister_script('jquery');
        wp_deregister_script('jquery-core');
        wp_deregister_script('jquery-migrate');
        
        // Register and enqueue jQuery from WordPress core (in header)
        wp_register_script('jquery', includes_url('/js/jquery/jquery.js'), array(), '3.7.1', true);
        wp_register_script('jquery-migrate', includes_url('/js/jquery/jquery-migrate.min.js'), array('jquery'), '3.4.1', true);
        
        wp_enqueue_script('jquery');
        wp_enqueue_script('jquery-migrate');
        
        // Create the AJAX object for our script
        wp_add_inline_script('jquery', '
            window.ict_scraped_wfh = {
                ajax_url: "' . admin_url('admin-ajax.php') . '",
                nonce: "' . wp_create_nonce('ict_scraped_wfh_nonce') . '"
            };
        ', 'before');
    }
