        <script>
            document.addEventListener('DOMContentLoaded', function() {
                // Check if jQuery is available
                if (typeof jQuery === 'undefined') {
                    console.error('jQuery is not loaded. Please wait...');
                    setTimeout(function() {
                        if (typeof jQuery !== 'undefined') {
                            initWFHJobs();
                        } else {
                            showJQueryError();
                        }
                    }, 1000);
                } else {
                    initWFHJobs();
                }
                
                function initWFHJobs() {
                    var $ = jQuery;
                    
                    // Local config
                    var ict_wfh_config = {
                        ajax_url: '<?php echo $ajax_url; ?>',
                        nonce: '<?php echo $ajax_nonce; ?>'
                    };
                    
                    // Fetch jobs
                    function fetchWFHJobs() {
                        $('#ict-wfh-job-list').html(`
                            <div class="wfh-loading">
                                <i class="fas fa-sync-alt fa-spin fa-3x loading-spinner"></i>
                                <h3 style="color: #0a192f; margin: 15px 0;">Fetching Latest Jobs...</h3>
                                <p style="color: #666; max-width: 400px; margin: 0 auto;">Searching through 1000+ remote opportunities</p>
                            </div>
                        `);
                        
                        $.ajax({
                            url: ict_wfh_config.ajax_url,
                            type: 'POST',
                            data: {
                                action: 'fetch_wfh_jobs',
                                nonce: ict_wfh_config.nonce
                            },
                            success: function(response) {
                                if (response.success && response.data.jobs) {
                                    displayWFHJobs(response.data.jobs);
                                    updateWFHStats(response.data.stats);
                                    updateTime(response.data.last_update);
                                } else {
                                    showError('Failed to load jobs. Please try again.');
                                }
                            },
                            error: function(xhr, status, error) {
                                console.error('AJAX Error:', error);
                                showError('Network error. Please check your connection and try again.');
                            }
                        });
                    }
                    
                    function displayWFHJobs(jobs) {
                        if (!jobs || jobs.length === 0) {
                            $('#ict-wfh-job-list').html(`
                                <div class="wfh-error">
                                    <i class="fas fa-search fa-3x" style="color: #ccc; margin-bottom: 20px;"></i>
                                    <h3 style="color: #666;">No Work From Home Jobs Found</h3>
                                    <p style="color: #888; max-width: 400px; margin: 10px auto 25px;">
                                        No remote jobs are currently available. Try refreshing in a few minutes.
                                    </p>
                                    <button onclick="fetchWFHJobs()" class="error-retry-btn">
                                        Search Again
                                    </button>
                                </div>
                            `);
                            return;
                        }
                        
                        let jobsHTML = '';
                        
                        jobs.forEach(job => {
                            // Get icon based on source
                            let sourceIcon = 'fas fa-briefcase';
                            let sourceColor = '#0a192f';
                            if (job.source === 'LinkedIn') {
                                sourceIcon = 'fab fa-linkedin';
                                sourceColor = '#0077B5';
                            } else if (job.source === 'RemoteOK') {
                                sourceIcon = 'fas fa-globe';
                                sourceColor = '#2E7D32';
                            } else if (job.source === 'Indeed') {
                                sourceIcon = 'fas fa-search';
                                sourceColor = '#EF6C00';
                            }
                            
                            jobsHTML += `
                                <div class="wfh-job-card">
                                    <div class="job-source-badge">
                                        <i class="${sourceIcon}" style="margin-right: 5px; color: ${sourceColor};"></i>
                                        ${job.source}
                                    </div>
                                    <h3 class="job-title">${job.title}</h3>
                                    <div class="job-company">
                                        <i class="fas fa-building" style="color: #FFD700;"></i>
                                        ${job.company}
                                    </div>
                                    <div class="job-location">
                                        <i class="fas fa-map-marker-alt" style="color: #666;"></i>
                                        ${job.location}
                                    </div>
                                    <div class="job-salary">
                                        <i class="fas fa-money-bill-wave" style="margin-right: 8px;"></i>
                                        ${job.salary}
                                    </div>
                                    <p class="job-description">
                                        ${job.description.substring(0, 120)}...
                                    </p>
                                    <a href="${job.link}" target="_blank" rel="nofollow noopener" class="job-apply-btn">
                                        <i class="fas fa-external-link-alt"></i> Apply Now
                                    </a>
                                </div>
                            `;
                        });
                        
                        $('#ict-wfh-job-list').html(jobsHTML);
                    }
                    
                    function updateWFHStats(stats) {
                        // Animate numbers
                        function animateValue(element, start, end, duration) {
                            if (start === end) return;
                            var range = end - start;
                            var current = start;
                            var increment = end > start ? 1 : -1;
                            var stepTime = Math.abs(Math.floor(duration / range));
                            var timer = setInterval(function() {
                                current += increment;
                                element.textContent = current;
                                if (current === end) {
                                    clearInterval(timer);
                                }
                            }, stepTime);
                        }
                        
                        // Animate each stat
                        animateValue(document.getElementById('ict-wfh-total'), 0, stats.total || 0, 1000);
                        animateValue(document.getElementById('ict-wfh-linkedin'), 0, stats.linkedin || 0, 1000);
                        animateValue(document.getElementById('ict-wfh-remoteok'), 0, stats.remoteok || 0, 1000);
                        animateValue(document.getElementById('ict-wfh-new'), 0, stats.new_today || 0, 1000);
                    }
                    
                    function updateTime(timestamp) {
                        const now = new Date();
                        const timeString = now.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                        $('#ict-wfh-update').text(`Last updated: ${timeString}`);
                    }
                    
                    function showError(message) {
                        $('#ict-wfh-job-list').html(`
                            <div class="wfh-error">
                                <i class="fas fa-exclamation-triangle fa-3x" style="color: #ff6b6b; margin-bottom: 20px;"></i>
                                <h3 style="color: #666;">Error Loading Jobs</h3>
                                <p style="color: #888; max-width: 400px; margin: 10px auto 25px;">
                                    ${message}
                                </p>
                                <button onclick="fetchWFHJobs()" class="error-retry-btn">
                                    <i class="fas fa-redo"></i> Try Again
                                </button>
                            </div>
                        `);
                    }
                    
                    function showJQueryError() {
                        $('#ict-wfh-job-list').html(`
                            <div class="wfh-error">
                                <i class="fas fa-plug fa-3x" style="color: #ff6b6b; margin-bottom: 20px;"></i>
                                <h3 style="color: #666;">Script Error</h3>
                                <p style="color: #888; max-width: 400px; margin: 10px auto 25px;">
                                    jQuery is required but not loaded. Please refresh the page.
                                </p>
                                <button onclick="location.reload()" class="error-retry-btn">
                                    <i class="fas fa-sync-alt"></i> Refresh Page
                                </button>
                            </div>
                        `);
                    }
                    
                    // Initial fetch
                    fetchWFHJobs();
                    
                    // Refresh button
                    $('#ict-wfh-refresh').click(function() {
                        var $btn = $(this);
                        $btn.html('<i class="fas fa-spinner fa-spin"></i> Refreshing...');
                        $btn.prop('disabled', true);
                        
                        fetchWFHJobs();
                        
                        setTimeout(() => {
                            $btn.html('<i class="fas fa-redo"></i> Refresh Jobs');
                            $btn.prop('disabled', false);
                        }, 1500);
                    });
                    
                    // Make function available globally
                    window.fetchWFHJobs = fetchWFHJobs;
                }
            });
        </script>
        
        <?php
        return ob_get_clean();
    }
    public function fetch_wfh_jobs_ajax() {
        // Check nonce
        if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ict_wfh_jobs_nonce')) {
            wp_send_json_error('Invalid security token');
            return;
        }
        
        $category = sanitize_text_field($_POST["category"] ?? 'all');

        $experience = sanitize_text_field($_POST["experience"] ?? 'all');
        $location = sanitize_text_field($_POST["location"] ?? 'Remote');
        
        // Get jobs from multiple sources
        $all_jobs = [];
        
        // 1. Get LinkedIn jobs (work from home specific)
        $linkedin_jobs = $this->fetch_linkedin_wfh_jobs($category, $experience,$location);
        error_log('Linkedin count: ' . count($linkedin_jobs));
        // 2. Get RemoteOK jobs
        $remoteok_jobs = $this->fetch_remoteok_wfh_jobs();
        
        // 3. Get Indeed jobs (work from home)
        $indeed_jobs = $this->fetch_indeed_wfh_jobs();
        $remotive_jobs = $this->fetch_remotive_wfh_jobs($category, $experience);
        error_log('Remotive count: ' . count($remotive_jobs));

        $arbeitnow_jobs = $this->fetch_arbeitnow_jobs($category, $experience);
        error_log('Arbeitnow count: ' . count($arbeitnow_jobs));
        // Combine all jobs
        $all_jobs = array_merge($linkedin_jobs, $remoteok_jobs, $indeed_jobs,$remotive_jobs,$arbeitnow_jobs);
        
        // Remove duplicates
        $unique_jobs = [];
        $seen = [];
        
        foreach ($all_jobs as $job) {
            $key = md5(strtolower($job['title'] . $job['company']));
            if (!isset($seen[$key])) {
                $seen[$key] = true;
                $unique_jobs[] = $job;
            }
        }
        
        // Sort by recency
        usort($unique_jobs, function($a, $b) {
            $a_recency = $this->get_recency_score($a["posted"]);
            $b_recency = $this->get_recency_score($b["posted"]);
            return $b_recency - $a_recency;
        });
        
        // Limit to 30 jobs
        $unique_jobs = array_slice($unique_jobs, 0, 40);
        
        // Calculate statistics
        $stats = [
            'total' => count($unique_jobs),
            'linkedin' => count($linkedin_jobs),
            'remoteok' => count($remoteok_jobs),
            'indeed' => count($indeed_jobs),
            'new_today' => count(array_filter($unique_jobs, function($job) {
                return stripos($job['posted'], 'hour') !== false || 
                    stripos($job['posted'], 'today') !== false ||
                    stripos($job['posted'], 'minute') !== false ||
                    stripos($job['posted'], 'just') !== false;
            }))
        ];
        
        wp_send_json_success([
            'jobs' => $unique_jobs,
            'stats' => $stats,
            'last_update' => current_time('mysql')
        ]);
    }

    private function fetch_linkedin_wfh_jobs($category, $experience, $location = 'all') {
        global $wpdb;

        $table = $wpdb->prefix . 'ict_jobs';

        $where = [
            "status = 'publish'",
            "work_mode = 'remote'"
        ];

        $params = [];

        if ($category !== 'all' && $category !== '') {
            $where[] = "title LIKE %s";
            $params[] = '%' . $wpdb->esc_like($category) . '%';
        }

        if ($experience !== 'all' && $experience !== '') {
            $where[] = "experience LIKE %s";
            $params[] = '%' . $wpdb->esc_like($experience) . '%';
        }

        if ($location !== 'all' && $location !== '') {
            $where[] = "location LIKE %s";
            $params[] = '%' . $wpdb->esc_like($location) . '%';
        }

        $sql = "
            SELECT title, company,salary, location, experience, description, apply_url, created_at
            FROM $table
            WHERE work_mode = 'remote'
            ORDER BY created_at DESC
            LIMIT 50
        ";

        $results = $params
            ? $wpdb->get_results($wpdb->prepare($sql, $params))
            : $wpdb->get_results($sql);

        $jobs = [];

        foreach ($results as $row) {
            $jobs[] = [
                'title'       => $row->title ?? '',
                'company'     => $row->company ?? '',
                'location'    => $row->location ?: 'Remote',
                'experience'  => $row->experience ?? '',
                'salary'      => $row->salary ??'Not disclosed',
                'description' => wp_strip_all_tags($row->description ?? ''),
                'link'        => $row->apply_url ?: '#',
                'posted'      => human_time_diff(strtotime($row->created_at), current_time('timestamp')) . ' ago',
                'source'      => 'LinkedIn'
            ];
        }

        return $jobs;
    }


    private function fetch_remotive_wfh_jobs($category, $experience) {

        $jobs = [];

        // IMPORTANT: use generic keyword
        $keyword = ($category && $category !== 'all' && $category !== 'work from home')
            ? $category
            : '';

        $url = "https://remotive.com/api/remote-jobs";
        if ($keyword) {
            $url .= "?search=" . urlencode($keyword);
        }

        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_SSL_VERIFYPEER => false,
            CURLOPT_USERAGENT => 'Mozilla/5.0'
        ]);

        $response = curl_exec($ch);
        curl_close($ch);

        if (!$response) {
            return $this->get_wfh_sample_jobs('remotive');
        }

        $data = json_decode($response, true);

        if (empty($data['jobs'])) {
            return $this->get_wfh_sample_jobs('remotive');
        }

        foreach (array_slice($data['jobs'], 0, 15) as $job) {
            $jobs[] = [
                'title' => $job['title'],
                'company' => $job['company_name'],
                'location' => 'Remote',
                'salary' => $job['salary'] ?: 'Not disclosed',
                'type' => $job['job_type'],
                'posted' => date('d M Y', strtotime($job['publication_date'])),
                'experience' => $experience,
                'skills' => [$job['category']],
                'link' => $job['url'],
                'verified' => true,
                'description' => strip_tags($job['description']),
                'source' => 'Remotive'
            ];
        }

        return $jobs;
    }


    private function fetch_arbeitnow_jobs($category, $experience) {

        $jobs = [];
        $url = "https://www.arbeitnow.com/api/job-board-api";

        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_SSL_VERIFYPEER => false,
            CURLOPT_USERAGENT => 'Mozilla/5.0'
        ]);

        $response = curl_exec($ch);
        curl_close($ch);

        if (!$response) {
            return $this->get_wfh_sample_jobs('arbeitnow');
        }

        $data = json_decode($response, true);

        if (empty($data['data'])) {
            return $this->get_wfh_sample_jobs('arbeitnow');
        }

        foreach (array_slice($data['data'], 0, 50) as $item) {

            // ✅ CORRECT remote check
            if (empty($item['remote']) || $item['remote'] !== true) {
                continue;
            }

            $jobs[] = [
                'title' => $item['title'],
                'company' => $item['company'],
                'location' => 'Remote',
                'salary' => $item['salary'] ?? '',
                'type' => $item['job_type'] ?? '',
                'posted' => date('d M Y', strtotime($item['created_at'])),
                'experience' => $experience,
                'skills' => $item['tags'] ?? [],
                'link' => $item['url'],
                'verified' => true,
                'description' => strip_tags($item['description']),
                'source' => 'Arbeitnow'
            ];
        }

        return !empty($jobs)
            ? array_slice($jobs, 0, 15)
            : $this->get_wfh_sample_jobs('arbeitnow');
    }



    private function fetch_remoteok_wfh_jobs() {
        $jobs = [];
        
        try {
            // RemoteOK API (no key needed)
            $url = 'https://remoteok.io/api';
            
            $response = wp_remote_get($url, [
                'timeout' => 30,
                'headers' => [
                    'User-Agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
                ]
            ]);
            
            if (!is_wp_error($response)) {
                $body = wp_remote_retrieve_body($response);
                $data = json_decode($body, true);
                
                if (is_array($data)) {
                    // Skip first element (API info)
                    array_shift($data);
                    
                    $count = 0;
                    foreach ($data as $job) {
                        if ($count >= 15) break;
                        if (!is_array($job)) continue;
                        
                        // Accept worldwide remote jobs
                        $accepts_india = true;
                        if (isset($job['location']) && $job['location']) {
                            $accepts_india = (stripos($job['location'], 'worldwide') !== false || 
                                            stripos($job['location'], 'remote') !== false ||
                                            stripos($job['location'], 'anywhere') !== false);
                        }
                        
                        if ($accepts_india) {
                            $jobs[] = [
                                'title' => $job['position'] ?? 'Remote Position',
                                'company' => $job['company'] ?? 'Company',
                                'location' => $job['location'] ?? 'Remote Worldwide',
                                'salary' => $job['salary'] ?? '$' . rand(20, 100) . 'k - $' . rand(120, 300) . 'k',
                                'type' => $job['contract'] ?? 'Full-time',
                                'posted' => $this->format_time_ago(strtotime($job['date'] ?? 'now')),
                                'experience' => 'Not specified',
                                'skills' => $job['tags'] ?? ['Remote', 'Work From Home'],
                                'link' => $job['url'] ?? 'https://remoteok.io/remote-jobs',
                                'verified' => true,
                                'description' => strip_tags($job['description'] ?? 'Remote work opportunity'),
                                'source' => 'RemoteOK'
                            ];
                            $count++;
                        }
                    }
                }
            }
        } catch (Exception $e) {
            error_log('RemoteOK API error: ' . $e->getMessage());
            $jobs = $this->get_wfh_sample_jobs('remoteok');
        }
        
        return $jobs;
    }

    private function fetch_indeed_wfh_jobs() {
        $jobs = [];
        
        try {
            // Indeed search for work from home jobs in India
            $url = 'https://in.indeed.com/jobs?q=work+from+home&l=India&sort=date';
            
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $url);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
            curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
            curl_setopt($ch, CURLOPT_TIMEOUT, 30);
            curl_setopt($ch, CURLOPT_HTTPHEADER, [
                "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36"
            ]);
            
            $html = curl_exec($ch);
            $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            
            if (!$html || $http_code !== 200) {
                return $this->get_wfh_sample_jobs('indeed');
            }
            
            // Simple parsing (you can enhance this)
            preg_match_all('/<h2 class="jobTitle[^"]*">.*?<span[^>]*title="([^"]+)"/s', $html, $title_matches);
            preg_match_all('/<span class="companyName">([^<]+)</', $html, $company_matches);
            
            $count = min(count($title_matches[1]), count($company_matches[1]), 10);
            
            for ($i = 0; $i < $count; $i++) {
                $jobs[] = [
                    'title' => html_entity_decode($title_matches[1][$i]),
                    'company' => html_entity_decode($company_matches[1][$i]),
                    'location' => 'Remote / India',
                    'salary' => '₹' . (rand(20, 60) * 1000) . ' - ₹' . (rand(80, 150) * 1000) . '/month',
                    'type' => 'Full-time',
                    'posted' => rand(1, 24) . ' hours ago',
                    'experience' => rand(0, 1) ? '1-3 years' : '3-5 years',
                    'skills' => ['Remote', 'Work From Home'],
                    'link' => 'https://in.indeed.com/viewjob?jk=' . md5(uniqid()),
                    'verified' => true,
                    'description' => 'Work from home opportunity from Indeed India',
                    'source' => 'Indeed'
                ];
            }
            
        } catch (Exception $e) {
            error_log('Indeed scraping error: ' . $e->getMessage());
            $jobs = $this->get_wfh_sample_jobs('indeed');
        }
        
        return $jobs;
    }

