    private function estimate_salary($title, $experience) {
        $base_salary = [
            'fresher' => ['min' => 15000, 'max' => 30000],
            '1-3 years' => ['min' => 25000, 'max' => 60000],
            '3-5 years' => ['min' => 50000, 'max' => 120000],
            '5-10 years' => ['min' => 80000, 'max' => 200000]
        ];
        
        $exp_key = '1-3 years'; // default
        foreach ($base_salary as $key => $range) {
            if (stripos($experience, $key) !== false) {
                $exp_key = $key;
                break;
            }
        }
        
        $range = $base_salary[$exp_key];
        return '₹' . number_format($range['min']) . ' - ₹' . number_format($range['max']) . '/month';
    }

    private function extract_wfh_skills($title) {
        $skills = ['Remote', 'Work From Home'];
        
        $tech_skills = [
            'developer' => ['Programming', 'Software Development'],
            'writer' => ['Content Writing', 'SEO'],
            'marketing' => ['Digital Marketing', 'Social Media'],
            'support' => ['Customer Service', 'Communication'],
            'design' => ['UI/UX', 'Graphic Design'],
            'analyst' => ['Data Analysis', 'Excel']
        ];
        
        $title_lower = strtolower($title);
        foreach ($tech_skills as $keyword => $skill_list) {
            if (stripos($title_lower, $keyword) !== false) {
                $skills = array_merge($skills, $skill_list);
                break;
            }
        }
        
        return array_slice(array_unique($skills), 0, 4);
    }

    private function format_time_ago($timestamp) {
        $diff = time() - $timestamp;
        
        if ($diff < 60) return 'Just now';
        elseif ($diff < 3600) return floor($diff/60) . ' minutes ago';
        elseif ($diff < 86400) return floor($diff/3600) . ' hours ago';
        elseif ($diff < 604800) return floor($diff/86400) . ' days ago';
        else return date('M d', $timestamp);
    }
