            .niche-em { font-size: 1.8rem; margin-bottom: 10px; }
            .niche-chip h4 { font-size: .85rem; font-weight: 700; color: rgba(255,255,255,.8); }
            .niche-cpc { font-size: .72rem; color: var(--green); font-weight: 600; margin-top: 4px; }

            /* ── TECHNOLOGY STACK ── */
            .tech-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 20px; text-align: center; }
            .tech-item { background: var(--ink2); border: 1px solid rgba(255,255,255,.07); border-radius: var(--r); padding: 20px 12px; transition: all .25s; }
            .tech-item:hover { transform: translateY(-4px); border-color: var(--gold); }
            .tech-icon { font-size: 2rem; margin-bottom: 12px; color: var(--gold); }
            .tech-item span { font-size: .85rem; font-weight: 600; }

            /* ── SEO & TOPICAL GRIDS ── */
            .seo-grid, .topical-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
            .seo-item, .topical-item {
                background: var(--ink2); border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r); padding: 24px; text-align: center; transition: all .25s;
            }
            .seo-item:hover, .topical-item:hover { border-color: var(--gold); transform: translateY(-4px); }
            .seo-icon, .topical-icon { font-size: 2rem; color: var(--gold); margin-bottom: 16px; }
            .seo-item h3, .topical-item h3 { font-family: var(--font-head); font-size: 1rem; margin-bottom: 12px; }
            .seo-item p, .topical-item p { font-size: .85rem; color: rgba(255,255,255,.7); }

            /* ── PROCESS STEPS ── */
            .proc-grid { display: grid; grid-template-columns: repeat(6,1fr); gap: 0; position: relative; }
            .proc-grid::after {
                content: ''; position: absolute; top: 36px;
                left: calc(100%/12); right: calc(100%/12); height: 2px;
                background: linear-gradient(90deg, transparent, var(--gold), transparent); z-index: 0;
            }
            .proc-step { text-align: center; position: relative; z-index: 1; padding: 0 8px; }
            .proc-num {
                width: 72px; height: 72px;
                background: linear-gradient(135deg, var(--gold), var(--gold2));
                border-radius: 50%; display: flex; align-items: center; justify-content: center;
                font-family: var(--font-head); font-size: 1.5rem; font-weight: 800; color: var(--ink);
                margin: 0 auto 18px; box-shadow: 0 0 0 8px rgba(245,166,35,.1); transition: transform .3s;
            }
            .proc-step:hover .proc-num { transform: scale(1.08); }
            .proc-step h3 { font-family: var(--font-head); font-size: .88rem; font-weight: 700; margin-bottom: 8px; }
            .proc-step p { font-size: .78rem; color: rgba(255,255,255,.7); line-height: 1.55; }

            /* ── CASES GRID ── */
            .cases-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
            .case-card { background: var(--ink2); border: 1px solid rgba(255,255,255,.08); border-radius: var(--r2); padding: 28px; transition: all .3s; }
            .case-card:hover { transform: translateY(-6px); border-color: rgba(245,166,35,.3); }
            .case-badge { display: inline-block; background: rgba(245,166,35,.15); color: var(--gold); font-size: .7rem; font-weight: 700; padding: 4px 12px; border-radius: 50px; margin-bottom: 14px; }
            .case-title { font-family: var(--font-head); font-size: 1.1rem; margin-bottom: 12px; }
            .case-description { font-size: .85rem; color: rgba(255,255,255,.7); margin-bottom: 16px; }
            .case-tech { display: flex; gap: 16px; margin: 16px 0; font-size: .75rem; color: rgba(255,255,255,.6); }
            .proof-image-placeholder { background: rgba(255,255,255,.05); border-radius: var(--r); display: flex; align-items: center; justify-content: center; margin: 16px 0; height: 100px; }

            /* ── INCOME PROOF ── */
            .proof-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
            .proof-card { background: var(--ink2); border: 1px solid rgba(255,255,255,.08); border-radius: var(--r2); padding: 28px; text-align: center; }
            .proof-icon { font-size: 2rem; color: var(--gold); margin-bottom: 16px; }
            .proof-stats { display: flex; justify-content: center; gap: 24px; margin: 20px 0; }
            .proof-stat .value { font-size: 1.4rem; font-weight: 800; color: var(--gold); }
            .proof-stat .label { font-size: .7rem; color: rgba(255,255,255,.6); }

            /* ── COMPARISON TABLE ── */
            .cmp-table-wrapper { overflow-x: auto; border-radius: var(--r2); border: 1px solid rgba(255,255,255,.07); }
            .cmp-table { width: 100%; border-collapse: collapse; }
            .cmp-table th { background: var(--ink3); padding: 16px 20px; text-align: center; font-family: var(--font-head); font-size: .85rem; font-weight: 700; color: rgba(255,255,255,.7); }
            .cmp-table th:first-child { text-align: left; }
            .cmp-table td { padding: 14px 20px; text-align: center; border-bottom: 1px solid rgba(255,255,255,.05); font-size: .85rem; color: rgba(255,255,255,.7); }
            .cmp-table td:first-child { text-align: left; font-weight: 600; color: var(--white); }
            .cmp-table tr:last-child td { border-bottom: none; }
            .cmp-table tr:hover td { background: rgba(255,255,255,.02); }
            .cmp-table .ict-col { background: rgba(245,166,35,.04); }
            .yes { color: var(--green); font-weight: 700; }
            .no { color: rgba(255,255,255,.2); }
            .partial { color: var(--gold); }

            /* ── PRICING ── */
            .price-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 22px; align-items: start; }
            .price-card {
                background: var(--ink2); border: 1px solid rgba(255,255,255,.08);
                border-radius: var(--r2); padding: 34px 28px; transition: all .3s; position: relative; overflow: hidden;
            }
            .price-card.pop { background: linear-gradient(160deg, var(--ink3), rgba(245,166,35,.07)); border-color: rgba(245,166,35,.35); transform: scale(1.03); }
            .price-card:hover { transform: translateY(-6px) scale(1.01); box-shadow: var(--sh2); }
            .price-card.pop:hover { transform: scale(1.03) translateY(-6px); }
            .pop-badge { position: absolute; top: 18px; right: -28px; background: linear-gradient(135deg, var(--gold), var(--gold2)); color: var(--ink); font-size: .7rem; font-weight: 800; padding: 6px 40px; transform: rotate(45deg); }
            .price-plan { font-size: .72rem; font-weight: 700; letter-spacing: .6px; text-transform: uppercase; color: var(--gold); margin-bottom: 10px; }
            .price-usd { font-family: var(--font-head); font-size: 2.4rem; font-weight: 800; color: var(--white); margin-bottom: 2px; }
            .price-usd sup { font-size: 1rem; vertical-align: top; margin-top: 8px; color: rgba(255,255,255,.5); }
            .price-inr { font-size: .85rem; color: rgba(255,255,255,.7); margin-bottom: 6px; }
            .price-start { font-size: .75rem; color: var(--green); font-weight: 600; margin-bottom: 22px; }
            .price-feat { margin-bottom: 28px; }
            .price-feat li { display: flex; align-items: flex-start; gap: 10px; padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,.05); font-size: .85rem; color: rgba(255,255,255,.7); }
            .price-feat li:last-child { border-bottom: none; }
            .price-feat li::before { content: '✓'; color: var(--green); font-weight: 800; flex-shrink: 0; margin-top: 1px; }

            /* Price display toggle */
            .price-inr-display { display: none; font-size: .85rem; color: rgba(255,255,255,.7); margin-bottom: 6px; }
            .price-usd-display { display: block; }
            body.show-inr .price-usd-display { display: none; }
            body.show-inr .price-inr-display { display: block; }

            /* ── TESTIMONIALS ── */
            .testi-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
            .testi-card { background: var(--ink2); border: 1px solid rgba(255,255,255,.07); border-radius: var(--r2); padding: 28px; transition: all .3s; }
            .testi-card:hover { border-color: rgba(245,166,35,.2); transform: translateY(-4px); }
            .testi-stars { color: var(--gold); font-size: .9rem; margin-bottom: 16px; letter-spacing: 2px; }
            .testi-text { font-size: .88rem; color: rgba(255,255,255,.75); line-height: 1.7; font-style: italic; margin-bottom: 20px; }
            .testi-author { display: flex; align-items: center; gap: 12px; }
            .tav { width: 44px; height: 44px; border-radius: 50%; background: linear-gradient(135deg, var(--gold), var(--gold2)); display: flex; align-items: center; justify-content: center; font-family: var(--font-head); font-weight: 800; color: var(--ink); font-size: .9rem; flex-shrink: 0; }
            .tav-name { font-weight: 700; font-size: .88rem; }
            .tav-role { font-size: .76rem; color: rgba(255,255,255,.6); }

            /* ── BLOG GRID ── */
            .blog-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
            .blog-card { background: var(--ink2); border: 1px solid rgba(255,255,255,.07); border-radius: var(--r2); padding: 26px; transition: all .3s; display: flex; flex-direction: column; }
            .blog-card:hover { border-color: rgba(245,166,35,.25); transform: translateY(-4px); }
            .blog-cat { font-size: .7rem; font-weight: 700; letter-spacing: .5px; text-transform: uppercase; color: var(--gold); margin-bottom: 10px; }
            .blog-card h3 { font-family: var(--font-head); font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 10px; color: var(--white); }
            .blog-card p { font-size: .82rem; color: rgba(255,255,255,.7); line-height: 1.6; flex: 1; margin-bottom: 18px; }
            .blog-link { display: inline-flex; align-items: center; gap: 6px; color: var(--gold); font-size: .82rem; font-weight: 700; transition: gap .2s; }
            .blog-link:hover { gap: 12px; }
            .blog-date { font-size: .74rem; color: rgba(255,255,255,.5); margin-bottom: 6px; }

            /* ── FAQ ── */
            .faq-section { padding: 90px 0; }
            .faq-container { max-width: 800px; margin: 0 auto; }
            .faq-item { background: var(--ink2); border-radius: var(--r); margin-bottom: 16px; border: 1px solid rgba(255,255,255,.07); transition: all 0.25s; }
            .faq-question { display: flex; justify-content: space-between; align-items: center; padding: 20px 24px; cursor: pointer; font-weight: 600; color: var(--white); font-size: 1rem; background: transparent; border: none; width: 100%; text-align: left; font-family: var(--font-body); transition: color 0.2s; }
            .faq-question h3 { font-size: 1rem; font-weight: 600; margin: 0; color: var(--white); }
            .faq-question:hover { color: var(--gold); }
            .faq-question:hover h3 { color: var(--gold); }
            .faq-icon { font-size: 1rem; color: var(--gold); transition: transform 0.3s ease; flex-shrink: 0; margin-left: 12px; }
            .faq-item.active .faq-icon { transform: rotate(180deg); }
            .faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease; padding: 0 24px; color: rgba(255,255,255,.7); line-height: 1.65; font-size: 0.9rem; }
            .faq-item.active .faq-answer { max-height: 500px; padding: 0 24px 24px 24px; }
            .faq-answer p { margin: 0; }

            /* ── PLUGIN GRID ── */
            .plug-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 18px; }
            .plug-item { background: rgba(245,166,35,.05); border: 1px solid rgba(245,166,35,.12); border-radius: var(--r); padding: 24px 20px; text-align: center; transition: all .25s; }
            .plug-item:hover { background: rgba(245,166,35,.1); transform: translateY(-4px); }
            .plug-icon { font-size: 1.8rem; margin-bottom: 12px; }
            .plug-item h3 { font-family: var(--font-head); font-size: .9rem; font-weight: 700; margin-bottom: 6px; }
            .plug-item p { font-size: .78rem; color: rgba(255,255,255,.7); line-height: 1.55; }

            /* ── OWNERSHIP & RISK GRIDS ── */
            .ownership-grid, .risk-grid, .target-grid, .notfor-grid, .dont-grid, .competitor-grid, .guidelines-grid {
                display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px;
            }
            .ownership-item, .risk-item, .target-item, .notfor-item, .dont-item, .competitor-item, .guideline-item {
                background: var(--ink2); border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r); padding: 28px 20px; text-align: center; transition: all .25s;
            }
            .ownership-item:hover, .risk-item:hover, .target-item:hover, .notfor-item:hover, .dont-item:hover, .competitor-item:hover, .guideline-item:hover {
                border-color: var(--gold); transform: translateY(-4px);
            }
            .ownership-icon, .risk-icon, .target-icon, .notfor-icon, .dont-icon, .competitor-icon, .guideline-icon {
                font-size: 2rem; color: var(--gold); margin-bottom: 16px;
            }
            .ownership-item h3, .risk-item h3, .target-item h3, .notfor-item h3, .dont-item h3, .competitor-item h3, .guideline-item h3 {
                font-family: var(--font-head); font-size: 1rem; margin-bottom: 12px;
            }
            .ownership-item p, .risk-item p, .target-item p, .notfor-item p, .dont-item p, .competitor-item p, .guideline-item p {
                font-size: .85rem; color: rgba(255,255,255,.7);
            }

            /* ── LEAD MAGNET ── */
            .leadmagnet-box { background: linear-gradient(135deg, var(--ink3), var(--ink2)); border: 1px solid rgba(245,166,35,.2); border-radius: var(--r2); padding: 48px 32px; text-align: center; }
            .leadmagnet-title { font-size: 1.8rem; margin-bottom: 12px; color: var(--gold); }
            .leadmagnet-description { font-size: 1rem; margin-bottom: 24px; color: rgba(255,255,255,.8); }
            .leadmagnet-button { display: inline-flex; align-items: center; gap: 12px; background: #25D366; color: var(--white); padding: 12px 28px; border-radius: 50px; font-weight: 700; transition: transform .2s; }
            .leadmagnet-button:hover { transform: translateY(-3px); }

            /* ── CALCULATOR ── */
            .calculator-box { background: var(--ink2); border: 1px solid rgba(255,255,255,.07); border-radius: var(--r2); padding: 32px; max-width: 500px; margin: 0 auto; }
            .calculator-input-group { margin-bottom: 20px; }
            .calculator-input-group label { display: block; font-size: .85rem; margin-bottom: 6px; color: rgba(255,255,255,.8); }
            .calculator-input-group input { width: 100%; padding: 12px; border-radius: var(--r); border: 1px solid rgba(255,255,255,.2); background: rgba(0,0,0,.3); color: var(--white); font-size: 1rem; }
            .calculator-result { margin-top: 24px; text-align: center; }
            .result-number { font-size: 2rem; font-weight: 800; color: var(--gold); }

            /* ── TRUST BADGES ── */
            .trustbadges-grid, .logos-grid, .trust-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 24px; }
            .trustbadge-item, .logo-item, .trust-item { background: rgba(255,255,255,.05); padding: 12px 24px; border-radius: 50px; font-size: .85rem; font-weight: 600; color: rgba(255,255,255,.9); display: flex; align-items: center; gap: 8px; }
            .trustbadge-item i, .logo-item i, .trust-item i { color: var(--gold); }

            /* ── TIMELINE ── */
            .timeline-months { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 20px; }
            .timeline-month { flex: 1; min-width: 150px; background: var(--ink2); border-radius: var(--r); padding: 24px; text-align: center; }
            .month { font-size: 1.2rem; font-weight: 800; color: var(--gold); margin-bottom: 8px; }
            .milestone { font-size: .9rem; color: rgba(255,255,255,.8); }

            /* ── SCARCITY SECTION (NEW) ── */
            .scarcity-box {
                background: linear-gradient(135deg, rgba(239,71,111,.08), rgba(245,166,35,.08));
                border: 1px solid rgba(239,71,111,.25); border-radius: var(--r2);
                padding: 40px 32px; text-align: center;
            }
            .scarcity-title { font-family: var(--font-head); font-size: 1.6rem; font-weight: 800; margin-bottom: 12px; }
            .scarcity-slots { display: flex; justify-content: center; gap: 12px; margin: 24px 0; flex-wrap: wrap; }
            .slot-item {
                width: 48px; height: 48px; border-radius: 10px; display: flex; align-items: center; justify-content: center;
                font-weight: 800; font-size: .88rem;
            }
            .slot-taken { background: rgba(239,71,111,.2); border: 1px solid rgba(239,71,111,.4); color: var(--red); }
            .slot-free { background: rgba(6,214,160,.15); border: 1px solid rgba(6,214,160,.35); color: var(--green); }
            .scarcity-note { font-size: .85rem; color: rgba(255,255,255,.7); margin-bottom: 24px; }
            .scarcity-timer { display: flex; justify-content: center; gap: 16px; margin-bottom: 28px; flex-wrap: wrap; }
            .timer-unit { text-align: center; }
            .timer-num { font-family: var(--font-head); font-size: 2rem; font-weight: 800; color: var(--gold); display: block; background: rgba(245,166,35,.1); border-radius: 10px; padding: 8px 16px; min-width: 60px; }
            .timer-lab { font-size: .7rem; color: rgba(255,255,255,.6); margin-top: 6px; text-transform: uppercase; letter-spacing: .4px; }

            /* ── CTA ── */
            .cta-wrap {
                background: linear-gradient(135deg, var(--ink2), var(--ink3));
                border: 1px solid rgba(245,166,35,.15); border-radius: var(--r2);
                padding: 64px 48px; text-align: center; position: relative; overflow: hidden;
            }
            .cta-h2 { font-family: var(--font-head); font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 800; margin-bottom: 16px; letter-spacing: -.5px; }
            .cta-sub { font-size: 1.02rem; color: rgba(255,255,255,.75); max-width: 540px; margin: 0 auto 36px; line-height: 1.7; }
            .cta-btns { display: flex; flex-wrap: wrap; gap: 14px; justify-content: center; margin-bottom: 28px; }
            .cta-trust { display: flex; flex-wrap: wrap; gap: 20px; justify-content: center; font-size: .78rem; color: rgba(255,255,255,.6); }

            /* ── MOBILE STICKY CTA (NEW) ── */
            .mobile-sticky-cta {
                display: none; position: fixed; bottom: 0; left: 0; right: 0; z-index: 850;
                background: var(--ink2); border-top: 1px solid rgba(255,255,255,.1);
                padding: 12px 16px; gap: 10px;
            }
            .mobile-sticky-cta .btn { flex: 1; padding: 12px 16px; font-size: .82rem; }

            /* ── FLOATING ELEMENTS ── */
            .float-wa {
                position: fixed; bottom: 24px; right: 24px; width: 58px; height: 58px;
                background: #25D366; border-radius: 50%; display: flex; align-items: center; justify-content: center;
                font-size: 1.5rem; z-index: 800; box-shadow: 0 6px 24px rgba(37,211,102,.4);
                animation: floatBob 3s ease-in-out infinite; text-decoration: none; transition: transform .2s;
            }
            .float-wa:hover { transform: scale(1.12); animation: none; }
            .float-wa-label {
                position: absolute; right: 70px; background: var(--ink2); color: var(--white);
                font-size: .76rem; font-weight: 700; padding: 6px 12px; border-radius: 8px;
                white-space: nowrap; opacity: 0; pointer-events: none; transition: opacity .2s;
                border: 1px solid rgba(255,255,255,.1);
            }
            .float-wa:hover .float-wa-label { opacity: 1; }
            .scroll-top {
                position: fixed; bottom: 90px; right: 24px; width: 44px; height: 44px;
                background: var(--ink2); border: 1px solid rgba(255,255,255,.12); border-radius: 50%;
                display: flex; align-items: center; justify-content: center; color: var(--white);
                font-size: 1rem; z-index: 800; cursor: pointer;
                opacity: 0; transform: translateY(10px); transition: all .3s;
            }
            .scroll-top.show { opacity: 1; transform: translateY(0); }
            .scroll-top:hover { background: var(--gold); color: var(--ink); }

            /* ── SOCIAL PROOF TOAST ── */
            .sp-toast {
                position: fixed; bottom: 24px; left: 24px; background: var(--ink2);
                border: 1px solid rgba(255,255,255,.1); border-radius: 50px;
                padding: 10px 18px 10px 12px; display: flex; align-items: center; gap: 10px;
                z-index: 800; font-size: .8rem; color: rgba(255,255,255,.8); box-shadow: var(--sh);
                transform: translateX(-120%); transition: transform .5s cubic-bezier(.34,1.56,.64,1);
                max-width: 280px;
            }
            .sp-toast.show { transform: translateX(0); }
            .sp-dot { width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg, var(--gold), var(--gold2)); display: flex; align-items: center; justify-content: center; font-size: .75rem; font-weight: 800; color: var(--ink); flex-shrink: 0; }

            /* ── ANIMATIONS ── */
            @keyframes fadeUp { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
            @keyframes pulse { 0%,100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.7); opacity: .4; } }
            @keyframes floatBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
            .reveal { opacity: 0; transform: translateY(24px); transition: opacity .65s ease, transform .65s ease; }
            .reveal.in { opacity: 1; transform: translateY(0); }
            .reveal-d1 { transition-delay: .1s; }
            .reveal-d2 { transition-delay: .2s; }
            .reveal-d3 { transition-delay: .3s; }
            .reveal-d4 { transition-delay: .4s; }

            /* ── RESPONSIVE ── */
            @media (max-width: 1024px) {
                .hero-inner { grid-template-columns: 1fr; max-width: 680px; }
                .hero-card { display: none; }
                .srv-grid, .cases-grid, .proof-grid, .testi-grid, .blog-grid, .portfolio-grid { grid-template-columns: repeat(2,1fr); }
                .proc-grid { grid-template-columns: repeat(3,1fr); gap: 24px; }
                .proc-grid::after { display: none; }
                .price-grid { grid-template-columns: 1fr; }
                .price-card.pop { transform: none; }
                .stats-bar { grid-template-columns: repeat(2,1fr); }
                .solution-content { grid-template-columns: 1fr; text-align: center; }
                .ba-grid { grid-template-columns: 1fr; }
                .ba-arrow { display: none; }
            }
            @media (max-width: 768px) {
                .awd-section { padding: 60px 0; }
                .nav-links { display: none; }
                .nav-links.open {
                    display: flex; flex-direction: column; position: fixed;
                    top: 70px; left: 0; right: 0; background: rgba(10,15,30,.97);
                    padding: 20px; border-bottom: 1px solid var(--border); z-index: 890;
                }
