            <script>
            (function(){
                'use strict';
                function init(){
                    // Nav scroll
                    let ticking = false;
                    const nav = document.getElementById('awd-nav');
                    window.addEventListener('scroll', function(){
                        if(!ticking){
                            requestAnimationFrame(function(){
                                nav.style.background = window.scrollY > 40 ? 'rgba(10,15,30,.97)' : 'rgba(10,15,30,.82)';
                                ticking = false;
                            });
                            ticking = true;
                        }
                    }, {passive: true});

                    // Hamburger
                    const ham = document.getElementById('awd-ham');
                    const nl = document.getElementById('awd-nav-links');
                    if(ham && nl){
                        ham.addEventListener('click', function(){ nl.classList.toggle('open'); ham.innerHTML = nl.classList.contains('open') ? '<i class="fas fa-times"></i>' : '&#9776;'; });
                        document.addEventListener('click', function(e){ if(!ham.contains(e.target) && !nl.contains(e.target)){ nl.classList.remove('open'); ham.innerHTML = '&#9776;'; } });
                        nl.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', function(){ nl.classList.remove('open'); ham.innerHTML = '&#9776;'; }); });
                    }

                    // Scroll reveal
                    const io = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting) e.target.classList.add('in'); }); }, {threshold: 0.1, rootMargin: '0px 0px -40px 0px'});
                    document.querySelectorAll('.reveal').forEach(function(el){ io.observe(el); });

                    // Counter
                    let counted = false;
                    const statsIO = new IntersectionObserver(function(entries){
                        if(entries[0].isIntersecting && !counted){
                            counted = true;
                            document.querySelectorAll('.stat-num').forEach(function(el){
                                const target = parseInt(el.getAttribute('data-n') || '0');
                                let start = 0;
                                const step = Math.ceil(target / 60);
                                const timer = setInterval(function(){
                                    start += step;
                                    if(start >= target){ start = target; clearInterval(timer); }
                                    el.textContent = start + (el.getAttribute('data-n') === '95' ? '%' : '+');
                                }, 18);
                            });
                        }
                    }, {threshold: 0.5});
                    const sb = document.getElementById('stats-bar');
                    if(sb) statsIO.observe(sb);

                    // FAQ toggle
                    const faqItems = document.querySelectorAll('.faq-item');
                    faqItems.forEach(item => {
                        const question = item.querySelector('.faq-question');
                        if(question){
                            question.addEventListener('click', () => {
                                faqItems.forEach(other => { if(other !== item && other.classList.contains('active')) other.classList.remove('active'); });
                                item.classList.toggle('active');
                            });
                        }
                    });

                    // Scroll top
                    const st = document.getElementById('awd-scroll-top');
                    window.addEventListener('scroll', function(){ st.classList.toggle('show', window.scrollY > 600); }, {passive: true});
                    if(st) st.addEventListener('click', function(){ window.scrollTo({top: 0, behavior: 'smooth'}); });

                    // Social proof toast
                    const names = [
                        {init: 'RK', name: 'Rahul from Mumbai', action: 'just booked a strategy call'},
                        {init: 'SK', name: 'Sarah from London', action: 'just purchased Pro package'},
                        {init: 'AM', name: 'Ahmed from Dubai', action: 'just messaged us on WhatsApp'},
                        {init: 'PL', name: 'Priya from Bangalore', action: 'just got AdSense approved'},
                        {init: 'JT', name: 'James from Toronto', action: 'just started his WordPress site'}
                    ];
                    const toast = document.getElementById('awd-sp-toast');
                    let shown = 0;
                    function showToast(){
                        if(shown >= names.length) return;
                        const n = names[shown++];
                        toast.querySelector('.sp-dot').textContent = n.init;
                        toast.querySelector('span').innerHTML = '<strong>' + n.name + '</strong> ' + n.action;
                        toast.classList.add('show');
                        setTimeout(function(){ toast.classList.remove('show'); }, 5000);
                        if(shown < names.length) setTimeout(showToast, 12000);
                    }
                    setTimeout(showToast, 3500);

                    // Smooth scroll
                    document.querySelectorAll('a[href^="#"]').forEach(function(a){
                        a.addEventListener('click', function(e){
                            const t = this.getAttribute('href');
                            if(t === '#' || t === '#!') return;
                            const el = document.querySelector(t);
                            if(el){ e.preventDefault(); el.scrollIntoView({behavior: 'smooth'}); }
                        });
                    });

                    // Calculator
                    const calcBtn = document.getElementById('calculateBtn');
                    const calcResult = document.getElementById('calcResult');
                    const monthlyEarnings = document.getElementById('monthlyEarnings');
                    if(calcBtn){
                        calcBtn.addEventListener('click', function(){
                            const traffic = parseFloat(document.getElementById('traffic').value) || 0;
                            const rpm = parseFloat(document.getElementById('rpm').value) || 0;
                            const earnings = (traffic * rpm) / 1000;
                            monthlyEarnings.textContent = '$' + earnings.toFixed(2);
                            calcResult.style.display = 'block';
                        });
                    }

                    // Modal exit-intent
                    const modal = document.getElementById('awd-leadModal');
                    const modalClose = document.getElementById('awd-modalClose');
                    const leadForm = document.getElementById('awd-leadForm');
                    let modalShown = sessionStorage.getItem('modalShown') === 'true';
                    let modalActive = false;
                    function showModal(){
                        if(!modalShown && !modalActive){
                            modal.classList.add('active');
                            modalActive = true;
                            sessionStorage.setItem('modalShown', 'true');
                        }
                    }
                    if(!modalShown){
                        document.addEventListener('mouseleave', function(event){ if(event.clientY <= 0) showModal(); });
                    }
                    modalClose.addEventListener('click', function(){ modal.classList.remove('active'); modalActive = false; });
                    modal.addEventListener('click', function(e){ if(e.target === modal){ modal.classList.remove('active'); modalActive = false; } });
                    leadForm.addEventListener('submit', function(e){
                        e.preventDefault();
                        const name = leadForm.name.value.trim();
                        const email = leadForm.email.value.trim();
                        const phone = leadForm.phone.value.trim();
                        const niche = leadForm.niche.value;
                        const pkg = leadForm.package ? leadForm.package.value : '';
                        if(!name || !email || !phone){ alert('Please fill in all required fields.'); return; }
                        const message = `Hi, I'm interested in an AdSense-ready WordPress website.%0A%0A` +
                            `*Name:* ${encodeURIComponent(name)}%0A` +
                            `*Email:* ${encodeURIComponent(email)}%0A` +
                            `*Phone:* ${encodeURIComponent(phone)}%0A` +
                            `*Niche:* ${encodeURIComponent(niche || 'Not specified')}%0A` +
                            `*Package Interest:* ${encodeURIComponent(pkg || 'Not specified')}%0A%0A` +
                            `Please send me a custom proposal.`;
                        window.open(`https://wa.me/919751797695?text=${message}`, '_blank');
                        modal.classList.remove('active');
                        modalActive = false;
                    });

                    // COUNTDOWN TIMER (NEW)
                    function updateTimer(){
                        // End of April 2026
                        const endDate = new Date('2026-04-30T23:59:59');
                        const now = new Date();
                        const diff = endDate - now;
                        if(diff <= 0){ return; }
                        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
                        const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
                        const mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
                        const secs = Math.floor((diff % (1000 * 60)) / 1000);
                        const td = document.getElementById('t-days');
                        const th = document.getElementById('t-hours');
                        const tm = document.getElementById('t-mins');
                        const ts = document.getElementById('t-secs');
                        if(td) td.textContent = String(days).padStart(2, '0');
                        if(th) th.textContent = String(hours).padStart(2, '0');
                        if(tm) tm.textContent = String(mins).padStart(2, '0');
                        if(ts) ts.textContent = String(secs).padStart(2, '0');
                    }
                    updateTimer();
                    setInterval(updateTimer, 1000);
                }

                // CURRENCY TOGGLE (NEW - global function)
                window.toggleCurrency = function(){
                    const body = document.body;
                    const isINR = body.classList.contains('show-inr');
                    if(isINR){
                        body.classList.remove('show-inr');
                        document.querySelectorAll('#currFlag').forEach(el => el.textContent = '🇺🇸');
                        document.querySelectorAll('#currLabel').forEach(el => el.textContent = 'USD');
                    } else {
                        body.classList.add('show-inr');
                        document.querySelectorAll('#currFlag').forEach(el => el.textContent = '🇮🇳');
                        document.querySelectorAll('#currLabel').forEach(el => el.textContent = 'INR');
                    }
                };

                if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
                else init();
            })();
            </script>

        </div><!-- .awd-page -->
        <?php
        return ob_get_clean();
    }
