            }
            
            .mobile-link:hover, .mobile-link.active {
                color: var(--neon-cyan);
                border-left-color: var(--neon-cyan);
                background: rgba(0, 245, 255, 0.05);
            }
            
            .mobile-cta {
                padding: 20px;
            }
            
            .mobile-emergency {
                width: 100%;
                background: linear-gradient(90deg, var(--warning-red), #ff3300);
                border: none;
                color: white;
                padding: 15px;
                border-radius: 5px;
                font-family: var(--font-orbitron);
                font-size: 1rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
            }
            
            /* ===== PREMIUM HERO SECTION ===== */
            .cyber-hero {
                min-height: 100vh;
                position: relative;
                overflow: hidden;
                padding: 150px 20px 100px;
                display: flex;
                align-items: center;
                justify-content: center;
                background: var(--gradient-premium);
            }
            
            .premium-bg {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                z-index: 1;
                overflow: hidden;
            }
            
            .gradient-overlay {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: linear-gradient(135deg, 
                    rgba(5, 5, 5, 0.9) 0%,
                    rgba(10, 26, 47, 0.7) 50%,
                    rgba(12, 35, 64, 0.4) 100%);
            }
            
            .circuit-pattern {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" opacity="0.03"><path d="M0,100 Q50,150 100,100 T200,100" stroke="white" fill="none"/><path d="M100,0 Q150,50 100,100 T100,200" stroke="white" fill="none"/></svg>');
                background-size: 200px 200px;
                opacity: 0.1;
            }
            
            .particles-container {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                pointer-events: none;
            }
            
            .particle {
                position: absolute;
                width: 2px;
                height: 2px;
                background: var(--neon-cyan);
                border-radius: 50%;
                filter: blur(1px);
                animation: floatParticle 20s infinite linear;
            }
            
            .data-dots {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
            
            .data-dot {
                position: absolute;
                width: 4px;
                height: 4px;
                background: rgba(0, 245, 255, 0.3);
                border-radius: 50%;
                animation: floatDot 15s infinite linear;
            }
            
            .scan-line {
                position: absolute;
                left: 0;
                width: 100%;
                height: 1px;
                background: linear-gradient(90deg, 
                    transparent 0%, 
                    rgba(0, 245, 255, 0.6) 50%, 
                    transparent 100%);
                box-shadow: 0 0 10px rgba(0, 245, 255, 0.3);
                z-index: 2;
            }
            
            .scan-1 {
                top: 30%;
                animation: scanMove 8s infinite linear;
            }
            
            .scan-2 {
                top: 60%;
                animation: scanMove 12s infinite linear reverse;
                animation-delay: 2s;
            }
            
            .scan-3 {
                top: 80%;
                animation: scanMove 10s infinite linear;
                animation-delay: 4s;
            }
            
            .flare {
                position: absolute;
                border-radius: 50%;
                filter: blur(60px);
                opacity: 0.1;
                z-index: 1;
            }
            
            .flare-1 {
                top: 20%;
                right: 10%;
                width: 300px;
                height: 300px;
                background: var(--neon-cyan);
                animation: flarePulse 8s infinite alternate;
            }
            
            .flare-2 {
                bottom: 30%;
                left: 10%;
                width: 200px;
                height: 200px;
                background: var(--neon-green);
                animation: flarePulse 6s infinite alternate-reverse;
            }
            
            .holographic-grid {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background-image: 
                    linear-gradient(rgba(0, 245, 255, 0.05) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(0, 245, 255, 0.05) 1px, transparent 1px);
                background-size: 50px 50px;
                mask-image: radial-gradient(ellipse at center, black 30%, transparent 70%);
                -webkit-mask-image: radial-gradient(ellipse at center, black 30%, transparent 70%);
            }
            
            .parallax-layer {
                position: absolute;
                width: 100%;
                height: 100%;
                background-size: contain;
                background-repeat: no-repeat;
                opacity: 0.05;
            }
            
            .layer-1 {
                background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="2" fill="%2300F5FF"/></svg>');
                animation: parallaxMove 40s infinite linear;
            }
            
            .layer-2 {
                background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect x="48" y="48" width="4" height="4" fill="%2300FF9C"/></svg>');
                animation: parallaxMove 60s infinite linear reverse;
            }
            
            .hero-content {
                position: relative;
                z-index: 10;
                max-width: 1200px;
                width: 100%;
                margin: 0 auto;
                text-align: center;
            }
            
            .hero-badge {
                display: inline-flex;
                align-items: center;
                gap: 12px;
                background: rgba(255, 255, 255, 0.1);
                backdrop-filter: var(--glass-blur);
                border: 1px solid var(--glass-border);
                padding: 15px 25px;
                border-radius: 50px;
                font-family: var(--font-orbitron);
                font-size: 0.9rem;
                color: white;
                margin-bottom: 40px;
                position: relative;
                overflow: hidden;
            }
            
            .badge-glow {
                position: absolute;
                top: 0;
                left: -100%;
                width: 100%;
                height: 100%;
                background: linear-gradient(90deg, 
                    transparent, 
                    rgba(255, 255, 255, 0.1), 
                    transparent);
                animation: badgeSlide 3s infinite;
            }
            
            .hero-title {
                font-family: var(--font-orbitron);
                font-size: clamp(3rem, 6vw, 5rem);
                font-weight: 900;
                line-height: 1.1;
                margin-bottom: 25px;
                letter-spacing: -1px;
            }
            
            .gradient-text {
                background: var(--gradient-cyber);
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                background-clip: text;
            }
            
            .hero-subtitle {
                font-size: clamp(1.1rem, 2vw, 1.4rem);
                color: rgba(255, 255, 255, 0.8);
                max-width: 700px;
                margin: 0 auto 50px;
                line-height: 1.6;
                font-weight: 300;
            }
            
            /* ===== THREAT MONITOR ===== */
            .threat-monitor {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid var(--glass-border);
                border-radius: 20px;
                padding: 30px;
                margin-bottom: 50px;
                max-width: 800px;
                margin-left: auto;
                margin-right: auto;
            }
            
            .monitor-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 25px;
            }
            
            .monitor-title {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.2rem;
                letter-spacing: 1px;
            }
            
            .monitor-status {
                display: flex;
                align-items: center;
                gap: 10px;
            }
            
            .status-dot {
                width: 10px;
                height: 10px;
                border-radius: 50%;
                background: var(--neon-green);
                box-shadow: 0 0 15px var(--neon-green);
                animation: pulse 2s infinite;
            }
            
            .status-text {
                color: var(--neon-green);
                font-size: 0.9rem;
                font-family: var(--font-space);
            }
            
            .monitor-stats {
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                gap: 25px;
            }
            
            .stat-item {
                text-align: center;
                padding: 20px;
                background: rgba(255, 255, 255, 0.03);
                border-radius: 15px;
                border: 1px solid rgba(255, 255, 255, 0.1);
            }
            
            .stat-value {
                font-family: var(--font-orbitron);
                font-size: 3rem;
                font-weight: 900;
                color: var(--neon-green);
                margin-bottom: 10px;
                line-height: 1;
            }
            
            .stat-label {
                font-size: 0.9rem;
                color: rgba(255, 255, 255, 0.7);
                text-transform: uppercase;
                letter-spacing: 1px;
                font-weight: 600;
            }
            
            /* ===== CTA BUTTONS ===== */
            .hero-cta {
                display: flex;
                justify-content: center;
                gap: 20px;
                margin-bottom: 50px;
                flex-wrap: wrap;
            }
            
            .cta-btn {
                position: relative;
                padding: 20px 35px;
                border: none;
                border-radius: 12px;
                font-family: var(--font-orbitron);
                font-size: 0.9rem;
                font-weight: 600;
                cursor: pointer;
                display: inline-flex;
                align-items: center;
                gap: 12px;
                transition: var(--transition-premium);
                overflow: hidden;
                letter-spacing: 1px;
            }
            
            .cta-btn.primary {
                background: var(--gradient-cyber);
                color: var(--black-primary);
                box-shadow: 0 10px 30px rgba(0, 245, 255, 0.3);
            }
            
            .cta-btn.secondary {
                background: rgba(255, 255, 255, 0.1);
                backdrop-filter: var(--glass-blur);
                border: 1px solid var(--glass-border);
                color: white;
            }
            
            .cta-btn.outline {
                background: transparent;
                border: 2px solid var(--neon-cyan);
                color: var(--neon-cyan);
            }
            
            .cta-btn:hover {
                transform: translateY(-5px);
                box-shadow: 0 15px 40px rgba(0, 245, 255, 0.4);
            }
            
            .btn-icon {
                font-size: 1.2rem;
            }
            
            .btn-glow {
                position: absolute;
                top: 0;
                left: -100%;
                width: 100%;
                height: 100%;
                background: linear-gradient(90deg, 
                    transparent, 
                    rgba(255, 255, 255, 0.2), 
                    transparent);
                animation: btnShine 3s infinite;
            }
            
            /* ===== TRUST INDICATORS ===== */
            .trust-indicators {
                display: flex;
                justify-content: center;
                gap: 40px;
                flex-wrap: wrap;
                margin-top: 50px;
            }
            
            .trust-item {
                display: flex;
                align-items: center;
                gap: 10px;
                color: rgba(255, 255, 255, 0.7);
                font-size: 0.9rem;
            }
            
            .trust-item i {
                color: var(--neon-cyan);
                font-size: 1.2rem;
            }
            
            /* ===== SCROLL INDICATOR ===== */
            .scroll-indicator {
                position: absolute;
                bottom: 30px;
                left: 50%;
                transform: translateX(-50%);
                text-align: center;
                z-index: 5;
            }
            
            .scroll-text {
                font-family: var(--font-orbitron);
                font-size: 0.8rem;
                color: var(--neon-cyan);
                margin-bottom: 10px;
                opacity: 0.7;
            }
            
            .scroll-line {
                width: 1px;
                height: 50px;
                background: linear-gradient(180deg, var(--neon-cyan), transparent);
                margin: 0 auto;
            }
            
            /* ===== TOOLKIT SECTION ===== */
            .toolkit-section {
                padding: 100px 20px;
                background: var(--black-secondary);
                position: relative;
            }
            
            .section-container {
                max-width: 1400px;
                margin: 0 auto;
            }
            
            .section-header {
                text-align: center;
                margin-bottom: 60px;
            }
            
            .section-title {
                font-family: var(--font-orbitron);
                font-size: 2.5rem;
                color: var(--neon-cyan);
                margin-bottom: 15px;
            }
            
            .section-subtitle {
                color: #8892B0;
                font-size: 1.1rem;
                max-width: 600px;
                margin: 0 auto;
            }
            
            .toolkit-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
            }
            
            .tool-card {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 35px 30px;
                text-align: center;
                transition: var(--transition-premium);
                position: relative;
                overflow: hidden;
            }
            
            .tool-card:hover {
                border-color: var(--neon-cyan);
                transform: translateY(-10px);
                box-shadow: var(--shadow-cyber);
            }
            
            .tool-icon {
                font-size: 3rem;
                color: var(--neon-cyan);
                margin-bottom: 25px;
            }
            
            .tool-title {
                font-family: var(--font-orbitron);
                font-size: 1.4rem;
                color: white;
                margin-bottom: 15px;
            }
            
            .tool-desc {
                font-size: 1rem;
                color: rgba(255, 255, 255, 0.7);
                line-height: 1.6;
                margin-bottom: 25px;
            }
            
            .tool-status {
                display: flex;
                justify-content: center;
                align-items: center;
                gap: 15px;
            }
            
            .status {
                font-family: var(--font-space);
                font-size: 0.8rem;
                padding: 5px 15px;
                border-radius: 20px;
                font-weight: 600;
            }
            
            .status.active {
                background: rgba(0, 255, 156, 0.1);
                color: var(--neon-green);
                border: 1px solid var(--neon-green);
            }
            
            /* ===== PROJECTS SECTION ===== */
            .projects-section {
                padding: 120px 20px;
                background: var(--navy-dark);
                position: relative;
                overflow: hidden;
            }
            
            .projects-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                gap: 30px;
                max-width: 1400px;
                margin: 0 auto 50px;
            }
            
            .project-card {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 35px;
                position: relative;
                overflow: hidden;
                transition: var(--transition-premium);
            }
            
            .project-card:hover {
                transform: translateY(-10px);
                border-color: var(--neon-cyan);
                box-shadow: 0 20px 40px rgba(0, 245, 255, 0.2);
            }
            
            .project-badge {
                position: absolute;
                top: 20px;
                right: 20px;
                background: var(--gradient-cyber);
                color: var(--black-primary);
                padding: 5px 15px;
                border-radius: 20px;
                font-family: var(--font-orbitron);
                font-size: 0.8rem;
                font-weight: 600;
            }
            
            .project-icon {
                font-size: 3rem;
                color: var(--neon-cyan);
                margin-bottom: 25px;
            }
            
            .project-title {
                font-family: var(--font-orbitron);
                font-size: 1.5rem;
                color: white;
                margin-bottom: 15px;
                line-height: 1.3;
            }
            
            .project-desc {
                color: rgba(255, 255, 255, 0.7);
                margin-bottom: 25px;
                line-height: 1.6;
            }
            
            .project-stats {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 20px;
                margin-bottom: 25px;
            }
            
            .project-stats .stat {
                text-align: center;
                padding: 15px;
                background: rgba(255, 255, 255, 0.05);
                border-radius: 10px;
            }
            
            .project-stats .stat-value {
                font-family: var(--font-orbitron);
                font-size: 1.8rem;
                color: var(--neon-green);
                margin-bottom: 5px;
            }
            
            .project-stats .stat-label {
                font-size: 0.8rem;
                color: rgba(255, 255, 255, 0.6);
                text-transform: uppercase;
                letter-spacing: 1px;
            }
            
            .project-tech {
                display: flex;
                gap: 10px;
                flex-wrap: wrap;
            }
            
            .tech-tag {
                background: rgba(0, 245, 255, 0.1);
                color: var(--neon-cyan);
                padding: 8px 15px;
                border-radius: 20px;
                font-size: 0.8rem;
                font-family: var(--font-space);
                border: 1px solid rgba(0, 245, 255, 0.3);
            }
            
            .projects-cta {
                text-align: center;
                margin-top: 50px;
            }
            
            .project-cta-btn {
                background: var(--gradient-gold);
                color: var(--black-primary);
                border: none;
                padding: 20px 40px;
                border-radius: 12px;
                font-family: var(--font-orbitron);
                font-size: 1rem;
                font-weight: 600;
                cursor: pointer;
                display: inline-flex;
                align-items: center;
                gap: 15px;
                transition: var(--transition-premium);
                box-shadow: 0 10px 30px rgba(255, 215, 0, 0.3);
            }
            
            .project-cta-btn:hover {
                transform: translateY(-5px);
                box-shadow: 0 15px 40px rgba(255, 215, 0, 0.4);
            }
            
            /* ===== DASHBOARD SECTION ===== */
            .dashboard-section {
                padding: 100px 20px;
                background: var(--black-secondary);
            }
            
            .dashboard-grid {
                display: grid;
                grid-template-columns: 1fr;
                gap: 30px;
            }
            
            @media (min-width: 1024px) {
                .dashboard-grid {
                    grid-template-columns: 2fr 1fr;
                    grid-template-rows: auto auto;
                }
            }
            
            .dashboard-card {
                background: rgba(5, 5, 5, 0.8);
                border: 1px solid rgba(0, 245, 255, 0.2);
                border-radius: 10px;
                padding: 25px;
                position: relative;
                overflow: hidden;
            }
            
            .dashboard-card.large {
                grid-column: 1 / -1;
            }
            
            @media (min-width: 1024px) {
                .dashboard-card.large {
                    grid-column: 1;
                    grid-row: 1 / span 2;
                }
            }
            
            .card-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 20px;
            }
            
            .card-title {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.2rem;
            }
            
            .card-icon {
                color: var(--neon-cyan);
                font-size: 1.5rem;
            }
            
            .card-controls {
                display: flex;
                gap: 10px;
            }
            
            .control-btn {
                background: rgba(0, 245, 255, 0.1);
                border: 1px solid var(--neon-cyan);
                color: var(--neon-cyan);
                padding: 5px 15px;
                border-radius: 2px;
                font-family: var(--font-space);
                font-size: 0.8rem;
                cursor: pointer;
                transition: all 0.3s;
            }
            
            .control-btn:hover, .control-btn.active {
                background: rgba(0, 245, 255, 0.2);
            }
            
            .world-map {
                height: 300px;
                background: rgba(0, 0, 0, 0.5);
                border-radius: 5px;
                position: relative;
                overflow: hidden;
            }
            
            .map-overlay {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
            
            .attack-line {
                position: absolute;
                height: 1px;
                background: linear-gradient(90deg, var(--warning-red), transparent);
                transform-origin: left center;
                animation: attackLine 2s infinite;
            }
            
            #attack1 {
                top: 30%;
                left: 40%;
                width: 100px;
                transform: rotate(45deg);
                animation-delay: 0s;
            }
            
            #attack2 {
                top: 60%;
                left: 60%;
                width: 120px;
                transform: rotate(-30deg);
                animation-delay: 1s;
            }
            
            #attack3 {
                top: 45%;
                left: 20%;
                width: 80px;
                transform: rotate(15deg);
                animation-delay: 0.5s;
            }
            
            .attack-node {
                position: absolute;
                width: 8px;
                height: 8px;
                background: var(--warning-red);
                border-radius: 50%;
                box-shadow: 0 0 10px var(--warning-red);
            }
            
            .map-stats {
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                gap: 20px;
                margin-top: 20px;
            }
            
            .map-stat {
                text-align: center;
            }
            
            .map-stat .stat-value {
                font-size: 1.5rem;
                margin-bottom: 5px;
            }
            
            .map-stat .stat-label {
                font-size: 0.7rem;
            }
            
            .prediction-graph {
                height: 150px;
                margin-bottom: 20px;
            }
            
            #threatChart {
                width: 100%;
                height: 100%;
            }
            
            .prediction-stats {
                display: flex;
                flex-direction: column;
                gap: 15px;
            }
            
            .prediction-item {
                display: flex;
                align-items: center;
                gap: 10px;
            }
            
            .prediction-label {
                font-size: 0.8rem;
                color: #8892B0;
                width: 100px;
            }
            
            .prediction-value {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                width: 40px;
            }
            
            .prediction-bar {
                flex: 1;
                height: 5px;
                background: rgba(255, 255, 255, 0.1);
                border-radius: 3px;
                overflow: hidden;
            }
            
            .bar-fill {
                height: 100%;
                background: linear-gradient(90deg, var(--neon-cyan), var(--neon-green));
                border-radius: 3px;
            }
            
            .ddos-visual {
                height: 150px;
                position: relative;
                margin-bottom: 20px;
            }
            
            .server-node {
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                text-align: center;
            }
            
            .node-icon {
                font-size: 2rem;
                margin-bottom: 5px;
            }
            
            .node-label {
                font-family: var(--font-space);
                font-size: 0.7rem;
                color: var(--neon-cyan);
            }
            
            .attack-flow {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
            
            .flow-line {
                position: absolute;
                top: 50%;
                left: 0;
                width: 100%;
                height: 1px;
                background: linear-gradient(90deg, var(--warning-red), transparent);
                transform-origin: left center;
                animation: flowLine 1s infinite linear;
            }
            
            .flow-line:nth-child(2) {
                animation-delay: 0.3s;
            }
            
            .flow-line:nth-child(3) {
                animation-delay: 0.6s;
            }
            
            .botnet-nodes {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
            
            .bot-node {
                position: absolute;
                width: 6px;
                height: 6px;
                background: var(--warning-red);
                border-radius: 50%;
                animation: botPulse 2s infinite;
            }
            
            .bot-node:nth-child(1) { top: 20%; left: 10%; }
            .bot-node:nth-child(2) { top: 60%; left: 20%; }
            .bot-node:nth-child(3) { top: 30%; left: 80%; }
            .bot-node:nth-child(4) { top: 80%; left: 60%; }
            .bot-node:nth-child(5) { top: 40%; left: 40%; }
            
            .ddos-controls {
                display: flex;
                flex-direction: column;
                gap: 15px;
            }
            
            .ddos-btn {
                background: var(--gradient-danger);
                border: none;
                color: white;
                padding: 12px;
                border-radius: 5px;
                font-family: var(--font-orbitron);
                font-size: 0.9rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: all 0.3s;
            }
            
            .ddos-btn:hover {
                transform: translateY(-3px);
                box-shadow: 0 5px 20px rgba(255, 0, 51, 0.3);
            }
            
            .ddos-stats {
                display: flex;
                justify-content: space-between;
                font-family: var(--font-space);
                font-size: 0.7rem;
                color: #8892B0;
            }
            
            .blockchain-visual {
                height: 150px;
                position: relative;
                margin-bottom: 20px;
            }
            
            .block-node {
                position: absolute;
                width: 12px;
                height: 12px;
                border: 2px solid var(--neon-green);
                border-radius: 50%;
                background: var(--black-primary);
            }
            
            .block-node.active {
                background: var(--neon-green);
                box-shadow: 0 0 10px var(--neon-green);
                animation: pulse 2s infinite;
            }
            
            .block-node.inactive {
                border-color: #8892B0;
            }
            
            .block-node:nth-child(1) { top: 20%; left: 20%; }
            .block-node:nth-child(2) { top: 60%; left: 30%; }
            .block-node:nth-child(3) { top: 40%; left: 70%; }
            .block-node:nth-child(4) { top: 80%; left: 60%; }
            .block-node:nth-child(5) { top: 30%; left: 50%; }
            
            .block-connections {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
            }
            
            .blockchain-stats {
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                gap: 15px;
            }
            
            .block-stat {
                text-align: center;
            }
            
            .block-stat .stat-value {
                font-size: 1.2rem;
                margin-bottom: 5px;
            }
            
            .block-stat .stat-label {
                font-size: 0.7rem;
            }
            
            /* ===== TRUST SECTION ===== */
            .trust-section {
                padding: 80px 20px;
                background: var(--black-primary);
            }
            
            .trust-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 30px;
                margin-bottom: 60px;
            }
            
            .trust-badge {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 35px 30px;
                text-align: center;
                transition: var(--transition-premium);
            }
            
            .trust-badge:hover {
                border-color: var(--neon-cyan);
                transform: translateY(-5px);
                box-shadow: var(--shadow-cyber);
            }
            
            .badge-icon {
                font-size: 3rem;
                margin-bottom: 20px;
            }
            
            .badge-title {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.4rem;
                margin-bottom: 10px;
            }
            
            .badge-desc {
                font-size: 1rem;
                color: rgba(255, 255, 255, 0.7);
            }
            
            .client-logos {
                display: flex;
                justify-content: center;
                flex-wrap: wrap;
                gap: 40px;
                margin-top: 40px;
            }
            
            .logo-item {
                width: 120px;
                height: 120px;
                background: rgba(0, 245, 255, 0.05);
                border: 1px solid rgba(0, 245, 255, 0.2);
                border-radius: 20px;
                display: flex;
                align-items: center;
                justify-content: center;
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.5rem;
                position: relative;
                cursor: help;
                transition: var(--transition-premium);
            }
            
            .logo-item:hover {
                transform: translateY(-5px);
                border-color: var(--neon-cyan);
                box-shadow: var(--shadow-cyber);
            }
            
            .logo-placeholder {
                font-weight: 600;
            }
            
            .logo-item::after {
                content: attr(data-tooltip);
                position: absolute;
                bottom: 100%;
                left: 50%;
                transform: translateX(-50%);
                background: rgba(0, 0, 0, 0.9);
                border: 1px solid var(--neon-cyan);
                padding: 8px 12px;
                border-radius: 5px;
                font-size: 0.8rem;
                white-space: nowrap;
                opacity: 0;
                transition: opacity 0.3s;
                pointer-events: none;
            }
            
            .logo-item:hover::after {
                opacity: 1;
            }
            
            /* ===== GAMIFICATION SECTION ===== */
            .gamification-section {
                padding: 100px 20px;
                background: var(--navy-dark);
            }
            
            .score-container {
                display: grid;
                grid-template-columns: 1fr;
                gap: 40px;
                max-width: 1200px;
                margin: 0 auto;
            }
            
            @media (min-width: 768px) {
                .score-container {
                    grid-template-columns: 1fr 1fr;
                }
            }
            
            .score-card {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 40px;
            }
            
            .score-circle {
                text-align: center;
                margin-bottom: 40px;
            }
            
            .circle-progress {
                font-family: var(--font-orbitron);
                font-size: 4rem;
                color: var(--neon-green);
                position: relative;
                width: 200px;
                height: 200px;
                margin: 0 auto 20px;
                display: flex;
                align-items: center;
                justify-content: center;
            }
            
            .circle-progress::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                border-radius: 50%;
                background: conic-gradient(var(--neon-green) 0% 87%, rgba(255, 255, 255, 0.1) 87% 100%);
                mask: radial-gradient(circle at center, transparent 65%, black 66%);
                -webkit-mask: radial-gradient(circle at center, transparent 65%, black 66%);
            }
            
            .circle-label {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.2rem;
            }
            
            .score-breakdown {
                display: flex;
                flex-direction: column;
                gap: 20px;
            }
            
            .breakdown-item {
                display: flex;
                align-items: center;
                gap: 20px;
            }
            
            .breakdown-label {
                font-size: 1rem;
                color: rgba(255, 255, 255, 0.7);
                width: 120px;
            }
            
            .breakdown-score {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                width: 60px;
                font-size: 1.2rem;
            }
            
            .breakdown-bar {
                flex: 1;
                height: 10px;
                background: rgba(255, 255, 255, 0.1);
                border-radius: 5px;
                overflow: hidden;
            }
            
            .achievements {
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 40px;
            }
            
            .achievements-title {
                font-family: var(--font-orbitron);
                color: var(--neon-cyan);
                font-size: 1.8rem;
                margin-bottom: 30px;
                text-align: center;
            }
            
            .xp-bar {
                height: 20px;
                background: rgba(255, 255, 255, 0.1);
                border-radius: 10px;
                margin-bottom: 40px;
                overflow: hidden;
                position: relative;
            }
            
            .xp-progress {
                height: 100%;
                background: var(--gradient-cyber);
                border-radius: 10px;
            }
            
            .xp-text {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-family: var(--font-space);
                font-size: 0.9rem;
                color: white;
            }
            
            .badges-grid {
                display: grid;
                grid-template-columns: repeat(5, 1fr);
                gap: 20px;
            }
            
            .badge {
                aspect-ratio: 1;
                border-radius: 15px;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 2rem;
                position: relative;
                cursor: help;
                transition: var(--transition-premium);
            }
            
            .badge.earned {
                background: rgba(0, 245, 255, 0.1);
                border: 2px solid var(--neon-cyan);
                color: var(--neon-cyan);
            }
            
            .badge.locked {
                background: rgba(136, 146, 176, 0.1);
                border: 2px solid #8892B0;
                color: #8892B0;
            }
            
            .badge:hover {
                transform: scale(1.1);
            }
            
            .badge::after {
                content: attr(data-tooltip);
                position: absolute;
                bottom: 100%;
                left: 50%;
                transform: translateX(-50%);
                background: rgba(0, 0, 0, 0.9);
                border: 1px solid var(--neon-cyan);
                padding: 8px 12px;
                border-radius: 5px;
                font-size: 0.8rem;
                white-space: nowrap;
                opacity: 0;
                transition: opacity 0.3s;
                pointer-events: none;
            }
            
            .badge:hover::after {
                opacity: 1;
            }
            
            /* ===== CONTACT SECTION ===== */
            .contact-section {
                padding: 100px 20px;
                background: var(--black-primary);
            }
            
            .contact-card {
                max-width: 1200px;
                margin: 0 auto;
                background: rgba(255, 255, 255, 0.05);
                backdrop-filter: var(--glass-blur);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 20px;
                padding: 60px;
                text-align: center;
                position: relative;
                overflow: hidden;
            }
            
            .contact-header {
                margin-bottom: 50px;
            }
            
            .contact-title {
                font-family: var(--font-orbitron);
                font-size: 2.5rem;
                color: var(--neon-cyan);
                margin-bottom: 20px;
            }
            
            .contact-subtitle {
                color: rgba(255, 255, 255, 0.7);
                font-size: 1.2rem;
