            .contact-info {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 40px;
                margin-bottom: 50px;
            }
            
            .info-item {
                display: flex;
                align-items: center;
                gap: 20px;
                padding: 25px;
                background: rgba(255, 255, 255, 0.03);
                border-radius: 15px;
                border: 1px solid rgba(255, 255, 255, 0.1);
                transition: var(--transition-premium);
            }
            
            .info-item:hover {
                border-color: var(--neon-cyan);
                transform: translateY(-5px);
            }
            
            .info-icon {
                font-size: 2rem;
                color: var(--neon-cyan);
            }
            
            .info-content {
                text-align: left;
            }
            
            .info-label {
                font-family: var(--font-space);
                font-size: 0.9rem;
                color: rgba(255, 255, 255, 0.6);
                margin-bottom: 8px;
                text-transform: uppercase;
                letter-spacing: 1px;
            }
            
            .info-value {
                font-family: var(--font-orbitron);
                color: white;
                font-size: 1.3rem;
            }
            
            .contact-actions {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 25px;
            }
            
            .contact-btn {
                padding: 20px 30px;
                border: none;
                border-radius: 12px;
                font-family: var(--font-orbitron);
                font-size: 1rem;
                font-weight: 600;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 15px;
                transition: var(--transition-premium);
            }
            
            .contact-btn.emergency {
                background: var(--gradient-danger);
                color: white;
            }
            
            .contact-btn.whatsapp {
                background: linear-gradient(135deg, #25D366, #128C7E);
                color: white;
            }
            
            .contact-btn.schedule {
                background: transparent;
                border: 2px solid var(--neon-cyan);
                color: var(--neon-cyan);
            }
            
            .contact-btn:hover {
                transform: translateY(-5px);
                box-shadow: 0 15px 40px rgba(0, 245, 255, 0.3);
            }
            
            /* ===== FLOATING BUTTONS ===== */
            .floating-terminal {
                position: fixed;
                bottom: 100px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: var(--neon-cyan);
                border: none;
                border-radius: 50%;
                color: var(--black-primary);
                font-size: 1.5rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 100;
                box-shadow: 0 0 20px rgba(0, 245, 255, 0.5);
                animation: floatBtn 3s ease-in-out infinite;
                transition: var(--transition-premium);
            }
            
            .floating-terminal:hover {
                transform: scale(1.1);
                box-shadow: 0 0 30px rgba(0, 245, 255, 0.7);
            }
            
            .floating-emergency {
                position: fixed;
                bottom: 180px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: var(--warning-red);
                border: none;
                border-radius: 50%;
                color: white;
                font-size: 1.5rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 100;
                box-shadow: 0 0 20px rgba(255, 0, 51, 0.5);
                animation: floatBtn 3s ease-in-out infinite reverse;
                transition: var(--transition-premium);
            }
            
            .floating-emergency:hover {
                transform: scale(1.1);
                box-shadow: 0 0 30px rgba(255, 0, 51, 0.7);
            }
            
            .floating-theme {
                position: fixed;
                bottom: 260px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: var(--hacker-purple);
                border: none;
                border-radius: 50%;
                color: white;
                font-size: 1.5rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 100;
                box-shadow: 0 0 20px rgba(157, 0, 255, 0.5);
                animation: floatBtn 3s ease-in-out infinite;
                animation-delay: 1s;
                transition: var(--transition-premium);
            }
            
            .floating-theme:hover {
                transform: scale(1.1);
                box-shadow: 0 0 30px rgba(157, 0, 255, 0.7);
            }
            
            /* ===== EASTER EGG ===== */
            .easter-egg {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0, 0, 0, 0.9);
                z-index: 10000;
                display: none;
                align-items: center;
                justify-content: center;
            }
            
            .egg-content {
                background: rgba(10, 26, 47, 0.95);
                border: 3px solid var(--neon-green);
                border-radius: 10px;
                padding: 40px;
                text-align: center;
                max-width: 500px;
                animation: eggReveal 0.5s ease-out;
            }
            
            .egg-content h3 {
                font-family: var(--font-orbitron);
                color: var(--neon-green);
                font-size: 1.5rem;
                margin-bottom: 20px;
            }
            
            .egg-content p {
                color: #8892B0;
                margin-bottom: 30px;
            }
            
            .egg-content button {
                background: var(--neon-green);
                border: none;
                color: var(--black-primary);
                padding: 12px 30px;
                border-radius: 5px;
                font-family: var(--font-orbitron);
                font-size: 1rem;
                cursor: pointer;
            }
            
            /* ===== SOUND CONTROLS ===== */
            .sound-controls {
                position: fixed;
                bottom: 20px;
                left: 20px;
                z-index: 100;
            }
            
            .sound-btn {
                width: 50px;
                height: 50px;
                background: rgba(0, 245, 255, 0.1);
                border: 1px solid var(--neon-cyan);
                border-radius: 50%;
                color: var(--neon-cyan);
                font-size: 1.2rem;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                transition: var(--transition-premium);
            }
            
            .sound-btn:hover {
                background: rgba(0, 245, 255, 0.2);
                transform: scale(1.1);
            }
            
            /* ===== ANIMATIONS ===== */
            @keyframes ringPulse {
                0%, 100% { transform: scale(1); opacity: 1; }
                50% { transform: scale(1.1); opacity: 0.7; }
            }
            
            @keyframes corePulse {
                0%, 100% { transform: translate(-50%, -50%) scale(1); }
                50% { transform: translate(-50%, -50%) scale(1.2); }
            }
            
            @keyframes logAppear {
                from { opacity: 0; transform: translateY(10px); }
                to { opacity: 1; transform: translateY(0); }
            }
            
            @keyframes emergencyPulse {
                from { box-shadow: 0 0 30px rgba(255, 0, 51, 0.5); }
                to { box-shadow: 0 0 60px rgba(255, 0, 51, 0.8); }
            }
            
            @keyframes blink {
                0%, 100% { opacity: 1; }
                50% { opacity: 0; }
            }
            
            @keyframes floatParticle {
                0% {
                    transform: translateY(0) translateX(0);
                    opacity: 0;
                }
                10% {
                    opacity: 1;
                }
                90% {
                    opacity: 1;
                }
                100% {
                    transform: translateY(-100vh) translateX(100px);
                    opacity: 0;
                }
            }
            
            @keyframes floatDot {
                0% {
                    transform: translateY(0) translateX(0);
                }
                25% {
                    transform: translateY(-25vh) translateX(50px);
                }
                50% {
                    transform: translateY(-50vh) translateX(-25px);
                }
                75% {
                    transform: translateY(-75vh) translateX(75px);
                }
                100% {
                    transform: translateY(-100vh) translateX(0);
                }
            }
            
            @keyframes scanMove {
                0% {
                    top: 0;
                }
                100% {
                    top: 100%;
                }
            }
            
            @keyframes flarePulse {
                0% {
                    opacity: 0.05;
                    transform: scale(1);
                }
                100% {
                    opacity: 0.15;
                    transform: scale(1.1);
                }
            }
            
            @keyframes parallaxMove {
                0% {
                    background-position: 0 0;
                }
                100% {
                    background-position: 100px 100px;
                }
            }
            
            @keyframes badgeSlide {
                0% {
                    left: -100%;
                }
                100% {
                    left: 100%;
                }
            }
            
            @keyframes pulse {
                0%, 100% { opacity: 1; transform: scale(1); }
                50% { opacity: 0.5; transform: scale(1.05); }
            }
            
            @keyframes attackLine {
                0% { opacity: 0; width: 0; }
                50% { opacity: 1; }
                100% { opacity: 0; width: 150px; }
            }
            
            @keyframes flowLine {
                from { transform: translateX(-100%); }
                to { transform: translateX(100%); }
            }
            
            @keyframes botPulse {
                0%, 100% { transform: scale(1); }
                50% { transform: scale(1.2); }
            }
            
            @keyframes btnShine {
                0% { left: -100%; }
                100% { left: 100%; }
            }
            
            @keyframes alertPulse {
                0%, 100% { transform: scale(1); }
                50% { transform: scale(1.2); }
            }
            
            @keyframes logScroll {
                0% { transform: translateY(100%); }
                100% { transform: translateY(-100%); }
            }
            
            @keyframes floatBtn {
                0%, 100% { transform: translateY(0); }
                50% { transform: translateY(-10px); }
            }
            
            @keyframes eggReveal {
                from { transform: scale(0) rotate(-180deg); }
                to { transform: scale(1) rotate(0); }
            }
            
            @keyframes glitch {
                0% { transform: translate(0); }
                20% { transform: translate(-2px, 2px); }
                40% { transform: translate(-2px, -2px); }
                60% { transform: translate(2px, 2px); }
                80% { transform: translate(2px, -2px); }
                100% { transform: translate(0); }
            }
            
            /* ===== RESPONSIVE ===== */
            @media (max-width: 1024px) {
                .hero-title {
                    font-size: clamp(2.5rem, 5vw, 4rem);
                }
                
                .projects-grid {
                    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                }
                
                .dashboard-grid {
                    grid-template-columns: 1fr;
                }
                
                .contact-info {
                    grid-template-columns: 1fr;
                }
                
                .contact-actions {
                    grid-template-columns: 1fr;
                }
            }
            
            @media (max-width: 768px) {
                .nav-links, .nav-right {
                    display: none;
                }
                
                .mobile-menu-btn {
                    display: block;
                }
                
                .hero-title {
                    font-size: 2.5rem;
                }
                
                .hero-subtitle {
                    font-size: 1.1rem;
                }
                
                .hero-cta {
                    flex-direction: column;
                    align-items: center;
                }
                
                .cta-btn {
                    width: 100%;
                    max-width: 300px;
                }
                
                .monitor-stats {
                    grid-template-columns: 1fr;
                }
                
                .trust-indicators {
                    flex-direction: column;
                    gap: 20px;
                }
                
                .toolkit-grid {
                    grid-template-columns: 1fr;
                }
                
                .projects-grid {
                    grid-template-columns: 1fr;
                }
                
                .project-stats {
                    grid-template-columns: 1fr;
                }
                
                .trust-grid {
                    grid-template-columns: 1fr;
                }
                
                .score-container {
                    grid-template-columns: 1fr;
                }
                
                .badges-grid {
                    grid-template-columns: repeat(3, 1fr);
                }
                
                .contact-card {
                    padding: 30px 20px;
                }
                
                .contact-title {
                    font-size: 2rem;
                }
                
                .floating-terminal, 
                .floating-emergency, 
                .floating-theme {
                    width: 50px;
                    height: 50px;
                    font-size: 1.2rem;
                }
                
                .floating-emergency {
                    bottom: 160px;
                }
                
                .floating-theme {
                    bottom: 220px;
                }
            }
            
            @media (max-width: 480px) {
                .hero-title {
                    font-size: 2rem;
                }
                
                .section-title {
                    font-size: 2rem;
                }
                
                .project-card {
                    padding: 25px 20px;
                }
                
                .contact-info {
                    grid-template-columns: 1fr;
                }
            }
            
            /* ===== PERFORMANCE ===== */
            @media (prefers-reduced-motion: reduce) {
                * {
                    animation-duration: 0.01ms !important;
                    animation-iteration-count: 1 !important;
                    transition-duration: 0.01ms !important;
                }
            }
            
            /* ===== UTILITY CLASSES ===== */
            .animate-in {
                animation: fadeInUp 0.6s ease-out forwards;
            }
            
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(30px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
            
            .tooltip {
                position: absolute;
                background: rgba(0, 0, 0, 0.9);
                color: white;
                padding: 8px 12px;
                border-radius: 4px;
                font-size: 0.8rem;
                white-space: nowrap;
                z-index: 1000;
                pointer-events: none;
                border: 1px solid var(--neon-cyan);
            }
            
            /* ===== ACCESSIBILITY ===== */
            .sr-only {
                position: absolute;
                width: 1px;
                height: 1px;
                padding: 0;
                margin: -1px;
                overflow: hidden;
                clip: rect(0, 0, 0, 0);
                white-space: nowrap;
                border: 0;
            }
            
            /* ===== CUSTOM SCROLLBAR ===== */
            ::-webkit-scrollbar {
                width: 10px;
            }
            
            ::-webkit-scrollbar-track {
                background: var(--black-primary);
            }
            
            ::-webkit-scrollbar-thumb {
                background: var(--neon-cyan);
                border-radius: 5px;
            }
            
            ::-webkit-scrollbar-thumb:hover {
                background: var(--neon-green);
            }
            
            /* ===== SELECTION ===== */
            ::selection {
                background: rgba(0, 245, 255, 0.3);
                color: white;
            }
            
            /* ===== FOCUS STATES ===== */
            :focus {
                outline: 2px solid var(--neon-cyan);
                outline-offset: 2px;
            }
            
            :focus:not(:focus-visible) {
                outline: none;
            }
            
            /* ===== PRINT STYLES ===== */
            @media print {
                .cyber-nav,
                .floating-terminal,
                .floating-emergency,
                .floating-theme,
                .sound-controls {
                    display: none !important;
                }
                
                body {
                    background: white !important;
                    color: black !important;
                }
                
                .cyber-hero {
                    min-height: auto;
                    padding: 50px 20px;
                }
                
                .section-container {
                    max-width: 100%;
                }
                
                .tool-card,
                .project-card,
                .dashboard-card,
                .trust-badge,
                .score-card,
                .achievements,
                .contact-card {
                    break-inside: avoid;
                    border: 1px solid #ccc !important;
                    box-shadow: none !important;
                }
            }
        </style>
        
        <script>
            // Cyber Security Main Script
            document.addEventListener('DOMContentLoaded', function() {
                // Initialize all systems
                initPreloader();
                initCursor();
                initPremiumBackground();
                initTerminal();
                initAnimations();
                initStats();
                initDDOSSimulation();
                initAttackMap();
                initKonamiCode();
                initSoundSystem();
                initScrollAnimations();
                initThemeToggle();
                initTooltips();
                initGamification();
                initMobileMenu();
                initEmergencySystem();
                initFloatingElements();
                initSoundControls();
                initEasterEgg();
                initPerformanceMonitor();
                initProjectsSection();
                initThreatMonitor();
                initBlockchainVisual();
                initPredictionGraph();
                initWorldMap();
                initLiveLogs();
                initScrollEffects();
                initParallaxEffects();
                initInteractiveElements();
            });

            // ===== SYSTEM INITIALIZATION FUNCTIONS =====

            // Initialize Premium Preloader
            function initPreloader() {
                const preloader = document.getElementById('cyberPreloader');
                const progressBar = document.querySelector('.progress-bar');
                const progressText = document.querySelector('.progress-text');
                
                if (!preloader) return;
                
                let progress = 0;
                const interval = setInterval(() => {
                    progress += Math.random() * 15;
                    if (progress > 100) progress = 100;
                    
                    progressBar.style.width = progress + '%';
                    progressText.textContent = Math.floor(progress) + '%';
                    
                    if (progress >= 100) {
                        clearInterval(interval);
                        setTimeout(() => {
                            preloader.style.opacity = '0';
                            setTimeout(() => {
                                preloader.style.display = 'none';
                                document.body.style.overflow = 'auto';
                            }, 500);
                        }, 500);
                    }
                }, 100);
            }

            // Initialize Custom Cursor
            function initCursor() {
                const cursor = document.getElementById('cyberCursor');
                const glow = document.getElementById('cursorGlow');
                
                if (!cursor || !glow) return;
                
                let mouseX = 0, mouseY = 0;
                let cursorX = 0, cursorY = 0;
                let glowX = 0, glowY = 0;
                
                document.addEventListener('mousemove', (e) => {
                    mouseX = e.clientX;
                    mouseY = e.clientY;
                });

                // Interactive elements cursor effects
                const interactiveElements = document.querySelectorAll('button, a, .tool-card, .project-card, .dashboard-card, .trust-badge');
                
                interactiveElements.forEach(el => {
                    el.addEventListener('mouseenter', () => {
                        cursor.style.width = '40px';
                        cursor.style.height = '40px';
                        cursor.style.borderColor = '#00FF9C';
                        glow.style.opacity = '0.5';
                    });
                    
                    el.addEventListener('mouseleave', () => {
                        cursor.style.width = '20px';
                        cursor.style.height = '20px';
                        cursor.style.borderColor = '#00F5FF';
                        glow.style.opacity = '0.3';
                    });
                });

                // Emergency button special cursor
                const emergencyBtns = document.querySelectorAll('.cta-btn.danger, .mobile-emergency, .floating-emergency');
                emergencyBtns.forEach(btn => {
                    btn.addEventListener('mouseenter', () => {
                        cursor.style.borderColor = '#FF0033';
                        cursor.style.animation = 'pulse 0.5s infinite';
                    });
                    
                    btn.addEventListener('mouseleave', () => {
                        cursor.style.borderColor = '#00F5FF';
                        cursor.style.animation = '';
                    });
                });

                function animateCursor() {
                    cursorX += (mouseX - cursorX) * 0.15;
                    cursorY += (mouseY - cursorY) * 0.15;
                    
                    glowX += (mouseX - glowX) * 0.1;
                    glowY += (mouseY - glowY) * 0.1;
                    
                    cursor.style.left = cursorX + 'px';
                    cursor.style.top = cursorY + 'px';
                    
                    glow.style.left = glowX + 'px';
                    glow.style.top = glowY + 'px';
                    
                    requestAnimationFrame(animateCursor);
                }
                
                animateCursor();
            }

            // Initialize Premium Background Effects
            function initPremiumBackground() {
                createParticles();
                createDataDots();
                animateScanLines();
                animateFlares();
            }

            function createParticles() {
                const container = document.querySelector('.particles-container');
                if (!container) return;
                
                const particleCount = 150;
                
                for (let i = 0; i < particleCount; i++) {
                    const particle = document.createElement('div');
                    particle.className = 'particle';
                    
                    // Random position
                    particle.style.left = Math.random() * 100 + '%';
                    particle.style.top = Math.random() * 100 + '%';
                    
                    // Random size
                    const size = 1 + Math.random() * 3;
                    particle.style.width = size + 'px';
                    particle.style.height = size + 'px';
                    
                    // Random color with cyber palette
                    const colors = ['#00F5FF', '#00FF9C', '#007BFF', '#9D00FF'];
                    particle.style.background = colors[Math.floor(Math.random() * colors.length)];
                    
                    // Random opacity
                    particle.style.opacity = 0.1 + Math.random() * 0.3;
                    
                    // Random animation delay and duration
                    particle.style.animationDelay = Math.random() * 20 + 's';
                    particle.style.animationDuration = 15 + Math.random() * 10 + 's';
                    
                    container.appendChild(particle);
                }
            }

            function createDataDots() {
                const container = document.querySelector('.data-dots');
                if (!container) return;
                
                const dotCount = 75;
                
                for (let i = 0; i < dotCount; i++) {
                    const dot = document.createElement('div');
                    dot.className = 'data-dot';
                    
                    // Random position
                    dot.style.left = Math.random() * 100 + '%';
                    dot.style.top = Math.random() * 100 + '%';
                    
                    // Random size
                    const size = 2 + Math.random() * 6;
                    dot.style.width = size + 'px';
                    dot.style.height = size + 'px';
                    
                    // Random opacity
                    dot.style.opacity = 0.1 + Math.random() * 0.4;
                    
                    // Random animation delay
                    dot.style.animationDelay = Math.random() * 15 + 's';
                    
                    container.appendChild(dot);
                }
            }

            function animateScanLines() {
                const scanLines = document.querySelectorAll('.scan-line');
                scanLines.forEach((line, index) => {
                    line.style.animationDelay = (index * 2) + 's';
                });
            }

            function animateFlares() {
                const flares = document.querySelectorAll('.flare');
                flares.forEach((flare, index) => {
