                    hack: 'Access denied. Unauthorized command detected.\n' +
                        'Security protocols engaged.',
                    
                    sudo: 'You are already root user.',
                    
                    ls: 'Available files:\n' +
                        'system.log  security.md  protocols/\n' +
                        'firewall.conf  keys/  backups/',
                    
                    pwd: '/root/cybershield/secure',
                    
                    project: (args) => {
                        const projectNum = parseInt(args);
                        const projects = [
                            'Global Bank Security: Complete infrastructure modernization for multinational bank',
                            'Hospital Network: HIPAA-compliant security for healthcare provider network',
                            'E-commerce Fraud: Real-time fraud detection system for online retailer',
                            'Government Agency: Classified information protection for government',
                            'University Network: Protection for 50,000+ users across campus',
                            'Industrial IoT: OT/IT security convergence for manufacturing'
                        ];
                        return projects[projectNum - 1] || 'Invalid project number';
                    }
                };
                
                input.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') {
                        const fullCommand = input.value.trim();
                        const parts = fullCommand.split(' ');
                        const command = parts[0].toLowerCase();
                        const args = parts.slice(1).join(' ');
                        
                        input.value = '';
                        
                        // Add command to output
                        output.innerHTML += `<div class="output-line">root@cybershield:~$ ${fullCommand}</div>`;
                        
                        // Execute command
                        if (commands[command]) {
                            if (typeof commands[command] === 'function') {
                                const result = args ? commands[command](args) : commands[command]();
                                if (result) {
                                    output.innerHTML += `<div class="output-line">${result}</div>`;
                                }
                            } else {
                                output.innerHTML += `<div class="output-line">${commands[command]}</div>`;
                            }
                        } else {
                            output.innerHTML += `<div class="output-line">Command not found: ${command}. Type 'help' for available commands.</div>`;
                        }
                        
                        // Scroll to bottom
                        output.scrollTop = output.scrollHeight;
                    }
                });

                // Add command history
                let commandHistory = [];
                let historyIndex = -1;
                
                input.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowUp') {
                        if (historyIndex < commandHistory.length - 1) {
                            historyIndex++;
                            input.value = commandHistory[historyIndex];
                        }
                        e.preventDefault();
                    } else if (e.key === 'ArrowDown') {
                        if (historyIndex > 0) {
                            historyIndex--;
                            input.value = commandHistory[historyIndex];
                        } else {
                            input.value = '';
                            historyIndex = -1;
                        }
                        e.preventDefault();
                    } else if (e.key === 'Enter' && input.value.trim()) {
                        commandHistory.unshift(input.value.trim());
                        historyIndex = -1;
                    }
                });
            }

            // Open Terminal Function
            window.openTerminal = function() {
                const terminal = document.getElementById('cyberTerminal');
                if (terminal) {
                    terminal.style.display = 'flex';
                    document.getElementById('terminalInput').focus();
                    
                    // Play terminal sound
                    if (window.terminalSound) {
                        terminalSound.play();
                    }
                }
            };

            // Close Terminal Function
            window.closeTerminal = function() {
                const terminal = document.getElementById('cyberTerminal');
                if (terminal) {
                    terminal.style.display = 'none';
                }
            };

            // Initialize Animations
            function initAnimations() {
                // Animate counters
                const statValues = document.querySelectorAll('.stat-value[data-count]');
                statValues.forEach(stat => {
                    const target = parseFloat(stat.getAttribute('data-count'));
                    animateCounter(stat, target);
                });

                // Animate progress bars
                const progressBars = document.querySelectorAll('.bar-fill');
                progressBars.forEach(bar => {
                    const width = bar.style.width;
                    bar.style.width = '0';
                    setTimeout(() => {
                        bar.style.width = width;
                        bar.style.transition = 'width 1.5s ease-out';
                    }, 500);
                });

                // Animate security score
                const securityScore = document.getElementById('securityScore');
                if (securityScore) {
                    const target = parseInt(securityScore.getAttribute('data-value'));
                    animateCounter(securityScore, target);
                }

                // Add animation to tool cards
                const toolCards = document.querySelectorAll('.tool-card');
                toolCards.forEach((card, index) => {
                    card.style.animationDelay = (index * 0.1) + 's';
                    card.classList.add('animate-in');
                });

                // Add animation to project cards
                const projectCards = document.querySelectorAll('.project-card');
                projectCards.forEach((card, index) => {
                    card.style.animationDelay = (index * 0.15) + 's';
                    card.classList.add('animate-in');
                });
            }

            // Counter Animation Function
            function animateCounter(element, target) {
                let current = 0;
                const increment = target / 50;
                const isPercentage = element.textContent.includes('%');
                
                const timer = setInterval(() => {
                    current += increment;
                    if (current >= target) {
                        current = target;
                        clearInterval(timer);
                    }
                    
                    if (isPercentage) {
                        element.textContent = current.toFixed(1) + '%';
                    } else {
                        element.textContent = Math.floor(current).toLocaleString();
                    }
                }, 30);
            }

            // Initialize Real-time Stats
            function initStats() {
                // Update threat level randomly
                setInterval(() => {
                    const threatLevels = ['LOW', 'MEDIUM', 'HIGH'];
                    const colors = ['#00FF9C', '#FFA500', '#FF0033'];
                    const random = Math.random();
                    
                    let level, color;
                    if (random < 0.7) {
                        level = 'LOW';
                        color = colors[0];
                    } else if (random < 0.9) {
                        level = 'MEDIUM';
                        color = colors[1];
                    } else {
                        level = 'HIGH';
                        color = colors[2];
                    }
                    
                    const threatIndicator = document.querySelector('.threat-indicator');
                    const threatStatus = document.querySelector('.threat-status');
                    
                    if (threatIndicator && threatStatus) {
                        threatIndicator.style.background = color;
                        threatIndicator.style.boxShadow = `0 0 10px ${color}`;
                        threatStatus.textContent = level;
                        threatStatus.style.color = color;
                        
                        // Add notification for high threat
                        if (level === 'HIGH') {
                            showNotification('🚨 HIGH THREAT LEVEL DETECTED', 'warning');
                        }
                    }
                }, 10000);

                // Update live stats
                setInterval(() => {
                    const statValues = document.querySelectorAll('.stat-value[data-count]');
                    statValues.forEach(stat => {
                        const current = parseInt(stat.textContent.replace(/,/g, ''));
                        const target = parseInt(stat.getAttribute('data-count'));
                        const variation = Math.floor(Math.random() * 10) - 5;
                        const newValue = Math.max(0, current + variation);
                        
                        if (stat.textContent.includes('%')) {
                            stat.textContent = Math.min(100, Math.max(0, newValue)).toFixed(1) + '%';
                        } else {
                            stat.textContent = newValue.toLocaleString();
                        }
                    });
                }, 5000);
            }

            // Initialize DDoS Simulation
            function initDDOSSimulation() {
                let isSimulating = false;
                let simulationInterval;
                
                window.startDDOSSimulation = function() {
                    if (isSimulating) return;
                    isSimulating = true;
                    
                    const ddosBtn = document.querySelector('.ddos-btn');
                    if (ddosBtn) {
                        ddosBtn.innerHTML = '<i class="fas fa-stop"></i> STOP ATTACK';
                        ddosBtn.onclick = stopDDOSSimulation;
                    }
                    
                    // Animate bot nodes
                    const botNodes = document.querySelectorAll('.bot-node');
                    botNodes.forEach(node => {
                        node.style.animation = 'botPulse 0.5s infinite';
                    });
                    
                    // Animate flow lines
                    const flowLines = document.querySelectorAll('.flow-line');
                    flowLines.forEach(line => {
                        line.style.animation = 'flowLine 0.5s infinite linear';
                    });
                    
                    // Update stats
                    let requests = 2483;
                    let power = 4.2;
                    
                    simulationInterval = setInterval(() => {
                        requests += Math.floor(Math.random() * 100) - 25;
                        power += (Math.random() * 0.2) - 0.1;
                        power = Math.max(3.5, Math.min(5.0, power));
                        
                        const stats = document.querySelector('.ddos-stats');
                        if (stats) {
                            stats.innerHTML = `<span>BOTNET: ${requests.toLocaleString()} NODES</span><span>POWER: ${power.toFixed(1)} TB/s</span>`;
                        }
                    }, 500);
                };
                
                window.stopDDOSSimulation = function() {
                    isSimulating = false;
                    
                    const ddosBtn = document.querySelector('.ddos-btn');
                    if (ddosBtn) {
                        ddosBtn.innerHTML = '<i class="fas fa-play"></i> SIMULATE ATTACK';
                        ddosBtn.onclick = startDDOSSimulation;
                    }
                    
                    const botNodes = document.querySelectorAll('.bot-node');
                    botNodes.forEach(node => {
                        node.style.animation = '';
                    });
                    
                    const flowLines = document.querySelectorAll('.flow-line');
                    flowLines.forEach(line => {
                        line.style.animation = '';
                    });
                    
                    if (simulationInterval) {
                        clearInterval(simulationInterval);
                    }
                };
            }

            // Initialize Attack Map
            function initAttackMap() {
                let attackSimulationInterval;
                
                window.startAttackSimulation = function() {
                    const attackLines = document.querySelectorAll('.attack-line');
                    attackLines.forEach(line => {
                        line.style.animation = 'attackLine 2s infinite';
                    });
                    
                    const attackNodes = document.querySelectorAll('.attack-node');
                    attackNodes.forEach(node => {
                        node.style.animation = 'pulse 1s infinite';
                    });
                    
                    // Add random attacks
                    attackSimulationInterval = setInterval(() => {
                        if (Math.random() < 0.3) {
                            addRandomAttack();
                        }
                    }, 2000);
                    
                    // Update stats
                    const mapStats = document.querySelectorAll('.map-stat .stat-value');
                    if (mapStats.length >= 3) {
                        setInterval(() => {
                            const attacks = 1248 + Math.floor(Math.random() * 100);
                            const countries = 42 + Math.floor(Math.random() * 5);
                            const damage = 4.2 + Math.random() * 0.5;
                            
                            mapStats[0].textContent = attacks.toLocaleString();
                            mapStats[1].textContent = countries.toString();
                            mapStats[2].textContent = '$' + damage.toFixed(1) + 'M';
                        }, 3000);
                    }
                };
                
                window.pauseAttackSimulation = function() {
                    const attackLines = document.querySelectorAll('.attack-line');
                    attackLines.forEach(line => {
                        line.style.animation = '';
                    });
                    
                    const attackNodes = document.querySelectorAll('.attack-node');
                    attackNodes.forEach(node => {
                        node.style.animation = '';
                    });
                    
                    if (attackSimulationInterval) {
                        clearInterval(attackSimulationInterval);
                    }
                };
                
                function addRandomAttack() {
                    const worldMap = document.getElementById('worldMap');
                    if (!worldMap) return;
                    
                    const attack = document.createElement('div');
                    attack.className = 'random-attack';
                    attack.style.position = 'absolute';
                    attack.style.left = Math.random() * 90 + '%';
                    attack.style.top = Math.random() * 90 + '%';
                    attack.style.width = '8px';
                    attack.style.height = '8px';
                    attack.style.background = '#FF0033';
                    attack.style.borderRadius = '50%';
                    attack.style.boxShadow = '0 0 15px #FF0033';
                    attack.style.animation = 'pulse 1s infinite';
                    attack.style.zIndex = '10';
                    
                    worldMap.appendChild(attack);
                    
                    // Remove after animation
                    setTimeout(() => {
                        if (attack.parentNode) {
                            attack.parentNode.removeChild(attack);
                        }
                    }, 3000);
                }
                
                // Start simulation after delay
                setTimeout(startAttackSimulation, 2000);
            }

            // Initialize Projects Section
            function initProjectsSection() {
                const projectCards = document.querySelectorAll('.project-card');
                
                projectCards.forEach(card => {
                    // Add hover effects
                    card.addEventListener('mouseenter', () => {
                        card.style.transform = 'translateY(-10px) scale(1.02)';
                        card.style.boxShadow = '0 25px 50px rgba(0, 245, 255, 0.3)';
                        
                        // Add subtle glow effect
                        const glow = document.createElement('div');
                        glow.className = 'project-glow';
                        glow.style.position = 'absolute';
                        glow.style.top = '0';
                        glow.style.left = '0';
                        glow.style.width = '100%';
                        glow.style.height = '100%';
                        glow.style.background = 'radial-gradient(circle at center, rgba(0,245,255,0.1), transparent)';
                        glow.style.borderRadius = '20px';
                        glow.style.zIndex = '-1';
                        card.appendChild(glow);
                    });
                    
                    card.addEventListener('mouseleave', () => {
                        card.style.transform = 'translateY(0) scale(1)';
                        card.style.boxShadow = '';
                        
                        // Remove glow effect
                        const glow = card.querySelector('.project-glow');
                        if (glow) {
                            glow.remove();
                        }
                    });
                    
                    // Add click effect for details
                    card.addEventListener('click', (e) => {
                        if (!e.target.closest('button')) {
                            const title = card.querySelector('.project-title').textContent;
                            const desc = card.querySelector('.project-desc').textContent;
                            showProjectDetails(title, desc);
                        }
                    });
                });
                
                // Project CTA button
                const projectCtaBtn = document.querySelector('.project-cta-btn');
                if (projectCtaBtn) {
                    projectCtaBtn.addEventListener('click', () => {
                        openTerminal();
                        // Auto-type consultation command
                        setTimeout(() => {
                            const input = document.getElementById('terminalInput');
                            if (input) {
                                input.value = 'project consultation';
                                input.dispatchEvent(new KeyboardEvent('keypress', {key: 'Enter'}));
                            }
                        }, 500);
                    });
                }
            }

            // Show Project Details Modal
