                });
                
                // Close modal on outside click
                modal.addEventListener('click', (e) => {
                    if (e.target === modal) {
                        modal.remove();
                    }
                });
                
                // CTA button action
                modal.querySelector('.modal-cta').addEventListener('click', () => {
                    modal.remove();
                    openTerminal();
                });
            }

            // Initialize Konami Code (Easter Egg)
            function initKonamiCode() {
                const konamiCode = [
                    'ArrowUp', 'ArrowUp', 
                    'ArrowDown', 'ArrowDown', 
                    'ArrowLeft', 'ArrowRight', 
                    'ArrowLeft', 'ArrowRight', 
                    'b', 'a'
                ];
                let konamiIndex = 0;
                
                document.addEventListener('keydown', (e) => {
                    if (e.key === konamiCode[konamiIndex]) {
                        konamiIndex++;
                        if (konamiIndex === konamiCode.length) {
                            activateEasterEgg();
                            konamiIndex = 0;
                        }
                    } else {
                        konamiIndex = 0;
                    }
                });
            }

            function activateEasterEgg() {
                const easterEgg = document.getElementById('easterEgg');
                if (easterEgg) {
                    easterEgg.style.display = 'flex';
                    
                    // Add special effects
                    document.body.style.overflow = 'hidden';
                    
                    // Play victory sound
                    if (window.howler) {
                        const victorySound = new Howl({
                            src: ['https://assets.mixkit.co/sfx/preview/mixkit-winning-chimes-2015.mp3'],
                            volume: 0.5
                        });
                        victorySound.play();
                    }
                    
                    // Add particle explosion
                    createEasterEggParticles();
                }
            }

            function createEasterEggParticles() {
                const container = document.querySelector('body');
                const colors = ['#00F5FF', '#00FF9C', '#9D00FF', '#FF0033', '#FFD700'];
                
                for (let i = 0; i < 100; i++) {
                    const particle = document.createElement('div');
                    particle.style.position = 'fixed';
                    particle.style.width = '10px';
                    particle.style.height = '10px';
                    particle.style.background = colors[Math.floor(Math.random() * colors.length)];
                    particle.style.borderRadius = '50%';
                    particle.style.left = '50%';
                    particle.style.top = '50%';
                    particle.style.zIndex = '9998';
                    particle.style.pointerEvents = 'none';
                    
                    const angle = Math.random() * Math.PI * 2;
                    const velocity = 2 + Math.random() * 3;
                    const vx = Math.cos(angle) * velocity;
                    const vy = Math.sin(angle) * velocity;
                    
                    let x = 50;
                    let y = 50;
                    
                    function animate() {
                        x += vx;
                        y += vy;
                        
                        particle.style.left = x + '%';
                        particle.style.top = y + '%';
                        particle.style.opacity = 1 - (Math.abs(x - 50) + Math.abs(y - 50)) / 100;
                        
                        if (Math.abs(x - 50) < 100 && Math.abs(y - 50) < 100) {
                            requestAnimationFrame(animate);
                        } else {
                            particle.remove();
                        }
                    }
                    
                    container.appendChild(particle);
                    animate();
                }
            }

            window.closeEasterEgg = function() {
                const easterEgg = document.getElementById('easterEgg');
                if (easterEgg) {
                    easterEgg.style.display = 'none';
                    document.body.style.overflow = 'auto';
                }
            };

            // Initialize Sound System
            function initSoundSystem() {
                // Check if Howler is available
                if (typeof Howl === 'undefined') {
                    console.warn('Howler.js not loaded - sound system disabled');
                    return;
                }
                
                try {
                    // Background ambient sound
                    window.ambientSound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-computer-hum-loop-2479.mp3'],
                        loop: true,
                        volume: 0.1,
                        autoplay: false
                    });
                    
                    // Click sounds
                    window.clickSound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-select-click-1109.mp3'],
                        volume: 0.3
                    });
                    
                    // Hover sounds
                    window.hoverSound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-plastic-bubble-click-1124.mp3'],
                        volume: 0.2
                    });
                    
                    // Emergency sound
                    window.emergencySound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-alarm-905.mp3'],
                        volume: 0.5
                    });
                    
                    // Terminal sound
                    window.terminalSound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-typewriter-click-1106.mp3'],
                        volume: 0.2
                    });
                    
                    // Success sound
                    window.successSound = new Howl({
                        src: ['https://assets.mixkit.co/sfx/preview/mixkit-success-bell-893.mp3'],
                        volume: 0.4
                    });
                    
                    // Add sound to buttons
                    const buttons = document.querySelectorAll('button:not(.sound-btn)');
                    buttons.forEach(btn => {
                        btn.addEventListener('click', () => {
                            if (btn.classList.contains('danger') || btn.classList.contains('emergency')) {
                                emergencySound.play();
                            } else if (btn.classList.contains('terminal')) {
                                terminalSound.play();
                            } else if (btn.classList.contains('primary') || btn.classList.contains('success')) {
                                successSound.play();
                            } else {
                                clickSound.play();
                            }
                        });
                        
                        btn.addEventListener('mouseenter', () => {
                            hoverSound.play();
                        });
                    });
                    
                    // Start ambient sound after user interaction
                    document.addEventListener('click', function startAmbientSound() {
                        if (window.ambientSound && !window.ambientSound.playing()) {
                            window.ambientSound.play();
                        }
                        document.removeEventListener('click', startAmbientSound);
                    }, { once: true });
                    
                } catch (error) {
                    console.error('Sound system initialization failed:', error);
                }
            }

            // Initialize Scroll Animations
            function initScrollAnimations() {
                const observerOptions = {
                    threshold: 0.1,
                    rootMargin: '0px 0px -100px 0px'
                };
                
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('animate-in');
                            
                            // Special animations for specific elements
                            if (entry.target.classList.contains('tool-card')) {
                                entry.target.style.animationDelay = '0s';
                            }
                            
                            if (entry.target.classList.contains('project-card')) {
                                const index = Array.from(entry.target.parentNode.children).indexOf(entry.target);
                                entry.target.style.animationDelay = (index * 0.1) + 's';
                            }
                        }
                    });
                }, observerOptions);
                
                // Observe all animated elements
                const elementsToAnimate = document.querySelectorAll(
                    '.tool-card, .project-card, .dashboard-card, .trust-badge, .score-card, .achievements, .client-logos .logo-item'
                );
                
                elementsToAnimate.forEach(el => observer.observe(el));
            }

            // Initialize Theme Toggle
            function initThemeToggle() {
                const themeToggle = document.getElementById('themeToggle');
                const darkModeToggle = document.getElementById('darkModeToggle');
                
                const themes = {
                    'default': {
                        '--black-primary': '#050505',
                        '--neon-cyan': '#00F5FF',
                        '--neon-cyan-glow': '0 0 30px rgba(0, 245, 255, 0.7)'
                    },
                    'ultra-dark': {
                        '--black-primary': '#000000',
                        '--neon-cyan': '#00FFFF',
                        '--neon-cyan-glow': '0 0 40px rgba(0, 255, 255, 0.8)'
                    },
                    'matrix': {
                        '--black-primary': '#000000',
                        '--neon-cyan': '#00FF41',
                        '--neon-cyan-glow': '0 0 30px rgba(0, 255, 65, 0.7)'
                    },
                    'cyberpunk': {
                        '--black-primary': '#0A0A12',
                        '--neon-cyan': '#FF00FF',
                        '--neon-cyan-glow': '0 0 30px rgba(255, 0, 255, 0.7)'
                    }
                };
                
                let currentTheme = 'default';
                const themeOrder = ['default', 'ultra-dark', 'matrix', 'cyberpunk'];
                
                function applyTheme(themeName) {
                    const theme = themes[themeName];
                    for (const [property, value] of Object.entries(theme)) {
                        document.documentElement.style.setProperty(property, value);
                    }
                    currentTheme = themeName;
                    
                    // Update icon
                    const icons = document.querySelectorAll('#themeToggle i, #darkModeToggle i');
                    icons.forEach(icon => {
                        if (themeName === 'default') {
                            icon.className = 'fas fa-moon';
                        } else if (themeName === 'ultra-dark') {
                            icon.className = 'fas fa-sun';
                        } else if (themeName === 'matrix') {
                            icon.className = 'fas fa-code';
                        } else if (themeName === 'cyberpunk') {
                            icon.className = 'fas fa-gamepad';
                        }
                    });
                    
                    // Save to localStorage
                    localStorage.setItem('cyberTheme', themeName);
                }
                
                // Load saved theme
                const savedTheme = localStorage.getItem('cyberTheme');
                if (savedTheme && themes[savedTheme]) {
                    applyTheme(savedTheme);
                }
                
                // Toggle theme function
                window.toggleTheme = function() {
                    const currentIndex = themeOrder.indexOf(currentTheme);
                    const nextIndex = (currentIndex + 1) % themeOrder.length;
                    applyTheme(themeOrder[nextIndex]);
                    
                    // Show theme notification
                    showNotification(`Theme: ${themeOrder[nextIndex].toUpperCase()}`, 'info');
                };
                
                // Add event listeners
                if (themeToggle) {
                    themeToggle.addEventListener('click', toggleTheme);
                }
                
                if (darkModeToggle) {
                    darkModeToggle.addEventListener('click', toggleTheme);
                }
            }

            // Initialize Tooltips
            function initTooltips() {
                const tooltipElements = document.querySelectorAll('[data-tooltip]');
                
                tooltipElements.forEach(el => {
                    el.addEventListener('mouseenter', (e) => {
                        const tooltip = document.createElement('div');
                        tooltip.className = 'cyber-tooltip';
                        tooltip.textContent = el.getAttribute('data-tooltip');
                        tooltip.style.cssText = `
                            position: absolute;
                            background: rgba(0, 0, 0, 0.9);
                            border: 1px solid #00F5FF;
                            color: white;
                            padding: 8px 12px;
                            border-radius: 4px;
                            font-size: 0.8rem;
                            white-space: nowrap;
                            z-index: 10000;
                            pointer-events: none;
                            transform: translateY(-100%) translateX(-50%);
                            backdrop-filter: blur(10px);
                        `;
                        
                        document.body.appendChild(tooltip);
                        
                        const rect = el.getBoundingClientRect();
                        tooltip.style.left = (rect.left + rect.width / 2) + 'px';
                        tooltip.style.top = (rect.top - 10) + 'px';
                        
                        el.tooltip = tooltip;
                    });
                    
                    el.addEventListener('mouseleave', () => {
                        if (el.tooltip) {
                            el.tooltip.remove();
                            el.tooltip = null;
                        }
                    });
                });
            }

            // Initialize Gamification
            function initGamification() {
                // Update XP bar randomly
                setInterval(() => {
                    const xpBar = document.querySelector('.xp-progress');
                    if (xpBar) {
                        const currentWidth = parseFloat(xpBar.style.width) || 65;
                        const newWidth = Math.min(100, currentWidth + Math.random() * 0.5);
                        xpBar.style.width = newWidth + '%';
                        
                        const xpText = document.querySelector('.xp-text');
                        if (xpText) {
                            const level = Math.floor(newWidth / 10) + 1;
                            xpText.textContent = `Level ${level} - ${Math.floor(newWidth)}%`;
                        }
                    }
                }, 10000);
                
                // Unlock badges randomly
                setInterval(() => {
                    const lockedBadges = document.querySelectorAll('.badge.locked');
                    if (lockedBadges.length > 0 && Math.random() < 0.05) {
                        const randomBadge = lockedBadges[Math.floor(Math.random() * lockedBadges.length)];
                        randomBadge.classList.remove('locked');
                        randomBadge.classList.add('earned');
                        
                        // Random badge icon
                        const icons = ['🛡️', '🔐', '🔍', '🚀', '💻', '🔒', '⚡', '🎯'];
                        randomBadge.innerHTML = `<div class="badge-icon">${icons[Math.floor(Math.random() * icons.length)]}</div>`;
                        
                        // Show notification
                        showNotification('🎖️ New Achievement Unlocked!', 'success');
                    }
                }, 30000);
                
                // Update security score randomly
                setInterval(() => {
                    const securityScore = document.getElementById('securityScore');
                    if (securityScore) {
                        const currentScore = parseInt(securityScore.textContent);
                        const variation = Math.floor(Math.random() * 3) - 1; // -1, 0, or 1
                        const newScore = Math.max(80, Math.min(95, currentScore + variation));
                        securityScore.textContent = newScore;
                        securityScore.setAttribute('data-value', newScore);
                        
                        // Update progress circle
                        const circle = document.querySelector('.circle-progress');
                        if (circle) {
                            circle.style.setProperty('--progress', newScore + '%');
                        }
                    }
                }, 15000);
            }

