            // Initialize Emergency System
            function initEmergencySystem() {
                window.activateEmergency = function() {
                    const overlay = document.getElementById('emergencyOverlay');
                    const countdown = document.getElementById('lockdownCountdown');
                    
                    if (!overlay || !countdown) return;
                    
                    // Show overlay
                    overlay.style.display = 'flex';
                    document.body.style.overflow = 'hidden';
                    
                    // Play emergency sound
                    if (window.emergencySound) {
                        emergencySound.play();
                    }
                    
                    // Start countdown
                    let seconds = 5;
                    const interval = setInterval(() => {
                        countdown.textContent = seconds;
                        
                        // Add countdown animation
                        countdown.style.transform = 'scale(1.2)';
                        setTimeout(() => {
                            countdown.style.transform = 'scale(1)';
                        }, 200);
                        
                        seconds--;
                        
                        if (seconds < 0) {
                            clearInterval(interval);
                            overlay.style.display = 'none';
                            document.body.style.overflow = 'auto';
                            
                            // Show success message
                            showNotification('🚨 EMERGENCY LOCKDOWN ACTIVATED\nAll systems secured.', 'success');
                            
                            // Reset countdown
                            countdown.textContent = '5';
                        }
                    }, 1000);
                };
                
                // Add emergency shortcut (Ctrl + Alt + E)
                document.addEventListener('keydown', (e) => {
                    if (e.ctrlKey && e.altKey && e.key === 'e') {
                        e.preventDefault();
                        activateEmergency();
                    }
                });
                
                // Add mobile emergency button
                const mobileEmergencyBtn = document.querySelector('.mobile-emergency');
                if (mobileEmergencyBtn) {
                    mobileEmergencyBtn.addEventListener('click', activateEmergency);
                }
            }

