            // Initialize Performance Monitor
            function initPerformanceMonitor() {
                // Monitor FPS
                let frameCount = 0;
                let lastTime = performance.now();
                let fps = 60;
                
                function updateFPS() {
                    frameCount++;
                    const currentTime = performance.now();
                    
                    if (currentTime - lastTime >= 1000) {
                        fps = Math.round(frameCount);
                        frameCount = 0;
                        lastTime = currentTime;
                        
                        // Reduce animations if FPS is low
                        if (fps < 30) {
                            document.body.classList.add('reduce-motion');
                            console.warn('Low FPS detected, reducing motion');
                        } else {
                            document.body.classList.remove('reduce-motion');
                        }
                    }
                    
                    requestAnimationFrame(updateFPS);
                }
                
                updateFPS();
                
                // Monitor memory (if available)
                if (performance.memory) {
                    setInterval(() => {
                        const memory = performance.memory;
                        const used = Math.round(memory.usedJSHeapSize / 1024 / 1024);
                        const total = Math.round(memory.totalJSHeapSize / 1024 / 1024);
                        
                        if (used > total * 0.8) {
                            console.warn(`High memory usage: ${used}MB / ${total}MB`);
                        }
                    }, 30000);
                }
            }

            // Initialize Threat Monitor
            function initThreatMonitor() {
                const threatMap = document.querySelector('.threat-map');
                if (!threatMap) return;
                
                // Create threat visualization
                setInterval(() => {
                    // Clear previous threats
                    const existingThreats = threatMap.querySelectorAll('.threat-dot');
                    existingThreats.forEach(threat => threat.remove());
                    
