                    for (let i = 0; i < threatCount; i++) {
                        const threat = document.createElement('div');
                        threat.className = 'threat-dot';
                        threat.style.position = 'absolute';
                        threat.style.left = Math.random() * 95 + '%';
                        threat.style.top = Math.random() * 95 + '%';
                        threat.style.width = (5 + Math.random() * 10) + 'px';
                        threat.style.height = threat.style.width;
                        threat.style.background = Math.random() > 0.5 ? '#FF0033' : '#FFA500';
                        threat.style.borderRadius = '50%';
                        threat.style.boxShadow = `0 0 ${10 + Math.random() * 10}px ${threat.style.background}`;
                        threat.style.animation = `pulse ${1 + Math.random()}s infinite`;
                        threat.style.zIndex = '5';
                        
                        threatMap.appendChild(threat);
                    }
                }, 2000);
