            // Initialize Blockchain Visual
            function initBlockchainVisual() {
                const blockchainVisual = document.querySelector('.blockchain-visual');
                if (!blockchainVisual) return;
                
                // Create connections between nodes
                const nodes = blockchainVisual.querySelectorAll('.block-node');
                const connections = blockchainVisual.querySelector('.block-connections');
                
                if (!connections) return;
                
                // Clear existing connections
                connections.innerHTML = '';
                
                // Draw lines between nodes
                nodes.forEach((node1, i) => {
                    nodes.forEach((node2, j) => {
                        if (i < j && Math.random() > 0.6 && 
                            node1.classList.contains('active') && 
                            node2.classList.contains('active')) {
                            
                            const rect1 = node1.getBoundingClientRect();
                            const rect2 = node2.getBoundingClientRect();
                            const parentRect = blockchainVisual.getBoundingClientRect();
                            
                            const x1 = rect1.left - parentRect.left + rect1.width / 2;
                            const y1 = rect1.top - parentRect.top + rect1.height / 2;
                            const x2 = rect2.left - parentRect.left + rect2.width / 2;
                            const y2 = rect2.top - parentRect.top + rect2.height / 2;
                            
                            const line = document.createElement('div');
                            line.className = 'blockchain-connection';
                            line.style.position = 'absolute';
                            line.style.left = x1 + 'px';
                            line.style.top = y1 + 'px';
                            line.style.width = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2)) + 'px';
                            line.style.height = '1px';
                            line.style.background = 'linear-gradient(90deg, rgba(0,255,156,0.3), transparent)';
                            line.style.transformOrigin = '0 0';
                            line.style.transform = `rotate(${Math.atan2(y2 - y1, x2 - x1)}rad)`;
                            line.style.zIndex = '1';
                            
                            connections.appendChild(line);
                        }
                    });
                });
                
                // Animate connections
                setInterval(() => {
                    const connectionLines = connections.querySelectorAll('.blockchain-connection');
                    connectionLines.forEach(line => {
                        line.style.background = `linear-gradient(90deg, rgba(${Math.random() * 255},${Math.random() * 255},255,0.3), transparent)`;
                    });
                }, 3000);
            }

            // Initialize Prediction Graph
            function initPredictionGraph() {
                const canvas = document.getElementById('threatChart');
                if (!canvas) return;
                
                const ctx = canvas.getContext('2d');
                canvas.width = canvas.clientWidth;
                canvas.height = canvas.clientHeight;
                
                // Generate initial data
                const data = [];
                for (let i = 0; i < 24; i++) {
                    data.push(30 + Math.sin(i * 0.5) * 20 + Math.random() * 10);
                }
                
                function draw() {
                    ctx.clearRect(0, 0, canvas.width, canvas.height);
                    
                    // Draw grid
                    ctx.strokeStyle = 'rgba(0, 245, 255, 0.1)';
                    ctx.lineWidth = 1;
                    
                    // Vertical lines
                    for (let i = 0; i <= 6; i++) {
                        const x = (canvas.width / 6) * i;
                        ctx.beginPath();
                        ctx.moveTo(x, 0);
                        ctx.lineTo(x, canvas.height);
                        ctx.stroke();
                    }
                    
                    // Horizontal lines
                    for (let i = 0; i <= 5; i++) {
                        const y = (canvas.height / 5) * i;
                        ctx.beginPath();
                        ctx.moveTo(0, y);
                        ctx.lineTo(canvas.width, y);
                        ctx.stroke();
                    }
                    
                    // Draw line
                    ctx.beginPath();
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = '#00F5FF';
                    
                    data.forEach((value, index) => {
                        const x = (canvas.width / (data.length - 1)) * index;
                        const y = canvas.height - (value / 100 * canvas.height);
                        
                        if (index === 0) {
                            ctx.moveTo(x, y);
                        } else {
                            ctx.lineTo(x, y);
                        }
                    });
                    
                    ctx.stroke();
                    
                    // Fill area under line
                    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
                    gradient.addColorStop(0, 'rgba(0, 245, 255, 0.3)');
                    gradient.addColorStop(1, 'rgba(0, 245, 255, 0)');
                    
                    ctx.fillStyle = gradient;
                    ctx.beginPath();
                    
                    data.forEach((value, index) => {
                        const x = (canvas.width / (data.length - 1)) * index;
                        const y = canvas.height - (value / 100 * canvas.height);
                        
                        if (index === 0) {
                            ctx.moveTo(x, canvas.height);
                            ctx.lineTo(x, y);
                        } else {
                            ctx.lineTo(x, y);
                        }
                    });
                    
                    ctx.lineTo(canvas.width, canvas.height);
                    ctx.lineTo(0, canvas.height);
                    ctx.closePath();
                    ctx.fill();
                    
                    // Add data points
                    ctx.fillStyle = '#00F5FF';
                    data.forEach((value, index) => {
                        const x = (canvas.width / (data.length - 1)) * index;
                        const y = canvas.height - (value / 100 * canvas.height);
                        
                        ctx.beginPath();
                        ctx.arc(x, y, 3, 0, Math.PI * 2);
                        ctx.fill();
                    });
                    
                    // Update data (shift and add new)
                    data.shift();
                    data.push(30 + Math.sin(data.length * 0.5) * 20 + Math.random() * 10);
                }
                
                // Animation loop
                function animate() {
                    draw();
                    requestAnimationFrame(animate);
                }
                
                // Start animation with slower update
                setInterval(() => {
                    draw();
                }, 1000);
                
                // Initial draw
                draw();
                
                // Handle resize
                window.addEventListener('resize', () => {
                    canvas.width = canvas.clientWidth;
                    canvas.height = canvas.clientHeight;
                    draw();
                });
            }

            // Initialize World Map
            function initWorldMap() {
                // Already initialized in initAttackMap
            }

            // Initialize Live Logs
            function initLiveLogs() {
                const logs = [
                    '⚠️ Threat detected: Port scan from 192.168.1.100',
                    '✅ Firewall updated: New rule #4832 applied',
                    '📡 Monitoring: Network traffic stable',
                    '🔒 Encryption: Session keys rotated',
                    '🛡️ DDoS protection: 2,483 requests blocked',
                    '🤖 AI Analysis: Threat level decreased',
                    '🌐 VPN: Secure tunnel established',
                    '📊 Analytics: System performance optimal',
                    '🚨 Alert: Unusual activity detected',
                    '✅ Update: Security patches installed',
                    '🔐 MFA: Multi-factor authentication enabled',
                    '🌍 Geolocation: Attack traced to location',
                    '⚡ Response: Incident contained in 0.2s',
                    '📈 Performance: Throughput increased 15%',
                    '🔍 Scan: Vulnerability assessment complete'
                ];
                
                const logsContainer = document.querySelector('.logs-container');
                if (!logsContainer) return;
                
                // Create initial logs
                for (let i = 0; i < 4; i++) {
                    const randomLog = logs[Math.floor(Math.random() * logs.length)];
                    addLogEntry(randomLog);
                }
                
                // Add new logs periodically
                setInterval(() => {
                    const randomLog = logs[Math.floor(Math.random() * logs.length)];
                    addLogEntry(randomLog);
                }, 3000);
                
                function addLogEntry(logText) {
                    const logEntry = document.createElement('div');
                    logEntry.className = 'log-entry';
                    logEntry.textContent = logText;
                    
                    // Add appropriate class based on content
                    if (logText.includes('⚠️') || logText.includes('🚨')) {
                        logEntry.classList.add('threat');
                    } else if (logText.includes('✅')) {
                        logEntry.classList.add('success');
                    } else if (logText.includes('🤖') || logText.includes('📊')) {
                        logEntry.classList.add('warning');
                    } else {
                        logEntry.classList.add('normal');
                    }
                    
                    logsContainer.appendChild(logEntry);
                    
                    // Remove old logs
                    if (logsContainer.children.length > 10) {
                        logsContainer.removeChild(logsContainer.firstChild);
                    }
                }
            }

            // Initialize Scroll Effects
            function initScrollEffects() {
                // Add scroll effect to navigation
                let lastScroll = 0;
                
                window.addEventListener('scroll', () => {
                    const nav = document.getElementById('cyberNav');
                    const currentScroll = window.pageYOffset;
                    
                    if (nav) {
                        if (currentScroll > 50) {
                            nav.style.background = 'rgba(5, 5, 5, 0.98)';
                            nav.style.backdropFilter = 'blur(30px)';
                            
                            if (currentScroll > lastScroll && currentScroll > 100) {
                                nav.style.transform = 'translateY(-100%)';
                            } else {
                                nav.style.transform = 'translateY(0)';
                            }
                        } else {
                            nav.style.background = 'rgba(5, 5, 5, 0.95)';
                            nav.style.backdropFilter = 'blur(25px)';
                            nav.style.transform = 'translateY(0)';
                        }
                    }
                    
                    lastScroll = currentScroll;
                    
                    // Update active navigation link
                    const sections = document.querySelectorAll('section[id]');
                    const navLinks = document.querySelectorAll('.nav-link, .mobile-link');
                    
                    let currentSection = '';
                    sections.forEach(section => {
                        const sectionTop = section.offsetTop - 100;
                        const sectionHeight = section.clientHeight;
                        if (window.scrollY >= sectionTop && window.scrollY < sectionTop + sectionHeight) {
                            currentSection = section.id;
                        }
                    });
                    
                    navLinks.forEach(link => {
                        link.classList.remove('active');
                        if (link.getAttribute('href') === `#${currentSection}`) {
                            link.classList.add('active');
                        }
                    });
                    
                    // Add parallax effects
                    const parallaxElements = document.querySelectorAll('.parallax-layer');
                    parallaxElements.forEach(element => {
                        const speed = element.classList.contains('layer-1') ? 0.5 : 0.3;
                        const yPos = -(window.scrollY * speed);
                        element.style.transform = `translateY(${yPos}px)`;
                    });
                });
                
                // Smooth scrolling for navigation links
                document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                    anchor.addEventListener('click', function(e) {
                        e.preventDefault();
                        
                        const targetId = this.getAttribute('href');
                        if (targetId === '#') return;
                        
                        const targetElement = document.querySelector(targetId);
                        if (targetElement) {
                            window.scrollTo({
                                top: targetElement.offsetTop - 80,
                                behavior: 'smooth'
                            });
                        }
                    });
                });
            }

            // Initialize Parallax Effects
            function initParallaxEffects() {
                const premiumBg = document.querySelector('.premium-bg');
                if (!premiumBg) return;
                
                document.addEventListener('mousemove', (e) => {
                    const x = (e.clientX / window.innerWidth) * 20 - 10;
                    const y = (e.clientY / window.innerHeight) * 20 - 10;
                    
                    // Move background elements slightly
                    const scanLines = document.querySelectorAll('.scan-line');
                    scanLines.forEach(line => {
                        line.style.transform = `translateX(${x * 0.5}px)`;
                    });
                    
                    const flares = document.querySelectorAll('.flare');
                    flares.forEach((flare, index) => {
                        const multiplier = index === 0 ? 0.3 : 0.5;
                        flare.style.transform = `translate(${x * multiplier}px, ${y * multiplier}px)`;
                    });
                });
            }

            // Initialize Interactive Elements
            function initInteractiveElements() {
                // CTA Button Actions
                window.initiateProtection = function() {
                    showNotification('🛡️ Protection sequence initiated!\nAll security systems activated.', 'success');
                    
                    // Animate protection sequence
                    const protectionSequence = document.querySelector('.protection-sequence');
                    if (!protectionSequence) {
                        const sequence = document.createElement('div');
                        sequence.className = 'protection-sequence';
                        sequence.style.cssText = `
                            position: fixed;
                            top: 0;
                            left: 0;
                            width: 100%;
                            height: 100%;
                            background: radial-gradient(circle, transparent 0%, rgba(0,245,255,0.1) 100%);
                            z-index: 999;
                            pointer-events: none;
                            animation: fadeOut 2s forwards;
                        `;
                        document.body.appendChild(sequence);
                        
                        setTimeout(() => {
                            sequence.remove();
                        }, 2000);
                    }
                };
                
                window.runSecurityScan = function() {
                    showNotification('🔍 Security scan started...\nScanning all systems...', 'info');
                    
                    // Open terminal with scan command
                    setTimeout(() => {
                        openTerminal();
                        const input = document.getElementById('terminalInput');
                        if (input) {
                            input.value = 'scan';
                            input.dispatchEvent(new KeyboardEvent('keypress', {key: 'Enter'}));
                        }
                    }, 1000);
                };
                
                window.scheduleDemo = function() {
                    showNotification('📅 Demo scheduled!\nOur security team will contact you within 24 hours.', 'success');
                    
                    // Open contact modal or terminal
                    setTimeout(() => {
                        openTerminal();
                        const input = document.getElementById('terminalInput');
                        if (input) {
                            input.value = 'help';
                            input.dispatchEvent(new KeyboardEvent('keypress', {key: 'Enter'}));
                        }
                    }, 1500);
                };
                
                // Add ripple effect to buttons
                const buttons = document.querySelectorAll('.cta-btn, .contact-btn, .ddos-btn, .control-btn');
                buttons.forEach(button => {
                    button.addEventListener('click', function(e) {
                        const rect = this.getBoundingClientRect();
                        const x = e.clientX - rect.left;
                        const y = e.clientY - rect.top;
                        
                        const ripple = document.createElement('span');
                        ripple.style.cssText = `
                            position: absolute;
                            border-radius: 50%;
                            background: rgba(255, 255, 255, 0.3);
                            transform: scale(0);
                            animation: ripple 0.6s linear;
                            width: 100px;
                            height: 100px;
                            top: ${y - 50}px;
                            left: ${x - 50}px;
                            pointer-events: none;
                        `;
                        
                        this.appendChild(ripple);
                        
                        setTimeout(() => {
                            ripple.remove();
                        }, 600);
                    });
                });
            }

            // ===== UTILITY FUNCTIONS =====

            // Show Notification Function
            function showNotification(message, type = 'info') {
                const notification = document.createElement('div');
                notification.className = `cyber-notification ${type}`;
                notification.innerHTML = `
                    <div class="notification-content">
                        <div class="notification-icon">
                            ${type === 'success' ? '✅' : type === 'warning' ? '⚠️' : type === 'danger' ? '🚨' : 'ℹ️'}
                        </div>
                        <div class="notification-text">${message}</div>
                        <button class="notification-close">×</button>
                    </div>
                `;
                
                notification.style.cssText = `
                    position: fixed;
                    top: 20px;
                    right: 20px;
                    background: rgba(10, 26, 47, 0.95);
                    border: 1px solid ${type === 'success' ? '#00FF9C' : type === 'warning' ? '#FFA500' : type === 'danger' ? '#FF0033' : '#00F5FF'};
                    border-radius: 10px;
                    padding: 15px;
                    z-index: 9999;
                    backdrop-filter: blur(10px);
                    transform: translateX(120%);
                    transition: transform 0.3s ease-out;
                    max-width: 400px;
                    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.3);
                `;
                
                document.body.appendChild(notification);
                
                // Animate in
                setTimeout(() => {
                    notification.style.transform = 'translateX(0)';
                }, 10);
                
                // Close button
                notification.querySelector('.notification-close').addEventListener('click', () => {
                    notification.style.transform = 'translateX(120%)';
                    setTimeout(() => {
                        notification.remove();
                    }, 300);
                });
                
                // Auto remove after 5 seconds
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.style.transform = 'translateX(120%)';
                        setTimeout(() => {
                            if (notification.parentNode) {
                                notification.remove();
                            }
                        }, 300);
                    }
                }, 5000);
            }

            // Add CSS for ripple animation
            const style = document.createElement('style');
            style.textContent = `
                @keyframes ripple {
                    to {
                        transform: scale(4);
                        opacity: 0;
                    }
                }
                @keyframes fadeOut {
                    from { opacity: 1; }
                    to { opacity: 0; }
                }
                .protection-sequence {
                    animation: fadeOut 2s forwards;
                }
                .cyber-notification .notification-content {
                    display: flex;
                    align-items: center;
                    gap: 15px;
                }
                .cyber-notification .notification-icon {
                    font-size: 1.5rem;
                }
                .cyber-notification .notification-text {
                    flex: 1;
                    white-space: pre-line;
                    font-family: 'Space Mono', monospace;
                    font-size: 0.9rem;
                }
                .cyber-notification .notification-close {
                    background: none;
                    border: none;
                    color: #8892B0;
                    font-size: 1.5rem;
                    cursor: pointer;
                    padding: 0;
                    width: 24px;
                    height: 24px;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                }
                .cyber-notification .notification-close:hover {
                    color: #00F5FF;
                }
            `;
            document.head.appendChild(style);

            // Window resize handler
            window.addEventListener('resize', () => {
                // Reinitialize responsive elements
                initPremiumBackground();
                initPredictionGraph();
                initBlockchainVisual();
            });

            // Beforeunload handler
            window.addEventListener('beforeunload', () => {
                // Stop all animations and sounds
                if (window.ambientSound) {
                    window.ambientSound.stop();
                }
                
                // Save theme
                const currentTheme = localStorage.getItem('cyberTheme') || 'default';
                localStorage.setItem('cyberTheme', currentTheme);
            });

            // Keyboard shortcuts
            document.addEventListener('keydown', (e) => {
                // Ctrl + T to open terminal
                if (e.ctrlKey && e.key === 't') {
                    e.preventDefault();
                    openTerminal();
                }
                
                // Escape to close terminal
                if (e.key === 'Escape') {
                    const terminal = document.getElementById('cyberTerminal');
                    if (terminal && terminal.style.display === 'flex') {
                        closeTerminal();
                    }
                }
                
                // Ctrl + S to run security scan
                if (e.ctrlKey && e.key === 's') {
                    e.preventDefault();
                    runSecurityScan();
                }
            });

            // Initialize console greeting
            console.log('%c🔒 CYBER SHIELD SYSTEMS: ONLINE', 'color: #00F5FF; font-size: 16px; font-weight: bold;');
            console.log('%c🚀 All security protocols activated', 'color: #00FF9C;');
            console.log('%c🛡️ Ready to protect digital assets', 'color: #00F5FF;');
            console.log('%c⚡ System initialized at ' + new Date().toLocaleTimeString(), 'color: #8892B0;');

            // Initialize performance tracking
            if (typeof performance !== 'undefined' && performance.mark) {
                performance.mark('cyberShieldInitialized');
            }

        </script>      
        </body>
        </html>
        <?php
        return ob_get_clean();
    }
