            .benefit-item::before {
                content: '✓';
                position: absolute;
                left: 0;
                color: var(--accent-orange);
                font-weight: bold;
            }

            /* ===== TECHNOLOGY STACK ===== */
            .tech-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .tech-grid {
                display: flex;
                flex-wrap: wrap;
                justify-content: center;
                gap: 25px;
                margin-top: 40px;
            }

            .tech-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: 12px;
                padding: 20px;
                text-align: center;
                width: 140px;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .tech-item:hover {
                border-color: var(--wordpress-blue);
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-medium);
            }

            .tech-icon {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--wordpress-blue);
            }

            .tech-item span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== PROCESS SECTION ===== */
            .process-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .process-steps {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .process-step {
                text-align: center;
                position: relative;
            }

            .step-number {
                width: 60px;
                height: 60px;
                background: var(--blue-gradient);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.5rem;
                font-weight: 800;
                margin: 0 auto 20px;
                transition: var(--transition-smooth);
            }

            .process-step:hover .step-number {
                transform: scale(1.1) rotate(360deg);
            }

            .step-title {
                font-size: 1.2rem;
                font-weight: 700;
                margin-bottom: 10px;
                color: var(--navy-dark);
            }

            .step-description {
                color: #6B7280;
                font-size: 0.95rem;
            }

            /* ===== PRICING SECTION ===== */
            .pricing-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .pricing-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .pricing-card {
                background: white;
                border: 2px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 30px;
                text-align: center;
                transition: var(--transition-smooth);
                position: relative;
                overflow: hidden;
            }

            .pricing-card.popular {
                border-color: var(--wordpress-blue);
                transform: scale(1.05);
                box-shadow: var(--shadow-medium);
            }

            .pricing-card.popular::before {
                content: 'MOST POPULAR';
                position: absolute;
                top: 15px;
                right: -30px;
                background: var(--wordpress-blue);
                color: white;
                padding: 5px 30px;
                transform: rotate(45deg);
                font-size: 0.8rem;
                font-weight: 700;
            }

            .pricing-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
            }

            .pricing-header {
                margin-bottom: 30px;
            }

            .pricing-title {
                font-size: 1.5rem;
                font-weight: 800;
                color: var(--navy-dark);
                margin-bottom: 10px;
            }

            .pricing-description {
                color: #6B7280;
                font-size: 0.95rem;
            }

            .price-amount {
                font-size: 3rem;
                font-weight: 800;
                color: var(--wordpress-blue);
                margin: 20px 0;
            }

            .price-period {
                color: #6B7280;
                font-size: 1rem;
            }

            .pricing-features {
                text-align: left;
                margin: 30px 0;
            }

            .pricing-feature {
                padding: 8px 0;
                border-bottom: 1px solid var(--light-gray);
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .pricing-feature i {
                color: var(--accent-orange);
            }

            /* ===== TESTIMONIALS ===== */
            .testimonials-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .testimonials-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .testimonial-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .testimonial-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .client-info {
                display: flex;
                align-items: center;
                gap: 15px;
                margin-bottom: 20px;
            }

            .client-avatar {
                width: 50px;
                height: 50px;
                background: var(--blue-gradient);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: 700;
                font-size: 1.2rem;
            }

            .client-details h4 {
                color: var(--navy-dark);
                margin-bottom: 5px;
            }

            .client-details p {
                color: #6B7280;
                font-size: 0.9rem;
            }

            .stars {
                color: #FBBF24;
                margin-bottom: 15px;
            }

            .testimonial-text {
                color: #4B5563;
                font-style: italic;
                line-height: 1.6;
            }

            /* ===== FAQ SECTION ===== */
            .faq-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .faq-container {
                max-width: 800px;
                margin: 0 auto;
            }

            .faq-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                margin-bottom: 15px;
                overflow: hidden;
                transition: var(--transition-fast);
            }

            .faq-item:hover {
                border-color: var(--wordpress-blue);
                box-shadow: var(--shadow-soft);
            }

            .faq-question {
                padding: 20px;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                background: var(--off-white);
            }

            .faq-question h3 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin: 0;
            }

            .faq-icon {
                color: var(--wordpress-blue);
                transition: transform 0.3s;
            }

            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-answer {
                padding: 0 20px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s ease-out;
            }

            .faq-item.active .faq-answer {
                padding: 20px;
                max-height: 500px;
            }

            .faq-answer p {
                color: #6B7280;
                line-height: 1.6;
            }

            /* ===== SEO CONTENT SECTION ===== */
            .seo-content-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .seo-content-section .container {
                max-width: 900px;
            }

            .seo-content-section h2 {
                font-size: 2rem;
                color: var(--navy-dark);
                margin-bottom: 25px;
                padding-bottom: 15px;
                border-bottom: 3px solid var(--wordpress-blue);
            }

            .seo-content-section h3 {
                font-size: 1.5rem;
                color: var(--wordpress-blue);
                margin: 30px 0 15px;
            }

            .seo-content-section p {
                color: #4B5563;
                margin-bottom: 15px;
                line-height: 1.7;
            }

            .seo-content-section ul {
                margin: 15px 0 15px 25px;
                color: #4B5563;
            }

            .seo-content-section li {
                margin-bottom: 8px;
                line-height: 1.6;
            }

            .content-card {
                background: white;
                padding: 30px;
                border-radius: var(--border-radius);
                box-shadow: var(--shadow-soft);
                margin-bottom: 30px;
            }

            /* ===== CTA SECTION ===== */
            .cta-section {
                padding: 80px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--wordpress-blue) 100%);
                text-align: center;
                color: white;
            }

            .cta-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 20px;
            }

            .cta-description {
                font-size: 1.1rem;
                margin-bottom: 40px;
                max-width: 700px;
                margin-left: auto;
                margin-right: auto;
                opacity: 0.9;
            }

            .cta-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-bottom: 40px;
            }

            @media (min-width: 768px) {
                .cta-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .btn {
                padding: 16px 40px;
                font-size: 1.1rem;
                font-weight: 700;
                border-radius: var(--border-radius);
                text-decoration: none;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: var(--transition-smooth);
                min-width: 220px;
                border: 2px solid transparent;
                cursor: pointer;
            }

            .btn-primary {
                background: var(--cta-gradient);
                color: white;
                box-shadow: var(--shadow-medium);
            }

            .btn-secondary {
                background: rgba(255, 255, 255, 0.1);
                border: 2px solid rgba(255, 255, 255, 0.3);
                color: white;
                backdrop-filter: blur(10px);
            }

            .btn:hover {
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-hard);
            }

            /* ===== FLOATING ELEMENTS ===== */
            .floating-whatsapp {
                position: fixed;
                bottom: 20px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: #25D366;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 28px;
                z-index: 1000;
                box-shadow: var(--shadow-hard);
                animation: float 3s ease-in-out infinite;
                text-decoration: none;
                transition: var(--transition-smooth);
            }

            .floating-whatsapp:hover {
                transform: scale(1.1) rotate(10deg);
                animation: none;
            }

            .scroll-to-top {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--wordpress-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 18px;
                z-index: 1000;
                cursor: pointer;
                opacity: 0;
                visibility: hidden;
                transition: all 0.3s;
                box-shadow: var(--shadow-soft);
            }

            .scroll-to-top.visible {
                opacity: 1;
                visibility: visible;
            }

            .scroll-to-top:hover {
                background: var(--navy-dark);
                transform: translateY(-5px);
            }

            /* ===== ANIMATION CLASSES ===== */
            .animate-on-scroll {
                opacity: 0;
                transform: translateY(30px);
                transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1), 
                            transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            }

            .animate-on-scroll.visible {
                opacity: 1;
                transform: translateY(0);
            }

            .animate-left {
                opacity: 0;
                transform: translateX(-30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-left.visible {
                opacity: 1;
                transform: translateX(0);
            }

            .animate-right {
                opacity: 0;
                transform: translateX(30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-right.visible {
                opacity: 1;
                transform: translateX(0);
            }

            /* ===== MOBILE RESPONSIVE ===== */
            @media (max-width: 768px) {
                .hero-title {
                    font-size: clamp(1.8rem, 4vw, 2.2rem);
                }
                
                .features-grid {
                    grid-template-columns: 1fr;
                }
                
                .use-cases-grid {
                    grid-template-columns: 1fr;
                }
                
                .pricing-grid {
                    grid-template-columns: 1fr;
                }
                
                .pricing-card.popular {
                    transform: none;
                }
                
                .process-steps {
                    grid-template-columns: 1fr;
                }
                
                .testimonials-grid {
                    grid-template-columns: 1fr;
                }
                
                .btn {
                    min-width: 100%;
                    padding: 14px 30px;
                }
                
                .floating-whatsapp {
                    width: 50px;
                    height: 50px;
                    font-size: 24px;
                    bottom: 80px;
                    right: 15px;
                }
                
                .scroll-to-top {
                    bottom: 140px;
                    right: 15px;
                }
                
                .intent-grid {
                    grid-template-columns: 1fr;
                }
            }

            /* ===== CHENNAI LOCAL SECTION ===== */
            .chennai-local-section {
                background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
                padding: 80px 15px;
                color: white;
            }

            .local-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .local-card {
                background: rgba(255, 255, 255, 0.05);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 15px;
                padding: 30px;
                text-align: center;
                backdrop-filter: blur(10px);
                transition: var(--transition-fast);
            }

            .local-card:hover {
                background: rgba(255, 255, 255, 0.1);
                transform: translateY(-5px);
            }

            .local-icon {
                width: 60px;
                height: 60px;
                background: linear-gradient(135deg, #FF6B35, #FF8E53);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            /* ===== COMPARISON SECTION ===== */
            .comparison-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .comparison-table {
                background: white;
                border-radius: var(--border-radius);
                overflow: hidden;
                box-shadow: var(--shadow-soft);
                margin-top: 40px;
            }

            .comparison-header {
                background: var(--wordpress-blue);
                color: white;
                padding: 20px;
                display: grid;
                grid-template-columns: 2fr 1fr 1fr;
                font-weight: 700;
            }

            .comparison-row {
                display: grid;
                grid-template-columns: 2fr 1fr 1fr;
                padding: 15px 20px;
                border-bottom: 1px solid var(--light-gray);
                align-items: center;
            }

            .comparison-row:nth-child(even) {
                background: rgba(33, 117, 155, 0.05);
            }

            .check-mark {
                color: #10B981;
                font-weight: bold;
            }

            .cross-mark {
                color: #EF4444;
                font-weight: bold;
            }
            /* ===== STATS COUNTER SECTION ===== */
            .stats-counter {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 20px;
                max-width: 800px;
                margin: 40px auto;
                animation: fadeInUp 0.8s ease 0.8s both;
            }

            @media (min-width: 768px) {
                .stats-counter {
                    grid-template-columns: repeat(4, 1fr);
                    gap: 30px;
                }
            }

            .stat-item {
                text-align: center;
                padding: 25px 20px;
                background: white;
                border-radius: var(--border-radius);
                box-shadow: var(--shadow-soft);
                border: 1px solid rgba(33, 117, 155, 0.1);
                transition: var(--transition-smooth);
                position: relative;
                overflow: hidden;
            }

            .stat-item:hover {
                transform: translateY(-10px) scale(1.05);
                box-shadow: var(--shadow-hard);
                border-color: var(--wordpress-blue);
            }

            .stat-item::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 3px;
                background: linear-gradient(90deg, var(--wordpress-blue), var(--accent-orange));
                transform: scaleX(0);
                transform-origin: left;
                transition: transform 0.5s ease;
            }

            .stat-item:hover::before {
                transform: scaleX(1);
            }

            .stat-number {
                font-size: 2.8rem;
                font-weight: 900;
                color: var(--wordpress-blue);
                margin-bottom: 8px;
                line-height: 1;
                font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
                background: linear-gradient(135deg, var(--wordpress-blue) 0%, var(--accent-orange) 100%);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
                display: block;
                transition: var(--transition-fast);
            }

            .stat-item:hover .stat-number {
                transform: scale(1.1);
            }

            .stat-label {
                font-size: 0.95rem;
                color: #6B7280;
                font-weight: 600;
                text-transform: uppercase;
                letter-spacing: 0.5px;
                position: relative;
                display: inline-block;
                padding: 0 5px;
            }

            .stat-label::after {
                content: '';
                position: absolute;
                bottom: -5px;
                left: 50%;
                transform: translateX(-50%);
                width: 30px;
                height: 2px;
                background: var(--accent-orange);
                opacity: 0;
                transition: var(--transition-fast);
            }

            .stat-item:hover .stat-label::after {
                opacity: 1;
                width: 50px;
            }

            /* Animation for counting numbers */
            @keyframes countUp {
                from {
                    opacity: 0;
                    transform: translateY(20px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            .stat-number.animated {
                animation: countUp 0.5s ease forwards;
            }

            /* ===== TRUST BADGES SECTION ===== */
            .trust-badges {
                display: flex;
                flex-wrap: wrap;
                justify-content: center;
                gap: 20px;
                margin: 50px auto;
                max-width: 900px;
            }

            .badge {
                display: flex;
                align-items: center;
                gap: 12px;
                background: white;
                padding: 18px 25px;
                border-radius: var(--border-radius);
                box-shadow: var(--shadow-soft);
                font-weight: 700;
                color: var(--navy-dark);
                transition: var(--transition-smooth);
                border: 1px solid rgba(33, 117, 155, 0.1);
                position: relative;
                overflow: hidden;
                min-width: 220px;
                backdrop-filter: blur(10px);
            }

            .badge::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: linear-gradient(135deg, rgba(33, 117, 155, 0.05) 0%, rgba(255, 107, 53, 0.05) 100%);
                opacity: 0;
                transition: var(--transition-fast);
            }

            .badge:hover {
                transform: translateY(-8px) scale(1.05);
                box-shadow: var(--shadow-hard);
                border-color: var(--wordpress-blue);
                background: white;
            }

            .badge:hover::before {
                opacity: 1;
            }

            .badge i {
                font-size: 1.4rem;
                width: 45px;
                height: 45px;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                flex-shrink: 0;
                transition: var(--transition-smooth);
                position: relative;
                z-index: 1;
            }

            .badge:nth-child(1) i {
                background: linear-gradient(135deg, var(--wordpress-blue), #36a1d6);
            }

            .badge:nth-child(2) i {
                background: linear-gradient(135deg, #10B981, #34D399);
            }

            .badge:nth-child(3) i {
                background: linear-gradient(135deg, #F59E0B, #FBBF24);
            }

            .badge:nth-child(4) i {
                background: linear-gradient(135deg, #8B5CF6, #A78BFA);
            }

            .badge:hover i {
                transform: rotate(360deg) scale(1.1);
            }

            .badge span {
                font-size: 1rem;
                line-height: 1.4;
                position: relative;
                z-index: 1;
                transition: var(--transition-fast);
            }

            .badge:hover span {
                color: var(--wordpress-blue);
            }

            /* Badge animation */
            @keyframes badgeFloat {
                0%, 100% {
                    transform: translateY(0);
                }
                50% {
                    transform: translateY(-5px);
                }
            }

            .badge {
                animation: badgeFloat 4s ease-in-out infinite;
                animation-delay: calc(var(--badge-index, 0) * 0.2s);
            }

            /* Responsive adjustments */
            @media (max-width: 992px) {
                .trust-badges {
                    gap: 15px;
                }
                
                .badge {
                    min-width: 180px;
                    padding: 15px 20px;
                }
                
                .badge span {
                    font-size: 0.9rem;
                }
            }

            @media (max-width: 768px) {
                .stats-counter {
                    gap: 15px;
                }
                
                .stat-item {
                    padding: 20px 15px;
                }
                
                .stat-number {
                    font-size: 2.2rem;
                }
                
                .stat-label {
                    font-size: 0.85rem;
                }
                
                .trust-badges {
                    flex-direction: column;
                    align-items: center;
                    gap: 15px;
                }
                
                .badge {
                    width: 100%;
                    max-width: 300px;
                    min-width: auto;
                    justify-content: flex-start;
                    animation: none;
                }
                
                .badge:hover {
                    transform: translateY(-5px) scale(1.02);
                }
            }

            @media (max-width: 480px) {
                .stats-counter {
                    grid-template-columns: 1fr;
                    max-width: 300px;
                }
                
                .stat-number {
                    font-size: 2.5rem;
                }
                
                .badge {
                    padding: 12px 15px;
                }
                
                .badge i {
                    width: 40px;
                    height: 40px;
                    font-size: 1.2rem;
                }
            }

            /* Dark mode support */
            @media (prefers-color-scheme: dark) {
                .stat-item {
                    background: #1a1a2e;
                    border-color: rgba(33, 117, 155, 0.3);
                    color: white;
                }
                
                .stat-label {
                    color: #cbd5e1;
                }
                
                .badge {
                    background: #1a1a2e;
                    border-color: rgba(33, 117, 155, 0.3);
                    color: white;
                }
                
                .badge:hover {
                    background: #1a1a2e;
                    border-color: var(--wordpress-blue);
                }
                
                .badge::before {
                    background: linear-gradient(135deg, rgba(33, 117, 155, 0.1) 0%, rgba(255, 107, 53, 0.1) 100%);
                }
            }

            /* Hover effects for mobile */
            @media (hover: none) {
                .stat-item:hover {
                    transform: none;
                    box-shadow: var(--shadow-soft);
                }
                
                .badge:hover {
                    transform: none;
                    box-shadow: var(--shadow-soft);
                    animation: badgeFloat 4s ease-in-out infinite;
                }
                
                .badge:hover i {
                    transform: none;
                }
            }

            /* Print styles */
            @media print {
                .stats-counter {
                    break-inside: avoid;
                    box-shadow: none;
                    border: 1px solid #ddd;
                }
                
                .stat-item {
                    box-shadow: none;
                    border: 1px solid #ddd;
                }
                
                .trust-badges {
                    break-inside: avoid;
                }
                
                .badge {
                    box-shadow: none;
                    border: 1px solid #ddd;
                    color: black !important;
                }
                
                .badge i {
                    background: #666 !important;
                    color: white !important;
                }
            }
            /* ===== NEW SECTIONS STYLES ===== */

            /* Comparison Infographic */
            .comparison-infographic {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin: 50px 0;
            }

            .comparison-column {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                position: relative;
                transition: var(--transition-smooth);
            }

            .comparison-column.recommended {
                border: 2px solid var(--wordpress-blue);
                transform: scale(1.02);
                background: linear-gradient(to bottom, rgba(33, 117, 155, 0.03) 0%, transparent 100%);
            }

            .comparison-column.recommended::before {
                content: 'RECOMMENDED';
                position: absolute;
                top: -12px;
                left: 50%;
                transform: translateX(-50%);
                background: var(--wordpress-blue);
                color: white;
                padding: 6px 20px;
                border-radius: 20px;
                font-size: 0.8rem;
                font-weight: 700;
                letter-spacing: 1px;
            }

            .column-header {
                text-align: center;
                margin-bottom: 25px;
                padding-bottom: 20px;
                border-bottom: 1px solid var(--light-gray);
            }

            .column-title {
                font-size: 1.4rem;
                color: var(--navy-dark);
                margin-bottom: 10px;
            }

            .column-subtitle {
                color: var(--wordpress-blue);
                font-weight: 700;
                font-size: 1.8rem;
            }

            .comparison-points {
                list-style: none;
            }

            .comparison-points li {
                padding: 12px 0;
                border-bottom: 1px dashed var(--light-gray);
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .comparison-points li:last-child {
                border-bottom: none;
            }

            .point-positive {
                color: #10B981;
            }

            .point-negative {
                color: #EF4444;
            }

            .point-neutral {
                color: #6B7280;
            }

            /* Industry Grid */
            .industry-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 25px;
                margin: 40px 0;
            }

            .industry-card {
                background: white;
                border-radius: 12px;
                padding: 25px;
                border: 1px solid var(--light-gray);
                transition: var(--transition-smooth);
                text-align: center;
                position: relative;
                overflow: hidden;
            }

            .industry-card:hover {
                transform: translateY(-5px);
                border-color: var(--wordpress-blue);
                box-shadow: var(--shadow-medium);
            }

            .industry-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 4px;
                background: linear-gradient(90deg, var(--wordpress-blue), var(--accent-orange));
                opacity: 0;
                transition: var(--transition-fast);
            }

            .industry-card:hover::before {
                opacity: 1;
            }

            .industry-icon {
                width: 60px;
                height: 60px;
                background: linear-gradient(135deg, rgba(33, 117, 155, 0.1) 0%, rgba(33, 117, 155, 0.05) 100%);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                color: var(--wordpress-blue);
                font-size: 24px;
            }

            .industry-card h4 {
                color: var(--navy-dark);
                margin-bottom: 15px;
                font-size: 1.1rem;
            }

            .industry-features {
                list-style: none;
                text-align: left;
                margin-top: 15px;
            }

            .industry-features li {
                padding: 6px 0;
                font-size: 0.9rem;
                color: #4B5563;
                display: flex;
                align-items: center;
                gap: 8px;
            }

            .industry-features li::before {
                content: '✓';
                color: var(--accent-orange);
                font-weight: bold;
                font-size: 0.9rem;
            }

            /* Architecture Diagram */
            .architecture-diagram {
                background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
                border-radius: var(--border-radius);
                padding: 40px;
                margin: 40px 0;
                border: 1px solid var(--light-gray);
                position: relative;
                overflow: hidden;
            }

            .diagram-layer {
                display: flex;
                align-items: center;
                margin: 20px 0;
                padding: 20px;
                background: white;
                border-radius: 10px;
                border-left: 4px solid var(--wordpress-blue);
                transition: var(--transition-fast);
            }

            .diagram-layer:hover {
                transform: translateX(10px);
                box-shadow: var(--shadow-soft);
            }

            .layer-number {
                width: 40px;
                height: 40px;
                background: var(--blue-gradient);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-weight: 700;
                margin-right: 20px;
                flex-shrink: 0;
            }

            .layer-content {
                flex: 1;
            }

            .layer-title {
                color: var(--navy-dark);
                font-weight: 700;
                margin-bottom: 5px;
                font-size: 1.1rem;
            }

            .layer-desc {
                color: #6B7280;
                font-size: 0.95rem;
            }

            /* Checklist Styles */
            .checklist-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 25px;
                margin: 40px 0;
            }

            .checklist-item {
                background: white;
                border-radius: 12px;
                padding: 25px;
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
                display: flex;
                align-items: flex-start;
                gap: 15px;
            }

            .checklist-item:hover {
                border-color: var(--wordpress-blue);
                transform: translateY(-3px);
                box-shadow: var(--shadow-soft);
            }

            .checklist-icon {
                width: 40px;
                height: 40px;
                background: rgba(33, 117, 155, 0.1);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: var(--wordpress-blue);
                font-size: 18px;
                flex-shrink: 0;
            }

            .checklist-content h4 {
                color: var(--navy-dark);
                margin-bottom: 10px;
                font-size: 1.1rem;
            }

            .checklist-content p {
                color: #4B5563;
                font-size: 0.95rem;
                line-height: 1.6;
            }

            /* Warning Box */
            .warning-box {
                background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%);
                border: 1px solid #F59E0B;
                border-radius: var(--border-radius);
                padding: 25px;
                margin: 30px 0;
                position: relative;
            }

            .warning-box::before {
                content: '⚠️';
                position: absolute;
                top: -15px;
                left: 20px;
                background: white;
                padding: 5px 10px;
                border-radius: 20px;
                font-size: 1.2rem;
                border: 1px solid #F59E0B;
            }

            .warning-title {
                color: #92400E;
                font-weight: 700;
                margin-bottom: 10px;
                font-size: 1.2rem;
            }

            .warning-list {
                list-style: none;
                margin: 15px 0;
            }

            .warning-list li {
                padding: 8px 0;
                border-bottom: 1px dashed rgba(146, 64, 14, 0.2);
                display: flex;
                align-items: flex-start;
                gap: 10px;
            }

            .warning-list li:last-child {
                border-bottom: none;
            }

            .warning-list li::before {
                content: '✗';
                color: #DC2626;
                font-weight: bold;
                flex-shrink: 0;
            }

            /* Extended FAQ */
            .extended-faq {
                background: white;
                border-radius: var(--border-radius);
                padding: 40px;
                box-shadow: var(--shadow-soft);
                margin: 50px 0;
            }

            .faq-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 20px;
                margin-top: 30px;
            }

            .faq-block {
                background: var(--off-white);
                border-radius: 10px;
                padding: 20px;
                border-left: 3px solid var(--wordpress-blue);
            }

            .faq-block h4 {
                color: var(--navy-dark);
                margin-bottom: 10px;
                font-size: 1.1rem;
            }

            .faq-block p {
                color: #4B5563;
                font-size: 0.95rem;
                line-height: 1.6;
            }

            /* Mobile Responsive for New Sections */
            @media (max-width: 768px) {
                .comparison-infographic {
                    grid-template-columns: 1fr;
                }
                
                .comparison-column.recommended {
                    transform: none;
                }
                
                .industry-grid {
                    grid-template-columns: 1fr;
                }
                
                .architecture-diagram {
                    padding: 20px;
                }
                
                .diagram-layer {
                    flex-direction: column;
                    align-items: flex-start;
                }
                
                .layer-number {
                    margin-bottom: 15px;
                }
                
                .checklist-grid {
                    grid-template-columns: 1fr;
                }
                
                .extended-faq {
                    padding: 25px;
                }
                
                .faq-grid {
                    grid-template-columns: 1fr;
                }
            }
            /* ===== PROOF OF EXPERTISE SECTION ===== */
            .proof-section {
                padding: 80px 15px;
                background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
            }

            .challenge-cards {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                gap: 30px;
                margin: 50px 0;
            }

            .challenge-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                position: relative;
                overflow: hidden;
                transition: var(--transition-smooth);
            }

            .challenge-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--wordpress-blue);
            }

            .challenge-badge {
                position: absolute;
                top: 0;
                right: 0;
                background: var(--wordpress-blue);
                color: white;
                padding: 8px 20px;
                border-radius: 0 0 0 12px;
                font-size: 0.8rem;
                font-weight: 700;
                letter-spacing: 1px;
            }

            .challenge-problem {
                padding: 20px;
                background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%);
                border-radius: 10px;
                margin: 20px 0;
                border-left: 4px solid #F59E0B;
            }

            .challenge-problem h4 {
                color: #92400E;
                margin-bottom: 10px;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .challenge-solution {
                padding: 20px;
                background: linear-gradient(135deg, #D1FAE5 0%, #A7F3D0 100%);
                border-radius: 10px;
                margin: 20px 0;
                border-left: 4px solid #10B981;
            }

            .challenge-solution h4 {
                color: #065F46;
                margin-bottom: 10px;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .challenge-result {
                padding: 20px;
                background: linear-gradient(135deg, #DBEAFE 0%, #BFDBFE 100%);
                border-radius: 10px;
                margin: 20px 0;
                border-left: 4px solid var(--wordpress-blue);
            }

            .challenge-result h4 {
                color: #1E40AF;
                margin-bottom: 10px;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .result-stats {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 15px;
                margin-top: 15px;
            }

            .result-stat {
                text-align: center;
                padding: 10px;
                background: white;
                border-radius: 8px;
                border: 1px solid rgba(30, 64, 175, 0.2);
            }

            .result-number {
                font-size: 1.5rem;
                font-weight: 800;
                color: var(--wordpress-blue);
                display: block;
                line-height: 1;
            }

            .result-label {
                font-size: 0.8rem;
                color: #4B5563;
                margin-top: 5px;
            }

            /* ===== TRUST & OWNERSHIP SECTION ===== */
            .trust-section {
                padding: 80px 15px;
                background: var(--white);
                border-top: 1px solid var(--light-gray);
                border-bottom: 1px solid var(--light-gray);
            }

            .ownership-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 25px;
                margin: 40px 0;
            }

            .ownership-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                text-align: center;
                border: 2px solid var(--light-gray);
                transition: var(--transition-smooth);
                position: relative;
                overflow: hidden;
            }

            .ownership-card.featured {
                border-color: var(--wordpress-blue);
                transform: scale(1.05);
                box-shadow: var(--shadow-medium);
                background: linear-gradient(to bottom, rgba(33, 117, 155, 0.03) 0%, transparent 100%);
            }

            .ownership-card.featured::before {
                content: '★ RECOMMENDED';
                position: absolute;
                top: -12px;
                left: 50%;
                transform: translateX(-50%);
                background: var(--wordpress-blue);
                color: white;
                padding: 6px 20px;
                border-radius: 20px;
                font-size: 0.8rem;
                font-weight: 700;
                letter-spacing: 1px;
            }

            .ownership-icon {
                width: 70px;
                height: 70px;
                background: var(--blue-gradient);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                color: white;
                font-size: 28px;
            }

            .ownership-card h3 {
                color: var(--navy-dark);
                margin-bottom: 15px;
                font-size: 1.3rem;
            }

            .ownership-card p {
                color: #6B7280;
                font-size: 0.95rem;
                line-height: 1.6;
            }

            .legal-note {
                background: rgba(33, 117, 155, 0.05);
                border: 1px solid rgba(33, 117, 155, 0.2);
                border-radius: var(--border-radius);
                padding: 25px;
                margin-top: 40px;
                text-align: center;
            }

            .legal-note h4 {
                color: var(--wordpress-blue);
                margin-bottom: 15px;
                font-size: 1.1rem;
            }

            /* ===== INTERNAL LINK HUB SECTION ===== */
            .services-hub-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .services-hub {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
                gap: 25px;
                margin: 40px 0;
            }

            .service-link-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                border: 1px solid var(--light-gray);
                transition: var(--transition-smooth);
                position: relative;
                overflow: hidden;
                text-decoration: none;
                color: inherit;
                display: block;
            }

            .service-link-card:hover {
                transform: translateY(-10px);
                border-color: var(--wordpress-blue);
                box-shadow: var(--shadow-hard);
            }

            .service-link-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 4px;
                background: var(--blue-gradient);
                transform: scaleX(0);
                transition: transform 0.3s ease;
            }

            .service-link-card:hover::before {
                transform: scaleX(1);
            }

            .service-icon {
                width: 60px;
                height: 60px;
                background: var(--blue-gradient);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin-bottom: 20px;
                color: white;
                font-size: 24px;
            }

            .service-link-card h3 {
                color: var(--navy-dark);
                margin-bottom: 15px;
                font-size: 1.2rem;
            }

            .service-link-card p {
                color: #6B7280;
                font-size: 0.95rem;
                margin-bottom: 20px;
                line-height: 1.6;
            }

            .service-cta {
                color: var(--wordpress-blue);
                font-weight: 700;
                font-size: 0.9rem;
                display: flex;
                align-items: center;
                gap: 8px;
                transition: var(--transition-fast);
            }

            .service-link-card:hover .service-cta {
                gap: 12px;
            }

            /* ===== DECISION STAGE SECTION ===== */
            .decision-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .decision-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                gap: 30px;
                margin: 40px 0;
            }

            .decision-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                border: 2px solid var(--light-gray);
                transition: var(--transition-smooth);
                position: relative;
                overflow: hidden;
            }

            .decision-card.recommended {
                border-color: var(--wordpress-blue);
                background: linear-gradient(to bottom, rgba(33, 117, 155, 0.03) 0%, transparent 100%);
            }

            .decision-card h3 {
                color: var(--navy-dark);
                margin-bottom: 20px;
                padding-bottom: 15px;
                border-bottom: 2px solid var(--light-gray);
                font-size: 1.4rem;
            }

            .decision-list {
                list-style: none;
                margin: 20px 0;
            }

            .decision-list li {
                padding: 10px 0;
                border-bottom: 1px dashed var(--light-gray);
                display: flex;
                align-items: flex-start;
                gap: 10px;
            }

            .decision-list li:last-child {
                border-bottom: none;
            }

            .decision-list li i {
                flex-shrink: 0;
                margin-top: 3px;
            }

            .decision-list.recommended-list li i {
                color: #10B981;
            }

            .decision-list.not-recommended-list li i {
                color: #EF4444;
            }

            .roi-calculator {
                background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
                border-radius: var(--border-radius);
                padding: 30px;
                margin-top: 40px;
                border: 1px solid var(--light-gray);
            }

            .roi-calculator h4 {
                color: var(--navy-dark);
                margin-bottom: 20px;
                font-size: 1.2rem;
            }

            .roi-points {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 20px;
            }

            .roi-point {
                background: white;
                padding: 15px;
                border-radius: 8px;
                border-left: 4px solid var(--accent-orange);
            }

            .roi-point h5 {
                color: var(--navy-dark);
                margin-bottom: 5px;
                font-size: 1rem;
            }

            .roi-point p {
                color: #6B7280;
                font-size: 0.9rem;
            }

            /* ===== TRENDS 2026 SECTION ===== */
            .trends-section {
                padding: 80px 15px;
                background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
                color: white;
            }

            .trends-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
                gap: 25px;
                margin: 40px 0;
            }

            .trend-card {
                background: rgba(255, 255, 255, 0.05);
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 15px;
                padding: 30px;
                transition: var(--transition-smooth);
                backdrop-filter: blur(10px);
                position: relative;
                overflow: hidden;
            }

            .trend-card:hover {
                background: rgba(255, 255, 255, 0.1);
                transform: translateY(-5px);
                border-color: var(--wordpress-blue);
            }

            .trend-badge {
                position: absolute;
                top: 15px;
                right: 15px;
                background: var(--accent-orange);
                color: white;
                padding: 4px 12px;
                border-radius: 20px;
                font-size: 0.7rem;
                font-weight: 700;
            }

            .trend-icon {
                width: 60px;
                height: 60px;
                background: linear-gradient(135deg, #FF6B35, #FF8E53);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                margin-bottom: 20px;
                font-size: 24px;
                color: white;
            }

            .trend-card h3 {
                color: white;
                margin-bottom: 15px;
                font-size: 1.2rem;
            }

            .trend-card p {
                color: rgba(255, 255, 255, 0.8);
                font-size: 0.95rem;
                line-height: 1.6;
            }

            /* ===== MEDIA PROOF SECTION ===== */
            .media-proof-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .media-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin: 40px 0;
            }

            .media-card {
                background: white;
                border-radius: var(--border-radius);
                overflow: hidden;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-smooth);
            }

            .media-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--wordpress-blue);
            }

            .media-image {
                width: 100%;
                height: 200px;
                background: linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%);
                display: flex;
                align-items: center;
                justify-content: center;
                position: relative;
                overflow: hidden;
            }

            .media-image::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: linear-gradient(45deg, rgba(33, 117, 155, 0.1) 0%, transparent 100%);
            }

            .media-content {
                padding: 25px;
            }

            .media-content h3 {
                color: var(--navy-dark);
                margin-bottom: 15px;
                font-size: 1.2rem;
