    public function enqueue_plugin_dev_styles() {
        $css_file = (defined('WP_DEBUG') && WP_DEBUG)
            ? 'assets/css/plugin-dev-shortcode.css'
            : 'assets/css/plugin-dev-shortcode.min.css';

        wp_register_style(
            'ict-plugin-dev-style',
            plugin_dir_url(__FILE__) . $css_file,
            [],
            filemtime(plugin_dir_path(__FILE__) . $css_file)
        );
    }
