                    if(ham && nl){
                        ham.addEventListener('click', function(){ nl.classList.toggle('open'); ham.innerHTML = nl.classList.contains('open') ? '<i class="fas fa-times"></i>' : '&#9776;'; });
                        document.addEventListener('click', function(e){ if(!ham.contains(e.target) && !nl.contains(e.target)){ nl.classList.remove('open'); ham.innerHTML = '&#9776;'; } });
                        nl.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', function(){ nl.classList.remove('open'); ham.innerHTML = '&#9776;'; }); });
                    }
                    if('IntersectionObserver' in window){
                        var io = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting) e.target.classList.add('in'); }); },{threshold:0.08, rootMargin:'0px 0px -30px 0px'});
                        qsa('.rv').forEach(function(el){ io.observe(el); });
                    } else { qsa('.rv').forEach(function(el){ el.classList.add('in'); }); }
                    var counted = false, sb = q('stats');
                    if(sb){
                        var sio = new IntersectionObserver(function(entries){
                            if(entries[0].isIntersecting && !counted){
                                counted = true;
                                sb.querySelectorAll('.sn').forEach(function(el){
                                    var target = parseInt(el.getAttribute('data-n')||'0');
                                    var step = Math.ceil(target/60);
                                    var start = 0;
                                    var suffix = el.getAttribute('data-n') === '98' ? '%' : '+';
                                    var timer = setInterval(function(){ start += step; if(start >= target){ start = target; clearInterval(timer); } el.textContent = start + suffix; }, 18);
                                });
                            }
                        },{threshold:0.5});
                        sio.observe(sb);
                    }
                    document.querySelectorAll('.faq-question').forEach(function(q){ q.addEventListener('click', function(){ this.parentElement.classList.toggle('active'); }); });
                    var stbtn = q('stbtn');
                    window.addEventListener('scroll', function(){ if(stbtn) stbtn.classList.toggle('show', window.scrollY > 600); },{passive:true});
                    if(stbtn) stbtn.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });
                    var names = [{i:'RK',n:'Raj from <?php echo $city_name; ?>',a:'just booked a consultation'},{i:'SP',n:'Saranya from Coimbatore',a:'got an ERP plugin quote'},{i:'AM',n:'Arun from Chennai',a:'just started WooCommerce plugin'}];
                    var toast = q('toast'), shown = 0;
                    function showToast(){ if(shown >= names.length) return; var n = names[shown++]; toast.querySelector('.spd').textContent = n.i; toast.querySelector('span').innerHTML = '<strong>'+n.n+'</strong> '+n.a; toast.classList.add('show'); setTimeout(function(){ toast.classList.remove('show'); }, 5000); if(shown < names.length) setTimeout(showToast, 13000); }
                    setTimeout(showToast, 4000);
                    qsa('a[href^="#"]').forEach(function(a){ a.addEventListener('click', function(e){ var t = this.getAttribute('href'); if(t === '#' || t === '#!') return; var el = document.querySelector(t); if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth'}); } }); });
                    var modal = q('modal'), mclose = q('mclose'), mform = q('form'), mshown = sessionStorage.getItem(uid+'_modal') === '1';
                    if(!mshown){ document.addEventListener('mouseleave', function(e){ if(e.clientY <= 0 && modal && !mshown){ modal.classList.add('active'); mshown = true; sessionStorage.setItem(uid+'_modal','1'); } }); }
                    if(mclose) mclose.addEventListener('click', function(){ modal.classList.remove('active'); });
                    if(modal) modal.addEventListener('click', function(e){ if(e.target === modal) modal.classList.remove('active'); });
                    if(mform) mform.addEventListener('submit', function(e){ e.preventDefault(); var name = this.name.value.trim(), email = this.email.value.trim(), phone = this.phone.value.trim(), ptype = this.plugin_type.value; if(!name || !email || !phone){ alert('Please fill all fields.'); return; } var msg = 'WP+Plugin+Lead+from+<?php echo $city_url; ?>%0AName:'+encodeURIComponent(name)+'%0AEmail:'+encodeURIComponent(email)+'%0APhone:'+encodeURIComponent(phone)+'%0APlugin+Type:'+encodeURIComponent(ptype||'Not+specified')+'%0A%0APlease+send+the+guide.'; window.open('https://wa.me/919751797695?text='+msg, '_blank'); modal.classList.remove('active'); });
                }
                if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
            })();
