            <script>
                (function(){
                    const uid = '<?php echo $uid; ?>';
                    function fmtINR(n) {
                        if(n >= 100000) return '₹' + (n/100000).toFixed(1) + 'L';
                        if(n >= 1000) return '₹' + (n/1000).toFixed(0) + 'K';
                        return '₹' + n.toLocaleString('en-IN');
                    }
                    function calcROI() {
                        const emp      = +document.getElementById(uid+'-empCount').value;
                        const hrHrs    = +document.getElementById(uid+'-hrHours').value;
                        const hrCost   = +document.getElementById(uid+'-hrCost').value;
                        const invLoss  = +document.getElementById(uid+'-invLoss').value;
                        const curCost  = +document.getElementById(uid+'-curCost').value;
                
                        // Update display values
                        document.getElementById(uid+'-empVal').textContent  = emp;
                        document.getElementById(uid+'-hrVal').textContent   = hrHrs + ' hrs';
                        document.getElementById(uid+'-costVal').textContent = '₹' + hrCost;
                        document.getElementById(uid+'-invVal').textContent  = fmtINR(invLoss);
                        document.getElementById(uid+'-curVal').textContent  = fmtINR(curCost);
                
                        // Calculations (ERP saves ~60% HR time, ~80% inventory errors, ~50% software cost)
                        const hrSaveAnnual   = Math.round(emp * hrHrs * hrCost * 0.6 * 12);
                        const invSaveAnnual  = Math.round(invLoss * 0.8 * 12);
                        // Our ERP cost estimate (based on Business package ₹1,20,000 / 24 months = ₹5,000/mo)
                        const ictMonthlyCost = 5000;
                        const softSaveAnnual = Math.max(0, Math.round((curCost - ictMonthlyCost) * 12));
                        const total          = hrSaveAnnual + invSaveAnnual + softSaveAnnual;
                
                        document.getElementById(uid+'-hrSave').textContent   = fmtINR(hrSaveAnnual);
                        document.getElementById(uid+'-invSave').textContent  = fmtINR(invSaveAnnual);
                        document.getElementById(uid+'-softSave').textContent = fmtINR(softSaveAnnual);
                        document.getElementById(uid+'-totalSave').textContent = fmtINR(total);
                
                        // Payback period (assume Business ERP ₹1,20,000)
                        const investment = 120000;
                        if(total > 0) {
                            const months = Math.ceil((investment / total) * 12);
                            document.getElementById(uid+'-payback').textContent =
                                'Payback Period: ~' + months + ' month' + (months > 1 ? 's' : '');
                        }
                    }
                    ['empCount','hrHours','hrCost','invLoss','curCost'].forEach(function(id){
                        const el = document.getElementById(uid+'-'+id);
                        if(el) el.addEventListener('input', calcROI);
                    });
                    calcROI(); // initial calculation
                })();
            </script>
