            <script>
                (function(){
                    'use strict';
                    const uid = '<?php echo $uid; ?>';

                    function q(id) { return document.getElementById(uid + '-' + id); }
                    function qsa(sel) { return document.querySelectorAll('.' + uid + ' ' + sel); }

                    function init() {
                        // Nav scroll effect
                        const nav = q('nav');
                        window.addEventListener('scroll', function() {
                            if (nav) {
                                nav.style.background = window.scrollY > 40 ? 'rgba(10,15,30,.97)' : 'rgba(10,15,30,.82)';
                            }
                        }, {passive: true});

                        // Hamburger menu
                        const ham = q('ham');
                        const nl = q('nav-links');
                        if (ham && nl) {
                            ham.addEventListener('click', function() {
                                nl.classList.toggle('open');
                                ham.innerHTML = nl.classList.contains('open') ? '<i class="fas fa-times"></i>' : '&#9776;';
                            });
                            document.addEventListener('click', function(e) {
                                if (!ham.contains(e.target) && !nl.contains(e.target)) {
                                    nl.classList.remove('open');
                                    ham.innerHTML = '&#9776;';
                                }
                            });
                            nl.querySelectorAll('a').forEach(function(a) {
                                a.addEventListener('click', function() {
                                    nl.classList.remove('open');
                                    ham.innerHTML = '&#9776;';
                                });
                            });
                        }

                        // Scroll reveal
                        const io = new IntersectionObserver(function(entries) {
                            entries.forEach(function(e) {
                                if (e.isIntersecting) e.target.classList.add('in');
                            });
                        }, {threshold: 0.1, rootMargin: '0px 0px -40px 0px'});
                        qsa('.reveal').forEach(function(el) { io.observe(el); });

                        // Counter animation
                        let counted = false;
                        const statsIO = new IntersectionObserver(function(entries) {
                            if (entries[0].isIntersecting && !counted) {
                                counted = true;
                                qsa('.stat-num').forEach(function(el) {
                                    const target = parseInt(el.getAttribute('data-n') || '0');
                                    let start = 0;
                                    const step = Math.ceil(target / 60);
                                    const timer = setInterval(function() {
                                        start += step;
                                        if (start >= target) { start = target; clearInterval(timer); }
                                        el.textContent = start + (el.getAttribute('data-n') === '95' ? '%' : '+');
                                    }, 18);
                                });
                            }
                        }, {threshold: 0.5});
                        const sb = q('stats');
                        if (sb) statsIO.observe(sb);

                        // FAQ toggle
                        qsa('.faq-q').forEach(function(btn) {
                            btn.addEventListener('click', function() {
                                const item = this.parentElement;
                                const wasOpen = item.classList.contains('open');
                                qsa('.faq-item.open').forEach(function(o) { o.classList.remove('open'); });
                                if (!wasOpen) item.classList.add('open');
                            });
                        });

                        // Scroll to top
                        const st = q('scroll-top');
                        window.addEventListener('scroll', function() {
                            if (st) st.classList.toggle('show', window.scrollY > 600);
                        }, {passive: true});
                        if (st) st.addEventListener('click', function() { window.scrollTo({top: 0, behavior: 'smooth'}); });

                        // Module filtering
                        const tabs = document.querySelectorAll('.' + uid + ' button[data-filter="module"]');
                        const modules = qsa('.module-card');
                        tabs.forEach(tab => {
                            tab.addEventListener('click', function() {
                                const filter = this.dataset.module;
                                tabs.forEach(t => t.classList.remove('active'));
                                this.classList.add('active');
                                modules.forEach(module => {
                                    if (filter === 'all' || module.dataset.module === filter) {
                                        module.style.display = 'block';
                                    } else {
                                        module.style.display = 'none';
                                    }
                                });
                            });
                        });

                        // Modal (exit-intent)
                        const modal = q('leadModal');
                        const modalClose = q('modalClose');
                        const leadForm = q('leadForm');
                        let modalShown = sessionStorage.getItem(uid + '_modalShown') === 'true';
                        let modalActive = false;

                        if (!modalShown && modal) {
                            document.addEventListener('mouseleave', function(event) {
                                if (event.clientY <= 0 && !modalActive) {
                                    modal.classList.add('active');
                                    modalActive = true;
                                    sessionStorage.setItem(uid + '_modalShown', 'true');
                                }
                            });
                        }

                        if (modalClose) {
                            modalClose.addEventListener('click', function() {
                                modal.classList.remove('active');
                                modalActive = false;
                            });
                        }
                        if (modal) {
                            modal.addEventListener('click', function(e) {
                                if (e.target === modal) {
                                    modal.classList.remove('active');
                                    modalActive = false;
                                }
                            });
                        }

                        if (leadForm) {
                            leadForm.addEventListener('submit', function(e) {
                                e.preventDefault();
                                const name = this.name.value.trim();
                                const email = this.email.value.trim();
                                const phone = this.phone.value.trim();
                                const business = this.business.value;
                                if (!name || !email || !phone) {
                                    alert('Please fill all fields.');
                                    return;
                                }
                                const msg = `New ERP Inquiry from <?php echo $city; ?>:%0A%0AName: ${encodeURIComponent(name)}%0AEmail: ${encodeURIComponent(email)}%0APhone: ${encodeURIComponent(phone)}%0ABusiness: ${encodeURIComponent(business)}`;
                                window.open(`https://wa.me/919751797695?text=${msg}`, '_blank');
                                modal.classList.remove('active');
                                modalActive = false;
                            });
                        }

                        // Smooth scrolling
                        qsa('a[href^="#"]').forEach(function(a) {
                            a.addEventListener('click', function(e) {
                                const t = this.getAttribute('href');
                                if (t === '#' || t === '#!') return;
                                const el = document.querySelector(t);
                                if (el) {
                                    e.preventDefault();
                                    el.scrollIntoView({behavior: 'smooth'});
                                }
                            });
                        });
                    }

                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', init);
                    } else {
                        init();
                    }
                })();
            </script>
        </div><!-- .erp-shortcode -->
        <?php
        return ob_get_clean();
    }
