                --shadow-soft: 0 4px 12px rgba(0, 0, 0, 0.08);
                --shadow-medium: 0 8px 20px rgba(0, 0, 0, 0.12);
                --shadow-hard: 0 12px 30px rgba(0, 0, 0, 0.15);
                --transition-fast: all 0.3s ease;
                --transition-smooth: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
                --border-radius: 12px;
                --card-radius: 16px;
            }

            * {
                margin: 0;
                padding: 0;
                box-sizing: border-box;
                -webkit-font-smoothing: antialiased;
                -moz-osx-font-smoothing: grayscale;
            }

            html {
                scroll-behavior: smooth;
                scroll-padding-top: 100px;
            }

            body {
                font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
                background: var(--white);
                color: #334155;
                line-height: 1.6;
                overflow-x: hidden;
            }

            .container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 0 20px;
                width: 100%;
            }

            /* ===== PRELOADER ===== */
            .preloader {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: var(--white);
                z-index: 9999;
                display: flex;
                justify-content: center;
                align-items: center;
                transition: opacity 0.5s ease;
            }

            .loader {
                width: 50px;
                height: 50px;
                border: 3px solid var(--light-gray);
                border-top: 3px solid var(--royal-blue);
                border-radius: 50%;
                animation: spin 1s linear infinite;
            }

            @keyframes spin {
                0% { transform: rotate(0deg); }
                100% { transform: rotate(360deg); }
            }

            /* ===== PROFESSIONAL NAVIGATION ===== */
            .professional-nav {
                background: var(--white);
                box-shadow: var(--shadow-soft);
                position: fixed;
                top: 0;
                width: 100%;
                z-index: 1000;
                padding: 15px 0;
            }

            .nav-container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 0 20px;
                display: flex;
                justify-content: space-between;
                align-items: center;
            }

            .logo {
                font-size: 1.8rem;
                font-weight: 800;
                color: var(--navy-dark);
                text-decoration: none;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .logo span {
                background: var(--gradient-primary);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
            }

            .nav-links {
                display: flex;
                gap: 30px;
                align-items: center;
            }

            .nav-links a {
                color: var(--navy-medium);
                text-decoration: none;
                font-weight: 600;
                font-size: 0.95rem;
                transition: var(--transition-fast);
                padding: 8px 12px;
                border-radius: 6px;
            }

            .nav-links a:hover {
                color: var(--royal-blue);
                background: rgba(37, 99, 235, 0.1);
            }

            .nav-cta {
                background: var(--gradient-primary);
                color: white !important;
                padding: 10px 25px !important;
                border-radius: 25px;
            }

            .nav-cta:hover {
                transform: translateY(-2px);
                box-shadow: var(--shadow-medium);
            }

            .mobile-menu-btn {
                display: none;
                background: none;
                border: none;
                font-size: 1.5rem;
                color: var(--navy-dark);
                cursor: pointer;
            }

            /* ===== HERO SECTION ===== */
            .hero-section {
                min-height: 90vh;
                padding: 160px 15px 80px;
                background: linear-gradient(135deg, var(--off-white) 0%, var(--white) 100%);
                position: relative;
                overflow: hidden;
            }

            .hero-content {
                max-width: 1200px;
                margin: 0 auto;
                text-align: center;
            }

            .hero-badge {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                background: rgba(37, 99, 235, 0.1);
                border: 2px solid var(--royal-blue);
                color: var(--royal-blue);
                padding: 10px 25px;
                border-radius: 30px;
                font-weight: 700;
                margin-bottom: 30px;
                font-size: 0.95rem;
                animation: fadeInUp 0.8s ease;
            }

            .hero-title {
                font-size: clamp(2.5rem, 5vw, 3.8rem);
                font-weight: 800;
                line-height: 1.1;
                margin-bottom: 25px;
                color: var(--navy-dark);
                animation: fadeInUp 0.8s ease 0.2s both;
            }

            .hero-title span {
                background: var(--gradient-primary);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
            }

            .hero-subtitle {
                font-size: clamp(1.2rem, 2.5vw, 1.5rem);
                color: #475569;
                margin-bottom: 25px;
                max-width: 800px;
                margin-left: auto;
                margin-right: auto;
                animation: fadeInUp 0.8s ease 0.4s both;
            }

            .hero-description {
                font-size: 1.1rem;
                color: #64748B;
                max-width: 800px;
                margin: 0 auto 40px;
                line-height: 1.7;
                animation: fadeInUp 0.8s ease 0.6s both;
            }

            .platform-badges {
                display: flex;
                justify-content: center;
                gap: 20px;
                flex-wrap: wrap;
                margin: 40px auto;
                max-width: 800px;
                animation: fadeInUp 0.8s ease 0.8s both;
            }

            .platform-badge {
                display: flex;
                align-items: center;
                gap: 12px;
                background: white;
                padding: 15px 25px;
                border-radius: var(--card-radius);
                box-shadow: var(--shadow-soft);
                font-weight: 600;
                color: var(--navy-dark);
                transition: var(--transition-smooth);
                border: 1px solid var(--light-gray);
            }

            .platform-badge.android {
                border-left: 4px solid #3DDC84;
            }

            .platform-badge.ios {
                border-left: 4px solid #000000;
            }

            .platform-badge.cross {
                border-left: 4px solid var(--royal-blue);
            }

            .platform-badge:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .platform-badge i {
                font-size: 24px;
            }

            .platform-badge.android i {
                color: #3DDC84;
            }

            .platform-badge.ios i {
                color: #000000;
            }

            .platform-badge.cross i {
                color: var(--royal-blue);
            }

            .stats-counter {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 20px;
                max-width: 800px;
                margin: 50px auto;
                animation: fadeInUp 0.8s ease 1s both;
            }

            @media (min-width: 768px) {
                .stats-counter {
                    grid-template-columns: repeat(4, 1fr);
                    gap: 30px;
                }
            }

            .stat-item {
                text-align: center;
                padding: 25px;
                background: white;
                border-radius: var(--card-radius);
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
            }

            .stat-number {
                font-size: 2.5rem;
                font-weight: 800;
                color: var(--royal-blue);
                margin-bottom: 5px;
            }

            .stat-label {
                font-size: 0.95rem;
                color: #64748B;
                font-weight: 600;
            }

            .hero-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .hero-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .btn {
                padding: 16px 40px;
                font-size: 1.1rem;
                font-weight: 700;
                border-radius: var(--border-radius);
                text-decoration: none;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: var(--transition-smooth);
                min-width: 220px;
                border: 2px solid transparent;
                cursor: pointer;
            }

            .btn-primary {
                background: var(--gradient-primary);
                color: white;
                box-shadow: var(--shadow-medium);
            }

            .btn-secondary {
                background: white;
                border: 2px solid var(--royal-blue);
                color: var(--royal-blue);
            }

            .btn:hover {
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-hard);
            }

            /* ===== ANIMATIONS ===== */
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(30px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            /* ===== SERVICES SECTION ===== */
            .services-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .section-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                text-align: center;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .section-subtitle {
                font-size: 1.1rem;
                text-align: center;
                color: #64748B;
                max-width: 700px;
                margin: 0 auto 50px;
            }

            .services-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 0 auto;
            }

            .service-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--card-radius);
                padding: 35px;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
                position: relative;
                overflow: hidden;
                text-align: center;
            }

            .service-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 5px;
                background: var(--gradient-primary);
                transform: scaleX(0);
                transition: transform 0.3s ease;
            }

            .service-card:hover {
                transform: translateY(-10px) scale(1.02);
                box-shadow: var(--shadow-hard);
                border-color: var(--royal-blue);
            }

            .service-card:hover::before {
                transform: scaleX(1);
            }

            .service-icon {
                width: 70px;
                height: 70px;
                background: var(--gradient-primary);
                border-radius: 16px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 25px;
                font-size: 28px;
                color: white;
                transition: var(--transition-smooth);
            }

            .service-card:hover .service-icon {
                transform: rotate(360deg) scale(1.1);
            }

            .service-card h3 {
                font-size: 1.3rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .service-card p {
                color: #64748B;
                font-size: 0.95rem;
                line-height: 1.6;
            }

            /* ===== INDUSTRIES SERVED ===== */
            .industries-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .industries-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 25px;
                max-width: 1000px;
                margin: 50px auto 0;
            }

            .industry-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--card-radius);
                padding: 30px 20px;
                text-align: center;
                transition: var(--transition-fast);
                box-shadow: var(--shadow-soft);
            }

            .industry-item:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--royal-blue);
            }

            .industry-icon {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--royal-blue);
            }

            .industry-item h4 {
                font-size: 1.1rem;
                font-weight: 700;
                color: var(--navy-dark);
            }

            /* ===== TECHNOLOGY STACK ===== */
            .tech-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .tech-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
                gap: 25px;
                max-width: 1000px;
                margin: 50px auto 0;
            }

            .tech-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 25px 15px;
                text-align: center;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .tech-item:hover {
                border-color: var(--royal-blue);
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .tech-icon {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--royal-blue);
            }

            .tech-item span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== DEVELOPMENT PROCESS ===== */
            .process-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .process-steps {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 30px;
                margin-top: 50px;
                position: relative;
            }

            .process-steps::before {
                content: '';
                position: absolute;
                top: 40px;
                left: 50px;
                right: 50px;
                height: 3px;
                background: var(--light-gray);
                z-index: 1;
            }

            @media (max-width: 768px) {
                .process-steps::before {
                    display: none;
                }
            }

            .process-step {
                text-align: center;
                position: relative;
                z-index: 2;
            }

            .step-number {
                width: 80px;
                height: 80px;
                background: var(--gradient-primary);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 2rem;
                font-weight: 800;
                margin: 0 auto 25px;
                transition: var(--transition-smooth);
                border: 5px solid var(--white);
            }

            .process-step:hover .step-number {
                transform: scale(1.1);
                box-shadow: var(--shadow-medium);
            }

            .step-title {
                font-size: 1.2rem;
                font-weight: 700;
                margin-bottom: 10px;
                color: var(--navy-dark);
            }

            .step-description {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== CASE STUDIES ===== */
            .cases-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .cases-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .case-card {
                background: white;
                border-radius: var(--card-radius);
                overflow: hidden;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .case-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
            }

            .case-header {
                padding: 25px 25px 15px;
            }

            .case-badge {
                display: inline-block;
                background: rgba(37, 99, 235, 0.1);
                color: var(--royal-blue);
                padding: 5px 15px;
                border-radius: 20px;
                font-size: 0.85rem;
                font-weight: 600;
                margin-bottom: 15px;
            }

            .case-title {
                font-size: 1.3rem;
                font-weight: 700;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .case-description {
                color: #64748B;
                font-size: 0.95rem;
                margin-bottom: 20px;
                line-height: 1.6;
            }

            .case-tech {
                display: flex;
                flex-wrap: wrap;
                gap: 8px;
                margin-bottom: 20px;
            }

            .case-tech span {
                background: var(--light-gray);
                color: var(--navy-dark);
                padding: 4px 12px;
                border-radius: 15px;
                font-size: 0.8rem;
                font-weight: 500;
            }

            .case-footer {
                padding: 20px 25px;
                background: var(--off-white);
                text-align: center;
            }

            /* ===== WHY CHOOSE US ===== */
            .advantages-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .advantages-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 50px auto 0;
            }

            .advantage-card {
                background: white;
                border-radius: var(--card-radius);
                padding: 35px;
                text-align: center;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .advantage-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--accent-green);
            }

            .advantage-icon {
                width: 60px;
                height: 60px;
                background: var(--gradient-success);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            .advantage-card h3 {
                font-size: 1.2rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .advantage-card p {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== TESTIMONIALS ===== */
            .testimonials-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .testimonials-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .testimonial-card {
                background: white;
                border-radius: var(--card-radius);
                padding: 35px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .testimonial-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .client-info {
                display: flex;
                align-items: center;
                gap: 15px;
                margin-bottom: 20px;
            }

            .client-avatar {
                width: 60px;
                height: 60px;
                background: var(--gradient-primary);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: 700;
                font-size: 1.4rem;
            }

            .client-details h4 {
                color: var(--navy-dark);
                margin-bottom: 5px;
                font-size: 1.1rem;
            }

            .client-details p {
                color: #64748B;
                font-size: 0.9rem;
            }

            .stars {
                color: #FBBF24;
                margin-bottom: 20px;
            }

            .testimonial-text {
                color: #475569;
                line-height: 1.6;
                font-style: italic;
            }

            /* ===== TRUST SIGNALS ===== */
            .trust-section {
                padding: 80px 15px;
                background: var(--off-white);
                text-align: center;
            }

            .trust-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 30px;
                max-width: 1000px;
                margin: 40px auto 0;
            }

            .trust-item {
                background: white;
                border-radius: var(--card-radius);
                padding: 30px 20px;
                box-shadow: var(--shadow-soft);
                transition: var(--transition-fast);
            }

            .trust-item:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .trust-icon {
                font-size: 40px;
                color: var(--royal-blue);
                margin-bottom: 15px;
            }

            .trust-item span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== FAQ SECTION ===== */
            .faq-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .faq-container {
                max-width: 800px;
                margin: 0 auto;
            }

            .faq-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                margin-bottom: 15px;
                overflow: hidden;
                transition: var(--transition-fast);
            }

            .faq-item:hover {
                border-color: var(--royal-blue);
                box-shadow: var(--shadow-soft);
            }

            .faq-question {
                padding: 25px;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                background: var(--off-white);
            }

            .faq-question h3 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin: 0;
                font-weight: 600;
            }

            .faq-icon {
                color: var(--royal-blue);
                transition: transform 0.3s;
            }

            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-answer {
                padding: 0 25px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s ease-out;
            }

            .faq-item.active .faq-answer {
                padding: 25px;
                max-height: 500px;
            }

            .faq-answer p {
                color: #64748B;
                line-height: 1.6;
            }

            /* ===== CTA SECTION ===== */
            .cta-section {
                padding: 100px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--royal-blue) 100%);
                text-align: center;
                color: white;
            }

            .cta-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 20px;
            }

            .cta-description {
                font-size: 1.1rem;
                margin-bottom: 40px;
                max-width: 700px;
                margin-left: auto;
                margin-right: auto;
                opacity: 0.9;
            }

            .cta-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-bottom: 40px;
            }

            @media (min-width: 768px) {
                .cta-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .cta-contact {
                display: flex;
                flex-direction: column;
                gap: 20px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .cta-contact {
                    flex-direction: row;
                    gap: 40px;
                }
            }

            .contact-item {
                display: flex;
                align-items: center;
                gap: 12px;
                color: white;
                text-decoration: none;
                opacity: 0.9;
                transition: var(--transition-fast);
            }

            .contact-item:hover {
                opacity: 1;
                transform: translateY(-3px);
            }

            .contact-item i {
                background: rgba(255, 255, 255, 0.1);
                width: 40px;
                height: 40px;
                border-radius: 50%;
                display: flex;
