            <script>
                (function(){
                    var uid = '<?php echo $uid; ?>';
                    var projData = {
                        web:     {days:30, ourDays:4,  price:'₹3,999'},
                        ml:      {days:45, ourDays:6,  price:'₹6,999'},
                        iot:     {days:35, ourDays:5,  price:'₹5,499'},
                        ieee:    {days:40, ourDays:7,  price:'₹8,999'},
                        android: {days:32, ourDays:5,  price:'₹4,499'}
                    };
                    var stressMap = ['Very High','Very High','High','Medium','Low'];
                    var approvalMap = ['45%','55%','65%','75%','82%'];
                    var costMap = {
                        service: '₹15,000–20,000',
                        product: '₹25,000–40,000',
                        startup: '₹20,000–30,000',
                        govt:    '₹10,000–15,000'
                    };
                    var verdicts = {
                        web:     'A Web project takes ~30 days alone. With ICT, you get it in 4 days — spend those 26 days on interviews!',
                        ml:      'ML projects are complex. Students who attempt alone often miss viva because they don\'t understand the model. We explain every line.',
                        iot:     'IoT needs hardware + coding. Doing both alone in final year = recipe for disaster. We handle both.',
                        ieee:    'IEEE projects need literature survey + paper review + implementation. That\'s 40+ days. We deliver in 7.',
                        android: 'Android projects look simple but Play Store integration and UI take time. We\'ve done 500+ already.'
                    };
                
                    function calc() {
                        var sel   = document.getElementById(uid+'-projType');
                        var proj  = sel ? sel.value : 'web';
                        var skill = +(document.querySelector('input[name="'+uid+'-skill"]:checked') || {value:1}).value;
                        var hours = +(document.getElementById(uid+'-hoursDay') || {value:2}).value;
                        var comp  = document.getElementById(uid+'-targetComp');
                        var compVal = comp ? comp.value : 'service';
                
                        document.getElementById(uid+'-hoursVal').textContent = hours + ' hrs/day';
                
                        var pd = projData[proj];
                        // Self completion days = base days ÷ (skill × hours / 3)
                        var selfDays = Math.round(pd.days / ((skill * hours) / 3));
                        selfDays = Math.max(selfDays, 10);
                
                        function f(id, val) {
                            var el = document.getElementById(uid+'-'+id);
                            if(el) el.textContent = val;
                        }
                
                        f('selfDays',    selfDays + ' days');
                        f('selfStress',  stressMap[Math.min(skill - 1, 4)]);
                        f('selfApproval', approvalMap[Math.min(skill - 1, 4)]);
                        f('selfCost',    costMap[compVal] + ' lost');
                        f('ictDays',     pd.ourDays + ' days');
                        f('ictCost',     pd.price);
                
                        var vEl = document.getElementById(uid+'-verdict');
                        if(vEl) {
                            vEl.querySelector('.calc-verdict-text').textContent = verdicts[proj];
                        }
                    }
                
                    ['projType','hoursDay','targetComp'].forEach(function(id){
                        var el = document.getElementById(uid+'-'+id);
                        if(el) el.addEventListener('change', calc);
                        if(el) el.addEventListener('input', calc);
                    });
                    document.querySelectorAll('input[name="'+uid+'-skill"]').forEach(function(r){
                        r.addEventListener('change', calc);
                    });
                    calc();
                })();
            </script>
