            <!-- ═══════════════ JAVASCRIPT (enhanced) ═══════════════ -->
            <script>
                (function(){
                    'use strict';
                    var uid='<?php echo $uid; ?>';
                    function q(id){return document.getElementById(uid+'-'+id);}
                    function qsa(sel){return document.querySelectorAll('.'+uid+' '+sel);}

                    function init(){
                        // Nav scroll
                        var nav=q('nav'), ticking=false;
                        window.addEventListener('scroll',function(){
                            if(!ticking){requestAnimationFrame(function(){nav.style.background=window.scrollY>40?'rgba(10,15,30,.97)':'rgba(10,15,30,.82)';ticking=false;});ticking=true;}
                        },{passive:true});

                        // Hamburger
                        var ham=q('ham'),nl=q('nl');
                        if(ham&&nl){
                            ham.addEventListener('click',function(){nl.classList.toggle('open');ham.innerHTML=nl.classList.contains('open')?'<i class="fas fa-times"></i>':'&#9776;';});
                            document.addEventListener('click',function(e){if(!ham.contains(e.target)&&!nl.contains(e.target)){nl.classList.remove('open');ham.innerHTML='&#9776;';}});
                            nl.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){nl.classList.remove('open');ham.innerHTML='&#9776;';});});
                        }

                        // Scroll reveal
                        if('IntersectionObserver' in window){
                            var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting)e.target.classList.add('in');});},{threshold:0.08,rootMargin:'0px 0px -30px 0px'});
                            qsa('.rv').forEach(function(el){io.observe(el);});
                        } else { qsa('.rv').forEach(function(el){el.classList.add('in');}); }

                        // Counter animation
                        var counted=false, sb=q('stats');
                        if(sb){
                            var sio=new IntersectionObserver(function(entries){
                                if(entries[0].isIntersecting&&!counted){
                                    counted=true;
                                    sb.querySelectorAll('.sn').forEach(function(el){
                                        var target=parseInt(el.getAttribute('data-n')||'0'),start=0,step=Math.ceil(target/60);
                                        var suffix=el.getAttribute('data-n')==='98'?'%':'+';
                                        var timer=setInterval(function(){start+=step;if(start>=target){start=target;clearInterval(timer);}el.textContent=start+suffix;},18);
                                    });
                                }
                            },{threshold:0.5});
                            sio.observe(sb);
                        }

                        // FAQ toggle
                        qsa('.fi').forEach(function(item){
                            var btn=item.querySelector('.fq');
                            if(btn) btn.addEventListener('click',function(){
                                qsa('.fi.open').forEach(function(o){if(o!==item)o.classList.remove('open');});
                                item.classList.toggle('open');
                            });
                        });

                        // Scroll top
                        var stbtn=q('stbtn');
                        window.addEventListener('scroll',function(){stbtn.classList.toggle('show',window.scrollY>600);},{passive:true});
                        if(stbtn)stbtn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});

                        // Countdown timer
                        function updateTimer(){
                            var now=new Date(),end=new Date(now.getFullYear(),now.getMonth()+1,1);
                            var diff=end-now;
                            if(diff<=0)return;
                            var d=Math.floor(diff/864e5),h=Math.floor((diff%864e5)/36e5),m=Math.floor((diff%36e5)/6e4),s=Math.floor((diff%6e4)/1e3);
                            function pad(n){return String(n).padStart(2,'0');}
                            var td=q('td'),th=q('th'),tm=q('tm'),ts=q('ts');
                            if(td)td.textContent=pad(d);if(th)th.textContent=pad(h);if(tm)tm.textContent=pad(m);if(ts)ts.textContent=pad(s);
                        }
                        updateTimer();setInterval(updateTimer,1000);

                        // Social proof toast
                        var names=[
                            {i:'RK',n:'Rahul from <?php echo $city; ?>',a:'just requested project list'},
                            {i:'SK',n:'Sanjay from Coimbatore',a:'just got project delivered'},
                            {i:'AM',n:'Arun from Madurai',a:'just messaged on WhatsApp'},
                            {i:'PL',n:'Priya from <?php echo $city; ?>',a:'just got placed at TCS'},
                            {i:'JT',n:'Jayanthi from Trichy',a:'just started her ML project'}
                        ];
                        var toast=q('toast'),shown=0;
                        function showToast(){
                            if(shown>=names.length)return;
                            var n=names[shown++];
                            toast.querySelector('.spd').textContent=n.i;
                            toast.querySelector('span').innerHTML='<strong>'+n.n+'</strong> '+n.a;
                            toast.classList.add('show');
                            setTimeout(function(){toast.classList.remove('show');},5000);
                            if(shown<names.length)setTimeout(showToast,13000);
                        }
                        setTimeout(showToast,4000);

                        // Smooth scroll anchors
                        qsa('a[href^="#"]').forEach(function(a){
                            a.addEventListener('click',function(e){
                                var t=this.getAttribute('href');
                                if(t==='#'||t==='#!')return;
                                var el=document.querySelector(t);
                                if(el){e.preventDefault();el.scrollIntoView({behavior:'smooth'});}
                            });
                        });

                        // Modal for download trigger
                        var modal=q('modal'),mclose=q('mclose'),mform=q('form');
                        var mshown=sessionStorage.getItem(uid+'_modal')==='1';
                        if(!mshown){
                            document.addEventListener('mouseleave',function(e){
                                if(e.clientY<=0&&modal&&!mshown){modal.classList.add('active');mshown=true;sessionStorage.setItem(uid+'_modal','1');}
                            });
                        }
                        if(mclose)mclose.addEventListener('click',function(){modal.classList.remove('active');});
                        if(modal)modal.addEventListener('click',function(e){if(e.target===modal)modal.classList.remove('active');});
                        var downloadBtn=document.getElementById(uid+'-download-trigger');
                        if(downloadBtn){
                            downloadBtn.addEventListener('click',function(e){e.preventDefault();if(modal)modal.classList.add('active');});
                        }
                        if(mform)mform.addEventListener('submit',function(e){
                            e.preventDefault();
                            var name=this.name.value.trim(),email=this.email.value.trim(),phone=this.phone.value.trim(),course=this.course.value;
                            if(!name||!email||!phone){alert('Please fill all required fields.');return;}
                            var msg='Hi,+I+need+final+year+project+guidance.%0A%0AName:+'+encodeURIComponent(name)+'%0AEmail:+'+encodeURIComponent(email)+'%0APhone:+'+encodeURIComponent(phone)+'%0ACourse:+'+encodeURIComponent(course||'Not+specified')+'%0ACity:+<?php echo $city_url; ?>%0A%0APlease+send+me+the+project+catalog.';
                            window.open('https://wa.me/919751797695?text='+msg,'_blank');
                            modal.classList.remove('active');
                        });
                    }
                    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);
                    else init();
                })();
            </script>

        </div><!-- .fyci-shortcode -->
        <?php
        return ob_get_clean();
    }
