                color: var(--royal-blue);
                text-decoration: none;
                font-weight: 600;
                display: inline-flex;
                align-items: center;
                gap: 8px;
                transition: var(--transition-fast);
            }

            .blog-link:hover {
                color: var(--cta-orange);
                gap: 12px;
            }

            /* ===== TESTIMONIALS ===== */
            .testimonials-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .testimonials-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .testimonial-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 30px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .testimonial-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .student-info {
                display: flex;
                align-items: center;
                gap: 15px;
                margin-bottom: 20px;
            }

            .student-avatar {
                width: 50px;
                height: 50px;
                background: var(--blue-gradient);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: 700;
                font-size: 1.2rem;
            }

            .student-details h4 {
                color: var(--navy-dark);
                margin-bottom: 5px;
            }

            .student-details p {
                color: #6B7280;
                font-size: 0.9rem;
            }

            .stars {
                color: #FBBF24;
                margin-bottom: 15px;
            }

            .testimonial-text {
                color: #4B5563;
                font-style: italic;
                line-height: 1.6;
            }

            /* ===== FAQ SECTION ===== */
            .faq-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .faq-container {
                max-width: 800px;
                margin: 0 auto;
            }

            .faq-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                margin-bottom: 15px;
                overflow: hidden;
                transition: var(--transition-fast);
            }

            .faq-item:hover {
                border-color: var(--royal-blue);
                box-shadow: var(--shadow-soft);
            }

            .faq-question {
                padding: 20px;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                background: var(--off-white);
            }

            .faq-question h3 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin: 0;
            }

            .faq-icon {
                color: var(--royal-blue);
                transition: transform 0.3s;
            }

            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-answer {
                padding: 0 20px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s ease-out;
            }

            .faq-item.active .faq-answer {
                padding: 20px;
                max-height: 500px;
            }

            .faq-answer p {
                color: #6B7280;
                line-height: 1.6;
            }

            /* ===== NEW SEO CONTENT SECTION ===== */
            .seo-content-section {
                padding: 80px 15px;
                background: var(--off-white);
            }

            .seo-content-section .container {
                max-width: 900px;
            }

            .seo-content-section h2 {
                font-size: 2rem;
                color: var(--navy-dark);
                margin-bottom: 25px;
                padding-bottom: 15px;
                border-bottom: 3px solid var(--royal-blue);
            }

            .seo-content-section h3 {
                font-size: 1.5rem;
                color: var(--royal-blue);
                margin: 30px 0 15px;
            }

            .seo-content-section h4 {
                font-size: 1.2rem;
                color: var(--navy-dark);
                margin: 20px 0 10px;
            }

            .seo-content-section p {
                color: #4B5563;
                margin-bottom: 15px;
                line-height: 1.7;
            }

            .seo-content-section ul {
                margin: 15px 0 15px 25px;
                color: #4B5563;
            }

            .seo-content-section li {
                margin-bottom: 8px;
                line-height: 1.6;
            }

            .content-card {
                background: white;
                padding: 30px;
                border-radius: var(--border-radius);
                box-shadow: var(--shadow-soft);
                margin-bottom: 30px;
            }

            .content-card h3 {
                color: var(--royal-blue);
                font-size: 1.5rem;
                margin-bottom: 20px;
            }

            .highlight-box {
                background: var(--soft-orange);
                border-left: 4px solid var(--royal-blue);
                padding: 20px;
                margin: 20px 0;
                border-radius: 0 8px 8px 0;
            }

            .highlight-box p {
                margin: 0;
                color: #4B5563;
                font-style: italic;
            }

            .key-points {
                background: var(--soft-blue);
                padding: 20px;
                border-radius: 8px;
                margin: 20px 0;
            }

            .key-points h4 {
                color: var(--royal-blue);
                margin-top: 0;
            }

            /* ===== CTA SECTION ===== */
            .cta-section {
                padding: 80px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--royal-blue) 100%);
                text-align: center;
                color: white;
            }

            .cta-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 20px;
            }

            .cta-description {
                font-size: 1.1rem;
                margin-bottom: 40px;
                max-width: 700px;
                margin-left: auto;
                margin-right: auto;
                opacity: 0.9;
            }

            .cta-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-bottom: 40px;
            }

            @media (min-width: 768px) {
                .cta-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .btn {
                padding: 16px 40px;
                font-size: 1.1rem;
                font-weight: 700;
                border-radius: var(--border-radius);
                text-decoration: none;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: var(--transition-smooth);
                min-width: 220px;
                border: 2px solid transparent;
                cursor: pointer;
            }

            .btn-primary {
                background: var(--cta-gradient);
                color: white;
                box-shadow: var(--shadow-medium);
            }

            .btn-secondary {
                background: rgba(255, 255, 255, 0.1);
                border: 2px solid rgba(255, 255, 255, 0.3);
                color: white;
                backdrop-filter: blur(10px);
            }

            .btn:hover {
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-hard);
            }

            .contact-info {
                display: flex;
                flex-direction: column;
                gap: 20px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .contact-info {
                    flex-direction: row;
                    gap: 40px;
                }
            }

            .contact-item {
                display: flex;
                align-items: center;
                gap: 12px;
                color: white;
                text-decoration: none;
                opacity: 0.9;
                transition: var(--transition-fast);
            }

            .contact-item:hover {
                opacity: 1;
                transform: translateY(-3px);
            }

            .contact-item i {
                background: rgba(255, 255, 255, 0.1);
                width: 40px;
                height: 40px;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            /* ===== FLOATING ELEMENTS ===== */
            .floating-whatsapp {
                position: fixed;
                bottom: 20px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: #25D366;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 28px;
                z-index: 1000;
                box-shadow: var(--shadow-hard);
                animation: float 3s ease-in-out infinite;
                text-decoration: none;
                transition: var(--transition-smooth);
            }

            .floating-whatsapp:hover {
                transform: scale(1.1) rotate(10deg);
                animation: none;
            }

            .floating-call {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 20px;
                z-index: 1000;
                box-shadow: var(--shadow-medium);
                text-decoration: none;
                transition: var(--transition-fast);
                display: none;
            }

            @media (max-width: 768px) {
                .floating-call {
                    display: flex;
                }
            }

            .floating-call:hover {
                transform: scale(1.1);
            }

            .scroll-to-top {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 18px;
                z-index: 1000;
                cursor: pointer;
                opacity: 0;
                visibility: hidden;
                transition: all 0.3s;
                box-shadow: var(--shadow-soft);
            }

            @media (max-width: 768px) {
                .scroll-to-top {
                    bottom: 150px;
                }
            }

            .scroll-to-top.visible {
                opacity: 1;
                visibility: visible;
            }

            .scroll-to-top:hover {
                background: var(--navy-dark);
                transform: translateY(-5px);
            }

            /* ===== ANIMATION CLASSES ===== */
            .animate-on-scroll {
                opacity: 0;
                transform: translateY(30px);
                transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1), 
                            transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            }

            .animate-on-scroll.visible {
                opacity: 1;
                transform: translateY(0);
            }

            .animate-left {
                opacity: 0;
                transform: translateX(-30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-left.visible {
                opacity: 1;
                transform: translateX(0);
            }

            .animate-right {
                opacity: 0;
                transform: translateX(30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-right.visible {
                opacity: 1;
                transform: translateX(0);
            }

            .animate-zoom {
                opacity: 0;
                transform: scale(0.9);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-zoom.visible {
                opacity: 1;
                transform: scale(1);
            }

            /* ===== MODAL POPUP ===== */
            .modal-overlay {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0, 0, 0, 0.8);
                z-index: 2000;
                display: none;
                justify-content: center;
                align-items: center;
                padding: 20px;
            }

            .modal-content {
                background: white;
                border-radius: var(--border-radius);
                padding: 40px;
                max-width: 500px;
                width: 100%;
                position: relative;
                animation: zoomIn 0.5s ease;
            }

            .modal-close {
                position: absolute;
                top: 15px;
                right: 15px;
                background: none;
                border: none;
                font-size: 24px;
                color: #6B7280;
                cursor: pointer;
                transition: var(--transition-fast);
            }

            .modal-close:hover {
                color: var(--navy-dark);
                transform: rotate(90deg);
            }

            /* ===== MOBILE RESPONSIVE ===== */
            @media (max-width: 768px) {
                .nav-links {
                    display: none;
                    position: fixed;
                    top: 70px;
                    left: 0;
                    width: 100%;
                    background: white;
                    flex-direction: column;
                    padding: 20px;
                    box-shadow: var(--shadow-hard);
                    z-index: 999;
                }
                
                .nav-links.active {
                    display: flex;
                }
                
                .mobile-menu-btn {
                    display: block;
                    background: none;
                    border: none;
                    font-size: 1.5rem;
                    color: var(--navy-dark);
                    cursor: pointer;
                    z-index: 1001;
                }
                
                .hero-title {
                    font-size: clamp(1.8rem, 4vw, 2.2rem);
                }
                
                .features-grid {
                    grid-template-columns: 1fr;
                }
                
                .projects-grid {
                    grid-template-columns: 1fr;
                }
                
                .process-steps {
                    grid-template-columns: 1fr;
                }
                
                .tech-grid {
                    justify-content: center;
                }
                
                .blog-grid {
                    grid-template-columns: 1fr;
                }
                
                .testimonials-grid {
                    grid-template-columns: 1fr;
                }
                
                .btn {
                    min-width: 100%;
                    padding: 14px 30px;
                }
                
                .seo-content-section h2 {
                    font-size: 1.8rem;
                }
                
                .seo-content-section h3 {
                    font-size: 1.3rem;
                }
                
                .content-card {
                    padding: 20px;
                }
                
                .floating-whatsapp {
                    width: 50px;
                    height: 50px;
                    font-size: 24px;
                    bottom: 80px;
                    right: 15px;
                }
                
                .floating-call {
                    bottom: 140px;
                    right: 15px;
                }
                
                .scroll-to-top {
                    bottom: 200px;
                    right: 15px;
                }
                
                .intent-grid {
                    grid-template-columns: 1fr;
                }
            }

            /* ===== KEYWORD HIGHLIGHTS ===== */
            .keyword {
                color: var(--royal-blue);
                font-weight: 800;
                position: relative;
                display: inline-block;
            }

            .keyword::after {
                content: '';
                position: absolute;
                bottom: 2px;
                left: 0;
                width: 100%;
                height: 3px;
                background: var(--cta-orange);
                opacity: 0.3;
                border-radius: 2px;
            }

            .highlight {
                background: rgba(30, 64, 175, 0.1);
                padding: 3px 8px;
                border-radius: 6px;
                font-weight: 700;
                color: var(--royal-blue);
            }
            
            /* Breadcrumb */
            .breadcrumb {
                padding: 15px 0;
                font-size: 0.9rem;
                color: #6B7280;
                margin-bottom: 20px;
            }
            
            .breadcrumb a {
                color: var(--royal-blue);
                text-decoration: none;
            }
            
            .breadcrumb a:hover {
                text-decoration: underline;
            }
            
            .breadcrumb span:last-child {
                color: var(--navy-dark);
                font-weight: 600;
            }
            .trending-badge {
                background: linear-gradient(45deg, #ff6b6b, #ffa500);
                color: white;
                padding: 3px 8px;
                border-radius: 12px;
                font-size: 0.7rem;
                font-weight: 600;
                margin-left: auto;
            }

            .startup-info {
                margin-top: 15px;
                padding-top: 10px;
                border-top: 1px dashed #e0e0e0;
                display: flex;
                justify-content: space-between;
                align-items: center;
            }

            .company-tag {
                background: #e8f5e9;
                color: #2e7d32;
                padding: 4px 10px;
                border-radius: 15px;
                font-size: 0.75rem;
                font-weight: 500;
            }

            .price-original {
                text-decoration: line-through;
                color: #999;
                font-size: 0.9rem;
                font-weight: 500;
            }

            .price-discount {
                background: #ffebee;
                color: #d32f2f;
                padding: 2px 8px;
                border-radius: 10px;
                font-size: 0.75rem;
                font-weight: 600;
                margin-left: 8px;
            }

            .project-price {
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .price-amount {
                font-size: 1.4rem;
                font-weight: 700;
                color: #2196f3;
            }

            .difficulty.beginner {
                background: #4caf50;
            }

            .difficulty.intermediate {
                background: #ff9800;
            }

            .difficulty.advanced {
                background: #f44336;
            }
            .faq-cta {
                text-align: center;
                margin-top: 40px;
                padding: 30px;
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                border-radius: 15px;
                color: white;
            }

            .faq-cta p {
                font-size: 1.2rem;
                margin-bottom: 20px;
            }

            .cta-button {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                background: #25D366;
                color: white;
                padding: 12px 30px;
                border-radius: 50px;
                text-decoration: none;
                font-weight: 600;
                font-size: 1.1rem;
                transition: transform 0.3s, box-shadow 0.3s;
            }

            .cta-button:hover {
                transform: translateY(-3px);
                box-shadow: 0 10px 20px rgba(37, 211, 102, 0.3);
            }

            .cta-button i {
                font-size: 1.3rem;
            }

            .response-time {
                margin-top: 15px;
                font-size: 0.9rem;
                opacity: 0.9;
            }

            /* Keyword styling for SEO */
            .keyword {
                background: #fff3cd;
                color: #856404;
                padding: 2px 6px;
                border-radius: 4px;
                font-weight: 600;
                font-style: italic;
            }

            /* FAQ animation */
            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-question {
                cursor: pointer;
                padding: 20px;
                background: #f8f9fa;
                border-radius: 10px;
                margin-bottom: 10px;
                display: flex;
                justify-content: space-between;
                align-items: center;
                transition: background 0.3s;
            }

            .faq-question:hover {
                background: #e9ecef;
            }

            .faq-question h3 {
                margin: 0;
                font-size: 1.1rem;
                color: #333;
            }

            .faq-icon {
                transition: transform 0.3s;
            }

            .faq-answer {
                padding: 0 20px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s, padding 0.3s;
            }

            .faq-item.active .faq-answer {
                padding: 20px;
                max-height: 1000px;
            }

            .faq-answer p {
                margin: 0;
                line-height: 1.6;
                color: #666;
            }

            .faq-answer br {
                margin-bottom: 8px;
                display: block;
            }
            .why-choose-section {
                background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
                padding: 80px 0;
                position: relative;
                overflow: hidden;
            }

            .why-choose-section::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 5px;
                background: linear-gradient(90deg, #667eea, #764ba2, #f093fb);
            }

            .section-header {
                text-align: center;
                margin-bottom: 60px;
            }

            .section-title {
                font-size: 2.8rem;
                background: linear-gradient(90deg, #667eea, #764ba2);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
                margin-bottom: 15px;
                font-weight: 800;
            }

            .section-subtitle {
                font-size: 1.2rem;
                color: #666;
                max-width: 700px;
                margin: 0 auto;
            }

            /* USP Banner */
            .usp-banner {
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                border-radius: 20px;
                padding: 40px;
                color: white;
                margin-bottom: 50px;
                display: flex;
                justify-content: space-between;
                align-items: center;
                box-shadow: 0 20px 40px rgba(102, 126, 234, 0.3);
            }

            .usp-content h3 {
                font-size: 1.8rem;
                margin-bottom: 15px;
            }

            .usp-content p {
                font-size: 1.1rem;
                opacity: 0.9;
                max-width: 600px;
            }

            .usp-stats {
                display: flex;
                gap: 40px;
            }

            .stat-item {
                text-align: center;
            }

            .stat-number {
                display: block;
                font-size: 2.5rem;
                font-weight: 800;
                line-height: 1;
            }

            .stat-label {
                font-size: 0.9rem;
                opacity: 0.9;
                margin-top: 5px;
            }

            /* Features Grid */
            .features-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                gap: 30px;
                margin-bottom: 60px;
            }

            .feature-premium {
                background: white;
                border-radius: 15px;
                padding: 30px;
                box-shadow: 0 10px 30px rgba(0,0,0,0.08);
                border: 2px solid transparent;
                transition: all 0.3s ease;
                position: relative;
                overflow: hidden;
            }

            .feature-premium:hover {
                transform: translateY(-10px);
                box-shadow: 0 20px 40px rgba(0,0,0,0.15);
                border-color: #667eea;
            }

            .feature-badge {
                position: absolute;
                top: 15px;
                right: 15px;
                background: linear-gradient(45deg, #667eea, #764ba2);
                color: white;
                padding: 5px 15px;
                border-radius: 20px;
                font-size: 0.8rem;
                font-weight: 600;
            }

            .feature-icon {
                width: 70px;
                height: 70px;
                background: linear-gradient(135deg, #667eea, #764ba2);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                margin-bottom: 25px;
                font-size: 1.8rem;
                color: white;
            }

            .feature-card h3 {
                font-size: 1.4rem;
                margin-bottom: 15px;
                color: #333;
            }

            .feature-card p {
                color: #666;
                line-height: 1.6;
                margin-bottom: 20px;
            }

            .feature-list {
                list-style: none;
                padding: 0;
            }

            .feature-list li {
                padding: 8px 0;
                color: #555;
                position: relative;
                padding-left: 25px;
            }

            .feature-list li:before {
                content: '✓';
                position: absolute;
                left: 0;
                color: #4CAF50;
                font-weight: bold;
            }

            /* Process Timeline */
            .process-timeline {
                background: white;
                border-radius: 20px;
                padding: 40px;
                margin: 60px 0;
                box-shadow: 0 10px 30px rgba(0,0,0,0.08);
            }

            .timeline-title {
                text-align: center;
                font-size: 2rem;
                margin-bottom: 40px;
                color: #333;
            }

            .timeline {
                display: flex;
                flex-wrap: wrap;
                gap: 30px;
                justify-content: center;
            }

            .timeline-step {
                flex: 1;
                min-width: 250px;
                position: relative;
                padding: 25px;
                background: #f8f9fa;
                border-radius: 15px;
                border-left: 4px solid #667eea;
            }

            .step-number {
                position: absolute;
                top: -15px;
                left: -15px;
                width: 40px;
                height: 40px;
                background: linear-gradient(135deg, #667eea, #764ba2);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-weight: bold;
                font-size: 1.2rem;
            }

            .step-content h4 {
                color: #333;
                margin-bottom: 10px;
                font-size: 1.1rem;
            }

            .step-content p {
                color: #666;
                font-size: 0.95rem;
                line-height: 1.5;
            }

            /* Comparison Table */
            .comparison-table {
                margin: 60px 0;
                background: white;
                border-radius: 20px;
                padding: 40px;
                box-shadow: 0 10px 30px rgba(0,0,0,0.08);
            }

            .comparison-table h3 {
                text-align: center;
                font-size: 2rem;
                margin-bottom: 40px;
                color: #333;
            }

            .table-responsive {
                overflow-x: auto;
            }

            .comparison {
                width: 100%;
                border-collapse: collapse;
            }

            .comparison th {
                background: #f8f9fa;
                padding: 20px;
                text-align: left;
                font-weight: 600;
                color: #333;
                border-bottom: 2px solid #667eea;
            }

            .comparison td {
                padding: 15px 20px;
                border-bottom: 1px solid #eee;
                color: #666;
            }

            .comparison tr:hover {
                background: #f9f9f9;
            }

            .comparison .highlight {
                background: #e8f5e9;
                color: #2e7d32;
                font-weight: 600;
                position: relative;
            }

            .comparison .highlight:after {
                content: '✓';
                position: absolute;
                right: 20px;
                color: #4CAF50;
                font-weight: bold;
            }

            /* Trust Indicators */
            .trust-indicators {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin: 60px 0;
            }

            .trust-card {
                background: white;
                padding: 30px;
                border-radius: 15px;
                text-align: center;
                box-shadow: 0 10px 20px rgba(0,0,0,0.05);
                transition: transform 0.3s;
            }

            .trust-card:hover {
                transform: translateY(-5px);
            }

            .trust-icon {
                width: 60px;
                height: 60px;
                background: linear-gradient(135deg, #667eea, #764ba2);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 1.5rem;
                color: white;
            }

            .trust-card h4 {
                color: #333;
                margin-bottom: 15px;
                font-size: 1.2rem;
            }

            .trust-card p {
                color: #666;
                font-size: 0.95rem;
                line-height: 1.5;
            }

            /* Final CTA */
            .final-cta {
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                border-radius: 20px;
                padding: 50px;
                text-align: center;
                color: white;
                box-shadow: 0 20px 40px rgba(102, 126, 234, 0.3);
            }

            .final-cta h3 {
                font-size: 2.2rem;
                margin-bottom: 20px;
            }

            .final-cta p {
                font-size: 1.1rem;
                opacity: 0.9;
                max-width: 700px;
                margin: 0 auto 30px;
            }

            .cta-buttons {
                display: flex;
                gap: 20px;
                justify-content: center;
                flex-wrap: wrap;
            }

            .btn-primary, .btn-secondary {
                padding: 15px 30px;
                border-radius: 50px;
                text-decoration: none;
                font-weight: 600;
                font-size: 1.1rem;
                display: inline-flex;
                align-items: center;
                gap: 10px;
                transition: all 0.3s;
            }

            .btn-primary {
                background: white;
                color: #667eea;
            }

            .btn-primary:hover {
                background: #f8f9fa;
                transform: translateY(-3px);
                box-shadow: 0 10px 20px rgba(255,255,255,0.2);
            }

            .btn-secondary {
                background: transparent;
                color: white;
                border: 2px solid white;
            }

            .btn-secondary:hover {
                background: rgba(255,255,255,0.1);
                transform: translateY(-3px);
            }

            /* Responsive Design */
            @media (max-width: 992px) {
                .usp-banner {
                    flex-direction: column;
                    text-align: center;
                    gap: 30px;
                }
                
                .usp-stats {
                    justify-content: center;
                    gap: 30px;
                }
                
                .features-grid {
                    grid-template-columns: 1fr;
                }
            }

            @media (max-width: 768px) {
                .section-title {
                    font-size: 2.2rem;
                }
                
                .usp-stats {
                    flex-wrap: wrap;
                }
                
                .timeline-step {
                    min-width: 100%;
                }
                
                .trust-indicators {
                    grid-template-columns: 1fr;
                }
                
                .final-cta {
                    padding: 30px 20px;
                }
                
                .final-cta h3 {
                    font-size: 1.8rem;
                }
                
                .cta-buttons {
                    flex-direction: column;
                    align-items: center;
                }
                
                .btn-primary, .btn-secondary {
                    width: 100%;
                    justify-content: center;
                }
            }

            /* Animation */
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(30px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            .animate-on-scroll {
                animation: fadeInUp 0.6s ease-out;
            }
            /* ===== NEW SEO SECTION STYLES ===== */
