            .intent-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-left-color: var(--amber-accent);
            }

            .intent-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 4px;
                background: var(--corporate-gradient);
                transform: scaleX(0);
                transition: transform 0.3s ease;
            }

            .intent-card:hover::before {
                transform: scaleX(1);
