            .question-item p {
                color: #4B5563;
                line-height: 1.7;
                margin-left: 40px;
                font-size: 1rem;
                padding-right: 10px;
            }

            /* Animation for paragraph reveal */
            .question-item p {
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.5s ease-out, margin-top 0.3s ease;
                margin-top: 0;
            }

            .question-item.active p {
                max-height: 500px;
