            /* Add subtle background pattern to student questions */
            .student-questions {
                background-image: 
                    radial-gradient(circle at 10% 20%, rgba(180, 83, 9, 0.05) 0%, transparent 20%),
                    radial-gradient(circle at 90% 80%, rgba(31, 41, 51, 0.05) 0%, transparent 20%);
                background-repeat: no-repeat;
            }

            /* Add numbers to intent cards */
            .intent-card {
                counter-increment: intent-card;
            }

            .intent-card::after {
                content: '0' counter(intent-card);
                position: absolute;
                top: 15px;
                right: 15px;
                font-size: 2.5rem;
                font-weight: 900;
                color: rgba(31, 41, 51, 0.1);
                line-height: 1;
                transition: var(--transition-fast);
            }

            .intent-card:hover::after {
                color: rgba(180, 83, 9, 0.2);
                transform: scale(1.1);
            }

            /* For 4th card, remove the zero */
            .intent-card:nth-child(4)::after {
                content: counter(intent-card);
            }
