            <!-- ══ JAVASCRIPT (unchanged except variable names) ══ -->
            <script>
            (function(){
                'use strict';
                var uid = '<?php echo $uid; ?>';
                function q(id){ return document.getElementById(uid+'-'+id); }
                function qsa(sel){ return document.querySelectorAll('.'+uid+' '+sel); }

                function init(){
                    // Hamburger menu
                    var ham = q('ham'), nl = q('nl');
                    if(ham && nl){
                        ham.addEventListener('click', function(){
                            nl.classList.toggle('open');
                            ham.innerHTML = nl.classList.contains('open') ? '<i class="fas fa-times"></i>' : '&#9776;';
                        });
                        document.addEventListener('click', function(e){
                            if(!ham.contains(e.target) && !nl.contains(e.target)){
                                nl.classList.remove('open'); ham.innerHTML = '&#9776;';
                            }
                        });
                        nl.querySelectorAll('a').forEach(function(a){
                            a.addEventListener('click', function(){ nl.classList.remove('open'); ham.innerHTML = '&#9776;'; });
                        });
                    }

                    // Scroll reveal
                    if('IntersectionObserver' in window){
                        var io = new IntersectionObserver(function(entries){
                            entries.forEach(function(e){ if(e.isIntersecting) e.target.classList.add('in'); });
                        },{threshold:0.08, rootMargin:'0px 0px -30px 0px'});
                        qsa('.rv').forEach(function(el){ io.observe(el); });
                    } else { qsa('.rv').forEach(function(el){ el.classList.add('in'); }); }

                    // Counter animation
                    var counted = false, sb = q('stats');
                    if(sb){
                        var sio = new IntersectionObserver(function(entries){
                            if(entries[0].isIntersecting && !counted){
                                counted = true;
                                sb.querySelectorAll('.sn').forEach(function(el){
                                    var target = parseInt(el.getAttribute('data-n')||'0');
                                    var step   = Math.ceil(target/60);
                                    var start  = 0;
                                    var suffix = el.getAttribute('data-n') === '98' ? '%' : '+';
                                    var timer  = setInterval(function(){
                                        start += step;
                                        if(start >= target){ start = target; clearInterval(timer); }
                                        el.textContent = start + suffix;
                                    }, 18);
                                });
                            }
                        },{threshold:0.5});
                        sio.observe(sb);
                    }

                    // FAQ toggle
                    qsa('.fi').forEach(function(item){
                        var btn = item.querySelector('.fq');
                        if(btn) btn.addEventListener('click', function(){
                            qsa('.fi.open').forEach(function(o){ if(o !== item) o.classList.remove('open'); });
                            item.classList.toggle('open');
                        });
                    });

                    // Scroll to top
                    var stbtn = q('stbtn');
                    window.addEventListener('scroll', function(){ if(stbtn) stbtn.classList.toggle('show', window.scrollY > 600); },{passive:true});
                    if(stbtn) stbtn.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });

                    // Social proof toast
                    var names = [
                        {i:'PR',n:'Priya from <?php echo $city; ?>',a:'just booked a consultation'},
                        {i:'KS',n:'Karthik from Coimbatore',   a:'just got SPSS analysis done'},
                        {i:'AM',n:'Arun from Madurai',         a:'just WhatsApp-ed for topic list'},
                        {i:'SL',n:'Sneha from <?php echo $city; ?>',a:'just got MBA report delivered'},
                        {i:'RJ',n:'Ravi from Trichy',          a:'just started BBA project'},
                    ];
                    var toast = q('toast'), shown = 0;
                    function showToast(){
                        if(shown >= names.length) return;
                        var n = names[shown++];
                        toast.querySelector('.spd').textContent = n.i;
                        toast.querySelector('span').innerHTML = '<strong>'+n.n+'</strong> '+n.a;
                        toast.classList.add('show');
                        setTimeout(function(){ toast.classList.remove('show'); }, 5000);
                        if(shown < names.length) setTimeout(showToast, 13000);
                    }
                    setTimeout(showToast, 4000);

                    // Smooth scroll anchors
                    qsa('a[href^="#"]').forEach(function(a){
                        a.addEventListener('click', function(e){
                            var t = this.getAttribute('href');
                            if(t === '#' || t === '#!') return;
                            var el = document.querySelector(t);
                            if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth'}); }
                        });
                    });

                    // Modal — exit intent
                    var modal  = q('modal');
                    var mclose = q('mclose');
                    var mform  = q('form');
                    var mshown = sessionStorage.getItem(uid+'_modal') === '1';
                    if(!mshown){
                        document.addEventListener('mouseleave', function(e){
                            if(e.clientY <= 0 && modal && !mshown){
                                modal.classList.add('active'); mshown = true;
                                sessionStorage.setItem(uid+'_modal','1');
                            }
                        });
                    }
                    if(mclose) mclose.addEventListener('click', function(){ modal.classList.remove('active'); });
                    if(modal)  modal.addEventListener('click',  function(e){ if(e.target === modal) modal.classList.remove('active'); });
                    if(mform) mform.addEventListener('submit', function(e){
                        e.preventDefault();
                        var name   = this.name.value.trim();
                        var email  = this.email.value.trim();
                        var phone  = this.phone.value.trim();
                        var course = this.course.value;
                        if(!name || !email || !phone){ alert('Please fill all required fields.'); return; }
                        var msg = 'MBA/BBA+Lead+from+<?php echo $city_url; ?>%0AName:+'+encodeURIComponent(name)
                                + '%0AEmail:+'+encodeURIComponent(email)
                                + '%0APhone:+'+encodeURIComponent(phone)
                                + '%0ACourse:+'+encodeURIComponent(course||'Not+specified')
                                + '%0A%0APlease+send+me+the+project+topic+catalog.';
                        window.open('https://wa.me/919751797695?text='+msg, '_blank');
                        modal.classList.remove('active');
                    });

                    // Callback widget
                    var cbBtn = q('cbBtn');
                    if(cbBtn){
                        cbBtn.addEventListener('click', function(){
                            var name    = (document.getElementById(uid+'-cbName').value||'').trim();
                            var phone   = (document.getElementById(uid+'-cbPhone').value||'').trim();
                            var domain  = document.getElementById(uid+'-cbDomain').value;
                            var urgency = document.getElementById(uid+'-cbUrgency').value;
                            if(!name || !phone){ alert('Please enter your name and phone number.'); return; }
                            var msg = 'Callback+Request+from+<?php echo $city_url; ?>%0AName:+'+encodeURIComponent(name)
                                    + '%0APhone:+'+encodeURIComponent(phone)
                                    + '%0ASpecialization:+'+encodeURIComponent(domain||'Not+specified')
                                    + '%0AUrgency:+'+encodeURIComponent(urgency||'Not+specified');
                            window.open('https://wa.me/919751797695?text='+msg, '_blank');
                            document.getElementById(uid+'-cbInputs').style.display = 'none';
                            document.getElementById(uid+'-cbSuccess').style.display = 'block';
                        });
                    }
                }

                if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
                else init();
            })();
            </script>

        </div><!-- .fymb-shortcode -->
        <?php
        return ob_get_clean();
    }
