                border-radius: var(--border-radius);
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
            }

            .stat-number {
                font-size: 2.5rem;
                font-weight: 800;
                color: var(--royal-blue);
                margin-bottom: 5px;
            }

            .stat-label {
                font-size: 0.9rem;
                color: #64748B;
                font-weight: 600;
            }

            .cta-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                margin-top: 40px;
                animation: fadeInUp 0.8s ease 1s both;
            }

            @media (min-width: 768px) {
                .cta-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            /* ===== ANIMATIONS ===== */
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(30px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            @keyframes slideInLeft {
                from {
                    opacity: 0;
                    transform: translateX(-30px);
                }
                to {
                    opacity: 1;
                    transform: translateX(0);
                }
            }

            @keyframes slideInRight {
                from {
                    opacity: 0;
                    transform: translateX(30px);
                }
                to {
                    opacity: 1;
                    transform: translateX(0);
                }
            }

            @keyframes zoomIn {
                from {
                    opacity: 0;
                    transform: scale(0.9);
                }
                to {
                    opacity: 1;
                    transform: scale(1);
                }
            }

            /* ===== SECTION COMMON STYLES ===== */
            .section-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                text-align: center;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .section-subtitle {
                font-size: 1.1rem;
                text-align: center;
                color: #64748B;
                max-width: 700px;
                margin: 0 auto 50px;
                line-height: 1.6;
            }

            /* ===== SERVICES SECTION ===== */
            .services-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .services-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 0 auto;
            }

            .service-card {
                background: var(--white);
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius-lg);
                padding: 40px 30px;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
                position: relative;
                overflow: hidden;
            }

            .service-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 4px;
                background: var(--cta-gradient);
                transform: scaleX(0);
                transition: transform 0.3s ease;
            }

            .service-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--royal-blue);
            }

            .service-card:hover::before {
                transform: scaleX(1);
            }

            .service-icon {
                width: 70px;
                height: 70px;
                background: var(--cta-gradient);
                border-radius: 16px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 25px;
                font-size: 28px;
                color: white;
                transition: var(--transition-smooth);
            }

            .service-card:hover .service-icon {
                transform: rotate(360deg) scale(1.1);
            }

            .service-card h3 {
                font-size: 1.4rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
                text-align: center;
            }

            .service-card p {
                color: #64748B;
                font-size: 1rem;
                text-align: center;
                line-height: 1.6;
            }

            .service-features {
                margin-top: 20px;
                text-align: left;
            }

            .service-features li {
                color: #64748B;
                font-size: 0.95rem;
                margin-bottom: 8px;
                padding-left: 20px;
                position: relative;
            }

            .service-features li::before {
                content: '✓';
                position: absolute;
                left: 0;
                color: var(--accent-green);
                font-weight: bold;
            }

            /* ===== INDUSTRIES SECTION ===== */
            .industries-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .industries-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 25px;
                max-width: 1200px;
                margin: 40px auto 0;
            }

            .industry-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 30px;
                text-align: center;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .industry-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--royal-blue);
            }

            .industry-icon {
                width: 60px;
                height: 60px;
                background: var(--accent-gradient);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            .industry-card h3 {
                font-size: 1.2rem;
                margin-bottom: 10px;
                color: var(--navy-dark);
            }

            .industry-card p {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== TECHNOLOGY STACK ===== */
            .tech-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .tech-categories {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .tech-category {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 30px;
                box-shadow: var(--shadow-soft);
            }

            .tech-category h3 {
                color: var(--navy-dark);
                margin-bottom: 20px;
                font-size: 1.3rem;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .tech-category h3 i {
                color: var(--royal-blue);
            }

            .tech-tags {
                display: flex;
                flex-wrap: wrap;
                gap: 10px;
            }

            .tech-tag {
                background: var(--soft-blue);
                color: var(--navy-dark);
                padding: 8px 16px;
                border-radius: 20px;
                font-size: 0.9rem;
                font-weight: 500;
                transition: var(--transition-fast);
            }

            .tech-tag:hover {
                background: var(--royal-blue);
                color: white;
                transform: translateY(-2px);
            }

            /* ===== PROCESS SECTION ===== */
            .process-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .process-steps {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
                gap: 30px;
                margin-top: 50px;
                position: relative;
            }

            .process-steps::before {
                content: '';
                position: absolute;
                top: 60px;
                left: 50px;
                right: 50px;
                height: 2px;
                background: var(--light-gray);
                z-index: 0;
            }

            @media (max-width: 768px) {
                .process-steps::before {
                    display: none;
                }
            }

            .process-step {
                text-align: center;
                position: relative;
                z-index: 1;
            }

            .step-number {
                width: 70px;
                height: 70px;
                background: var(--cta-gradient);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.5rem;
                font-weight: 800;
                margin: 0 auto 20px;
                transition: var(--transition-smooth);
                border: 5px solid white;
                box-shadow: var(--shadow-medium);
            }

            .process-step:hover .step-number {
                transform: scale(1.1) rotate(360deg);
            }

            .step-title {
                font-size: 1.2rem;
                font-weight: 700;
                margin-bottom: 10px;
                color: var(--navy-dark);
            }

            .step-description {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== CASE STUDIES ===== */
            .case-studies-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .case-studies-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .case-study-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                overflow: hidden;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .case-study-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--royal-blue);
            }

            .case-study-content {
                padding: 30px;
            }

            .case-study-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 20px;
            }

            .case-study-category {
                display: inline-block;
                background: rgba(37, 99, 235, 0.1);
                color: var(--royal-blue);
                padding: 5px 15px;
                border-radius: 20px;
                font-size: 0.85rem;
                font-weight: 600;
            }

            .case-study-title {
                font-size: 1.4rem;
                font-weight: 700;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .case-study-description {
                color: #64748B;
                font-size: 0.95rem;
                margin-bottom: 20px;
                line-height: 1.6;
            }

            .case-study-results {
                background: var(--soft-blue);
                padding: 20px;
                border-radius: 8px;
                margin-top: 20px;
            }

            .case-study-results h5 {
                color: var(--royal-blue);
                font-size: 0.9rem;
                margin-bottom: 10px;
                font-weight: 700;
            }

            .results-list {
                list-style: none;
            }

            .results-list li {
                color: #475569;
                font-size: 0.85rem;
                margin-bottom: 5px;
                padding-left: 20px;
                position: relative;
            }

            .results-list li::before {
                content: '✓';
                position: absolute;
                left: 0;
                color: var(--accent-green);
                font-weight: bold;
            }

            /* ===== WHY CHOOSE US ===== */
            .why-choose-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .why-choose-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 40px auto 0;
            }

            .why-choose-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 30px;
                text-align: center;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .why-choose-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--accent-green);
            }

            .why-choose-icon {
                width: 60px;
                height: 60px;
                background: var(--accent-gradient);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            .why-choose-card h3 {
                font-size: 1.2rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .why-choose-card p {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== TESTIMONIALS ===== */
            .testimonials-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .testimonials-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 40px;
            }

            .testimonial-card {
                background: white;
                border-radius: var(--border-radius);
                padding: 40px 30px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .testimonial-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .client-info {
                display: flex;
                align-items: center;
                gap: 15px;
                margin-bottom: 20px;
            }

            .client-avatar {
                width: 60px;
                height: 60px;
                background: var(--cta-gradient);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: 700;
                font-size: 1.5rem;
            }

            .client-details h4 {
                color: var(--navy-dark);
                margin-bottom: 5px;
                font-size: 1.1rem;
            }

            .client-details p {
                color: #64748B;
                font-size: 0.9rem;
            }

            .stars {
                color: #FBBF24;
                margin-bottom: 15px;
                font-size: 1.1rem;
            }

            .testimonial-text {
                color: #475569;
                font-style: italic;
                line-height: 1.6;
                font-size: 1rem;
            }

            .client-company {
                display: inline-block;
                background: var(--soft-blue);
                color: var(--royal-blue);
                padding: 5px 12px;
                border-radius: 15px;
                font-size: 0.85rem;
                font-weight: 600;
                margin-top: 15px;
            }

            /* ===== TRUST BADGES ===== */
            .trust-section {
                padding: 80px 15px;
                background: var(--white);
            }

            .trust-grid {
                display: flex;
                flex-wrap: wrap;
                justify-content: center;
                gap: 30px;
                margin-top: 40px;
            }

            .trust-badge {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 25px;
                text-align: center;
                width: 200px;
                transition: var(--transition-fast);
                box-shadow: var(--shadow-soft);
            }

            .trust-badge:hover {
                border-color: var(--royal-blue);
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .trust-badge i {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--royal-blue);
            }

            .trust-badge span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== FAQ SECTION ===== */
            .faq-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .faq-container {
                max-width: 800px;
                margin: 0 auto;
            }

            .faq-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                margin-bottom: 15px;
                overflow: hidden;
                transition: var(--transition-fast);
            }

            .faq-item:hover {
                border-color: var(--royal-blue);
                box-shadow: var(--shadow-soft);
            }

            .faq-question {
                padding: 25px;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                background: var(--off-white);
            }

            .faq-question h3 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin: 0;
            }

            .faq-icon {
                color: var(--royal-blue);
                transition: transform 0.3s;
            }

            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-answer {
                padding: 0 25px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s ease-out;
            }

            .faq-item.active .faq-answer {
                padding: 25px;
                max-height: 500px;
            }

            .faq-answer p {
                color: #64748B;
                line-height: 1.6;
            }

            /* ===== CTA SECTION ===== */
            .cta-section {
                padding: 100px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--royal-blue) 100%);
                text-align: center;
                color: white;
            }

            .cta-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 20px;
            }

            .cta-description {
                font-size: 1.1rem;
                margin-bottom: 40px;
                max-width: 700px;
                margin-left: auto;
                margin-right: auto;
                opacity: 0.9;
            }

            .btn {
                padding: 16px 40px;
                font-size: 1.1rem;
                font-weight: 700;
                border-radius: var(--border-radius);
                text-decoration: none;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: var(--transition-smooth);
                min-width: 220px;
                border: 2px solid transparent;
                cursor: pointer;
            }

            .btn-primary {
                background: var(--cta-gradient);
                color: white;
                box-shadow: var(--shadow-medium);
            }

            .btn-secondary {
                background: rgba(255, 255, 255, 0.1);
                border: 2px solid rgba(255, 255, 255, 0.3);
                color: white;
                backdrop-filter: blur(10px);
            }

            .btn:hover {
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-hard);
            }

            .contact-info {
                display: flex;
                flex-direction: column;
                gap: 20px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .contact-info {
                    flex-direction: row;
                    gap: 40px;
                }
            }

            .contact-item {
                display: flex;
                align-items: center;
                gap: 12px;
                color: white;
                text-decoration: none;
                opacity: 0.9;
                transition: var(--transition-fast);
            }

            .contact-item:hover {
                opacity: 1;
                transform: translateY(-3px);
            }

            .contact-item i {
                background: rgba(255, 255, 255, 0.1);
                width: 40px;
                height: 40px;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            /* ===== FLOATING ELEMENTS ===== */
            .floating-whatsapp {
                position: fixed;
                bottom: 20px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: #25D366;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 28px;
                z-index: 1000;
                box-shadow: var(--shadow-hard);
                animation: float 3s ease-in-out infinite;
                text-decoration: none;
                transition: var(--transition-smooth);
            }

            .floating-whatsapp:hover {
                transform: scale(1.1) rotate(10deg);
                animation: none;
            }

            .floating-call {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 20px;
                z-index: 1000;
                box-shadow: var(--shadow-medium);
                text-decoration: none;
                transition: var(--transition-fast);
                display: none;
            }

            @media (max-width: 768px) {
                .floating-call {
                    display: flex;
                }
            }

            .floating-call:hover {
                transform: scale(1.1);
            }

            .scroll-to-top {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 18px;
                z-index: 1000;
                cursor: pointer;
                opacity: 0;
                visibility: hidden;
                transition: all 0.3s;
                box-shadow: var(--shadow-soft);
            }

            @media (max-width: 768px) {
                .scroll-to-top {
                    bottom: 150px;
                }
            }

            .scroll-to-top.visible {
                opacity: 1;
                visibility: visible;
            }

            .scroll-to-top:hover {
                background: var(--navy-dark);
                transform: translateY(-5px);
            }

            @keyframes float {
                0%, 100% { transform: translateY(0); }
                50% { transform: translateY(-10px); }
            }

            /* ===== ANIMATION CLASSES ===== */
            .animate-on-scroll {
                opacity: 0;
                transform: translateY(30px);
                transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1), 
                            transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            }

            .animate-on-scroll.visible {
                opacity: 1;
                transform: translateY(0);
            }

            .animate-left {
                opacity: 0;
                transform: translateX(-30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-left.visible {
                opacity: 1;
                transform: translateX(0);
            }

            .animate-right {
                opacity: 0;
                transform: translateX(30px);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-right.visible {
                opacity: 1;
                transform: translateX(0);
            }

            .animate-zoom {
                opacity: 0;
                transform: scale(0.9);
                transition: opacity 0.8s ease, transform 0.8s ease;
            }

            .animate-zoom.visible {
                opacity: 1;
                transform: scale(1);
            }

            /* ===== MODAL POPUP ===== */
            .modal-overlay {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0, 0, 0, 0.8);
                z-index: 2000;
                display: none;
                justify-content: center;
                align-items: center;
                padding: 20px;
            }

            .modal-content {
                background: white;
                border-radius: var(--border-radius);
                padding: 40px;
                max-width: 500px;
                width: 100%;
                position: relative;
                animation: zoomIn 0.5s ease;
            }

            .modal-close {
                position: absolute;
                top: 15px;
                right: 15px;
                background: none;
                border: none;
                font-size: 24px;
                color: #64748B;
                cursor: pointer;
                transition: var(--transition-fast);
            }

            .modal-close:hover {
                color: var(--navy-dark);
                transform: rotate(90deg);
            }

            /* ===== MOBILE RESPONSIVE ===== */
            @media (max-width: 768px) {
                .nav-links {
                    display: none;
                    position: fixed;
                    top: 70px;
                    left: 0;
                    width: 100%;
                    background: white;
                    flex-direction: column;
                    padding: 20px;
                    box-shadow: var(--shadow-hard);
                    z-index: 999;
                }
                
                .nav-links.active {
