        <script>
        document.addEventListener('DOMContentLoaded', function() {
            // Performance Optimizations
            const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
            
            // Preloader
            window.addEventListener('load', function() {
                setTimeout(() => {
                    const preloader = document.getElementById('preloader');
                    preloader.style.opacity = '0';
                    setTimeout(() => {
                        preloader.style.display = 'none';
                    }, 300);
                }, 300);
            });

            // Mobile Menu
            const mobileBtn = document.getElementById('mobileMenuBtn');
            const navLinks = document.getElementById('navLinks');
            
            if (mobileBtn) {
                mobileBtn.addEventListener('click', function() {
                    navLinks.classList.toggle('active');
                    this.innerHTML = navLinks.classList.contains('active') ? 
                        '<i class="fas fa-times"></i>' : 
                        '<i class="fas fa-bars"></i>';
                });
            }

            // Close mobile menu when clicking outside
            document.addEventListener('click', function(event) {
                if (!mobileBtn.contains(event.target) && !navLinks.contains(event.target)) {
                    navLinks.classList.remove('active');
                    mobileBtn.innerHTML = '<i class="fas fa-bars"></i>';
                }
            });

            // Sticky Navigation
            const nav = document.getElementById('stickyNav');
            let lastScrollTop = 0;
            
            window.addEventListener('scroll', function() {
                const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
                
                if (scrollTop > 100) {
                    nav.classList.remove('hidden');
                    if (scrollTop > lastScrollTop && scrollTop > 200) {
                        nav.classList.add('hidden');
                    } else {
                        nav.classList.remove('hidden');
                    }
                } else {
                    nav.classList.remove('hidden');
                }
                
                lastScrollTop = scrollTop;
            });

            // Intersection Observer for animations
            const observerOptions = {
                threshold: 0.1,
                rootMargin: '0px 0px -50px 0px'
            };

            const scrollObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                    }
                });
            }, observerOptions);

            // Observe all animated elements
            document.querySelectorAll('.animate-on-scroll, .animate-left, .animate-right, .animate-zoom').forEach(el => {
                scrollObserver.observe(el);
            });

            // Stats Counter Animation
            const statNumbers = document.querySelectorAll('.stat-number');
            const countObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const stat = entry.target;
                        const target = parseInt(stat.getAttribute('data-count'));
                        const increment = target / 50;
                        let current = 0;
                        
                        const updateCount = () => {
                            if (current < target) {
                                current += increment;
                                stat.textContent = Math.floor(current) + (stat.textContent.includes('%') ? '%' : '+');
                                setTimeout(updateCount, 20);
                            } else {
                                stat.textContent = target + (stat.textContent.includes('%') ? '%' : '+');
                            }
                        };
                        
                        updateCount();
                        countObserver.unobserve(stat);
                    }
                });
            }, { threshold: 0.5 });
            
            statNumbers.forEach(stat => {
                countObserver.observe(stat);
            });

            // FAQ Toggle
            document.querySelectorAll('.faq-question').forEach(question => {
                question.addEventListener('click', function() {
                    const item = this.parentElement;
                    item.classList.toggle('active');
                });
            });

            // Scroll to Top
            const scrollBtn = document.getElementById('scrollToTop');
            window.addEventListener('scroll', () => {
                scrollBtn.classList.toggle('visible', window.scrollY > 500);
            });

            scrollBtn.addEventListener('click', () => {
                window.scrollTo({ top: 0, behavior: 'smooth' });
            });

            // Smooth Scrolling
            document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                anchor.addEventListener('click', function(e) {
                    const href = this.getAttribute('href');
                    if (href === '#' || href === '#!') return;
                    
                    e.preventDefault();
                    const target = document.querySelector(href);
                    if (target) {
                        if (navLinks.classList.contains('active')) {
                            navLinks.classList.remove('active');
                            mobileBtn.innerHTML = '<i class="fas fa-bars"></i>';
                        }
                        
                        target.scrollIntoView({
                            behavior: 'smooth',
                            block: 'start'
                        });
                    }
                });
            });

            // Countdown Timer
            function updateCountdown() {
                const now = new Date();
                const endTime = new Date(now);
                endTime.setHours(23, 59, 59, 999);
                
                const diff = endTime - now;
                
                const hours = Math.floor(diff / (1000 * 60 * 60));
                const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
                const seconds = Math.floor((diff % (1000 * 60)) / 1000);
                
                document.getElementById('hours').textContent = hours.toString().padStart(2, '0');
                document.getElementById('minutes').textContent = minutes.toString().padStart(2, '0');
                document.getElementById('seconds').textContent = seconds.toString().padStart(2, '0');
            }
            
            setTimeout(() => {
                document.getElementById('countdownBanner').style.display = 'block';
                updateCountdown();
                setInterval(updateCountdown, 1000);
            }, 5000);

            // Lead Modal
            const leadModal = document.getElementById('leadModal');
            const modalClose = document.getElementById('modalClose');
            const leadForm = document.getElementById('leadForm');
            
            function showModal() {
                leadModal.style.display = 'flex';
            }
            
            // Show modal after 20 seconds
            setTimeout(() => {
                if (!localStorage.getItem('modalShown')) {
                    showModal();
                }
            }, 20000);
            
            // Exit intent modal
            document.addEventListener('mouseout', function(e) {
                if (!e.toElement && !e.relatedTarget && e.clientY < 10) {
                    if (!localStorage.getItem('modalShown')) {
                        showModal();
                    }
                }
            });
            
            // Close modal
            modalClose.addEventListener('click', () => {
                leadModal.style.display = 'none';
                localStorage.setItem('modalShown', 'true');
            });
            
            leadModal.addEventListener('click', (e) => {
                if (e.target === leadModal) {
                    leadModal.style.display = 'none';
                    localStorage.setItem('modalShown', 'true');
                }
            });
            
            // Form submission
            leadForm.addEventListener('submit', function(e) {
                e.preventDefault();
                
                const formData = new FormData(this);
                const name = formData.get('name') || 'Not provided';
                const company = formData.get('company') || 'Not provided';
                const email = formData.get('email') || 'Not provided';
                const phone = formData.get('phone') || 'Not provided';
                const service = formData.get('service') || 'Not provided';
                const description = formData.get('description') || 'Not provided';
                
                const message = `New Enterprise Lead:%0A%0AName: ${name}%0ACompany: ${company}%0AEmail: ${email}%0APhone: ${phone}%0AService: ${service}%0ADescription: ${description}`;
                
                window.open(`https://wa.me/919751797695?text=${message}`, '_blank');
                
                leadModal.style.display = 'none';
                localStorage.setItem('modalShown', 'true');
                
                // Show success message
                alert('Thank you! Our team will contact you within 24 hours with a detailed proposal.');
                
                // Reset form
                this.reset();
            });

            // Lazy load images
            if ('IntersectionObserver' in window) {
                const imageObserver = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            const img = entry.target;
                            img.src = img.dataset.src;
                            img.classList.add('loaded');
                            imageObserver.unobserve(img);
                        }
                    });
                });
                
                document.querySelectorAll('img[data-src]').forEach(img => {
                    imageObserver.observe(img);
                });
            }
        });
        </script>
