            }

            .container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 0 20px;
                width: 100%;
            }

            /* ===== PRELOADER ===== */
            .preloader {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: var(--white);
                z-index: 9999;
                display: flex;
                justify-content: center;
                align-items: center;
                transition: opacity 0.5s ease;
            }

            .loader {
                width: 50px;
                height: 50px;
                border: 3px solid var(--light-gray);
                border-top: 3px solid var(--royal-blue);
                border-radius: 50%;
                animation: spin 1s linear infinite;
            }

            @keyframes spin {
                0% { transform: rotate(0deg); }
                100% { transform: rotate(360deg); }
            }

            /* ===== PROFESSIONAL NAVIGATION ===== */
            .professional-nav {
                background: var(--white);
                box-shadow: var(--shadow-soft);
                position: fixed;
                top: 0;
                width: 100%;
                z-index: 1000;
                padding: 15px 0;
            }

            .nav-container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 0 20px;
                display: flex;
                justify-content: space-between;
                align-items: center;
            }

            .logo {
                font-size: 1.8rem;
                font-weight: 800;
                color: var(--navy-dark);
                text-decoration: none;
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .logo span {
                background: var(--cta-gradient);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
            }

            .nav-links {
                display: flex;
                gap: 30px;
                align-items: center;
            }

            .nav-links a {
                color: var(--navy-medium);
                text-decoration: none;
                font-weight: 600;
                font-size: 0.95rem;
                transition: var(--transition-fast);
                padding: 8px 12px;
                border-radius: 6px;
            }

            .nav-links a:hover {
                color: var(--royal-blue);
                background: rgba(37, 99, 235, 0.1);
            }

            .nav-cta {
                background: var(--cta-gradient);
                color: white !important;
                padding: 10px 25px !important;
                border-radius: 25px;
            }

            .nav-cta:hover {
                transform: translateY(-2px);
                box-shadow: var(--shadow-medium);
            }

            .mobile-menu-btn {
                display: none;
                background: none;
                border: none;
                font-size: 1.5rem;
                color: var(--navy-dark);
                cursor: pointer;
            }

            /* ===== HERO SECTION ===== */
            .hero-section {
                min-height: 90vh;
                padding: 160px 15px 80px;
                background: linear-gradient(135deg, var(--off-white) 0%, var(--white) 100%);
                position: relative;
                overflow: hidden;
            }

            .hero-content {
                max-width: 1200px;
                margin: 0 auto;
                text-align: center;
            }

            .hero-badge {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                background: rgba(37, 99, 235, 0.1);
                border: 2px solid var(--royal-blue);
                color: var(--royal-blue);
                padding: 10px 25px;
                border-radius: 30px;
                font-weight: 700;
                margin-bottom: 30px;
                font-size: 0.95rem;
                animation: fadeInUp 0.8s ease;
            }

            .hero-title {
                font-size: clamp(2.5rem, 5vw, 3.8rem);
                font-weight: 800;
                line-height: 1.1;
                margin-bottom: 25px;
                color: var(--navy-dark);
                animation: fadeInUp 0.8s ease 0.2s both;
            }

            .hero-title span {
                background: var(--cta-gradient);
                -webkit-background-clip: text;
                background-clip: text;
                color: transparent;
            }

            .hero-subtitle {
                font-size: clamp(1.2rem, 2.5vw, 1.5rem);
                color: #475569;
                margin-bottom: 25px;
                max-width: 800px;
                margin-left: auto;
                margin-right: auto;
                animation: fadeInUp 0.8s ease 0.4s both;
            }

            .hero-description {
                font-size: 1.1rem;
                color: #64748B;
                max-width: 800px;
                margin: 0 auto 40px;
                line-height: 1.7;
                animation: fadeInUp 0.8s ease 0.6s both;
            }

            .features-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 20px;
                max-width: 900px;
                margin: 40px auto;
                animation: fadeInUp 0.8s ease 0.8s both;
            }

            .feature-item {
                text-align: center;
                padding: 25px 20px;
                background: white;
                border-radius: var(--card-radius);
                box-shadow: var(--shadow-soft);
                transition: var(--transition-smooth);
                border: 1px solid var(--light-gray);
            }

            .feature-item:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--royal-blue);
            }

            .feature-icon {
                width: 60px;
                height: 60px;
                background: var(--cta-gradient);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            .feature-item h4 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin-bottom: 10px;
            }

            .feature-item p {
                color: #64748B;
                font-size: 0.9rem;
            }

            .stats-counter {
                display: grid;
                grid-template-columns: repeat(2, 1fr);
                gap: 20px;
                max-width: 800px;
                margin: 50px auto;
                animation: fadeInUp 0.8s ease 1s both;
            }

            @media (min-width: 768px) {
                .stats-counter {
                    grid-template-columns: repeat(4, 1fr);
                    gap: 30px;
                }
            }

            .stat-item {
                text-align: center;
                padding: 25px;
                background: white;
                border-radius: var(--card-radius);
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
            }

            .stat-number {
                font-size: 2.5rem;
                font-weight: 800;
                color: var(--royal-blue);
                margin-bottom: 5px;
            }

            .stat-label {
                font-size: 0.95rem;
                color: #64748B;
                font-weight: 600;
            }

            .hero-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .hero-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .btn {
                padding: 16px 40px;
                font-size: 1.1rem;
                font-weight: 700;
                border-radius: var(--border-radius);
                text-decoration: none;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                transition: var(--transition-smooth);
                min-width: 220px;
                border: 2px solid transparent;
                cursor: pointer;
            }

            .btn-primary {
                background: var(--cta-gradient);
                color: white;
                box-shadow: var(--shadow-medium);
            }

            .btn-secondary {
                background: white;
                border: 2px solid var(--royal-blue);
                color: var(--royal-blue);
            }

            .btn:hover {
                transform: translateY(-5px) scale(1.05);
                box-shadow: var(--shadow-hard);
            }

            /* ===== ANIMATIONS ===== */
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(30px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }

            @keyframes slideInLeft {
                from {
                    opacity: 0;
                    transform: translateX(-30px);
                }
                to {
                    opacity: 1;
                    transform: translateX(0);
                }
            }

            @keyframes slideInRight {
                from {
                    opacity: 0;
                    transform: translateX(30px);
                }
                to {
                    opacity: 1;
                    transform: translateX(0);
                }
            }

            /* ===== TRAINING PROGRAMS ===== */
            .training-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .section-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                text-align: center;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .section-subtitle {
                font-size: 1.1rem;
                text-align: center;
                color: #64748B;
                max-width: 700px;
                margin: 0 auto 50px;
            }

            .programs-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 0 auto;
            }

            .program-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--card-radius);
                padding: 35px;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
                position: relative;
                overflow: hidden;
            }

            .program-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 5px;
                background: var(--cta-gradient);
                transform: scaleX(0);
                transition: transform 0.3s ease;
            }

            .program-card:hover {
                transform: translateY(-10px) scale(1.02);
                box-shadow: var(--shadow-hard);
                border-color: var(--royal-blue);
            }

            .program-card:hover::before {
                transform: scaleX(1);
            }

            .program-icon {
                width: 70px;
                height: 70px;
                background: var(--cta-gradient);
                border-radius: 16px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 25px;
                font-size: 28px;
                color: white;
                transition: var(--transition-smooth);
            }

            .program-card:hover .program-icon {
                transform: rotate(360deg) scale(1.1);
            }

            .program-card h3 {
                font-size: 1.3rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
                text-align: center;
            }

            .program-features {
                list-style: none;
                margin: 25px 0;
            }

            .program-features li {
                color: #64748B;
                font-size: 0.95rem;
                margin-bottom: 10px;
                padding-left: 25px;
                position: relative;
            }

            .program-features li::before {
                content: '✓';
                position: absolute;
                left: 0;
                color: var(--accent-green);
                font-weight: bold;
            }

            .program-price {
                font-size: 1.8rem;
                font-weight: 800;
                color: var(--navy-dark);
                text-align: center;
                margin: 20px 0;
            }

            .program-price span {
                font-size: 0.9rem;
                color: #64748B;
                font-weight: 500;
            }

            /* ===== CONSULTING SERVICES ===== */
            .consulting-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .services-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 50px auto 0;
            }

            .service-card {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--card-radius);
                padding: 35px;
                text-align: center;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .service-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
                border-color: var(--accent-green);
            }

            .service-icon {
                width: 70px;
                height: 70px;
                background: var(--success-gradient);
                border-radius: 16px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 25px;
                font-size: 28px;
                color: white;
            }

            .service-card h3 {
                font-size: 1.3rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .service-card p {
                color: #64748B;
                font-size: 0.95rem;
                line-height: 1.6;
            }

            /* ===== INDUSTRIES SERVED ===== */
            .industries-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .industries-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 25px;
                max-width: 1000px;
                margin: 50px auto 0;
            }

            .industry-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--card-radius);
                padding: 30px 20px;
                text-align: center;
                transition: var(--transition-fast);
                box-shadow: var(--shadow-soft);
            }

            .industry-item:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--royal-blue);
            }

            .industry-icon {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--royal-blue);
            }

            .industry-item h4 {
                font-size: 1.1rem;
                font-weight: 700;
                color: var(--navy-dark);
            }

            /* ===== TECHNOLOGY STACK ===== */
            .tech-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .tech-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
                gap: 25px;
                max-width: 1000px;
                margin: 50px auto 0;
            }

            .tech-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                padding: 25px 15px;
                text-align: center;
                transition: var(--transition-smooth);
                box-shadow: var(--shadow-soft);
            }

            .tech-item:hover {
                border-color: var(--royal-blue);
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .tech-icon {
                font-size: 40px;
                margin-bottom: 15px;
                color: var(--royal-blue);
            }

            .tech-item span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== PROCESS SECTION ===== */
            .process-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .process-steps {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 30px;
                margin-top: 50px;
                position: relative;
            }

            .process-steps::before {
                content: '';
                position: absolute;
                top: 40px;
                left: 50px;
                right: 50px;
                height: 3px;
                background: var(--light-gray);
                z-index: 1;
            }

            @media (max-width: 768px) {
                .process-steps::before {
                    display: none;
                }
            }

            .process-step {
                text-align: center;
                position: relative;
                z-index: 2;
            }

            .step-number {
                width: 80px;
                height: 80px;
                background: var(--cta-gradient);
                color: white;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 2rem;
                font-weight: 800;
                margin: 0 auto 25px;
                transition: var(--transition-smooth);
                border: 5px solid var(--white);
            }

            .process-step:hover .step-number {
                transform: scale(1.1);
                box-shadow: var(--shadow-medium);
            }

            .step-title {
                font-size: 1.2rem;
                font-weight: 700;
                margin-bottom: 10px;
                color: var(--navy-dark);
            }

            .step-description {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== WHY CHOOSE US ===== */
            .advantages-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .advantages-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                max-width: 1200px;
                margin: 50px auto 0;
            }

            .advantage-card {
                background: white;
                border-radius: var(--card-radius);
                padding: 35px;
                text-align: center;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .advantage-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--accent-green);
            }

            .advantage-icon {
                width: 60px;
                height: 60px;
                background: var(--success-gradient);
                border-radius: 12px;
                display: flex;
                align-items: center;
                justify-content: center;
                margin: 0 auto 20px;
                font-size: 24px;
                color: white;
            }

            .advantage-card h3 {
                font-size: 1.2rem;
                margin-bottom: 15px;
                color: var(--navy-dark);
            }

            .advantage-card p {
                color: #64748B;
                font-size: 0.95rem;
            }

            /* ===== TESTIMONIALS ===== */
            .testimonials-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .testimonials-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .testimonial-card {
                background: white;
                border-radius: var(--card-radius);
                padding: 35px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .testimonial-card:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .student-info {
                display: flex;
                align-items: center;
                gap: 15px;
                margin-bottom: 20px;
            }

            .student-avatar {
                width: 60px;
                height: 60px;
                background: var(--cta-gradient);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: 700;
                font-size: 1.4rem;
            }

            .student-details h4 {
                color: var(--navy-dark);
                margin-bottom: 5px;
                font-size: 1.1rem;
            }

            .student-details p {
                color: #64748B;
                font-size: 0.9rem;
            }

            .stars {
                color: #FBBF24;
                margin-bottom: 20px;
            }

            .testimonial-text {
                color: #475569;
                line-height: 1.6;
                font-style: italic;
            }

            /* ===== TRUST SIGNALS ===== */
            .trust-section {
                padding: 80px 15px;
                background: var(--off-white);
                text-align: center;
            }

            .trust-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 30px;
                max-width: 1000px;
                margin: 40px auto 0;
            }

            .trust-item {
                background: white;
                border-radius: var(--card-radius);
                padding: 30px 20px;
                box-shadow: var(--shadow-soft);
                transition: var(--transition-fast);
            }

            .trust-item:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .trust-icon {
                font-size: 40px;
                color: var(--royal-blue);
                margin-bottom: 15px;
            }

            .trust-item span {
                color: var(--navy-dark);
                font-weight: 600;
                font-size: 0.95rem;
            }

            /* ===== FAQ SECTION ===== */
            .faq-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .faq-container {
                max-width: 800px;
                margin: 0 auto;
            }

            .faq-item {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: var(--border-radius);
                margin-bottom: 15px;
                overflow: hidden;
                transition: var(--transition-fast);
            }

            .faq-item:hover {
                border-color: var(--royal-blue);
                box-shadow: var(--shadow-soft);
            }

            .faq-question {
                padding: 25px;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                background: var(--off-white);
            }

            .faq-question h3 {
                font-size: 1.1rem;
                color: var(--navy-dark);
                margin: 0;
                font-weight: 600;
            }

            .faq-icon {
                color: var(--royal-blue);
                transition: transform 0.3s;
            }

            .faq-item.active .faq-icon {
                transform: rotate(180deg);
            }

            .faq-answer {
                padding: 0 25px;
                max-height: 0;
                overflow: hidden;
                transition: max-height 0.3s ease-out;
            }

            .faq-item.active .faq-answer {
                padding: 25px;
                max-height: 500px;
            }

            .faq-answer p {
                color: #64748B;
                line-height: 1.6;
            }

            /* ===== CTA SECTION ===== */
            .cta-section {
                padding: 100px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--royal-blue) 100%);
                text-align: center;
                color: white;
            }

            .cta-title {
                font-size: clamp(2rem, 4vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 20px;
            }

            .cta-description {
                font-size: 1.1rem;
                margin-bottom: 40px;
                max-width: 700px;
                margin-left: auto;
                margin-right: auto;
                opacity: 0.9;
            }

            .cta-buttons {
                display: flex;
                flex-direction: column;
                gap: 15px;
                justify-content: center;
                align-items: center;
                margin-bottom: 40px;
            }

            @media (min-width: 768px) {
                .cta-buttons {
                    flex-direction: row;
                    gap: 20px;
                }
            }

            .cta-contact {
                display: flex;
                flex-direction: column;
                gap: 20px;
                justify-content: center;
                align-items: center;
                margin-top: 40px;
            }

            @media (min-width: 768px) {
                .cta-contact {
                    flex-direction: row;
                    gap: 40px;
                }
            }

            .contact-item {
                display: flex;
                align-items: center;
                gap: 12px;
                color: white;
                text-decoration: none;
                opacity: 0.9;
                transition: var(--transition-fast);
            }

            .contact-item:hover {
                opacity: 1;
                transform: translateY(-3px);
            }

            .contact-item i {
                background: rgba(255, 255, 255, 0.1);
                width: 40px;
                height: 40px;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            /* ===== FLOATING ELEMENTS ===== */
            .floating-whatsapp {
                position: fixed;
                bottom: 20px;
                right: 20px;
                width: 60px;
                height: 60px;
                background: #25D366;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 28px;
                z-index: 1000;
                box-shadow: var(--shadow-hard);
                animation: float 3s ease-in-out infinite;
                text-decoration: none;
                transition: var(--transition-smooth);
            }

            .floating-whatsapp:hover {
                transform: scale(1.1) rotate(10deg);
                animation: none;
            }

            @keyframes float {
                0%, 100% { transform: translateY(0); }
                50% { transform: translateY(-10px); }
            }

            .floating-call {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 20px;
                z-index: 1000;
                box-shadow: var(--shadow-medium);
                text-decoration: none;
                transition: var(--transition-fast);
                display: none;
            }

            @media (max-width: 768px) {
                .floating-call {
                    display: flex;
                }
            }

            .floating-call:hover {
                transform: scale(1.1);
            }

            .scroll-to-top {
                position: fixed;
                bottom: 90px;
                right: 20px;
                width: 50px;
                height: 50px;
                background: var(--royal-blue);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: white;
                font-size: 18px;
                z-index: 1000;
                cursor: pointer;
                opacity: 0;
                visibility: hidden;
                transition: all 0.3s;
                box-shadow: var(--shadow-soft);
            }

            @media (max-width: 768px) {
                .scroll-to-top {
                    bottom: 150px;
                }
            }

            .scroll-to-top.visible {
                opacity: 1;
                visibility: visible;
            }

            .scroll-to-top:hover {
                background: var(--navy-dark);
                transform: translateY(-5px);
            }

            /* ===== ANIMATION CLASSES ===== */
            .animate-on-scroll {
                opacity: 0;
                transform: translateY(30px);
                transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1), 
                            transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            }

            .animate-on-scroll.visible {
                opacity: 1;
                transform: translateY(0);
            }

            /* ===== MODAL POPUP ===== */
            .modal-overlay {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0, 0, 0, 0.8);
                z-index: 2000;
                display: none;
                justify-content: center;
                align-items: center;
                padding: 20px;
            }

            .modal-content {
                background: white;
                border-radius: var(--card-radius);
                padding: 40px;
                max-width: 500px;
                width: 100%;
                position: relative;
                animation: fadeInUp 0.5s ease;
            }

            .modal-close {
                position: absolute;
                top: 15px;
                right: 15px;
                background: none;
                border: none;
                font-size: 24px;
                color: #64748B;
                cursor: pointer;
                transition: var(--transition-fast);
            }

            .modal-close:hover {
                color: var(--navy-dark);
                transform: rotate(90deg);
            }

            /* ===== MOBILE RESPONSIVE ===== */
            @media (max-width: 768px) {
                .mobile-menu-btn {
                    display: block;
                }
                
                .nav-links {
                    display: none;
                    position: fixed;
                    top: 70px;
                    left: 0;
                    width: 100%;
                    background: white;
                    flex-direction: column;
                    padding: 20px;
                    box-shadow: var(--shadow-hard);
                    z-index: 999;
                }
                
                .nav-links.active {
                    display: flex;
                }
                
                .hero-title {
                    font-size: clamp(2rem, 4vw, 2.5rem);
                }
                
                .programs-grid,
                .services-grid,
                .advantages-grid {
                    grid-template-columns: 1fr;
                }
                
                .industries-grid {
                    grid-template-columns: repeat(2, 1fr);
                }
                
                .tech-grid {
                    grid-template-columns: repeat(2, 1fr);
                }
                
                .process-steps {
                    grid-template-columns: 1fr;
                }
                
                .testimonials-grid {
                    grid-template-columns: 1fr;
                }
                
                .btn {
                    min-width: 100%;
                    padding: 14px 30px;
                }
                
                .floating-whatsapp {
                    width: 50px;
                    height: 50px;
                    font-size: 24px;
                    bottom: 80px;
                    right: 15px;
                }
                
                .floating-call {
                    bottom: 140px;
                    right: 15px;
                }
                
                .scroll-to-top {
                    bottom: 200px;
                    right: 15px;
                }
            }

            /* ===== KEYWORD HIGHLIGHTS ===== */
            .keyword {
                color: var(--royal-blue);
                font-weight: 700;
                position: relative;
            }

            .highlight {
                background: rgba(37, 99, 235, 0.1);
                padding: 3px 8px;
                border-radius: 6px;
                font-weight: 600;
                color: var(--royal-blue);
            }
            /* ===== PLACEMENT SUPPORT SECTION ===== */
            .placement-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .placement-section .container {
                max-width: 1200px;
                margin: 0 auto;
                text-align: center;
            }

            .placement-section .program-features {
                max-width: 800px;
                margin: 40px auto;
                list-style: none;
                text-align: left;
                background: white;
                border-radius: var(--card-radius);
                padding: 40px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-smooth);
            }

            .placement-section .program-features:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--accent-green);
            }

            .placement-section .program-features li {
                color: #64748B;
                font-size: 1rem;
                margin-bottom: 15px;
                padding-left: 30px;
                position: relative;
                line-height: 1.6;
            }

            .placement-section .program-features li::before {
                content: '✓';
                position: absolute;
                left: 0;
                color: var(--accent-green);
                font-weight: bold;
                font-size: 1.1rem;
                width: 24px;
                height: 24px;
                background: rgba(34, 197, 94, 0.1);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            .placement-section p {
                color: #64748B;
                font-size: 1.1rem;
                line-height: 1.7;
                max-width: 800px;
                margin: 30px auto 0;
            }

            .placement-section .highlight {
                background: rgba(37, 99, 235, 0.1);
                padding: 2px 10px;
                border-radius: 6px;
                color: var(--royal-blue);
                font-weight: 600;
            }

            /* ===== LOCATION SECTION ===== */
            .location-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .location-section .container {
                max-width: 1200px;
                margin: 0 auto;
                text-align: center;
            }

            .location-section p {
                color: #64748B;
                font-size: 1.1rem;
                line-height: 1.7;
                max-width: 800px;
                margin: 30px auto 0;
                padding: 30px;
                background: var(--off-white);
                border-radius: var(--card-radius);
                border: 1px solid var(--light-gray);
                transition: var(--transition-fast);
            }

            .location-section p:hover {
                transform: translateY(-3px);
                box-shadow: var(--shadow-soft);
                border-color: var(--royal-blue);
            }

            /* Location badges/grid for Chennai areas */
            .location-areas {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
                gap: 15px;
                max-width: 900px;
                margin: 40px auto 0;
            }

            .area-badge {
                background: white;
                border: 1px solid var(--light-gray);
                border-radius: 50px;
                padding: 12px 20px;
                font-size: 0.95rem;
                color: var(--navy-medium);
                font-weight: 600;
                transition: var(--transition-fast);
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 8px;
            }

            .area-badge:hover {
                background: var(--royal-blue);
                color: white;
                border-color: var(--royal-blue);
                transform: translateY(-3px);
                box-shadow: var(--shadow-soft);
            }

            .area-badge i {
                font-size: 0.9rem;
            }

            /* ===== RESPONSIVE ADJUSTMENTS ===== */
            @media (max-width: 768px) {
                .placement-section {
                    padding: 60px 15px;
                }
                
                .location-section {
                    padding: 60px 15px;
                }
                
                .placement-section .program-features {
                    padding: 25px 20px;
                    margin: 30px auto;
                }
                
                .placement-section .program-features li {
                    font-size: 0.95rem;
                    margin-bottom: 12px;
                    padding-left: 28px;
                }
                
                .location-areas {
                    grid-template-columns: repeat(2, 1fr);
                    gap: 12px;
                }
                
                .area-badge {
                    padding: 10px 15px;
                    font-size: 0.85rem;
                }
                
                .location-section p {
                    padding: 20px;
                    font-size: 1rem;
                }
            }

            @media (max-width: 480px) {
                .location-areas {
                    grid-template-columns: 1fr;
                }
                
                .placement-section .program-features li {
                    font-size: 0.9rem;
                }
            }

            /* Animation for the placement features */
            .placement-section .program-features {
                animation: fadeInUp 0.8s ease 0.2s both;
            }

            .location-section p {
                animation: fadeInUp 0.8s ease 0.4s both;
            }

            .location-areas .area-badge {
                animation: fadeInUp 0.8s ease both;
            }

            .location-areas .area-badge:nth-child(1) { animation-delay: 0.1s; }
            .location-areas .area-badge:nth-child(2) { animation-delay: 0.2s; }
            .location-areas .area-badge:nth-child(3) { animation-delay: 0.3s; }
            .location-areas .area-badge:nth-child(4) { animation-delay: 0.4s; }
            .location-areas .area-badge:nth-child(5) { animation-delay: 0.5s; }
            .location-areas .area-badge:nth-child(6) { animation-delay: 0.6s; }
            .location-areas .area-badge:nth-child(7) { animation-delay: 0.7s; }
            .location-areas .area-badge:nth-child(8) { animation-delay: 0.8s; }
            /* ===== ABOUT SECTION ===== */
            .about-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .about-section .container {
                max-width: 1200px;
                margin: 0 auto;
            }

            .about-section h2 {
                text-align: center;
                margin-bottom: 40px;
            }

            .about-section p {
                color: #64748B;
                font-size: 1.1rem;
                line-height: 1.8;
                margin-bottom: 25px;
                max-width: 900px;
                margin-left: auto;
                margin-right: auto;
                background: white;
                padding: 30px;
                border-radius: var(--card-radius);
                border: 1px solid var(--light-gray);
                box-shadow: var(--shadow-soft);
                transition: var(--transition-fast);
            }

            .about-section p:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
                border-color: var(--royal-blue);
            }

            .about-section strong {
                color: var(--royal-blue);
                background: rgba(37, 99, 235, 0.1);
                padding: 2px 6px;
                border-radius: 4px;
                font-weight: 700;
            }

            /* ===== TRAINER SECTION ===== */
            .trainer-section {
                padding: 100px 15px;
                background: linear-gradient(135deg, var(--navy-dark) 0%, var(--royal-blue) 100%);
                color: white;
                text-align: center;
            }

            .trainer-section .container {
                max-width: 1200px;
                margin: 0 auto;
            }

            .trainer-section h2 {
                color: white;
                margin-bottom: 30px;
                position: relative;
                display: inline-block;
            }

            .trainer-section h2::after {
                content: '';
                position: absolute;
                bottom: -10px;
                left: 50%;
                transform: translateX(-50%);
                width: 100px;
                height: 4px;
                background: var(--accent-green);
                border-radius: 2px;
            }

            .trainer-section p {
                font-size: 1.2rem;
                line-height: 1.8;
                max-width: 800px;
                margin: 0 auto;
                opacity: 0.95;
                padding: 30px;
                background: rgba(255, 255, 255, 0.1);
                backdrop-filter: blur(10px);
                border-radius: var(--card-radius);
                border: 1px solid rgba(255, 255, 255, 0.2);
                transition: var(--transition-smooth);
            }

            .trainer-section p:hover {
                transform: translateY(-5px);
                background: rgba(255, 255, 255, 0.15);
                box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            }

            .trainer-section strong {
                color: var(--accent-green);
                font-weight: 700;
            }

            /* Trainer Cards Grid */
            .trainers-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 30px;
                margin-top: 50px;
            }

            .trainer-card {
                background: rgba(255, 255, 255, 0.1);
                backdrop-filter: blur(10px);
                border-radius: var(--card-radius);
                padding: 30px;
                text-align: center;
                border: 1px solid rgba(255, 255, 255, 0.2);
                transition: var(--transition-smooth);
            }

            .trainer-card:hover {
                transform: translateY(-10px);
                background: rgba(255, 255, 255, 0.15);
                box-shadow: 0 15px 30px rgba(0, 0, 0, 0.25);
            }

            .trainer-avatar {
                width: 100px;
                height: 100px;
                background: var(--cta-gradient);
                border-radius: 50%;
                margin: 0 auto 20px;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 2.5rem;
                color: white;
                font-weight: 700;
                border: 4px solid rgba(255, 255, 255, 0.3);
            }

            .trainer-info h4 {
                font-size: 1.3rem;
                margin-bottom: 10px;
                color: white;
            }

            .trainer-info p {
                font-size: 0.9rem;
                opacity: 0.9;
                margin-bottom: 15px;
                padding: 0;
                background: transparent;
                border: none;
                box-shadow: none;
            }

            .trainer-experience {
                display: inline-block;
                background: var(--accent-green);
                color: white;
                padding: 5px 15px;
                border-radius: 20px;
                font-size: 0.9rem;
                font-weight: 600;
                margin-top: 10px;
            }

            /* ===== PLACEMENT PROOF SECTION ===== */
            .placement-proof-section {
                padding: 100px 15px;
                background: var(--white);
            }

            .placement-proof-section .container {
                max-width: 1200px;
                margin: 0 auto;
                text-align: center;
            }

            .placement-proof-section h2 {
                margin-bottom: 15px;
            }

            .placement-proof-section .program-features {
                max-width: 800px;
                margin: 40px auto;
                list-style: none;
                text-align: left;
                background: var(--off-white);
                border-radius: var(--card-radius);
                padding: 40px;
                box-shadow: var(--shadow-soft);
                border: 2px solid var(--accent-green);
                position: relative;
                overflow: hidden;
            }

            .placement-proof-section .program-features::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 5px;
                background: var(--success-gradient);
            }

            .placement-proof-section .program-features li {
                color: var(--navy-dark);
                font-size: 1rem;
                margin-bottom: 15px;
                padding-left: 35px;
                position: relative;
                line-height: 1.6;
                font-weight: 600;
            }

            .placement-proof-section .program-features li::before {
                content: '🏆';
                position: absolute;
                left: 0;
                top: 0;
                font-size: 1.2rem;
                width: 28px;
                height: 28px;
                background: rgba(34, 197, 94, 0.1);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            .placement-proof-section .program-features li strong {
                color: var(--accent-green);
                background: none;
                padding: 0;
            }

            .placement-proof-section p {
                color: #64748B;
                font-size: 1rem;
                line-height: 1.7;
                max-width: 800px;
                margin: 30px auto 0;
                font-style: italic;
                background: var(--off-white);
                padding: 20px 30px;
                border-radius: var(--border-radius);
                border-left: 4px solid var(--accent-green);
            }

            /* Stats within placement proof */
            .placement-stats {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 20px;
                max-width: 800px;
                margin: 40px auto;
            }

            .placement-stat {
                background: white;
                border: 2px solid var(--accent-green);
                border-radius: var(--card-radius);
                padding: 25px;
                text-align: center;
                transition: var(--transition-fast);
                position: relative;
                overflow: hidden;
            }

            .placement-stat::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: linear-gradient(135deg, rgba(34, 197, 94, 0.1) 0%, rgba(22, 163, 74, 0.1) 100%);
                opacity: 0;
                transition: opacity 0.3s;
            }

            .placement-stat:hover::before {
                opacity: 1;
            }

            .placement-stat:hover {
                transform: translateY(-5px);
                box-shadow: var(--shadow-medium);
            }

            .stat-value {
                font-size: 2.5rem;
                font-weight: 800;
                color: var(--accent-green);
                margin-bottom: 5px;
            }

            .stat-label {
                font-size: 0.9rem;
                color: var(--navy-dark);
                font-weight: 600;
            }

            /* ===== RESPONSIVE ADJUSTMENTS ===== */
            @media (max-width: 768px) {
                .about-section,
                .trainer-section,
                .placement-proof-section {
                    padding: 60px 15px;
                }
                
                .about-section p,
                .trainer-section p,
                .placement-proof-section p {
                    padding: 20px;
                    font-size: 1rem;
                }
                
                .trainer-section p {
                    font-size: 1.1rem;
                }
                
                .placement-proof-section .program-features {
                    padding: 25px 20px;
                    margin: 30px auto;
                }
                
                .placement-proof-section .program-features li {
                    font-size: 0.95rem;
                    margin-bottom: 12px;
                    padding-left: 30px;
                }
                
                .trainers-grid {
                    grid-template-columns: 1fr;
                    gap: 20px;
                }
                
                .placement-stats {
                    grid-template-columns: repeat(2, 1fr);
                    gap: 15px;
                }
                
                .stat-value {
                    font-size: 2rem;
                }
            }

            @media (max-width: 480px) {
                .placement-stats {
                    grid-template-columns: 1fr;
                }
                
                .trainer-section h2::after {
                    width: 60px;
                }
                
                .placement-proof-section .program-features li {
                    font-size: 0.9rem;
                }
            }

            /* Animation for new sections */
            .about-section .container > * {
                animation: fadeInUp 0.8s ease both;
            }

            .about-section .container > *:nth-child(1) { animation-delay: 0.1s; }
            .about-section .container > *:nth-child(2) { animation-delay: 0.3s; }
            .about-section .container > *:nth-child(3) { animation-delay: 0.5s; }

            .trainer-section .container > * {
                animation: fadeInUp 0.8s ease both;
            }

            .trainer-section .container > *:nth-child(1) { animation-delay: 0.2s; }
            .trainer-section .container > *:nth-child(2) { animation-delay: 0.4s; }
            .trainers-grid .trainer-card { 
                animation: fadeInUp 0.8s ease both; 
            }
            .trainers-grid .trainer-card:nth-child(1) { animation-delay: 0.1s; }
            .trainers-grid .trainer-card:nth-child(2) { animation-delay: 0.3s; }
            .trainers-grid .trainer-card:nth-child(3) { animation-delay: 0.5s; }

            .placement-proof-section .container > * {
                animation: fadeInUp 0.8s ease both;
            }

            .placement-proof-section .container > *:nth-child(1) { animation-delay: 0.1s; }
            .placement-proof-section .container > *:nth-child(2) { animation-delay: 0.2s; }
            .placement-proof-section .container > *:nth-child(3) { animation-delay: 0.3s; }
            .placement-proof-section .container > *:nth-child(4) { animation-delay: 0.4s; }
            .placement-stats .placement-stat { 
                animation: fadeInUp 0.8s ease both; 
            }
            .placement-stats .placement-stat:nth-child(1) { animation-delay: 0.5s; }
            .placement-stats .placement-stat:nth-child(2) { animation-delay: 0.6s; }
            .placement-stats .placement-stat:nth-child(3) { animation-delay: 0.7s; }
            /* ===== NEW SECTIONS CSS ===== */

            /* SECTION 1: Comparison Section */
            .comparison-section {
                padding: 100px 15px;
                background: var(--off-white);
            }

            .comparison-grid {
                display: grid;
                grid-template-columns: 1fr;
                gap: 30px;
                max-width: 1200px;
                margin: 50px auto;
            }

            @media (min-width: 992px) {
                .comparison-grid {
                    grid-template-columns: 1fr 1fr;
                }
            }

            .comparison-card {
                background: white;
                border-radius: var(--card-radius);
                padding: 35px;
                box-shadow: var(--shadow-soft);
                border: 1px solid var(--light-gray);
                transition: var(--transition-smooth);
            }

            .comparison-card.advantage {
                border-top: 5px solid var(--accent-green);
            }

            .comparison-card.other {
                border-top: 5px solid #ef4444;
            }

            .comparison-card:hover {
                transform: translateY(-10px);
                box-shadow: var(--shadow-hard);
            }

            .comparison-header {
                margin-bottom: 25px;
                padding-bottom: 15px;
                border-bottom: 2px solid var(--light-gray);
            }

            .comparison-header h3 {
                font-size: 1.4rem;
                color: var(--navy-dark);
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .comparison-card.advantage .comparison-header h3 {
                color: var(--accent-green);
            }

            .comparison-card.other .comparison-header h3 {
                color: #ef4444;
            }

            .comparison-features {
                list-style: none;
            }

            .comparison-features li {
                padding: 12px 0;
                border-bottom: 1px solid rgba(0,0,0,0.05);
                display: flex;
                align-items: flex-start;
                gap: 12px;
                color: #64748B;
            }

            .comparison-features li:last-child {
                border-bottom: none;
            }

            .comparison-features li i.fa-check {
                color: var(--accent-green);
                margin-top: 4px;
            }

            .comparison-features li i.fa-times {
                color: #ef4444;
