            .hero-actions {
                display: flex;
                flex-wrap: wrap;
                gap: 12px;
                margin-bottom: 40px;
                animation: fadeUp .6s .3s ease both;
            }
            .hero-trust {
                display: flex;
                align-items: center;
                gap: 20px;
                font-size: .8rem;
                color: rgba(255,255,255,.7);
                animation: fadeUp .6s .4s ease both;
                flex-wrap: wrap;
            }
            .hero-trust span {
                display: flex;
                align-items: center;
                gap: 6px;
            }
            .hero-trust .dot-g {
                width: 6px;
                height: 6px;
                border-radius: 50%;
                background: var(--green);
                flex-shrink: 0;
            }

            /* Hero right card */
            .hero-card {
                background: rgba(255,255,255,.04);
                border: 1px solid rgba(255,255,255,.1);
                border-radius: var(--r2);
                padding: 32px 28px;
                backdrop-filter: blur(12px);
                animation: fadeUp .7s .2s ease both;
            }
            .hcard-title {
                font-family: var(--font-head);
                font-size: 1.1rem;
                font-weight: 700;
                margin-bottom: 20px;
                color: var(--gold);
            }
            .hcard-row {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 12px 0;
                border-bottom: 1px solid rgba(255,255,255,.06);
            }
            .hcard-row:last-of-type {
                border-bottom: none;
            }
            .hcard-icon {
                width: 36px;
                height: 36px;
                border-radius: 10px;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: .95rem;
                flex-shrink: 0;
            }
            .hcard-icon.g {
                background: rgba(6,214,160,.15);
                color: var(--green);
            }
            .hcard-icon.o {
                background: rgba(245,166,35,.15);
                color: var(--gold);
            }
            .hcard-icon.b {
                background: rgba(99,102,241,.15);
                color: #818CF8;
            }
            .hcard-label {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                margin-bottom: 2px;
            }
            .hcard-val {
                font-size: .96rem;
                font-weight: 700;
                color: var(--white);
            }
            .hcard-cta {
                margin-top: 22px;
                width: 100%;
                display: flex;
                flex-direction: column;
                gap: 10px;
            }

            /* ── BUTTONS ── */
            .btn {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 9px;
                font-family: var(--font-body);
                font-weight: 700;
                font-size: .92rem;
                padding: 13px 28px;
                border-radius: 50px;
                border: none;
                cursor: pointer;
                transition: all .25s;
                text-decoration: none;
                white-space: nowrap;
            }
            .btn-gold {
                background: linear-gradient(135deg, var(--gold), var(--gold2));
                color: var(--ink);
                box-shadow: 0 4px 22px rgba(245,166,35,.35);
            }
            .btn-gold:hover {
                transform: translateY(-3px);
                box-shadow: 0 8px 36px rgba(245,166,35,.5);
                color: var(--ink);
            }
            .btn-outline {
                background: transparent;
                border: 1.5px solid rgba(255,255,255,.2);
                color: var(--white);
            }
            .btn-outline:hover {
                border-color: var(--gold);
                color: var(--gold);
                transform: translateY(-2px);
            }
            .btn-wa {
                background: #25D366;
                color: var(--white);
                box-shadow: 0 4px 18px rgba(37,211,102,.3);
            }
            .btn-wa:hover {
                transform: translateY(-3px);
                box-shadow: 0 8px 28px rgba(37,211,102,.45);
            }
            .btn-sm {
                padding: 10px 20px;
                font-size: .82rem;
            }
            .btn-full {
                width: 100%;
                justify-content: center;
            }
            .btn-icon {
                font-size: 1rem;
            }

            /* ── SECTION BASE ── */
            .sf-section {
                padding: 90px 0;
            }
            .sf-section.alt {
                background: rgba(255,255,255,.02);
            }
            .sec-tag {
                display: inline-block;
                background: rgba(245,166,35,.1);
                border: 1px solid rgba(245,166,35,.25);
                color: var(--gold);
                font-size: .72rem;
                font-weight: 700;
                letter-spacing: .6px;
                text-transform: uppercase;
                padding: 6px 14px;
                border-radius: 50px;
                margin-bottom: 14px;
            }
            .sec-h2 {
                font-family: var(--font-head);
                font-size: clamp(1.8rem, 3.5vw, 2.6rem);
                font-weight: 800;
                letter-spacing: -.6px;
                line-height: 1.15;
                margin-bottom: 14px;
                color: white;
            }
            .sec-h2 span {
                background: linear-gradient(90deg, var(--gold), var(--gold2));
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                background-clip: text;
            }
            .sec-sub {
                font-size: 1rem;
                color: rgba(255,255,255,.75);
                max-width: 620px;
                line-height: 1.7;
                margin-bottom: 50px;
            }
            .text-center {
                text-align: center;
            }
            .text-center .sec-sub {
                margin-left: auto;
                margin-right: auto;
            }

            /* ── STATS BAR ── */
            .stats-bar {
                display: grid;
                grid-template-columns: repeat(4,1fr);
                gap: 1px;
                background: rgba(255,255,255,.06);
                border: 1px solid rgba(255,255,255,.06);
                border-radius: var(--r2);
                overflow: hidden;
                margin: 60px 0 0;
            }
            .stat-cell {
                background: var(--ink2);
                padding: 28px 20px;
                text-align: center;
                transition: background .2s;
            }
            .stat-cell:hover {
                background: var(--ink3);
            }
            .stat-num {
                font-family: var(--font-head);
                font-size: 2rem;
                font-weight: 800;
                color: var(--gold);
                margin-bottom: 4px;
                min-width: 80px;
            }
            .stat-lab {
                font-size: .78rem;
                color: rgba(255,255,255,.7);
                font-weight: 500;
                text-transform: uppercase;
                letter-spacing: .4px;
            }

            /* ── PROBLEM SECTION ── */
            .prob-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
                gap: 20px;
            }
            .prob-card {
                background: rgba(239,71,111,.06);
                border: 1px solid rgba(239,71,111,.15);
                border-radius: var(--r);
                padding: 28px;
                transition: all .3s;
            }
            .prob-card:hover {
                border-color: rgba(239,71,111,.35);
                transform: translateY(-4px);
            }
            .prob-icon {
                font-size: 1.6rem;
                margin-bottom: 14px;
            }
            .prob-card h3 {
                font-family: var(--font-head);
                font-size: 1rem;
                font-weight: 700;
                margin-bottom: 8px;
                color: var(--white);
            }
            .prob-card p {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                line-height: 1.6;
            }

            /* ── SOLUTION SECTION ── */
            .solution-content {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 40px;
                align-items: center;
            }
            .solution-text h2 {
                font-family: var(--font-head);
                font-size: clamp(1.6rem, 3vw, 2.2rem);
                font-weight: 800;
                margin-bottom: 20px;
            }
            .solution-list {
                list-style: none;
                margin-top: 24px;
            }
            .solution-list li {
                display: flex;
                align-items: flex-start;
                gap: 12px;
                margin-bottom: 16px;
                font-size: .95rem;
                color: rgba(255,255,255,.8);
            }
            .solution-list li i {
                color: var(--green);
                font-size: 1.1rem;
                margin-top: 2px;
            }
            .solution-image {
                text-align: center;
                font-size: 4rem;
                color: var(--gold);
            }

            /* ── SERVICES GRID ── */
            .srv-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 20px;
            }
            .srv-card {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r2);
                padding: 30px 26px;
                position: relative;
                overflow: hidden;
                transition: all .3s;
                cursor: default;
            }
            .srv-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                height: 3px;
                background: linear-gradient(90deg, var(--gold), var(--gold2));
                transform: scaleX(0);
                transition: transform .3s;
            }
            .srv-card:hover {
                border-color: rgba(245,166,35,.2);
                transform: translateY(-6px);
                box-shadow: 0 20px 50px rgba(0,0,0,.3);
            }
            .srv-card:hover::before {
                transform: scaleX(1);
            }
            .srv-num {
                font-family: var(--font-head);
                font-size: 3rem;
                font-weight: 800;
                color: rgba(245,166,35,.08);
                line-height: 1;
                margin-bottom: 16px;
                transition: color .3s;
            }
            .srv-card:hover .srv-num {
                color: rgba(245,166,35,.15);
            }
            .srv-card h3 {
                font-family: var(--font-head);
                font-size: 1.05rem;
                font-weight: 700;
                margin-bottom: 10px;
            }
            .srv-card p {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                line-height: 1.65;
            }
            .srv-tag {
                display: inline-block;
                background: rgba(245,166,35,.1);
                color: var(--gold);
                font-size: .7rem;
                font-weight: 700;
                padding: 3px 10px;
                border-radius: 50px;
                margin-bottom: 14px;
                letter-spacing: .3px;
            }

            /* ── WHY US GRID (Benefits) ── */
            .why-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 20px;
            }
            .why-card {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r2);
                padding: 28px;
                text-align: center;
                transition: all .3s;
            }
            .why-card:hover {
                border-color: var(--gold);
                transform: translateY(-4px);
            }
            .why-icon {
                font-size: 2rem;
                color: var(--gold);
                margin-bottom: 16px;
            }
            .why-card h3 {
                font-family: var(--font-head);
                font-size: 1.05rem;
                margin-bottom: 12px;
            }
            .why-card p {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
            }

            /* ── TECHNOLOGY STACK ── */
            .tech-grid {
                display: flex;
                flex-wrap: wrap;
                justify-content: center;
                gap: 15px;
            }
            .tech-item {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r);
                padding: 15px 20px;
                text-align: center;
                min-width: 110px;
                transition: all .2s;
            }
            .tech-item:hover {
                border-color: var(--gold);
                transform: translateY(-3px);
            }
            .tech-icon {
                font-size: 1.8rem;
                color: var(--gold);
                margin-bottom: 8px;
            }
            .tech-item span {
                font-size: .8rem;
                font-weight: 600;
            }

            /* ── PROCESS STEPS ── */
            .proc-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 30px;
                margin-top: 30px;
            }
            .proc-step {
                text-align: center;
            }
            .proc-num {
                width: 70px;
                height: 70px;
                background: linear-gradient(135deg, var(--gold), var(--gold2));
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-family: var(--font-head);
                font-size: 1.5rem;
                font-weight: 800;
                color: var(--ink);
                margin: 0 auto 18px;
                box-shadow: 0 0 0 8px rgba(245,166,35,.1);
                transition: transform .3s;
            }
            .proc-step:hover .proc-num {
                transform: scale(1.08);
            }
            .proc-step h3 {
                font-family: var(--font-head);
                font-size: 1rem;
                font-weight: 700;
                margin-bottom: 10px;
            }
            .proc-step p {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                line-height: 1.6;
            }

            /* ── CASE STUDIES GRID ── */
            .cases-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 20px;
            }
            .case-card {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.08);
                border-radius: var(--r2);
                padding: 28px;
                transition: all .3s;
            }
            .case-card:hover {
                transform: translateY(-6px);
                border-color: rgba(245,166,35,.3);
            }
            .case-badge {
                display: inline-block;
                background: rgba(245,166,35,.15);
                color: var(--gold);
                font-size: .7rem;
                font-weight: 700;
                padding: 4px 12px;
                border-radius: 50px;
                margin-bottom: 14px;
            }
            .case-title {
                font-family: var(--font-head);
                font-size: 1.1rem;
                margin-bottom: 12px;
            }
            .case-description {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                margin-bottom: 16px;
            }
            .case-tech {
                display: flex;
                gap: 16px;
                margin: 16px 0;
                font-size: .75rem;
                color: rgba(255,255,255,.6);
            }

            /* ── TESTIMONIALS GRID ── */
            .testi-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 20px;
            }
            .testi-card {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.07);
                border-radius: var(--r2);
                padding: 28px;
                transition: all .3s;
            }
            .testi-card:hover {
                border-color: var(--gold);
                transform: translateY(-4px);
            }
            .testi-stars {
                color: var(--gold);
                font-size: .9rem;
                margin-bottom: 16px;
                letter-spacing: 2px;
            }
            .testi-text {
                font-size: .88rem;
                color: rgba(255,255,255,.75);
                line-height: 1.7;
                font-style: italic;
                margin-bottom: 20px;
            }
            .testi-author {
                display: flex;
                align-items: center;
                gap: 12px;
            }
            .tav {
                width: 44px;
                height: 44px;
                border-radius: 50%;
                background: linear-gradient(135deg, var(--gold), var(--gold2));
                display: flex;
                align-items: center;
                justify-content: center;
                font-family: var(--font-head);
                font-weight: 800;
                color: var(--ink);
                font-size: .9rem;
                flex-shrink: 0;
            }
            .tav-name {
                font-weight: 700;
                font-size: .88rem;
            }
            .tav-role {
                font-size: .76rem;
                color: rgba(255,255,255,.6);
            }

            /* ── FAQ ── */
            .faq-list {
                max-width: 800px;
                margin: 0 auto;
            }
            .faq-item {
                border-bottom: 1px solid rgba(255,255,255,.07);
            }
            .faq-q {
                width: 100%;
                background: none;
                border: none;
                color: var(--white);
                text-align: left;
                padding: 22px 0;
                font-family: var(--font-body);
                font-size: .96rem;
                font-weight: 600;
                cursor: pointer;
                display: flex;
                justify-content: space-between;
                align-items: center;
                gap: 16px;
                transition: color .2s;
            }
            .faq-q:hover {
                color: var(--gold);
            }
            .faq-icon {
                font-size: 1.2rem;
                color: var(--gold);
                transition: transform .3s;
                flex-shrink: 0;
            }
            .faq-item.open .faq-icon {
                transform: rotate(45deg);
            }
            .faq-a {
                max-height: 0;
                overflow: hidden;
                transition: max-height .35s ease, padding .3s;
            }
            .faq-item.open .faq-a {
                max-height: 400px;
                padding-bottom: 18px;
            }
            .faq-a p {
                font-size: .88rem;
                color: rgba(255,255,255,.7);
                line-height: 1.75;
            }

            /* ── PRICING ── */
            .price-grid {
                display: grid;
                grid-template-columns: repeat(3,1fr);
                gap: 22px;
                align-items: start;
            }
            .price-card {
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.08);
                border-radius: var(--r2);
                padding: 34px 28px;
                transition: all .3s;
                position: relative;
                overflow: hidden;
            }
            .price-card.pop {
                background: linear-gradient(160deg, var(--ink3), rgba(245,166,35,.07));
                border-color: rgba(245,166,35,.35);
                transform: scale(1.03);
            }
            .price-card:hover {
                transform: translateY(-6px) scale(1.01);
                box-shadow: var(--sh2);
            }
            .price-card.pop:hover {
                transform: scale(1.03) translateY(-6px);
            }
            .pop-badge {
                position: absolute;
                top: 18px;
                right: -28px;
                background: linear-gradient(135deg, var(--gold), var(--gold2));
                color: var(--ink);
                font-size: .7rem;
                font-weight: 800;
                padding: 6px 40px;
                transform: rotate(45deg);
            }
            .price-plan {
                font-size: .72rem;
                font-weight: 700;
                letter-spacing: .6px;
                text-transform: uppercase;
                color: var(--gold);
                margin-bottom: 10px;
            }
            .price-usd {
                font-family: var(--font-head);
                font-size: 2.4rem;
                font-weight: 800;
                color: var(--white);
                margin-bottom: 2px;
            }
            .price-usd sup {
                font-size: 1rem;
                vertical-align: top;
                margin-top: 8px;
                color: rgba(255,255,255,.5);
            }
            .price-inr {
                font-size: .85rem;
                color: rgba(255,255,255,.7);
                margin-bottom: 6px;
            }
            .price-start {
                font-size: .75rem;
                color: var(--green);
                font-weight: 600;
                margin-bottom: 22px;
            }
            .price-feat {
                margin-bottom: 28px;
            }
            .price-feat li {
                display: flex;
                align-items: flex-start;
                gap: 10px;
                padding: 8px 0;
                border-bottom: 1px solid rgba(255,255,255,.05);
                font-size: .85rem;
                color: rgba(255,255,255,.7);
            }
            .price-feat li:last-child {
                border-bottom: none;
            }
            .price-feat li::before {
                content: '✓';
                color: var(--green);
                font-weight: 800;
                flex-shrink: 0;
                margin-top: 1px;
            }

            /* ── SEO CONTENT SECTION (humanized) ── */
            .seo-content {
                max-width: 900px;
                margin: 0 auto;
            }
            .seo-content h3 {
                font-family: var(--font-head);
                font-size: 1.3rem;
                margin: 30px 0 15px;
                color: var(--gold);
            }
            .seo-content h4 {
                font-size: 1.1rem;
                margin: 20px 0 10px;
                color: var(--white);
            }
            .seo-content p {
                margin-bottom: 15px;
                color: rgba(255,255,255,.7);
                line-height: 1.7;
            }
            .seo-content ul, .seo-content ol {
                margin: 15px 0 15px 25px;
                color: rgba(255,255,255,.7);
            }
            .seo-content li {
                margin-bottom: 8px;
            }
            .highlight-box {
                background: rgba(245,166,35,.08);
                border-left: 4px solid var(--gold);
                padding: 20px;
                margin: 25px 0;
                border-radius: var(--r);
            }

            /* ── CTA SECTION ── */
            .cta-wrap {
                background: linear-gradient(135deg, var(--ink2), var(--ink3));
                border: 1px solid rgba(245,166,35,.15);
                border-radius: var(--r2);
                padding: 64px 48px;
                text-align: center;
                position: relative;
                overflow: hidden;
            }
            .cta-h2 {
                font-family: var(--font-head);
                font-size: clamp(1.8rem, 3.5vw, 2.8rem);
                font-weight: 800;
                margin-bottom: 16px;
                letter-spacing: -.5px;
            }
            .cta-sub {
                font-size: 1.02rem;
                color: rgba(255,255,255,.75);
                max-width: 540px;
                margin: 0 auto 36px;
                line-height: 1.7;
            }
            .cta-btns {
                display: flex;
                flex-wrap: wrap;
                gap: 14px;
                justify-content: center;
                margin-bottom: 28px;
            }
            .cta-trust {
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                justify-content: center;
                font-size: .78rem;
                color: rgba(255,255,255,.6);
            }

            /* ── FLOATING ELEMENTS ── */
            .float-wa {
                position: fixed;
                bottom: 24px;
                right: 24px;
                width: 58px;
                height: 58px;
                background: #25D366;
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.5rem;
                z-index: 800;
                box-shadow: 0 6px 24px rgba(37,211,102,.4);
                animation: floatBob 3s ease-in-out infinite;
                text-decoration: none;
                transition: transform .2s;
            }
            .float-wa:hover {
                transform: scale(1.12);
                animation: none;
            }
            .float-wa-label {
                position: absolute;
                right: 70px;
                background: var(--ink2);
                color: var(--white);
                font-size: .76rem;
                font-weight: 700;
                padding: 6px 12px;
                border-radius: 8px;
                white-space: nowrap;
                opacity: 0;
                pointer-events: none;
                transition: opacity .2s;
                border: 1px solid rgba(255,255,255,.1);
            }
            .float-wa:hover .float-wa-label {
                opacity: 1;
            }
            .scroll-top {
                position: fixed;
                bottom: 90px;
                right: 24px;
                width: 44px;
                height: 44px;
                background: var(--ink2);
                border: 1px solid rgba(255,255,255,.12);
                border-radius: 50%;
                display: flex;
                align-items: center;
                justify-content: center;
                color: var(--white);
                font-size: 1rem;
                z-index: 800;
                cursor: pointer;
                opacity: 0;
                transform: translateY(10px);
                transition: all .3s;
            }
            .scroll-top.show {
                opacity: 1;
                transform: translateY(0);
            }
            .scroll-top:hover {
                background: var(--gold);
                color: var(--ink);
            }

            /* ── MODAL POPUP ── */
            .sf-modal-overlay {
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: rgba(0,0,0,0.85);
                backdrop-filter: blur(8px);
                z-index: 1000;
                display: none;
                align-items: center;
                justify-content: center;
                opacity: 0;
                transition: opacity 0.3s ease;
            }
            .sf-modal-overlay.active {
                display: flex;
                opacity: 1;
            }
            .sf-modal-content {
                background: var(--white);
                border-radius: var(--r2);
                max-width: 500px;
                width: 90%;
                padding: 32px 28px;
                position: relative;
                box-shadow: var(--sh2);
                color: var(--ink);
                text-align: center;
            }
            .sf-modal-content h3 {
                font-family: var(--font-head);
                font-size: 1.5rem;
                font-weight: 800;
                margin-bottom: 12px;
                color: var(--ink);
            }
            .sf-modal-content p {
                font-size: 0.9rem;
                margin-bottom: 24px;
                color: var(--muted);
            }
            .sf-modal-close {
                position: absolute;
                top: 16px;
                right: 20px;
                background: none;
                border: none;
                font-size: 1.5rem;
                cursor: pointer;
                color: var(--muted);
                transition: color 0.2s;
            }
            .sf-modal-close:hover {
                color: var(--red);
            }
            .sf-modal-content input,
            .sf-modal-content select {
                width: 100%;
                padding: 12px 15px;
                border: 1px solid #e2e8f0;
                border-radius: var(--r);
                font-size: 0.95rem;
                background: #f8fafc;
                color: var(--ink);
            }
            .sf-modal-content .btn-primary {
                background: var(--gold);
                color: var(--ink);
                border: none;
                padding: 12px;
                font-weight: 700;
                width: 100%;
                margin-top: 10px;
            }

            /* ── ANIMATIONS ── */
            @keyframes fadeUp {
                from { opacity: 0; transform: translateY(28px); }
                to { opacity: 1; transform: translateY(0); }
            }
            @keyframes pulse {
                0%,100% { transform: scale(1); opacity: 1; }
                50% { transform: scale(1.7); opacity: .4; }
            }
            @keyframes floatBob {
                0%,100% { transform: translateY(0); }
                50% { transform: translateY(-8px); }
            }

            .reveal {
                opacity: 0;
                transform: translateY(24px);
                transition: opacity .65s ease, transform .65s ease;
            }
            .reveal.in {
                opacity: 1;
                transform: translateY(0);
            }
            .reveal-d1 { transition-delay: .1s; }
            .reveal-d2 { transition-delay: .2s; }
            .reveal-d3 { transition-delay: .3s; }
            .reveal-d4 { transition-delay: .4s; }

