            <script>
                (function(){
                    'use strict';
                    function init(){
                        // Nav scroll effect
                        const nav = document.getElementById('sf-nav');
                        window.addEventListener('scroll', function(){
                            nav.style.background = window.scrollY > 40 ? 'rgba(10,15,30,.97)' : 'rgba(10,15,30,.82)';
                        }, {passive:true});

                        // Hamburger menu
                        const ham = document.getElementById('sf-ham');
                        const nl = document.getElementById('sf-nav-links');
                        if(ham && nl){
                            ham.addEventListener('click', function(){
                                nl.classList.toggle('open');
                                ham.innerHTML = nl.classList.contains('open') ? '<i class="fas fa-times"></i>' : '&#9776;';
                            });
                            document.addEventListener('click', function(e){
                                if(!ham.contains(e.target) && !nl.contains(e.target)){
                                    nl.classList.remove('open');
                                    ham.innerHTML = '&#9776;';
                                }
                            });
                            nl.querySelectorAll('a').forEach(function(a){
                                a.addEventListener('click', function(){
                                    nl.classList.remove('open');
                                    ham.innerHTML = '&#9776;';
                                });
                            });
                        }

                        // Scroll reveal
                        const io = new IntersectionObserver(function(entries){
                            entries.forEach(function(e){
                                if(e.isIntersecting) e.target.classList.add('in');
                            });
                        }, {threshold:0.1, rootMargin:'0px 0px -40px 0px'});
                        document.querySelectorAll('.reveal').forEach(function(el){ io.observe(el); });

                        // Counter animation
                        let counted = false;
                        const statsIO = new IntersectionObserver(function(entries){
                            if(entries[0].isIntersecting && !counted){
                                counted = true;
                                document.querySelectorAll('.stat-num').forEach(function(el){
                                    const target = parseInt(el.getAttribute('data-n') || '0');
                                    let start = 0;
                                    const step = Math.ceil(target / 60);
                                    const timer = setInterval(function(){
                                        start += step;
                                        if(start >= target){ start = target; clearInterval(timer); }
                                        el.textContent = start + (el.getAttribute('data-n') === '95' ? '%' : '+');
                                    }, 18);
                                });
                            }
                        }, {threshold:0.5});
                        const sb = document.getElementById('stats-bar');
                        if(sb) statsIO.observe(sb);

                        // FAQ toggle
                        document.querySelectorAll('.faq-q').forEach(function(btn){
                            btn.addEventListener('click', function(){
                                const item = this.parentElement;
                                const wasOpen = item.classList.contains('open');
                                document.querySelectorAll('.faq-item.open').forEach(function(o){ o.classList.remove('open'); });
                                if(!wasOpen) item.classList.add('open');
                            });
                        });

                        // Scroll to top
                        const st = document.getElementById('sf-scroll-top');
                        window.addEventListener('scroll', function(){
                            st.classList.toggle('show', window.scrollY > 600);
                        }, {passive:true});
                        if(st) st.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });

                        // Smooth scrolling
                        document.querySelectorAll('a[href^="#"]').forEach(function(a){
                            a.addEventListener('click', function(e){
                                const t = this.getAttribute('href');
                                if(t === '#' || t === '#!') return;
                                const el = document.querySelector(t);
                                if(el){
                                    e.preventDefault();
                                    el.scrollIntoView({behavior:'smooth'});
                                }
                            });
                        });

                        // Modal (exit-intent)
                        const modal = document.getElementById('sf-leadModal');
                        const modalClose = document.getElementById('sf-modalClose');
                        const leadForm = document.getElementById('sf-leadForm');
                        let modalShown = sessionStorage.getItem('modalShown') === 'true';
                        let modalActive = false;

                        if(!modalShown){
                            document.addEventListener('mouseleave', function(event){
                                if(event.clientY <= 0 && !modalActive){
                                    modal.classList.add('active');
                                    modalActive = true;
                                    sessionStorage.setItem('modalShown', 'true');
                                }
                            });
                        }

                        modalClose.addEventListener('click', function(){
                            modal.classList.remove('active');
                            modalActive = false;
                        });
                        modal.addEventListener('click', function(e){
                            if(e.target === modal){
                                modal.classList.remove('active');
                                modalActive = false;
                            }
                        });

                        leadForm.addEventListener('submit', function(e){
                            e.preventDefault();
                            const name = this.name.value.trim();
                            const email = this.email.value.trim();
                            const phone = this.phone.value.trim();
                            const industry = this.industry.value;
                            if(!name || !email || !phone){
                                alert('Please fill all fields.');
                                return;
                            }
                            const msg = `New Salesforce Inquiry:%0A%0AName: ${encodeURIComponent(name)}%0AEmail: ${encodeURIComponent(email)}%0APhone: ${encodeURIComponent(phone)}%0AIndustry: ${encodeURIComponent(industry)}`;
                            window.open(`https://wa.me/919751797695?text=${msg}`, '_blank');
                            modal.classList.remove('active');
                            modalActive = false;
                        });
                    }
                    if(document.readyState === 'loading'){
                        document.addEventListener('DOMContentLoaded', init);
                    } else {
                        init();
                    }
                })();
            </script>
        </div><!-- .sf-page -->
